window.__CH("c1",["<div class=\"hw jl\">土</div><div class=\"def\">terra.</div><div class=\"def\">⇒<a href=\"entry://地面\">地面</a>,<a href=\"entry://大地\">大地</a>.</div>\r\n","<div class=\"hw jl\">土台</div><div class=\"def\">fundamen, fundus, fundamentum, substructio, crepido.</div><div class=\"def\">▼<b>～から</b> funditus.</div><div class=\"def\">▼<b>～を据える</b> substruo, fundo.</div>\r\n","<div class=\"hw jl\">土地</div><div class=\"def\">terra, locus, terrenum, ager.</div><div class=\"def\">▼<b>～の</b> terrestris.</div><div class=\"def\">⇒<a href=\"entry://地面\">地面</a>.</div>\r\n","<div class=\"hw jl\">土産</div><div class=\"def\">xenium.</div>\r\n","<div class=\"hw jl\">圧倒</div><div class=\"def\">oppressio.</div><div class=\"def\">▼<b>～する</b> opprimo, devinco, supero.</div>\r\n","<div class=\"hw jl\">圧力</div><div class=\"def\">pressus, pressio.</div><div class=\"def\">▼<b>～をかける</b> presso.</div>\r\n","<div class=\"hw jl\">圧縮</div><div class=\"def\">compressus, compressio.</div><div class=\"def\">▼<b>～された</b> compressus.</div><div class=\"def\">▼<b>～する</b> comprimo.</div>\r\n","<div class=\"hw jl\">圧迫</div><div class=\"def\">angor, oppressio.</div><div class=\"def\">▼<b>～する</b> ango, opprimo, urgeo.</div>\r\n","<div class=\"hw jl\">在庫</div><div class=\"def\">cumulus mercium in receptaculo.</div>\r\n","<div class=\"hw jl\">地上</div><div class=\"def\">▼<b>～の</b> terrestris.</div><div class=\"def\">▼<b>～に</b> supra terram.</div><div class=\"def\">⇒<a href=\"entry://天上\">天上</a>.</div>\r\n","<div class=\"hw jl\">地下</div><div class=\"def\">(建物の)hypogeum.</div><div class=\"def\">▼<b>～の</b> subterraneus, hypogeus, inferus, infernus.</div><div class=\"def\">▼<b>～に[で]</b> sub terra.</div>\r\n","<div class=\"hw jl\">地下鉄</div><div class=\"def\">(路線)ferrivia subterranea, subterranea ferrata via urbis;(列車)hamaxostichus subterraneus.</div>\r\n","<div class=\"hw jl\">地位</div><div class=\"def\">(社会的)locus, ordo, gradus.</div>\r\n","<div class=\"hw jl\">地区</div><div class=\"def\">pars.</div><div class=\"def\">⇒<a href=\"entry://地域\">地域</a>,<a href=\"entry://区域\">区域</a>.</div>\r\n","<div class=\"hw jl\">地名</div><div class=\"def\">loci nomen, toponymum.</div>\r\n","<div class=\"hw jl\">地味</div><div class=\"def\">▼<b>～な</b> simplex, incomptus.</div><div class=\"def\">⇒<a href=\"entry://質素\">質素</a>,<a href=\"entry://控えめ\">控えめ</a>.</div>\r\n","<div class=\"hw jl\">地図</div><div class=\"def\">charta geographica, regio in tabula depicta.</div><div class=\"def\">▼<b>世界～</b> orbis terrarum descriptio.</div>\r\n","<div class=\"hw jl\">地域</div><div class=\"def\">regio, terra, locus, orbis.</div><div class=\"def\">⇒<a href=\"entry://土地\">土地</a>,<a href=\"entry://地方\">地方</a>,<a href=\"entry://領地\">領地</a>,<a href=\"entry://区域\">区域</a>,<a href=\"entry://圏\">圏</a>.</div>\r\n","<div class=\"hw jl\">地平線</div><div class=\"def\">horizon, finiens circulus [orbis, linea], finitor circulus.</div>\r\n","<div class=\"hw jl\">地形</div><div class=\"def\">loci natura.</div>\r\n","<div class=\"hw jl\">地方</div><div class=\"def\">regio, terra, locus;(=属州)provincia.</div><div class=\"def\">▼<b>～の</b> regionalis;(=属州の)provincialis.</div>\r\n","<div class=\"hw jl\">地方都市</div><div class=\"def\">municipium, oppidum.</div><div class=\"def\">▼<b>～の</b> municipalis, oppidanus.</div><div class=\"def\">▼<b>～民</b> municipalis, oppidanus.</div><div class=\"def\">⇒<a href=\"entry://首都\">首都</a>.</div>\r\n","<div class=\"hw jl\">地獄</div><div class=\"def\">infernus, gehenna.</div><div class=\"def\">▼<b>～の</b> infernus,gehennalis.</div><div class=\"def\">⇒<a href=\"entry://天国\">天国</a>.</div>\r\n","<div class=\"hw jl\">地球</div><div class=\"def\">orbis(terrae [terrarum]), globus(terrae), terra.</div>\r\n","<div class=\"hw jl\">地理</div><div class=\"def\">▼<b>～(学)</b> geographia, regionum terrestrium aut maritimarum scientia.</div><div class=\"def\">▼<b>～(学)の</b> geographicus.</div><div class=\"def\">⇒<a href=\"entry://地図\">地図</a>.</div>\r\n","<div class=\"hw jl\">地震</div><div class=\"def\">terrae motus [quassatio].</div><div class=\"ex2\">～が発生した<span class=\"ext\">terrae motus accidit.</span></div>\r\n","<div class=\"hw jl\">地面</div><div class=\"def\">solum, humus, terra.</div>\r\n","<div class=\"hw jl\">坂</div><div class=\"def\">clivus.</div><div class=\"def\">▼<b>上り～</b> acclivitas.</div><div class=\"def\">▼<b>上り～の</b> acclivis.</div><div class=\"def\">▼<b>下り～</b> declivitas.</div><div class=\"def\">▼<b>下り～の</b> declivis.</div>\r\n","<div class=\"hw jl\">均衡</div><div class=\"def\">(状態)libramentum, aequitas.</div>\r\n","<div class=\"hw jl\">垂れる</div><div class=\"def\">(頭を)(=垂らす)(caput)demitto;(液体が)(=滴る)mano;(=垂れ下がる)dependeo, pendeo.</div>\r\n","<div class=\"hw jl\">垂直</div><div class=\"def\">▼<b>～の</b> directus, rectus, verticalis.</div>\r\n","<div class=\"hw jl\">型</div><div class=\"def\">(=鋳型)forma.</div><div class=\"def\">⇒<a href=\"entry://模型\">模型</a>,<a href=\"entry://模範\">模範</a>.</div>\r\n","<div class=\"hw jl\">垢</div><div class=\"def\">squalor.</div><div class=\"def\">▼<b>～にまみれた</b> squalidus.</div><div class=\"def\">▼<b>～にまみれている</b> squaleo.</div>\r\n","<div class=\"hw jl\">埋める</div><div class=\"def\">obruo, defodio;(=埋葬する)humo, sepelio.</div>\r\n","<div class=\"hw jl\">埋め立てる</div><div class=\"def\">terrae conjectu expleo.</div>\r\n","<div class=\"hw jl\">埋葬</div><div class=\"def\">humatio, sepultura.</div><div class=\"def\">▼<b>～する</b> humo, sepelio, operio.</div>\r\n","<div class=\"hw jl\">城</div><div class=\"def\">(=城塞, 要塞)castellum, arx;(=王宮, 宮殿)turris, aedes regiae(<i>pl</i>), regia.</div>\r\n","<div class=\"hw jl\">城壁</div><div class=\"def\">moenia(<i>pl</i>), murus.</div><div class=\"ex2\">～内に<span class=\"ext\">intra murum.</span></div>\r\n","<div class=\"hw jl\">執政官</div><div class=\"def\">consul.</div><div class=\"def\">▼<b>～の</b> consularis.</div>\r\n","<div class=\"hw jl\">執着</div><div class=\"def\">⇒<a href=\"entry://愛着\">愛着</a>.</div>\r\n","<div class=\"hw jl\">執筆</div><div class=\"def\">(本の)(libri)confectio.</div><div class=\"ex2\">歴史書の～に精を出す<span class=\"ext\">ad scribendam historiam se applicare(← applico).</span></div><div class=\"def\">⇒<a href=\"entry://書く・描く\">書く</a>,<a href=\"entry://作文\">作文</a>,<a href=\"entry://起草\">起草</a>.</div>\r\n","<div class=\"hw jl\">基づく</div><div class=\"def\">fundor(<i>pass</i>), nitor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">基地</div><div class=\"def\">statio, ea regio unde exercitui copiae cujusque generis suppeditantur.</div><div class=\"def\">▼<b>軍事～</b> stationes militares(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://要塞\">要塞</a>,<a href=\"entry://陣営\">陣営</a>.</div>\r\n","<div class=\"hw jl\">基本</div><div class=\"def\">(=初歩, 基礎)elementa(<i>pl</i>), initia(<i>pl</i>), principia(<i>pl</i>), rudimenta(<i>pl</i>).</div><div class=\"def\">▼<b>～の, ～的な</b> elementarius.</div><div class=\"def\">⇒<a href=\"entry://基礎\">基礎</a>.</div>\r\n","<div class=\"hw jl\">基準</div><div class=\"def\">(=標準)norma, regula.</div>\r\n","<div class=\"hw jl\">基礎</div><div class=\"def\">basis, solum, fundus, fundamentum, fundamen, principium, crepido;(学問・技芸の)elementum.</div><div class=\"def\">▼<b>～的な</b> principalis.</div><div class=\"def\">⇒<a href=\"entry://基本\">基本</a>.</div>\r\n","<div class=\"hw jl\">堂々</div><div class=\"def\">▼<b>～とした</b> magnificus, magnus.</div>\r\n","<div class=\"hw jl\">堅固</div><div class=\"def\">firmitas, soliditas.</div><div class=\"def\">▼<b>～な</b> firmus, solidus.</div><div class=\"def\">▼<b>～にする</b> solido.</div>\r\n","<div class=\"hw jl\">堅苦しい</div><div class=\"def\">inaniter [putide] urbanus, nimis officiosus.</div><div class=\"def\">▼<b>堅苦しさ</b> frigida [putida] urbanitas, nimia formulae observantia, nimia officiositas.</div>\r\n","<div class=\"hw jl\">堆積</div><div class=\"def\">acervus, congeries, congestus.</div><div class=\"def\">⇒<a href=\"entry://積み重ねる\">積み重ねる</a>,<a href=\"entry://積む\">積む</a>.</div>\r\n","<div class=\"hw jl\">堕胎</div><div class=\"def\">abortio.</div><div class=\"def\">⇒<a href=\"entry://流産\">流産</a>.</div>\r\n","<div class=\"hw jl\">堤防</div><div class=\"def\">agger, moles.</div>\r\n","<div class=\"hw jl\">報いる</div><div class=\"def\">(人に報償で)(=人に報酬を与える)(alqm praemio)remuneror(<i>dep</i>), dono, (alci praemium)do, tribuo, defero.</div>\r\n","<div class=\"hw jl\">報告</div><div class=\"def\">relatio, narratio, renuntiatio.</div><div class=\"def\">▼<b>～する</b> refero, narro, renuntio.</div><div class=\"def\">⇒<a href=\"entry://知らせる\">知らせる</a>,<a href=\"entry://告知\">告知</a>.</div>\r\n","<div class=\"hw jl\">報復</div><div class=\"def\">(=復讐)ultio, vindicatio, vindicta.</div><div class=\"def\">▼<b>～する</b> ulciscor(<i>dep</i>), vindico.</div>\r\n","<div class=\"hw jl\">報道</div><div class=\"def\">nuntiatio, nuntius.</div>\r\n","<div class=\"hw jl\">報酬</div><div class=\"def\">remuneratio, praemium, manupretium, merces.</div><div class=\"def\">▼(...に)<b> ～を与える</b> 〈alqm〉 remuneror(<i>dep</i>), 〈alqm〉 praemio dono.</div>\r\n","<div class=\"hw jl\">場</div><div class=\"def\">locus.</div>\r\n","<div class=\"hw jl\">場合</div><div class=\"def\">casus.</div><div class=\"def\">▼(...の)<b>～(は)</b> si.</div>\r\n","<div class=\"hw jl\">場所</div><div class=\"def\">locus.</div>\r\n","<div class=\"hw jl\">場面</div><div class=\"def\">actus.</div>\r\n","<div class=\"hw jl\">塀</div><div class=\"def\">maceria, maceries, paries, murus.</div><div class=\"def\">⇒<a href=\"entry://壁\">壁</a>,<a href=\"entry://城壁\">城壁</a>.</div>\r\n","<div class=\"hw jl\">塊</div><div class=\"def\">(ぎっしりつまった)massa;(大きな)moles.</div>\r\n","<div class=\"hw jl\">塔</div><div class=\"def\">turris.</div>\r\n","<div class=\"hw jl\">塗る</div><div class=\"def\">induco, lino, linio, illino, oblino;(色を)coloro;(油を)ungo.</div>\r\n","<div class=\"hw jl\">塗料</div><div class=\"def\">color, pigmentum.</div>\r\n","<div class=\"hw jl\">塗装</div><div class=\"def\">coloris inductio.</div><div class=\"def\">▼<b>～する</b> colorem induco.</div>\r\n","<div class=\"hw jl\">塩</div><div class=\"def\">sal.</div><div class=\"def\">▼<b>～の</b> salarius.</div>\r\n","<div class=\"hw jl\">塩素</div><div class=\"def\">chlorium.</div>\r\n","<div class=\"hw jl\">塩酸</div><div class=\"def\">muriaticum(hydrochloricum)acidum.</div>\r\n","<div class=\"hw jl\">境</div><div class=\"def\">(=境界線, 境目, 限界)terminus, finis, regio.</div><div class=\"def\">⇒<a href=\"entry://境界\">境界</a>.</div>\r\n","<div class=\"hw jl\">境界</div><div class=\"def\">finis.</div>\r\n","<div class=\"hw jl\">墓</div><div class=\"def\">sepulcrum.</div><div class=\"def\">▼<b>～石</b> sepulcri lapis.</div><div class=\"def\">▼<b>～穴</b> scrobis.</div><div class=\"def\">⇒<a href=\"entry://墓地\">墓地</a>,<a href=\"entry://墓標\">墓標</a>,<a href=\"entry://墓碑\">墓碑</a>.</div>\r\n","<div class=\"hw jl\">墓地</div><div class=\"def\">coemeterium.</div><div class=\"def\">⇒<a href=\"entry://墓\">墓</a>.</div>\r\n","<div class=\"hw jl\">墓標</div><div class=\"def\">sepulcri monumentum.</div><div class=\"def\">⇒<a href=\"entry://墓\">墓</a>.</div>\r\n","<div class=\"hw jl\">墓碑</div><div class=\"def\">(華麗な)mausoleum.</div><div class=\"def\">▼<b>～銘</b> elogium.</div><div class=\"def\">⇒<a href=\"entry://墓\">墓</a>.</div>\r\n","<div class=\"hw jl\">増える</div><div class=\"def\">(数が)(numero)cresco, multiplicor(<i>pass</i>), augeo.</div>\r\n","<div class=\"hw jl\">増やす</div><div class=\"def\">augeo, amplifico, multiplico.</div><div class=\"def\">⇒<a href=\"entry://増える\">増える</a>,<a href=\"entry://増加\">増加</a>.</div>\r\n","<div class=\"hw jl\">増加</div><div class=\"def\">amplificatio.</div><div class=\"def\">▼<b>～する</b> augesco.</div><div class=\"def\">▼<b>～させる</b> augeo.</div><div class=\"def\">⇒<a href=\"entry://増大\">増大</a>.</div>\r\n","<div class=\"hw jl\">増大</div><div class=\"def\">amplificatio, auctus, incrementum, multiplicatio.</div><div class=\"def\">▼<b>～する</b> incresco, accresco, augesco, multiplicor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://増やす\">増やす</a>,<a href=\"entry://増える\">増える</a>,<a href=\"entry://増加\">増加</a>.</div>\r\n","<div class=\"hw jl\">墨</div><div class=\"def\">⇒<a href=\"entry://インク\">インク</a>.</div>\r\n","<div class=\"hw jl\">墨汁</div><div class=\"def\">atramentum.</div>\r\n","<div class=\"hw jl\">壁</div><div class=\"def\">paries, maceria.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">外壁, 城壁<span class=\"ext\">murus.</span></div>\r\n","<div class=\"hw jl\">壊す</div><div class=\"def\">destruo.</div><div class=\"def\">▼<b>取り～</b> demolior(<i>dep</i>).</div><div class=\"def\">▼<b>取り～こと</b> demolitio.</div><div class=\"def\">⇒<a href=\"entry://破壊\">破壊</a>.</div>\r\n","<div class=\"hw jl\">壮大</div><div class=\"def\">magnificentia.</div><div class=\"def\">▼<b>～な</b> magnificus.</div>\r\n","<div class=\"hw jl\">声</div><div class=\"def\">vox.</div><div class=\"ex2\">大～で<span class=\"ext\">magna voce.</span></div><div class=\"ex2\">～を低くして<span class=\"ext\">voce submissa.</span></div>\r\n","<div class=\"hw jl\">声明</div><div class=\"def\">editio.</div>\r\n","<div class=\"hw jl\">売り上げ</div><div class=\"def\">acceptum.</div>\r\n","<div class=\"hw jl\">売る</div><div class=\"def\">vendo;(=売りに出す)vendito.</div><div class=\"def\">▼<b>売られる</b> veneo.</div><div class=\"ex2\">高い値段で売られる<span class=\"ext\">magno veneo.</span></div><div class=\"def\">▼<b>売り手</b> venditor.</div><div class=\"ex2\">アントニウスは王国を金で売り渡した<span class=\"ext\">Antonius regna addixit pecuniā</span></div><div class=\"def\">⇒<a href=\"entry://買う\">買う</a>.</div>\r\n","<div class=\"hw jl\">売却</div><div class=\"def\">venditio, venditum.</div><div class=\"def\">▼<b>～する</b> vendo.</div>\r\n","<div class=\"hw jl\">売春</div><div class=\"def\">meretricius quaestus, meretricia vita, meretricium.</div><div class=\"def\">▼<b>～婦</b> meretrix, scortum, lupa.</div><div class=\"def\">▼<b>～宿</b> lustra(<i>pl</i>), lupanar, ganea, fornix, stabulum.</div>\r\n","<div class=\"hw jl\">壺</div><div class=\"def\">vas, olla, cadus.</div>\r\n","<div class=\"hw jl\">変える</div><div class=\"def\">muto, commuto, moveo, converto, immuto;(決心・習慣・進路を)inflector(<i>pass</i>), flector(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://変化\">変化</a>.</div>\r\n","<div class=\"hw jl\">変な</div><div class=\"def\">(=異常な, 普通でない)insolitus, inusitatus, novus, mirus.</div><div class=\"def\">⇒<a href=\"entry://奇妙\">奇妙</a>.</div>\r\n","<div class=\"hw jl\">変動</div><div class=\"def\">mutatio, fluctuatio.</div><div class=\"def\">▼<b>～する</b> mutor(<i>pass</i>), fluctuor(<i>pass</i>).</div><div class=\"ex2\">気候～のために<span class=\"ext\">propter mutationes climaticas(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://変化\">変化</a>.</div>\r\n","<div class=\"hw jl\">変化</div><div class=\"def\">mutatio, commutatio, immutatio, motus, conversio.</div><div class=\"def\">▼<b>～しないこと</b>(=一様であること)constantia.</div><div class=\"def\">▼<b>～する</b>(=変わる)mutor(<i>pass</i>), commutor(<i>pass</i>);(=不定である)vario.</div><div class=\"def\">⇒<a href=\"entry://変える\">変える</a>,<a href=\"entry://不変\">不変</a>.</div>\r\n","<div class=\"hw jl\">変更</div><div class=\"def\">mutatio.</div><div class=\"def\">▼<b>～する</b> muto, novo.</div><div class=\"def\">⇒<a href=\"entry://変える\">変える</a>,<a href=\"entry://変化\">変化</a>.</div>\r\n","<div class=\"hw jl\">変装</div><div class=\"def\">permutatus habitus, habitus occultus.</div><div class=\"def\">▼<b>～して</b> in dissimulationem sui veste compositus.</div><div class=\"def\">▼<b>～した</b> personatus.</div><div class=\"def\">▼<b>～する</b> habitum permuto, vestem muto.</div><div class=\"def\">▼<b>～させる</b> cultu [habitu, veste] dissimulo.</div>\r\n","<div class=\"hw jl\">夏</div><div class=\"def\">aestas, aestus;(=夏至)solstitium.</div><div class=\"def\">▼<b>～の</b> aestivus;(=真夏の, 夏至の)solstitialis.</div><div class=\"def\">▼<b>～に</b> aestate.</div><div class=\"def\">⇒<a href=\"entry://季節\">季節</a>.</div>\r\n","<div class=\"hw jl\">夏休み</div><div class=\"def\">feriae aestivae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">夏至</div><div class=\"def\">solstitium.</div><div class=\"def\">▼<b>～の</b> solstitialis.</div>\r\n","<div class=\"hw jl\">夕方</div><div class=\"def\">(=晩, 日没から就寝まで)vesper, vespera.</div><div class=\"def\">▼<b>～の</b>(=晩の)vespertinus.</div><div class=\"def\">▼<b>～(に)</b> vesperi, ad vesperam.</div><div class=\"def\">▼<b>～の始めに</b> primo vespere, primā vesperā.</div><div class=\"def\">▼<b>～になる</b> vesperascit(<i>impers</i>), advesperascit(<i>impers</i>).</div><div class=\"def\">⇒<a href=\"entry://晩\">晩</a>,<a href=\"entry://夕暮れ\">夕暮れ</a>.</div>\r\n","<div class=\"hw jl\">夕暮れ</div><div class=\"def\">crepusculum.</div><div class=\"def\">▼<b>～時に</b> primo crepusculo, primis tenebris.</div><div class=\"def\">⇒<a href=\"entry://夕方\">夕方</a>.</div>\r\n","<div class=\"hw jl\">夕食</div><div class=\"def\">cena, cibus vespertinus.</div><div class=\"def\">▼<b>～を取る</b> ceno.</div><div class=\"def\">⇒<a href=\"entry://食事\">食事</a>.</div>\r\n","<div class=\"hw jl\">外</div><div class=\"def\">(=外部)exterior pars.</div><div class=\"def\">▼<b>～の</b> exter, externus.</div><div class=\"def\">▼<b>～で</b> foris.</div><div class=\"def\">▼<b>～へ</b> foras.</div><div class=\"def\">▼<b>～から</b> extrinsecus.</div><div class=\"def\">▼(...の)<b>～に</b> extra 〈+<i>acc</i>〉.</div><div class=\"ex2\">～で食事をする<span class=\"ext\">foris ceno.</span></div><div class=\"ex2\">～へ出る<span class=\"ext\">foras eo.</span></div><div class=\"ex2\">町の～へ<span class=\"ext\">extra oppidum.</span></div>\r\n","<div class=\"hw jl\">外交</div><div class=\"def\">res diplomatica, legationum obeundarum disciplina [ars, prudentia].</div><div class=\"def\">▼<b>～の, ～的な</b> diplomaticus.</div><div class=\"def\">▼<b>～官</b>(=使節)legatus.</div>\r\n","<div class=\"hw jl\">外出</div><div class=\"def\">▼<b>～する</b> domo egredior(<i>dep</i>)[exeo], foras exeo.</div>\r\n","<div class=\"hw jl\">外務</div><div class=\"def\">▼<b>～大臣</b> administer exteris rebus praepositus, administer exteris negotiis praepositus, minister a rebus exteris.</div><div class=\"def\">▼<b>～省</b> sedes administri exteris negotiis praepositi.</div>\r\n","<div class=\"hw jl\">外国</div><div class=\"def\">externi populi(<i>pl</i>), exterae gentes(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> externus, peregrinus, alienus.</div><div class=\"def\">▼<b>～に[で], ～へ[から]</b> peregre.</div>\r\n","<div class=\"hw jl\">外国人</div><div class=\"def\">peregrinus(homo), advena, alienigena.</div><div class=\"def\">▼<b>～の</b> peregrinus, alienigenus, externus, alienus.</div>\r\n","<div class=\"hw jl\">外套</div><div class=\"def\">(男性用の)pallium;(女性用の)palla.</div>\r\n","<div class=\"hw jl\">外科</div><div class=\"def\">▼<b>～医</b> chirurgus.</div><div class=\"def\">▼<b>～医術</b> chirurgia.</div><div class=\"def\">▼<b>～の</b> chirurgicus.</div>\r\n","<div class=\"hw jl\">多い</div><div class=\"def\">(=多くの, 多数の, たくさんの)multus, amplus;(人や回数が)frenquens.</div><div class=\"def\">▼<b>相当多くの</b> complures(<i>pl</i>).</div><div class=\"def\">▼<b>そんなに～</b> tantus, tot.</div><div class=\"def\">▼<b>～こと</b>(=多さ, 多数)multitudo.</div><div class=\"ex2\">多くの市民たち<span class=\"ext\">magnus civium numerus.</span></div>\r\n","<div class=\"hw jl\">多少</div><div class=\"def\">(=多少とも)aliquantum.</div><div class=\"def\">⇒<a href=\"entry://少し\">少し</a>.</div>\r\n","<div class=\"hw jl\">多彩</div><div class=\"def\">vatietas.</div><div class=\"def\">▼<b>～な</b> varius.</div>\r\n","<div class=\"hw jl\">多数</div><div class=\"def\">⇒<a href=\"entry://多い\">多い</a>.</div>\r\n","<div class=\"hw jl\">夜</div><div class=\"def\">nox, nocturnum tempus, tenebrae(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> nocturnus.</div><div class=\"def\">▼<b>～に</b> noctu.</div><div class=\"def\">▼<b>～になる前に</b> ante noctem.</div><div class=\"def\">▼<b>ある～に</b> una nocte.</div><div class=\"def\">▼<b>その～(に)</b> ea nocte.</div><div class=\"ex2\">～だった<span class=\"ext\">nox erat.</span></div><div class=\"ex2\">きみは何でこんな～にやって来るのか<span class=\"ext\">quid hoc noctis venis?</span></div>\r\n","<div class=\"hw jl\">夜中</div><div class=\"def\">(=真夜中)media nox;(=夜更け)multa nox.</div><div class=\"def\">▼<b>～に</b> noctu;(=真夜中に)media nocte;(=夜も更けて)multa nocte.</div>\r\n","<div class=\"hw jl\">夢</div><div class=\"def\">somnium.</div><div class=\"def\">▼(...を)<b> ～に見る</b> somnio 〈+<i>acc</i>;+<i>acc c. inf</i>〉, video somno, per somnum cerno.</div><div class=\"ex2\">～の中で<span class=\"ext\">in somniis.</span></div><div class=\"ex2\">私は～を見た<span class=\"ext\">mihi somnium evenit.</span></div><div class=\"ex2\">不思議な～を見る<span class=\"ext\">mirum somnium somnio.</span></div><div class=\"ex2\">とても良い～をみる<span class=\"ext\">jucundissimis somniis utor(<i>dep</i>).</span></div>\r\n","<div class=\"hw jl\">夢中</div><div class=\"def\">(=無我夢中, 我を忘れた状態, 狂気)furor, insania;(=過度な愛好)nimius amor.</div><div class=\"def\">▼(...に)<b> ～だ</b> 〈in+<i>abl</i>〉 totus sum, 〈+<i>dat</i>〉 in insaniam faveo.</div><div class=\"def\">▼(...に)<b> ～の</b> nimio amore 〈+<i>gen</i>〉 correptus.</div><div class=\"def\">▼<b>～に(なって)</b> in insaniam.</div><div class=\"def\">⇒<a href=\"entry://狂気\">狂気</a>,<a href=\"entry://熱狂\">熱狂</a>.</div>\r\n","<div class=\"hw jl\">夢想</div><div class=\"def\">(=起きたまま見る夢)alicujus vigilantis somnia(<i>pl</i>);(=夢, 空想)somnium.</div><div class=\"def\">⇒<a href=\"entry://空想\">空想</a>,<a href=\"entry://妄想\">妄想</a>.</div>\r\n","<div class=\"hw jl\">大きい</div><div class=\"def\">magnus, amplus.</div><div class=\"def\">▼<b>非常に～</b>(=巨大な)ingens.</div><div class=\"def\">▼<b>大きくする</b> amplifico, amplio.</div><div class=\"def\">▼<b>大きくなる</b> cresco.</div><div class=\"def\">▼<b>大きさ</b> magnitudo, amplitudo.</div>\r\n","<div class=\"hw jl\">大げさ</div><div class=\"def\">▼<b>～な</b> tumidus, tumens, inflatus, exaggeratus.</div><div class=\"def\">▼<b>～に言う</b> exaggero(oratione [verbis]).</div>\r\n","<div class=\"hw jl\">大事</div><div class=\"def\">⇒<a href=\"entry://重要\">重要</a>,<a href=\"entry://大切\">大切</a>.</div>\r\n","<div class=\"hw jl\">大人</div><div class=\"def\">pubes.</div><div class=\"def\">▼<b>～の</b> adultus, pubes.</div><div class=\"def\">⇒<a href=\"entry://成人\">成人</a>.</div>\r\n","<div class=\"hw jl\">大使</div><div class=\"def\">legatus.</div><div class=\"def\">▼<b>～館</b> legati sedes [domus].</div><div class=\"def\">⇒<a href=\"entry://使節\">使節</a>.</div>\r\n","<div class=\"hw jl\">大切</div><div class=\"def\">▼<b>～な</b> carus.</div><div class=\"def\">▼(<i>inf</i> を主語にして)<b>～である</b> refert, expedit, oportet.</div><div class=\"def\">▼<b>～にする</b> colo, parco.</div><div class=\"ex2\">すべての人々にとって正しく行なうことが～である<span class=\"ext\">interest omnium recte facere.</span></div>\r\n","<div class=\"hw jl\">大勢</div><div class=\"def\">▼<b>～の人々</b> magnus populus.</div><div class=\"ex2\">彼らは～でやってきた<span class=\"ext\">facta manu venerunt.</span></div>\r\n","<div class=\"hw jl\">大半</div><div class=\"def\">major pars, maxima pars, maximus numerus.</div><div class=\"def\">▼<b>～の人々</b> maxima pars hominum, plurimi(<i>pl</i>).</div><div class=\"ex2\">～のギリシア人<span class=\"ext\">plerique Graecorum.</span></div><div class=\"def\">⇒<a href=\"entry://大部分\">大部分</a>.</div>\r\n","<div class=\"hw jl\">大地</div><div class=\"def\">terra, tellus.</div>\r\n","<div class=\"hw jl\">大変</div><div class=\"def\">▼<b>～な</b>(=重大な)gravis, magnus;(=恐ろしい)terribilis, horribilis, horrendus;(=異常な, 甚だしい, ものすごい)enormis, immanis, immensus, vastus;(=つらい, 耐え難い, 困難な)durus, acerbus, difficilis, laboriosus.</div><div class=\"def\">▼<b>～(に)</b> ⇒ <a href=\"entry://非常に\">非常に</a>.</div>\r\n","<div class=\"hw jl\">大学</div><div class=\"def\">athenaeum, maxima studiorum sedes, (studiorum)universitas, academia.</div>\r\n","<div class=\"hw jl\">大気</div><div class=\"def\">(terris)circumjectus aer, circumfusus aer.</div>\r\n","<div class=\"hw jl\">大理石</div><div class=\"def\">marmor.</div><div class=\"def\">▼<b>～の</b> marmoreus.</div><div class=\"ex2\">～の彫像<span class=\"ext\">simulacrum ex marmore.</span></div>\r\n","<div class=\"hw jl\">大砲</div><div class=\"def\">instrumentum pyrobolos emittens, machina pyrobolorum expulsoria.</div>\r\n","<div class=\"hw jl\">大統領</div><div class=\"def\">praesidens, praeses(rei publicae).</div><div class=\"def\">▼<b>副～</b> vicarius praesidentis.</div><div class=\"def\">▼<b>～選挙</b> comitia praesidentialia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">大胆</div><div class=\"def\">(=大胆不敵)audacia, confidentia.</div><div class=\"def\">▼<b>～(不敵)な</b> audax, confidens.</div><div class=\"def\">▼<b>～(不敵)にも</b> audacter, confidenter.</div><div class=\"def\">⇒<a href=\"entry://勇敢\">勇敢</a>.</div>\r\n","<div class=\"hw jl\">大臣</div><div class=\"def\">administer civitatis, minister muneris publici.</div><div class=\"ex2\">外務～<span class=\"ext\">administer exteris rebus praepositus.</span></div><div class=\"ex2\">財務～<span class=\"ext\">administer rei nummariae publicae praepositus.</span></div><div class=\"ex2\">法務～<span class=\"ext\">administer rei judiciariae praepositus.</span></div><div class=\"ex2\">総理～(=首相)<span class=\"ext\">administrorum princeps.</span></div>\r\n","<div class=\"hw jl\">大衆</div><div class=\"def\">vulgus, multitudo, turba.</div><div class=\"def\">▼<b>～の</b> vulgaris.</div>\r\n","<div class=\"hw jl\">大西洋</div><div class=\"def\">Atlanticus oceanus.</div>\r\n","<div class=\"hw jl\">大豆</div><div class=\"def\">soia.</div>\r\n","<div class=\"hw jl\">大部分</div><div class=\"def\">⇒<a href=\"entry://大半\">大半</a>,<a href=\"entry://部分\">部分</a>,<a href=\"entry://過半数\">過半数</a>.</div>\r\n","<div class=\"hw jl\">大陸</div><div class=\"def\">(terra)continens, terrae continuatio.</div><div class=\"def\">▼<b>～の</b> continens, in continenti positus.</div>\r\n","<div class=\"hw jl\">大食い</div><div class=\"def\">edax.</div><div class=\"def\">▼<b>～の</b> edax, gulosus, vorax.</div>\r\n","<div class=\"hw jl\">天</div><div class=\"def\">caelum, aether.</div><div class=\"def\">▼<b>～の</b>(=天上の)caelestis, aetherius.</div><div class=\"ex2\">私は～にも昇る気持だ<span class=\"ext\">in caelo sum.</span></div>\r\n","<div class=\"hw jl\">天上</div><div class=\"def\">▼<b>～の</b> caelestis.</div>\r\n","<div class=\"hw jl\">天井</div><div class=\"def\">tectum;(アーチ形の)camera.</div>\r\n","<div class=\"hw jl\">天使</div><div class=\"def\">angelus.</div>\r\n","<div class=\"hw jl\">天国</div><div class=\"def\">paradisus.</div>\r\n","<div class=\"hw jl\">天才</div><div class=\"def\">ingenium.</div>\r\n","<div class=\"hw jl\">天文学</div><div class=\"def\">astrologia, astronomia.</div><div class=\"def\">▼<b>～の</b> astronomicus.</div>\r\n","<div class=\"hw jl\">天気</div><div class=\"def\">caeli status, caelum, tempestas;(良い)(=晴天)bona tempestas, (caeli)serenitas, sudum, serenum.</div><div class=\"def\">▼<b>～予報</b> nuntius meteorologicus.</div><div class=\"def\">⇒<a href=\"entry://曇る\">曇る</a>.</div>\r\n","<div class=\"hw jl\">天災</div><div class=\"def\">⇒<a href=\"entry://災難\">災難</a>.</div>\r\n","<div class=\"hw jl\">天然</div><div class=\"def\">▼<b>～の</b> naturalis, nativus.</div>\r\n","<div class=\"hw jl\">天皇</div><div class=\"def\">imperator.</div>\r\n","<div class=\"hw jl\">太い</div><div class=\"def\">crassus;(=太った)corpulentus, plenus, pinguis.</div><div class=\"def\">▼<b>太さ</b> crassitudo.</div><div class=\"def\">▼<b>太く</b> crasse.</div><div class=\"def\">⇒<a href=\"entry://太る\">太る</a>,<a href=\"entry://大きい\">大きい</a>.</div>\r\n","<div class=\"hw jl\">太る</div><div class=\"def\">crassesco, pinguesco.</div><div class=\"def\">▼<b>太った</b> crassus, pinguis.</div><div class=\"def\">⇒<a href=\"entry://太い\">太い</a>.</div>\r\n","<div class=\"hw jl\">太平洋</div><div class=\"def\">Pacificus oceanus.</div>\r\n","<div class=\"hw jl\">太陽</div><div class=\"def\">sol.</div><div class=\"def\">▼<b>～の</b> solaris.</div>\r\n","<div class=\"hw jl\">夫</div><div class=\"def\">maritus, vir.</div><div class=\"def\">▼<b>～の</b> maritalis.</div><div class=\"def\">⇒<a href=\"entry://妻\">妻</a>.</div>\r\n","<div class=\"hw jl\">夫人</div><div class=\"def\">uxor, conjux.</div>\r\n","<div class=\"hw jl\">夫婦</div><div class=\"def\">mariti(<i>pl</i>);(関係)conjugium.</div>\r\n","<div class=\"hw jl\">失う</div><div class=\"def\">perdo, amitto.</div><div class=\"def\">▼<b>～こと</b> amissio.</div><div class=\"def\">⇒<a href=\"entry://損害\">損害</a>,<a href=\"entry://損失\">損失</a>.</div>\r\n","<div class=\"hw jl\">失敗</div><div class=\"def\">offensio.</div><div class=\"def\">▼(...で)<b> ～する</b> 〈in re〉 offendo;(事業などで)〈alqd〉 male gero.</div>\r\n","<div class=\"hw jl\">失明</div><div class=\"def\">▼<b>～した</b> luminibus orbatus.</div><div class=\"def\">⇒<a href=\"entry://盲目\">盲目</a>.</div>\r\n","<div class=\"hw jl\">失業</div><div class=\"def\">occupationis carentia, invita operis vacatio, coacta desidia.</div><div class=\"def\">▼<b>～者</b> occupatione carentes(<i>pl</i>).</div><div class=\"def\">▼<b>～中の</b> invite otiosus, invite opere destitutus.</div>\r\n","<div class=\"hw jl\">失神</div><div class=\"def\">▼<b>～する</b> intermorior(<i>dep</i>), animo linquor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">奇妙</div><div class=\"def\">▼<b>～な</b>(=珍奇な, 特異な, 異常な)inusitatus, insolitus, insolens, novus, singularis, mirus, mirabilis.</div>\r\n","<div class=\"hw jl\">奇跡</div><div class=\"def\">miraculum, prodigium, portentum.</div><div class=\"def\">▼<b>～的な</b> portentosus.</div><div class=\"def\">▼<b>～的に</b> miraculose, prodigialiter.</div><div class=\"def\">⇒<a href=\"entry://不思議\">不思議</a>.</div>\r\n","<div class=\"hw jl\">奉仕</div><div class=\"def\">▼(召使いとして...に)<b> ～する</b>(=仕える)ministro, ministeria facio;(...に)(=献身的に尽くす)〈alci〉 inservio, deservio, operam praebeo, 〈alqm〉 ministro.</div>\r\n","<div class=\"hw jl\">契約</div><div class=\"def\">pactio, pactum, conventio, conventus, foedus.</div><div class=\"def\">▼<b>～する</b> paciscor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">奥</div><div class=\"def\">penetrale.</div><div class=\"def\">▼<b>～の</b> penetralis, interior.</div><div class=\"def\">▼<b>～にある場所</b> interior pars.</div><div class=\"def\">▼<b>最も～の</b> intimus.</div>\r\n","<div class=\"hw jl\">奨学金</div><div class=\"def\">annua pensio studiorum causā.</div>\r\n","<div class=\"hw jl\">奪う</div><div class=\"def\">privo;(=奪い取る)adimo, aufero;(大切なものを)orbo;(力ずくで)extorqueo;(=取り上げる)tollo;(=強奪する)rapio, eripio, diripio.</div>\r\n","<div class=\"hw jl\">奮起</div><div class=\"def\">▼<b>～する</b> expergiscor(<i>dep</i>).</div><div class=\"def\">▼<b>～させる</b> expergefacio.</div>\r\n","<div class=\"hw jl\">女</div><div class=\"def\">femina, mulier.</div><div class=\"def\">▼<b>～の</b> femineus, muliebris.</div><div class=\"def\">▼<b>～らしく</b> muliebriter.</div>\r\n","<div class=\"hw jl\">女性</div><div class=\"def\">mulier, femina;(既婚の)matrona.</div><div class=\"def\">▼<b>～の</b> muliebris, femineus.</div>\r\n","<div class=\"hw jl\">女王</div><div class=\"def\">regina.</div>\r\n","<div class=\"hw jl\">好き</div><div class=\"def\">▼<b>～である</b>(=好む)amo, diligo.</div><div class=\"ex2\">私は何もしないのが～だ<span class=\"ext\">me nihil agere delectat.</span></div>\r\n","<div class=\"hw jl\">好ましい</div><div class=\"def\"><span class=\"pos3\">[形]</span>(=好都合な)opportunus, gratus;(=望ましい)optabilis, optandus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(=気に入る, 好まれる)placet(<i>impers</i>).</div><div class=\"ex2\">(...する方が...するより)～(=優れている, よい)と思われた<span class=\"ext\">praestare visum est 〈+<i>inf</i>〉 quam 〈+<i>inf</i>〉.</span></div>\r\n","<div class=\"hw jl\">好み</div><div class=\"def\">(=心の傾向)animi inclinatio.</div><div class=\"ex2\">(人によって)～が違う<span class=\"ext\">varia sunt judicia.</span></div>\r\n","<div class=\"hw jl\">好む</div><div class=\"def\">amo;(むしろ...を)praefero, malo.</div>\r\n","<div class=\"hw jl\">好奇心</div><div class=\"def\">curiositas, exspectatio, videndi [cognoscendi, discendi] cupiditas [studium].</div><div class=\"def\">▼<b>～のある</b> curiosus.</div><div class=\"ex2\">～に満ちた<span class=\"ext\">plenus exspectatione.</span></div>\r\n","<div class=\"hw jl\">好意</div><div class=\"def\">benevolentia, voluntas, benignitas.</div><div class=\"def\">▼<b>～的な</b> benevolus, benevolens, benignus.</div><div class=\"def\">▼(人に)<b> ～を抱く</b> 〈alci〉 faveo.</div>\r\n","<div class=\"hw jl\">好機</div><div class=\"def\">(bona [opportuna, commoda])occasio, tempus.</div><div class=\"def\">⇒<a href=\"entry://時機\">時機</a>.</div>\r\n","<div class=\"hw jl\">好色</div><div class=\"def\">▼<b>～の</b> libidinosus.</div>\r\n","<div class=\"hw jl\">好評</div><div class=\"def\">▼(...に)<b> ～である</b>(=喜ばれる)〈+<i>dat</i>〉 placeo.</div>\r\n","<div class=\"hw jl\">好調</div><div class=\"def\">▼<b>～である</b> bene se habere(← habeo).</div>\r\n","<div class=\"hw jl\">好転</div><div class=\"def\">▼<b>～する</b> melior fieri(← fio), melius ire(← eo).</div>\r\n","<div class=\"hw jl\">好都合</div><div class=\"def\">opportunitas.</div><div class=\"def\">▼<b>～な</b> opportunus, commodus.</div><div class=\"def\">▼<b>～に</b> opportune, commode.</div><div class=\"def\">⇒<a href=\"entry://不都合\">不都合</a>,<a href=\"entry://都合\">都合</a>.</div>\r\n","<div class=\"hw jl\">妄想</div><div class=\"def\">error, vana opinio [imago], falsae rerum imagines(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://空想\">空想</a>,<a href=\"entry://錯覚\">錯覚</a>.</div>\r\n","<div class=\"hw jl\">妊娠</div><div class=\"def\">praegnatio, gravedo.</div><div class=\"def\">▼<b>～している</b> praegnans, gravidus, gravis, fetus.</div><div class=\"def\">▼<b>～させる</b> gravido.</div>\r\n","<div class=\"hw jl\">妥当</div><div class=\"def\">⇒<a href=\"entry://適当\">適当</a>.</div>\r\n","<div class=\"hw jl\">妨げ</div><div class=\"def\">impedimentum.</div><div class=\"def\">⇒<a href=\"entry://妨害\">妨害</a>,<a href=\"entry://邪魔\">邪魔</a>.</div>\r\n","<div class=\"hw jl\">妨げる</div><div class=\"def\">impedio, prohibeo.</div>\r\n","<div class=\"hw jl\">妨害</div><div class=\"def\">obstantia, obstaculum, impedimentum, impeditio, prohibitio.</div><div class=\"def\">▼<b>～する</b> obsto, obsisto, prohibeo, impedimentum infero, impedio, officio, moror(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">妬ける</div><div class=\"def\">⇒<a href=\"entry://妬む\">妬む</a>.</div>\r\n","<div class=\"hw jl\">妬む</div><div class=\"def\"><span class=\"pos3\">[動]</span>(...を)〈+<i>dat</i>〉 invideo, aemulor(<i>dep</i>).</div><div class=\"def\">━<span class=\"pos3\">[形]</span> invidus, invidiosus.</div><div class=\"def\">▼<b>妬ましい</b> invidendus.</div><div class=\"def\">▼<b>妬まれる</b> invidiam habeo, in invidia sum.</div><div class=\"def\">⇒<a href=\"entry://嫉妬\">嫉妬</a>.</div>\r\n","<div class=\"hw jl\">妹</div><div class=\"def\">(adulescentior)soror;(同じ父母から生まれた)germana soror.</div><div class=\"def\">⇒<a href=\"entry://姉\">姉</a>,<a href=\"entry://姉妹\">姉妹</a>.</div>\r\n","<div class=\"hw jl\">妻</div><div class=\"def\">uxor, conjunx(<i>f</i>), marita.</div><div class=\"def\">▼<b>～の</b> uxorius.</div><div class=\"def\">⇒<a href=\"entry://夫\">夫</a>.</div>\r\n","<div class=\"hw jl\">姉</div><div class=\"def\">(senior)soror.</div><div class=\"def\">⇒<a href=\"entry://妹\">妹</a>,<a href=\"entry://姉妹\">姉妹</a>.</div>\r\n","<div class=\"hw jl\">姉妹</div><div class=\"def\">soror(<i>sg</i>), sorores(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://姉\">姉</a>,<a href=\"entry://妹\">妹</a>,<a href=\"entry://義理\">義理</a>.</div>\r\n","<div class=\"hw jl\">始まり</div><div class=\"def\">⇒<a href=\"entry://始め\">始め</a>.</div>\r\n","<div class=\"hw jl\">始まる</div><div class=\"def\">incipio, orior(<i>dep</i>), initium capio.</div>\r\n","<div class=\"hw jl\">始め</div><div class=\"def\">(=始まり)initium, principium, exordium, origo, inceptum.</div>\r\n","<div class=\"hw jl\">始める</div><div class=\"def\">coepi(<i>pf</i>), committo, incipio, occipio, ordior(<i>dep</i>), ingredior(<i>dep</i>), incoho;(...から)initium capio 〈a [ex] re〉.</div>\r\n","<div class=\"hw jl\">姓</div><div class=\"def\">nomen gentile [gentilicium, paternum].</div><div class=\"def\">⇒<a href=\"entry://氏名\">氏名</a>.</div>\r\n","<div class=\"hw jl\">委ねる</div><div class=\"def\">(権限などを)offero, do.</div><div class=\"ex2\">ローマ国民はクラッススに戦争の遂行を～<span class=\"ext\">populus Romanus Crasso bellum gerendum dat.</span></div>\r\n","<div class=\"hw jl\">委任</div><div class=\"def\">mandatum.</div><div class=\"def\">▼(人に)<b> ～する</b> 〈alci〉 mando.</div>\r\n","<div class=\"hw jl\">委員</div><div class=\"def\">curator, procurator, legatus.</div><div class=\"def\">▼<b>～会</b> collegium, delecti quibus aliquid agendum, curandum, procurandum committitur, consilium virorum alicui rei faciendae.</div>\r\n","<div class=\"hw jl\">姦夫・姦婦</div><div class=\"def\">moechus(<i>m</i>), adulter(<i>m</i>), moecha(<i>f</i>), adultera(<i>f</i>).</div>\r\n","<div class=\"hw jl\">姦通</div><div class=\"def\">(=不義密通)adulterium.</div><div class=\"def\">▼<b>～の</b> adulter, adulterinus.</div><div class=\"def\">▼<b>～する</b> adultero, adulterium committo.</div><div class=\"def\">⇒<a href=\"entry://姦夫・姦婦\">姦夫</a>.</div>\r\n","<div class=\"hw jl\">姪</div><div class=\"def\">neptis;(=兄弟の娘)fratris filia;(=姉妹の娘)sororis filia.</div>\r\n","<div class=\"hw jl\">姻戚</div><div class=\"def\">▼<b>～(関係)</b> affinitas.</div><div class=\"def\">▼<b>～の</b> affinis.</div>\r\n","<div class=\"hw jl\">姿</div><div class=\"def\">imago.</div>\r\n","<div class=\"hw jl\">姿勢</div><div class=\"def\">status, statio.</div>\r\n","<div class=\"hw jl\">威力</div><div class=\"def\">vires(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">威厳</div><div class=\"def\">dignitas, majestas, gravitas, auctoritas, magnificentia.</div>\r\n","<div class=\"hw jl\">娘</div><div class=\"def\">(⇔息子)filia;(=未婚の女)puella.</div><div class=\"def\">⇒<a href=\"entry://少女\">少女</a>,<a href=\"entry://処女\">処女</a>.</div>\r\n","<div class=\"hw jl\">娯楽</div><div class=\"def\">oblectamentum, delectamentum, delectatio.</div>\r\n","<div class=\"hw jl\">婚礼</div><div class=\"def\">nuptiae(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> nuptialis.</div><div class=\"ex2\">～を行なう<span class=\"ext\">nuptias facio.</span></div><div class=\"ex2\">～の晩餐<span class=\"ext\">nuptialis cena.</span></div><div class=\"def\">⇒<a href=\"entry://結婚\">結婚</a>.</div>\r\n","<div class=\"hw jl\">婚約</div><div class=\"def\">pactio nuptialis, sponsalia(<i>pl</i>).</div><div class=\"def\">▼<b>～者</b> sponsus(<i>m</i>), sponsa(<i>f</i>).</div><div class=\"def\">▼<b>～式</b> sponsalia.</div><div class=\"def\">▼<b>～の</b> sponsalis.</div><div class=\"def\">▼<b>～させる</b> despondeo.</div><div class=\"def\">▼(...と)<b>～する</b> 〈alci〉 se despondere(← despondeo).</div>\r\n","<div class=\"hw jl\">媚びる</div><div class=\"def\">adulor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://へつらう\">へつらう</a>.</div>\r\n","<div class=\"hw jl\">媚薬</div><div class=\"def\">amatorium(medicamentum), philtrum.</div>\r\n","<div class=\"hw jl\">嫁</div><div class=\"def\">(=息子の配偶者)nurus;(=妻)uxor, conjunx.</div><div class=\"def\">▼<b>花～</b> nova nupta.</div><div class=\"ex2\">彼はその男に自分の娘を～にやる<span class=\"ext\">ei filiam suam in matrimoniam dat.</span></div>\r\n","<div class=\"hw jl\">嫉妬</div><div class=\"def\">invidentia, invidia.</div><div class=\"def\">▼<b>～深い</b> invidiosus, invidus.</div><div class=\"def\">▼<b>～する</b> invideo.</div>\r\n","<div class=\"hw jl\">嫌</div><div class=\"def\">▼<b>～な</b>(=嫌いな)molestus, odiosus.</div><div class=\"def\">▼<b>～な気持ちで</b> moleste.</div><div class=\"def\">▼<b>～になる</b> taedet(<i>impers</i>).</div><div class=\"def\">▼<b>嫌がらせる</b> piget(<i>impers</i>).</div><div class=\"ex2\">お～でなければ<span class=\"ext\">si tibi non est molestum / nisi molestum est / nisi taedet.</span></div><div class=\"def\">⇒<a href=\"entry://不快\">不快</a>.</div>\r\n","<div class=\"hw jl\">嫌々</div><div class=\"def\">▼<b>～の</b> invitus.</div><div class=\"def\">▼<b>～ながら</b>(=しぶしぶ)invite, pigre.</div>\r\n","<div class=\"hw jl\">嫌う</div><div class=\"def\">(=...が嫌いだ)(...を)〈+<i>acc</i>〉 odi, 〈alcis rei;in alqm〉 odium habeo.</div><div class=\"ex2\">(人に)嫌われている<span class=\"ext\">〈alci〉 odio sum.</span></div><div class=\"ex2\">(人に)大変嫌われている<span class=\"ext\">magno in odio 〈apud alqm〉 sum.</span></div><div class=\"ex2\">(人に)嫌われた<span class=\"ext\">〈alci〉 invisus / 〈apud alqm〉 invidiosus.</span></div><div class=\"def\">⇒<a href=\"entry://嫌悪\">嫌悪</a>,<a href=\"entry://反感\">反感</a>.</div>\r\n","<div class=\"hw jl\">嫌がる</div><div class=\"def\">(=嫌う)(...を)〈+<i>acc</i>〉 odi, 〈+<i>gen</i>;in+<i>acc</i>〉 odium habeo.</div><div class=\"def\">⇒<a href=\"entry://嫌う\">嫌う</a>.</div>\r\n","<div class=\"hw jl\">嫌み</div><div class=\"def\">cavillatio.</div><div class=\"def\">⇒<a href=\"entry://皮肉\">皮肉</a>.</div>\r\n","<div class=\"hw jl\">嫌悪</div><div class=\"def\">fastidium, taedium, aversatio.</div><div class=\"def\">▼<b>～を示す</b> fastidio, aversor(<i>dep</i>).</div><div class=\"def\">▼<b>～を覚えている</b> taedet(<i>impers</i>).</div><div class=\"def\">⇒<a href=\"entry://反感\">反感</a>,<a href=\"entry://嫌う\">嫌う</a>.</div>\r\n","<div class=\"hw jl\">嫌気</div><div class=\"def\">(...に対する)〈+<i>gen</i>〉 taedium, fastidium, odium.</div><div class=\"ex2\">私は人生に～がする<span class=\"ext\">me taedet vitae.</span></div>\r\n","<div class=\"hw jl\">嫌疑</div><div class=\"def\">suspicio.</div><div class=\"def\">⇒<a href=\"entry://疑う\">疑う</a>.</div>\r\n","<div class=\"hw jl\">子</div><div class=\"def\">(=息子・娘)filius(<i>m</i>), filia(<i>f</i>);(=...から生まれた者)natus(<i>m</i>), nata(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://子供\">子供</a>.</div>\r\n","<div class=\"hw jl\">子供</div><div class=\"def\">(7歳までの)infans, puer infans;(7‐17歳の)puer(<i>m</i>), puella(<i>f</i>).</div><div class=\"def\">▼<b>～たち</b> liberi(<i>pl</i>).</div><div class=\"def\">▼<b>～の頃</b> pueritia.</div><div class=\"def\">▼<b>～の, ～らしい, ～じみた</b> puerilis.</div><div class=\"def\">⇒<a href=\"entry://息子\">息子</a>,<a href=\"entry://娘\">娘</a>,<a href=\"entry://赤ん坊\">赤ん坊</a>,<a href=\"entry://少年\">少年</a>,<a href=\"entry://少女\">少女</a>.</div>\r\n","<div class=\"hw jl\">子孫</div><div class=\"def\">posteritas, posteri(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://先祖\">先祖</a>.</div>\r\n","<div class=\"hw jl\">子音</div><div class=\"def\">consonans, consona.</div>\r\n","<div class=\"hw jl\">字</div><div class=\"def\">⇒<a href=\"entry://文字\">文字</a>,<a href=\"entry://アルファベット\">アルファベット</a>.</div>\r\n","<div class=\"hw jl\">存在</div><div class=\"def\">exsistentia.</div><div class=\"def\">▼<b>～する</b> sum, exsisto.</div><div class=\"ex2\">彼らは魂の～を否定した<span class=\"ext\">nullum animum esse dixerunt.</span></div>\r\n","<div class=\"hw jl\">季節</div><div class=\"def\">anni tempus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">春 ver, 夏 aestas, 秋 autumnus, 冬 hiems.</div><div class=\"def\">⇒<a href=\"entry://春\">春</a>,<a href=\"entry://夏\">夏</a>,<a href=\"entry://秋\">秋</a>,<a href=\"entry://冬\">冬</a>.</div>\r\n","<div class=\"hw jl\">孤児</div><div class=\"def\">orbus(<i>m</i>), orba(<i>f</i>).</div><div class=\"def\">▼<b>～の境遇</b> orbitas.</div><div class=\"def\">▼<b>～の</b> orbus.</div>\r\n","<div class=\"hw jl\">孤独</div><div class=\"def\">solitudo.</div><div class=\"def\">▼<b>～な</b> solus, solitarius.</div><div class=\"ex2\">～に暮らす<span class=\"ext\">in secreto tempus tero.</span></div>\r\n","<div class=\"hw jl\">孤立</div><div class=\"def\">solitudo, secessio.</div><div class=\"def\">▼<b>～した</b> solitarius.</div><div class=\"def\">▼<b>～させる</b> secludo.</div>\r\n","<div class=\"hw jl\">学ぶ</div><div class=\"def\">disco;(さらに)(=学び加える)addisco;(徹底的に)perdisco;(あらかじめ)praedisco.</div><div class=\"def\">⇒<a href=\"entry://研究\">研究</a>,<a href=\"entry://勉強\">勉強</a>.</div>\r\n","<div class=\"hw jl\">学問</div><div class=\"def\">(=知識の体系)doctrina, scientia, disciplina.</div><div class=\"def\">⇒<a href=\"entry://勉強\">勉強</a>.</div>\r\n","<div class=\"hw jl\">学期</div><div class=\"def\">(6か月からなる)semestre(spatium);(3か月からなる)trimestre(spatium).</div>\r\n","<div class=\"hw jl\">学校</div><div class=\"def\">schola, ludus.</div><div class=\"def\">▼<b>～の</b> scholaris.</div><div class=\"def\">▼<b>～風に</b> scholastice.</div><div class=\"ex2\">私立の～<span class=\"ext\">schola privata.</span></div><div class=\"ex2\">公立の～<span class=\"ext\">schola publica.</span></div><div class=\"ex2\">市立の～<span class=\"ext\">schola municipalis.</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">小学校<span class=\"ext\">ludus litterarum.</span></div>\r\n","<div class=\"hw jl\">学生</div><div class=\"def\">scholaris, scholasticus;(文学の;法学の;医学の)studiosi(artium;juris;medicinae).</div><div class=\"def\">⇒<a href=\"entry://生徒\">生徒</a>.</div>\r\n","<div class=\"hw jl\">学習</div><div class=\"def\">▼<b>～する</b> disco.</div>\r\n","<div class=\"hw jl\">学識</div><div class=\"def\">doctrina, eruditio, scientia.</div><div class=\"def\">▼<b>～のある</b> doctus, eruditus.</div><div class=\"def\">⇒<a href=\"entry://知識\">知識</a>.</div>\r\n","<div class=\"hw jl\">孫</div><div class=\"def\">nepos(<i>m</i>), neptis(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://ひ孫\">ひ孫</a>.</div>\r\n","<div class=\"hw jl\">孵る</div><div class=\"def\">ex ovo orior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://孵化\">孵化</a>.</div>\r\n","<div class=\"hw jl\">孵化</div><div class=\"def\">▼<b>～する</b> excludo, edo.</div><div class=\"def\">⇒<a href=\"entry://孵る\">孵る</a>.</div>\r\n","<div class=\"hw jl\">宇宙</div><div class=\"def\">universitas, cosmos.</div><div class=\"def\">▼<b>～の</b> spatialis, cosmicus.</div><div class=\"def\">▼<b>～ステーション</b> statio spatialis.</div><div class=\"def\">▼<b>～空間</b> spatium cosmicum.</div><div class=\"def\">▼<b>～飛行士</b> astronauta.</div>\r\n","<div class=\"hw jl\">守る</div><div class=\"def\">defendo, tueor(<i>dep</i>), tego, tutor(<i>dep</i>);(=遵守する)observo.</div>\r\n","<div class=\"hw jl\">安い</div><div class=\"def\">(=安価な)vilis.</div><div class=\"def\">▼<b>～値段で</b> pretio parvo [exiguo].</div><div class=\"def\">▼<b>できるだけ～値段で</b> quam minimo pretio.</div><div class=\"def\">▼<b>安く買う</b> bene [parvo] emo.</div><div class=\"def\">⇒<a href=\"entry://高い\">高い</a>.</div>\r\n","<div class=\"hw jl\">安全</div><div class=\"def\">salus, tutum, securitas.</div><div class=\"def\">▼<b>～な</b> tutus, securus.</div><div class=\"def\">▼<b>～にする</b>(=保護する)tutor(<i>dep</i>), tutum reddo 〈alqd ab+<i>abl</i>〉.</div><div class=\"def\">▼<b>～に</b> tuto, sine periculo, bono periculo.</div><div class=\"def\">▼<b>～ベルト</b> ⇒ <a href=\"entry://シートベルト\">シートベルト</a>.</div><div class=\"def\">⇒<a href=\"entry://守る\">守る</a>.</div>\r\n","<div class=\"hw jl\">安定</div><div class=\"def\">stabilitas, firmitas.</div><div class=\"def\">▼<b>～した</b> stabilis, firmus.</div>\r\n","<div class=\"hw jl\">安心</div><div class=\"def\">(=心の平静)tranquillum, tranquillitas, securitas.</div><div class=\"def\">▼<b>～な</b>(=恐怖から解放された)metu solutus, tranquillus, securus.</div><div class=\"def\">▼<b>～して</b> sine metu, secure, in pace.</div>\r\n","<div class=\"hw jl\">安楽死</div><div class=\"def\">euthanasia.</div>\r\n","<div class=\"hw jl\">安物</div><div class=\"def\">merx vilis.</div>\r\n","<div class=\"hw jl\">完了</div><div class=\"def\">perfectio.</div><div class=\"def\">▼<b>～の, ～した</b> perfectus.</div><div class=\"def\">▼<b>～する</b>(=成就する, 終える)perficio, conficio, finem facio.</div>\r\n","<div class=\"hw jl\">完全</div><div class=\"def\">perfectio.</div><div class=\"def\">▼<b>～な</b> perfectus.</div><div class=\"def\">▼<b>～に</b> perfecte, omnino, ex toto.</div><div class=\"def\">⇒<a href=\"entry://全く\">全く</a>.</div>\r\n","<div class=\"hw jl\">完成</div><div class=\"def\">perfectio, effectus.</div><div class=\"def\">▼<b>～する</b> perficio, efficio.</div><div class=\"def\">▼<b>～した</b> perfectus.</div>\r\n","<div class=\"hw jl\">完璧</div><div class=\"def\">▼<b>～な</b> perfectus.</div>\r\n","<div class=\"hw jl\">宗教</div><div class=\"def\">religio, deorum [dei] cultus.</div><div class=\"def\">▼<b>～上の儀式</b> sacra(<i>pl</i>), res divinae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">官庁</div><div class=\"def\">publica sedes.</div><div class=\"def\">⇒<a href=\"entry://役所\">役所</a>,<a href=\"entry://省\">省</a>.</div>\r\n","<div class=\"hw jl\">官職</div><div class=\"def\">magistratus.</div>\r\n","<div class=\"hw jl\">定める</div><div class=\"def\">statuo, constituo, metior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://決定\">決定</a>,<a href=\"entry://定義\">定義</a>.</div>\r\n","<div class=\"hw jl\">定期</div><div class=\"def\">▼<b>～的な</b> status, certo tempore recurrens.</div>\r\n","<div class=\"hw jl\">定義</div><div class=\"def\">definitio.</div><div class=\"def\">▼<b>～する</b> definio.</div><div class=\"def\">▼(はっきりと)<b>～された</b> definitus.</div>\r\n","<div class=\"hw jl\">定規</div><div class=\"def\">regula.</div>\r\n","<div class=\"hw jl\">宝</div><div class=\"def\">(=宝物)thesaurus.</div>\r\n","<div class=\"hw jl\">宝庫</div><div class=\"def\">thesaurus, gaza.</div><div class=\"def\">⇒<a href=\"entry://金庫\">金庫</a>.</div>\r\n","<div class=\"hw jl\">宝石</div><div class=\"def\">gemma.</div>\r\n","<div class=\"hw jl\">実</div><div class=\"def\">(=果実)fructus.</div><div class=\"def\">▼<b>～をならせる</b> fructuarius.</div>\r\n","<div class=\"hw jl\">実に</div><div class=\"def\">vere.</div><div class=\"def\">⇒<a href=\"entry://本当\">本当</a>,<a href=\"entry://非常に\">非常に</a>.</div>\r\n","<div class=\"hw jl\">実在</div><div class=\"def\">▼<b>～する</b> sum, existo.</div><div class=\"def\">▼<b>～しない</b> nullus sum, non substantiam habeo.</div><div class=\"ex2\">神が～すると信じる<span class=\"ext\">credo Deum esse.</span></div>\r\n","<div class=\"hw jl\">実業</div><div class=\"def\">negotium.</div><div class=\"def\">⇒<a href=\"entry://企業\">企業</a>.</div>\r\n","<div class=\"hw jl\">実現</div><div class=\"def\">effectus.</div><div class=\"def\">▼<b>～する</b> efficio, perficio.</div>\r\n","<div class=\"hw jl\">実用的</div><div class=\"def\">▼<b>～な</b> ad usum aptus.</div><div class=\"def\">⇒<a href=\"entry://有益\">有益</a>.</div>\r\n","<div class=\"hw jl\">実行</div><div class=\"def\">effectus, effectio.</div><div class=\"def\">▼<b>～する</b> conficio, exsequor(<i>dep</i>), ago, gero, edo, perpetro.</div><div class=\"def\">⇒<a href=\"entry://行なう\">行なう</a>.</div>\r\n","<div class=\"hw jl\">実際</div><div class=\"def\">▼<b>～に</b>(in)re vera, re ipsa, reapse, re.</div><div class=\"ex2\">これらの神々は～には存在しないと言われている<span class=\"ext\">hos deos non re esse dicunt.</span></div>\r\n","<div class=\"hw jl\">実験</div><div class=\"def\">experimentum.</div><div class=\"def\">▼<b>～する</b> experimenta ago, experior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">客</div><div class=\"def\">hospes, is qui in hospitio est;(=訪問客)salutator(<i>m</i>), salutatrix(<i>f</i>), salutantes(<i>pl</i>);(=会食客)conviva(<i>m</i>, <i>f</i>);(=乗客)vector;(=観客)spectator;(=買物客)emptor.</div>\r\n","<div class=\"hw jl\">客観的</div><div class=\"def\">▼<b>～な</b> in natura situs [positus], objectivus.</div>\r\n","<div class=\"hw jl\">宣伝</div><div class=\"def\">praeconium, pervulgatio commendaticia, nuntii laudativi, divulgatio, rerum propositio.</div><div class=\"def\">▼<b>～する</b> evulgo, in hominum notitiam perfero.</div>\r\n","<div class=\"hw jl\">宣告</div><div class=\"def\">nuntiatio.</div>\r\n","<div class=\"hw jl\">宣戦布告</div><div class=\"def\">▼<b>～する</b> bellum indico.</div>\r\n","<div class=\"hw jl\">宣言</div><div class=\"def\">declaratio, professio.</div><div class=\"def\">▼<b>～する</b> declaro.</div>\r\n","<div class=\"hw jl\">室内</div><div class=\"def\">interior pars aedium.</div>\r\n","<div class=\"hw jl\">宮殿</div><div class=\"def\">regia, palatium, aedes regiae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">害</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[動]</span> noceo, laedo, damno, offendo. <span class=\"pos3\">[形]</span>(=有害な)nocens, noxius, injuriosus, damnosus.</div><div class=\"def\">⇒<a href=\"entry://損害\">損害</a>.</div>\r\n","<div class=\"hw jl\">宴会</div><div class=\"def\">(=饗宴, 酒宴, 晩餐)symposium, convivium, cena, epulae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">宵</div><div class=\"def\">⇒<a href=\"entry://晩\">晩</a>,<a href=\"entry://夕方\">夕方</a>.</div>\r\n","<div class=\"hw jl\">家</div><div class=\"def\">domus, aedes, tectum;(=家族全体, 一族, 氏族)familia, gens.</div><div class=\"def\">▼<b>小さな～</b>(=小屋)casa.</div><div class=\"ex2\">～にいる<span class=\"ext\">domi sum.</span></div><div class=\"def\">⇒<a href=\"entry://アパート\">アパート</a>.</div>\r\n","<div class=\"hw jl\">家</div><div class=\"ex2\">自分の～に<span class=\"ext\">ad se.</span></div><div class=\"ex2\">自分の～で<span class=\"ext\">domi.</span></div><div class=\"ex2\">自分の～にいる<span class=\"ext\">apud se domum esse(← sum).</span></div>\r\n","<div class=\"hw jl\">家主</div><div class=\"def\">habitationis possessor [dominus].</div>\r\n","<div class=\"hw jl\">家事</div><div class=\"def\">rerum domesticarum cura, domestica negotia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">家具</div><div class=\"def\">supellex.</div>\r\n","<div class=\"hw jl\">家庭</div><div class=\"def\">domus.</div><div class=\"def\">▼<b>～の</b> domesticus.</div><div class=\"def\">⇒<a href=\"entry://家族\">家族</a>.</div>\r\n","<div class=\"hw jl\">家庭教師</div><div class=\"def\">paedagogus.</div>\r\n","<div class=\"hw jl\">家族</div><div class=\"def\">familia.</div><div class=\"def\">▼<b>～の</b> familiaris.</div><div class=\"def\">⇒<a href=\"entry://家\">家</a>.</div>\r\n","<div class=\"hw jl\">家父長</div><div class=\"def\">pater familias.</div>\r\n","<div class=\"hw jl\">家畜</div><div class=\"def\">(=山羊・羊・豚等の小家畜)(一頭の)pecus, (群れ)pecus;(=牛等の大家畜)armentum;(=役獣)jumentum.</div><div class=\"def\">▼<b>～の</b> pecuarius.</div>\r\n","<div class=\"hw jl\">家賃</div><div class=\"def\">merces(habitationis), habitatio.</div><div class=\"ex2\">～を払う<span class=\"ext\">refero mercedem.</span></div>\r\n","<div class=\"hw jl\">家電</div><div class=\"def\">(=家庭用電気製品)electrica domus utensilia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">容器</div><div class=\"def\">excipulum, excipula.</div>\r\n","<div class=\"hw jl\">容姿</div><div class=\"def\">(=顔立ちと体つき)figura, forma, species, effigies;(=顔立ち)facies, vultus.</div>\r\n","<div class=\"hw jl\">容易</div><div class=\"def\">▼<b>～な</b> facilis, proclivis, expeditus.</div><div class=\"def\">▼<b>非常に～な</b> perfacilis.</div><div class=\"def\">▼<b>～に</b> facile, sine(ullo)labore.</div>\r\n","<div class=\"hw jl\">容疑</div><div class=\"def\">suspicio.</div><div class=\"def\">▼<b>～者</b> suspectus scelere [sceleris](<i>m</i>), reus sceleris.</div><div class=\"def\">⇒<a href=\"entry://疑う\">疑う</a>,<a href=\"entry://被告\">被告</a>.</div>\r\n","<div class=\"hw jl\">容積</div><div class=\"def\">mensura, dimensio, capacitas.</div>\r\n","<div class=\"hw jl\">容貌</div><div class=\"def\">(=顔つき)vultus, vultūs habitus, frons, os, facies.</div>\r\n","<div class=\"hw jl\">容赦</div><div class=\"def\">(=免罪)venia.</div><div class=\"def\">▼<b>～する</b> veniam do, ignosco.</div><div class=\"def\">⇒<a href=\"entry://許す・赦す\">許す</a>.</div>\r\n","<div class=\"hw jl\">宿題</div><div class=\"def\">pensum scholasticum.</div>\r\n","<div class=\"hw jl\">寂しい</div><div class=\"def\"><span class=\"pos3\">[形]</span> desertus, solus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(...がいなくて)desidero 〈alqm〉.</div><div class=\"def\">▼(...がいなくて)<b>非常に～</b> 〈alcis absentiā〉 non mediocriter afficior(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://孤独\">孤独</a>.</div>\r\n","<div class=\"hw jl\">寄り道</div><div class=\"def\">▼<b>～をする</b> devertor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">寄る</div><div class=\"def\">(=近寄る)appropinquo.</div><div class=\"def\">⇒<a href=\"entry://近づく\">近づく</a>,<a href=\"entry://忍び寄る\">忍び寄る</a>,<a href=\"entry://訪れる\">訪れる</a>.</div>\r\n","<div class=\"hw jl\">寄与</div><div class=\"def\">adjumentum.</div><div class=\"def\">▼<b>～する</b> adjuvo.</div><div class=\"def\">⇒<a href=\"entry://役立つ\">役立つ</a>.</div>\r\n","<div class=\"hw jl\">寄付</div><div class=\"def\">donatio, donativum, stipendium;(小額の)stips.</div><div class=\"def\">⇒<a href=\"entry://贈物\">贈物</a>,<a href=\"entry://贈る\">贈る</a>.</div>\r\n","<div class=\"hw jl\">寄生</div><div class=\"def\">parasitatio.</div><div class=\"def\">▼<b>～者</b> parasitus(<i>m</i>), parasita(<i>f</i>).</div><div class=\"def\">▼<b>～する</b> parasitor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://居候\">居候</a>.</div>\r\n","<div class=\"hw jl\">密</div><div class=\"def\">▼<b>～な</b> densus, condensus.</div><div class=\"def\">▼<b>～にする</b>(=濃縮する, 圧縮する)denso, denseo, condenso.</div>\r\n","<div class=\"hw jl\">密かに</div><div class=\"def\">occulte, arcano.</div><div class=\"def\">⇒<a href=\"entry://こっそり\">こっそり</a>.</div>\r\n","<div class=\"hw jl\">密告</div><div class=\"def\">delatio, indicium.</div><div class=\"def\">▼<b>～者</b> delator, index.</div><div class=\"def\">▼<b>～する</b> defero, indico.</div>\r\n","<div class=\"hw jl\">密売</div><div class=\"def\">(=闇取引)mercatura clandestina [furtiva, vetita].</div>\r\n","<div class=\"hw jl\">密度</div><div class=\"def\">densitas.</div>\r\n","<div class=\"hw jl\">密接</div><div class=\"def\">▼<b>～な</b> artus, conjunctus;(=親密な)intimus, familiaris.</div><div class=\"def\">▼(お互いに)<b>～している</b> inter se juncti(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://親密\">親密</a>.</div>\r\n","<div class=\"hw jl\">富ます</div><div class=\"def\">(=豊かにする)(...を...で)〈alqm re〉 locupleto.</div>\r\n","<div class=\"hw jl\">寒い</div><div class=\"def\"><span class=\"pos3\">[形]</span> frigidus, algidus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> frigeo;(=寒いと感じる)algeo.</div><div class=\"def\">▼<b>少し～</b> frigidulus.</div><div class=\"def\">▼<b>寒さ</b> frigus.</div><div class=\"def\">⇒<a href=\"entry://冷たい\">冷たい</a>.</div>\r\n","<div class=\"hw jl\">寛大</div><div class=\"def\">indulgentia, clementia.</div><div class=\"def\">▼<b>～な</b> indulgens, clemens, liberalis.</div><div class=\"def\">▼<b>～に</b> indulgenter, clementer, liberaliter.</div>\r\n","<div class=\"hw jl\">寝かす</div><div class=\"def\">(=眠らせる)sopio, consopio, soporo.</div>\r\n","<div class=\"hw jl\">寝ころぶ</div><div class=\"def\">recumbo.</div>\r\n","<div class=\"hw jl\">寝る</div><div class=\"def\">(=臥す)recumbo, decumbo, cubo;(=眠る)dormio.</div><div class=\"def\">⇒<a href=\"entry://眠る\">眠る</a>,<a href=\"entry://寝かす\">寝かす</a>.</div>\r\n","<div class=\"hw jl\">寝具</div><div class=\"def\">lecti strata(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">寝台</div><div class=\"def\">cubile, lectus(cubicularis).</div><div class=\"def\">▼<b>～車</b> currus dormitorius.</div>\r\n","<div class=\"hw jl\">寝室</div><div class=\"def\">cubiculum, dormitorium.</div>\r\n","<div class=\"hw jl\">寝巻き</div><div class=\"def\">cubitoria [cubicularia] vestis.</div>\r\n","<div class=\"hw jl\">寝床</div><div class=\"def\">(=寝台)lectus, lectulus.</div>\r\n","<div class=\"hw jl\">審査</div><div class=\"def\">recognitio.</div><div class=\"def\">▼<b>～する</b> recognosco.</div>\r\n","<div class=\"hw jl\">審美眼</div><div class=\"def\">(=良い趣味)sapor;(=判断力)sensus.</div>\r\n","<div class=\"hw jl\">審議</div><div class=\"def\">deliberatio, consilium.</div><div class=\"def\">▼<b>～する</b> delibero, consulo, consulto, consilior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://協議\">協議</a>,<a href=\"entry://討議\">討議</a>,<a href=\"entry://調査\">調査</a>,<a href=\"entry://吟味\">吟味</a>.</div>\r\n","<div class=\"hw jl\">寸法</div><div class=\"def\">mensura, modus, modulus.</div><div class=\"ex2\">自分の体の～に合わせて<span class=\"ext\">ad modum sui corporis.</span></div><div class=\"def\">⇒<a href=\"entry://大きい\">大きい</a>,<a href=\"entry://身長\">身長</a>.</div>\r\n","<div class=\"hw jl\">対して</div><div class=\"def\">(...に)contra 〈+<i>acc</i>〉, adversus 〈+<i>acc</i>〉, adversum 〈+<i>acc</i>〉.</div><div class=\"ex2\">ガリアに～<span class=\"ext\">adversus Galliam.</span></div><div class=\"ex2\">イタリアに～<span class=\"ext\">contra Italiam.</span></div><div class=\"def\">▼<b>それに～</b> contra.</div>\r\n","<div class=\"hw jl\">対する</div><div class=\"def\">(...に)contra 〈+<i>acc</i>〉, adversus 〈+<i>acc</i>〉, adversum 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">対応</div><div class=\"def\">▼<b>～する</b>(=相対する)respondeo.</div><div class=\"ex2\">ギリシア語の単語に～し同じ意味をもつラテン語の単語<span class=\"ext\">verbum Latinum par Graeco et quod idem valeat.</span></div>\r\n","<div class=\"hw jl\">対抗</div><div class=\"def\">(=対抗意識)rivalitas, aemulatio.</div><div class=\"def\">▼<b>～者</b> adversarius.</div><div class=\"def\">▼<b>～する</b> adversor(<i>dep</i>).</div><div class=\"def\">▼(...に)<b> ～して</b> contra 〈+<i>acc</i>〉.</div><div class=\"ex2\">イタリアに～して<span class=\"ext\">contra Italiam.</span></div><div class=\"def\">⇒<a href=\"entry://競争\">競争</a>,<a href=\"entry://抵抗\">抵抗</a>.</div>\r\n","<div class=\"hw jl\">対照</div><div class=\"def\">contrarium.</div><div class=\"def\">▼<b>～的な</b> contrarius.</div><div class=\"ex2\">～的な色<span class=\"ext\">dispares colores(<i>pl</i>).</span></div><div class=\"ex2\">(二人の)将軍の性格は～的だった<span class=\"ext\">diversi(duobus)imperatoribus mores fuere.</span></div><div class=\"def\">⇒<a href=\"entry://コントラスト\">コントラスト</a>,<a href=\"entry://比較\">比較</a>,<a href=\"entry://差異\">差異</a>,<a href=\"entry://違う\">違う</a>.</div>\r\n","<div class=\"hw jl\">対立</div><div class=\"def\">oppositio, repugnantia.</div><div class=\"def\">▼<b>～させる</b> oppono.</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[動]</span> obsto. <span class=\"pos3\">[形]</span> adversarius.</div><div class=\"def\">▼<b>～した</b> oppositus.</div><div class=\"def\">▼<b>～者</b> adversus.</div>\r\n","<div class=\"hw jl\">対等</div><div class=\"def\">▼<b>～な</b> aequalis, aequus.</div>\r\n","<div class=\"hw jl\">対策</div><div class=\"def\">(...に対する)〈contra+<i>acc</i>〉 consilium, ratio.</div><div class=\"ex2\">～を講じる<span class=\"ext\">consilium capio, consulo, rationem ineo.</span></div><div class=\"ex2\">テロ～<span class=\"ext\">consilium contra tromocratas.</span></div><div class=\"ex2\">～協議<span class=\"ext\">consilii capiendi deliberatio.</span></div>\r\n","<div class=\"hw jl\">対話</div><div class=\"def\">dialogus, collocutio, colloquium, sermo.</div><div class=\"def\">▼<b>～する</b> colloquor(<i>dep</i>), sermonem habeo.</div>\r\n","<div class=\"hw jl\">対象</div><div class=\"def\">res.</div><div class=\"ex2\">神々を考察の～にする哲学の部分<span class=\"ext\">philosophiae pars quae ad deos spectat.</span></div><div class=\"def\">⇒<a href=\"entry://主題\">主題</a>.</div>\r\n","<div class=\"hw jl\">寿命</div><div class=\"def\">⇒<a href=\"entry://命\">命</a>,<a href=\"entry://長寿\">長寿</a>.</div>\r\n","<div class=\"hw jl\">封鎖</div><div class=\"def\">obstructio, obsidio, obsessio, obsidium.</div><div class=\"def\">▼<b>～する</b> obstruo, obsideo.</div><div class=\"def\">⇒<a href=\"entry://閉鎖\">閉鎖</a>.</div>\r\n","<div class=\"hw jl\">専攻</div><div class=\"def\">⇒<a href=\"entry://専門\">専門</a>.</div>\r\n","<div class=\"hw jl\">専門</div><div class=\"def\">(分野)artis genus, scientiae genus, specialis doctrinae provincia, singularis peritia, singulare studium.</div><div class=\"def\">▼<b>～家(の)</b> qui uni alicui generi scientiae(artis [operis])se dedit.</div>\r\n","<div class=\"hw jl\">射撃</div><div class=\"def\">ictus, jactus.</div><div class=\"def\">▼(飛び道具で)<b> ～する</b>(tormentis)verbero, jaculor(<i>dep</i>), jacio.</div><div class=\"def\">⇒<a href=\"entry://銃\">銃</a>.</div>\r\n","<div class=\"hw jl\">将来</div><div class=\"def\"><span class=\"pos3\">[名]</span> futura, futurum tempus.</div>\r\n","<div class=\"hw jl\">将棋</div><div class=\"def\">⇒<a href=\"entry://チェス\">チェス</a>.</div>\r\n","<div class=\"hw jl\">尊厳</div><div class=\"def\">dignitas.</div>\r\n","<div class=\"hw jl\">尊大</div><div class=\"def\">arrogantia.</div><div class=\"def\">▼<b>～な</b> arrogans.</div><div class=\"def\">⇒<a href=\"entry://傲慢\">傲慢</a>.</div>\r\n","<div class=\"hw jl\">尊敬</div><div class=\"def\">reverentia, verecundia, honestas, honor.</div><div class=\"def\">▼<b>～する</b> revereor(<i>dep</i>), vereor(<i>dep</i>), deveneror(<i>dep</i>), reverentiam 〈alci〉 praesto, honesto.</div><div class=\"def\">▼<b>～すべき</b> honestus, verendus, venerandus.</div>\r\n","<div class=\"hw jl\">尊重</div><div class=\"def\">▼<b>～する</b> observo, diligo.</div>\r\n","<div class=\"hw jl\">尋ねる</div><div class=\"def\">rogo, quaero, exquiro, requiro;(しきりに)rogito.</div><div class=\"def\">⇒<a href=\"entry://質問\">質問</a>,<a href=\"entry://尋問\">尋問</a>.</div>\r\n","<div class=\"hw jl\">尋問</div><div class=\"def\">interrogatio, quaesitio, percontatio.</div><div class=\"def\">▼<b>～する</b> interrogo, quaero.</div><div class=\"def\">⇒<a href=\"entry://質問\">質問</a>.</div>\r\n","<div class=\"hw jl\">導く</div><div class=\"def\">(=先導する)duco;(=指揮する, 操る)rego, moderor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://指揮\">指揮</a>.</div>\r\n","<div class=\"hw jl\">導入</div><div class=\"def\">inductio, introductio.</div><div class=\"def\">▼<b>～する</b> induco, introduco.</div>\r\n","<div class=\"hw jl\">小さい</div><div class=\"def\">parvus, paucus, exiguus, minutus;(ごく)perparvus, parvulus, perexiguus.</div><div class=\"def\">⇒<a href=\"entry://大きい\">大きい</a>.</div>\r\n","<div class=\"hw jl\">小切手</div><div class=\"def\">(=チェック)perscripta pecunia, perscriptio pecuniae, mandatum nummarium.</div>\r\n","<div class=\"hw jl\">小包み</div><div class=\"def\">fasciculus.</div>\r\n","<div class=\"hw jl\">小型</div><div class=\"def\">▼<b>～の</b> minore forma, parvus.</div><div class=\"def\">⇒<a href=\"entry://小さい\">小さい</a>.</div>\r\n","<div class=\"hw jl\">小売り</div><div class=\"def\">mercium distractio.</div><div class=\"def\">▼<b>～業者</b>(商人, 店主)distractor, caupo.</div><div class=\"def\">▼<b>～する</b> divendo, distraho.</div>\r\n","<div class=\"hw jl\">小屋</div><div class=\"def\">casa.</div><div class=\"def\">▼<b>ほったて～</b> tugurium.</div><div class=\"def\">▼<b>家畜～</b> stabulum.</div>\r\n","<div class=\"hw jl\">小川</div><div class=\"def\">rivus, amniculus, rivulus.</div><div class=\"def\">⇒<a href=\"entry://川・河\">川</a>.</div>\r\n","<div class=\"hw jl\">小手先</div><div class=\"def\">▼<b>～で</b>(=軽々と)leviter.</div>\r\n","<div class=\"hw jl\">小指</div><div class=\"def\">digitus minimus, auricularis digitus.</div><div class=\"def\">⇒<a href=\"entry://指\">指</a>.</div>\r\n","<div class=\"hw jl\">小説</div><div class=\"def\">commenticia fabula, fabulosa narratio.</div><div class=\"def\">▼<b>～家</b> commenticiarum fabularum scriptor.</div>\r\n","<div class=\"hw jl\">少し</div><div class=\"def\">paulo;(ほんの)paululo.</div><div class=\"def\">▼<b>～前に</b> paulo ante.</div><div class=\"def\">▼<b>～後に</b> paulo post.</div><div class=\"def\">▼<b>～(の間)</b> paulum, paululum.</div><div class=\"def\">▼<b>～ずつ</b> paulatim, carptim.</div><div class=\"ex2\">もう～で(...する)ところである<span class=\"ext\">haud [non] multum abest quin 〈+<i>subj</i>〉.</span></div>\r\n","<div class=\"hw jl\">少ない</div><div class=\"def\">paucus.</div><div class=\"def\">⇒<a href=\"entry://少数\">少数</a>,<a href=\"entry://まれ\">まれ</a>.</div>\r\n","<div class=\"hw jl\">少なくとも</div><div class=\"def\">quidem, certe, utique, saltem.</div>\r\n","<div class=\"hw jl\">少女</div><div class=\"def\">puella;(幼い, かわいい)puellula.</div>\r\n","<div class=\"hw jl\">少年</div><div class=\"def\">puer.</div><div class=\"def\">▼<b>～であること, ～らしさ</b> pueritia.</div><div class=\"def\">▼<b>～の</b> puerilis.</div><div class=\"def\">▼<b>～愛</b> paedicatio, paederastia, paedophilia.</div><div class=\"def\">▼<b>～愛者</b> paedico, paedicator, paederastes.</div><div class=\"def\">⇒<a href=\"entry://幼年\">幼年</a>,<a href=\"entry://子供\">子供</a>.</div>\r\n","<div class=\"hw jl\">少数</div><div class=\"def\">paucitas.</div><div class=\"def\">▼<b>～者</b> pauci(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> paucus, pauculus.</div>\r\n","<div class=\"hw jl\">尚早</div><div class=\"def\">▼<b>(時期)～の</b> praematurus, praecox.</div>\r\n","<div class=\"hw jl\">尺度</div><div class=\"def\">mensura.</div>\r\n","<div class=\"hw jl\">尻</div><div class=\"def\">clunis, natis.</div><div class=\"def\">▼<b>～の穴</b> anus.</div>\r\n","<div class=\"hw jl\">尽きる</div><div class=\"def\">exaresco, aresco.</div>\r\n","<div class=\"hw jl\">尽くす</div><div class=\"def\">servio.</div><div class=\"ex2\">あらゆる手段を～<span class=\"ext\">omnes vias persequor(<i>dep</i>).</span></div><div class=\"ex2\">全力を～<span class=\"ext\">summa ope nitor(<i>dep</i>)/ omni ope atque opera enitor(<i>dep</i>).</span></div><div class=\"def\">⇒<a href=\"entry://奉仕\">奉仕</a>,<a href=\"entry://努力\">努力</a>,<a href=\"entry://捧げる\">捧げる</a>.</div>\r\n","<div class=\"hw jl\">尽力</div><div class=\"def\">⇒<a href=\"entry://努力\">努力</a>.</div>\r\n","<div class=\"hw jl\">尾</div><div class=\"def\">(動物の)cauda;(彗星の)crinis.</div>\r\n","<div class=\"hw jl\">尾根</div><div class=\"def\">(山の)(montis)jugum.</div>\r\n","<div class=\"hw jl\">尿</div><div class=\"def\">urina, lotium.</div><div class=\"def\">▼<b>～をする</b> mejo, mingo, urinam [lotium] facio.</div><div class=\"def\">⇒<a href=\"entry://排泄物\">排泄物</a>.</div>\r\n","<div class=\"hw jl\">居候</div><div class=\"def\">parasitus(<i>m</i>), parasita(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://寄生\">寄生</a>.</div>\r\n","<div class=\"hw jl\">居座る</div><div class=\"def\">(=ある場所・地位に居続ける)maneo, permaneo.</div>\r\n","<div class=\"hw jl\">居酒屋</div><div class=\"def\">caupona.</div><div class=\"def\">▼<b>～の主人</b> caupo.</div>\r\n","<div class=\"hw jl\">居間</div><div class=\"def\">cubiculum.</div>\r\n","<div class=\"hw jl\">屈折</div><div class=\"def\">(光線の)refractio, refractus.</div><div class=\"def\">▼<b>～の, ～する</b> refractivus.</div>\r\n","<div class=\"hw jl\">屈服</div><div class=\"def\">obsequium, obsequentia.</div><div class=\"def\">▼<b>～する</b> pareo.</div><div class=\"def\">⇒<a href=\"entry://従う\">従う</a>,<a href=\"entry://服従\">服従</a>,<a href=\"entry://降伏\">降伏</a>.</div>\r\n","<div class=\"hw jl\">届く</div><div class=\"def\">attineo, pertingo, attingo, pertineo, pervenio.</div>\r\n","<div class=\"hw jl\">屋内</div><div class=\"def\">interior pars(aedium).</div>\r\n","<div class=\"hw jl\">屋外</div><div class=\"def\">exterior pars.</div>\r\n","<div class=\"hw jl\">屋根</div><div class=\"def\">tectum.</div>\r\n","<div class=\"hw jl\">展望</div><div class=\"def\">prospectus.</div>\r\n","<div class=\"hw jl\">展示</div><div class=\"def\">propositio.</div><div class=\"def\">▼<b>～する</b>(in oculis;ante oculos)expono, propono.</div><div class=\"ex2\">絵画や彫刻の～<span class=\"ext\">tabulae et signa propalam collocata.</span></div>\r\n","<div class=\"hw jl\">展開</div><div class=\"def\">explicatio.</div><div class=\"def\">▼<b>～する</b> se explicare(← explico).</div>\r\n","<div class=\"hw jl\">屠殺</div><div class=\"def\">trucidatio.</div><div class=\"def\">▼<b>～する</b> trucido.</div>\r\n","<div class=\"hw jl\">履く</div><div class=\"def\">(靴を)(calceamenta)induo;(サンダルを)pedes(soleis)induo.</div><div class=\"def\">▼<b>靴を履かせる</b> calceo.</div>\r\n","<div class=\"hw jl\">履歴</div><div class=\"def\">▼<b>～(書)</b> curriculum vitae.</div>\r\n","<div class=\"hw jl\">履物</div><div class=\"def\">calceamentum.</div><div class=\"def\">⇒<a href=\"entry://靴\">靴</a>,<a href=\"entry://サンダル\">サンダル</a>.</div>\r\n","<div class=\"hw jl\">山</div><div class=\"def\">mons.</div><div class=\"def\">▼<b>～の</b> montanus.</div><div class=\"def\">▼<b>～の多い</b> montuosus.</div>\r\n","<div class=\"hw jl\">山脈</div><div class=\"def\">jugum.</div><div class=\"def\">▼<b>ピレネー～</b> montes Pyrenaei.</div>\r\n","<div class=\"hw jl\">岩</div><div class=\"def\">saxum.</div><div class=\"def\">⇒<a href=\"entry://石\">石</a>.</div>\r\n","<div class=\"hw jl\">岬</div><div class=\"def\">promontorium, promunturium.</div>\r\n","<div class=\"hw jl\">岸</div><div class=\"def\">(=海岸, 河岸)litus, ripa;(=海岸)ora.</div>\r\n","<div class=\"hw jl\">島</div><div class=\"def\">insula.</div><div class=\"def\">▼<b>～の</b> insularis.</div><div class=\"def\">⇒<a href=\"entry://半島\">半島</a>.</div>\r\n","<div class=\"hw jl\">崇高</div><div class=\"def\">sublimitas, granditas.</div><div class=\"def\">▼<b>～な</b> excelsus, grandis, sublimis.</div>\r\n","<div class=\"hw jl\">崖</div><div class=\"def\">locus praeceps;(=断崖, 絶壁)rupes, scopulus.</div>\r\n","<div class=\"hw jl\">崩す</div><div class=\"def\">deruo, subruo.</div><div class=\"def\">⇒<a href=\"entry://崩れる\">崩れる</a>.</div>\r\n","<div class=\"hw jl\">崩れる</div><div class=\"def\">ruo, deruo, corruo, collabor(<i>dep</i>), collabefacio.</div><div class=\"def\">⇒<a href=\"entry://倒す\">倒す</a>,<a href=\"entry://崩す\">崩す</a>.</div>\r\n","<div class=\"hw jl\">崩壊</div><div class=\"def\">ruina, labes.</div><div class=\"def\">▼<b>～する</b> ruo, corruo, concido, collabor(<i>dep</i>), occurro.</div>\r\n","<div class=\"hw jl\">嵐</div><div class=\"def\">tempestas;(=大嵐)procella;(=暴風雨)nimbus.</div>\r\n","<div class=\"hw jl\">川・河</div><div class=\"def\">flumen, fluvius, amnis;(小さな)rivus, amniculus, rivulus.</div><div class=\"def\">▼<b>～の</b> flumineus, fluvialis.</div><div class=\"ex2\">～を下って(=下流へ)<span class=\"ext\">secundo amne.</span></div><div class=\"ex2\">～を上って(=上流へ)<span class=\"ext\">adverso amne.</span></div>\r\n","<div class=\"hw jl\">巣</div><div class=\"def\">(鳥や蜂の)nidus;(蟻の)formicarum cavea;(蜜蜂の)alveus, alvus;(蜘蛛の)aranea, araneum;(獣の)cubile.</div>\r\n","<div class=\"hw jl\">工事</div><div class=\"def\">opus.</div><div class=\"def\">⇒<a href=\"entry://作業\">作業</a>.</div>\r\n","<div class=\"hw jl\">工作</div><div class=\"def\">fabricatio.</div><div class=\"def\">▼<b>～者</b> fabricator.</div><div class=\"def\">▼<b>～場</b> fabrica.</div><div class=\"def\">▼<b>～する</b> fabrico, fabricor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://工夫\">工夫</a>,<a href=\"entry://陰謀\">陰謀</a>.</div>\r\n","<div class=\"hw jl\">工具</div><div class=\"def\">instrumentum, ferramentum.</div><div class=\"def\">⇒<a href=\"entry://道具\">道具</a>.</div>\r\n","<div class=\"hw jl\">工場</div><div class=\"def\">officina, fabrica.</div><div class=\"def\">⇒<a href=\"entry://工作\">工作</a>.</div>\r\n","<div class=\"hw jl\">工夫</div><div class=\"def\">machinatio, commentum.</div><div class=\"def\">▼<b>～する</b> machinor(<i>dep</i>), excogito, procudo.</div>\r\n","<div class=\"hw jl\">工学</div><div class=\"def\">technologia.</div><div class=\"def\">▼<b>電気～</b> electridis naturae scientia [peritia], ars electrotechnica ars, electridis technica ratio [disciplina].</div><div class=\"def\">▼<b>電子～</b> electronica disciplina [ars].</div><div class=\"def\">▼<b>無線通信～</b> radiotechnice.</div><div class=\"def\">▼<b>機械～</b> disciplina machinalis.</div><div class=\"def\">⇒<a href=\"entry://技術\">技術</a>.</div>\r\n","<div class=\"hw jl\">工業</div><div class=\"def\">(=機械工業)machinalis industria.</div><div class=\"def\">▼<b>手～</b> artificia(<i>pl</i>).</div><div class=\"def\">▼<b>手～者</b> artifices(<i>pl</i>).</div><div class=\"def\">▼<b>～の, ～に関する</b> ad machinalem industriam pertinens.</div><div class=\"def\">▼<b>～化する</b> machinalem industriam induco.</div><div class=\"def\">⇒<a href=\"entry://工芸\">工芸</a>,<a href=\"entry://産業\">産業</a>.</div>\r\n","<div class=\"hw jl\">工芸</div><div class=\"def\">opificium artes et munera(<i>pl</i>).</div><div class=\"def\">▼<b>～家</b> opifex.</div>\r\n","<div class=\"hw jl\">左</div><div class=\"def\">sinistra pars, sinistrum latus.</div><div class=\"def\">▼<b>～手</b> sinistra [laeva] manus.</div><div class=\"def\">▼<b>～の</b> sinister, laevus.</div><div class=\"def\">▼<b>～に</b>(a)laeva, ad sinistram, (a)sinistra.</div>\r\n","<div class=\"hw jl\">巧み</div><div class=\"def\">▼<b>～な</b> sollers, callidus, artifex, peritus, versutus.</div><div class=\"def\">▼<b>～に</b> perite, scienter.</div><div class=\"def\">⇒<a href=\"entry://得意\">得意</a>,<a href=\"entry://巧妙\">巧妙</a>.</div>\r\n","<div class=\"hw jl\">巧妙</div><div class=\"def\">sollertia.</div><div class=\"def\">▼<b>～な</b> sollers, artificiosus, callidus.</div><div class=\"def\">▼<b>～に</b> sollerter.</div><div class=\"def\">⇒<a href=\"entry://狡猾\">狡猾</a>.</div>\r\n","<div class=\"hw jl\">差</div><div class=\"def\">differentia.</div><div class=\"def\">▼<b>～がある</b> differo.</div><div class=\"ex2\">きみたちと彼らの年齢の～は全くないかほとんどないかのどちらかだ<span class=\"ext\">aetates vestrae et illorum nihil aut non fere multum differunt.</span></div><div class=\"def\">⇒<a href=\"entry://差異\">差異</a>,<a href=\"entry://違う\">違う</a>.</div>\r\n","<div class=\"hw jl\">差し出す</div><div class=\"def\">propono, ostendo, praebeo, offero.</div>\r\n","<div class=\"hw jl\">差し当たって</div><div class=\"def\">in praesentia.</div>\r\n","<div class=\"hw jl\">差し込む</div><div class=\"def\">insero, inserto.</div><div class=\"def\">⇒<a href=\"entry://挿入\">挿入</a>.</div>\r\n","<div class=\"hw jl\">差別</div><div class=\"def\">discrimen.</div><div class=\"def\">▼<b>～する</b> discrimino.</div><div class=\"def\">▼<b>人種～</b> elatio phyletica discriminatrix, propriae stirpis elatio.</div>\r\n","<div class=\"hw jl\">差異</div><div class=\"def\">differentia, distantia, distinctio.</div><div class=\"def\">⇒<a href=\"entry://差\">差</a>,<a href=\"entry://区別\">区別</a>.</div>\r\n","<div class=\"hw jl\">巻く</div><div class=\"def\">(糸を)(filum)volvo;(...に...を)〈alqd re〉 cingo.</div><div class=\"def\">▼<b>身体に</b>(...を)<b>～</b> involvo 〈alqd〉 corpori.</div><div class=\"ex2\">とぐろを巻いた蛇<span class=\"ext\">serpentes sibi ipsae circumvolutae(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://取り巻く\">取り巻く</a>,<a href=\"entry://包囲\">包囲</a>,<a href=\"entry://帯\">帯</a>.</div>\r\n","<div class=\"hw jl\">市</div><div class=\"def\">(=定期市)nundinae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://マーケット\">マーケット</a>,<a href=\"entry://市場\">市場<SUB>いちば</SUB></a>.</div>\r\n","<div class=\"hw jl\">市</div><div class=\"def\">⇒<a href=\"entry://都市\">都市</a>.</div>\r\n","<div class=\"hw jl\">市場</div><div class=\"def\">(=市, 定期市)mercatus, emporium, nundinae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://マーケット\">マーケット</a>,<a href=\"entry://市\">市</a>.</div>\r\n","<div class=\"hw jl\">市場</div><div class=\"def\">mercatus.</div><div class=\"def\">▼<b>自由～</b> liber mercatus.</div><div class=\"def\">⇒<a href=\"entry://市場\">市場<SUB>いちば</SUB></a>.</div>\r\n","<div class=\"hw jl\">市役所</div><div class=\"def\">aedes magistri urbis.</div>\r\n","<div class=\"hw jl\">市民</div><div class=\"def\">civis, municeps.</div><div class=\"def\">▼<b>～権</b> civitas, jus civitatis.</div>\r\n","<div class=\"hw jl\">市長</div><div class=\"def\">urbis [oppidi] praefectus [princeps magistratus], civium magister.</div>\r\n","<div class=\"hw jl\">布</div><div class=\"def\">(=織物, 布地)vestis, textum, tela, textile.</div>\r\n","<div class=\"hw jl\">布告</div><div class=\"def\">edictum, pronuntiatio.</div><div class=\"def\">▼<b>～する</b> edico, pronuntio.</div>\r\n","<div class=\"hw jl\">帆</div><div class=\"def\">velum, carbasus, linteum.</div>\r\n","<div class=\"hw jl\">希望</div><div class=\"def\">spes.</div><div class=\"def\">▼<b>～する, ～をもつ</b> spero, spem habeo.</div>\r\n","<div class=\"hw jl\">席</div><div class=\"def\">sedes.</div><div class=\"def\">⇒<a href=\"entry://座席\">座席</a>,<a href=\"entry://予約\">予約</a>.</div>\r\n","<div class=\"hw jl\">帯</div><div class=\"def\">balteus;(女性の)cingulum, zona;(男性の)cinctus.</div><div class=\"def\">▼<b>～を締める</b> cingor(<i>pass</i>), se zonā circumdare(← circumdo).</div>\r\n","<div class=\"hw jl\">帰る・返る</div><div class=\"def\">redeo, regredior(<i>dep</i>), revertor(<i>dep</i>), revenio.</div><div class=\"def\">▼<b>～こと</b> reditus, regressio, reversio, recessus.</div><div class=\"ex2\">家に～<span class=\"ext\">domum me recipio / domum me confero / domum revertor(<i>dep</i>)/ domum repeto.</span></div>\r\n","<div class=\"hw jl\">帰化</div><div class=\"def\">▼<b>～(させること)</b> civitatis donatio.</div><div class=\"def\">▼<b>～させる</b> civitate dono, in civitatem suscipio, 〈+<i>dat</i>〉 civitatem do.</div>\r\n","<div class=\"hw jl\">帰国</div><div class=\"def\">▼<b>～する</b> ad patriam se referre(← refero), in patriam redeo.</div>\r\n","<div class=\"hw jl\">帰宅</div><div class=\"def\">▼<b>～する</b> domum abeo, domum redeo, domum se recipere(← recipio), domum(suam)revertor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">帳簿</div><div class=\"def\">codex, tabula.</div><div class=\"ex2\">～をつける<span class=\"ext\">tabulas conficio.</span></div>\r\n","<div class=\"hw jl\">常に</div><div class=\"def\">semper.</div>\r\n","<div class=\"hw jl\">常識</div><div class=\"def\">(=世人に共通の考え)communis [vulgaris] intelligentia, commune judicium.</div><div class=\"def\">⇒<a href=\"entry://良識\">良識</a>.</div>\r\n","<div class=\"hw jl\">常連</div><div class=\"def\">frequentator.</div>\r\n","<div class=\"hw jl\">帽子</div><div class=\"def\">petasus, pileus, pileum.</div><div class=\"def\">▼<b>小さな～</b> pileolus, pileolum.</div><div class=\"def\">▼<b>～をかぶった</b> petasatus.</div>\r\n","<div class=\"hw jl\">幅</div><div class=\"def\">latitudo.</div><div class=\"def\">▼<b>～のある</b>(=広い)latus.</div><div class=\"def\">⇒<a href=\"entry://長い\">長い</a>.</div>\r\n","<div class=\"hw jl\">幕</div><div class=\"def\">velum, plagula, siparium, velamentum;(劇場の)aulaeum.</div><div class=\"ex2\">冬季オリンピックが～を閉じた<span class=\"ext\">Ludi Olympici hiberni peracti sunt.</span></div>\r\n","<div class=\"hw jl\">干す</div><div class=\"def\">sicco.</div><div class=\"def\">⇒<a href=\"entry://乾く\">乾く</a>.</div>\r\n","<div class=\"hw jl\">干渉</div><div class=\"def\">intercursus, interventus.</div><div class=\"def\">▼<b>～する</b> intervenio, intercedo.</div>\r\n","<div class=\"hw jl\">平ら</div><div class=\"def\">▼<b>～な</b> aequus, planus.</div><div class=\"def\">▼<b>～にする</b> aequo.</div>\r\n","<div class=\"hw jl\">平凡</div><div class=\"def\">▼<b>～な</b> vulgaris, pervulgatus, pervagatus.</div><div class=\"def\">⇒<a href=\"entry://陳腐\">陳腐</a>.</div>\r\n","<div class=\"hw jl\">平和</div><div class=\"def\">pax, quies.</div><div class=\"def\">▼<b>～な</b>(=平時の)pacatus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">平時に<span class=\"ext\">in pace.</span></div><div class=\"def\">⇒<a href=\"entry://平静\">平静</a>.</div>\r\n","<div class=\"hw jl\">平地</div><div class=\"def\">(=広場)campus, campester locus, aequor, aequum.</div><div class=\"def\">▼<b>～の</b> campester.</div><div class=\"def\">⇒<a href=\"entry://平野\">平野</a>.</div>\r\n","<div class=\"hw jl\">平均</div><div class=\"def\">mediocritas.</div><div class=\"def\">▼<b>～的な</b> mediocris.</div>\r\n","<div class=\"hw jl\">平常</div><div class=\"def\">▼<b>～の</b> cottidianus, solitus, consuetus, assuetus, usitatus.</div><div class=\"def\">⇒<a href=\"entry://普通\">普通</a>,<a href=\"entry://日常\">日常</a>,<a href=\"entry://通常\">通常</a>.</div>\r\n","<div class=\"hw jl\">平手</div><div class=\"def\">palma.</div><div class=\"ex2\">(人の)顔を～で打つ<span class=\"ext\">〈alcis〉 os palmā pulso.</span></div>\r\n","<div class=\"hw jl\">平穏</div><div class=\"def\">tranquillitas, tranquillum, quies.</div><div class=\"def\">▼<b>～な</b> tranquillus, quietus, placidus.</div><div class=\"def\">⇒<a href=\"entry://平和\">平和</a>,<a href=\"entry://安心\">安心</a>,<a href=\"entry://静寂\">静寂</a>.</div>\r\n","<div class=\"hw jl\">平等</div><div class=\"def\">aequalitas.</div><div class=\"def\">▼<b>～な</b> aequalis, aequus.</div>\r\n","<div class=\"hw jl\">平行</div><div class=\"def\">aequilatatio.</div><div class=\"def\">▼<b>～な</b> parallelus.</div><div class=\"def\">▼<b>～して</b> paribus inter se intervallis.</div><div class=\"ex2\">～線を引く<span class=\"ext\">lineam parallelam signo.</span></div>\r\n","<div class=\"hw jl\">平野</div><div class=\"def\">(=平地)planities, planitia, campus, campestria, campester locus, aequor, aequum.</div>\r\n","<div class=\"hw jl\">平静</div><div class=\"def\">(心の)tranquillitas, constantia, aequitas, quies.</div><div class=\"def\">▼<b>～な</b> tranquillus, constans, aequus, quietus.</div><div class=\"def\">▼<b>～に</b> aequo animo.</div><div class=\"def\">⇒<a href=\"entry://静か\">静か</a>.</div>\r\n","<div class=\"hw jl\">平面</div><div class=\"def\">planities, planitia, aequum.</div><div class=\"def\">▼<b>～の</b> planus.</div>\r\n","<div class=\"hw jl\">年</div><div class=\"def\">annus.</div><div class=\"def\">▼<b>毎～の</b> annuus.</div><div class=\"def\">▼<b>次の～</b>(=翌年)insequens annus.</div><div class=\"def\">▼<b>次の～に</b> postero anno, anno post.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">今年<span class=\"ext\">hic annus.</span></div><div class=\"cf\">今年の<span class=\"ext\">hornus, hornotinus.</span></div><div class=\"def\">⇒<a href=\"entry://...歳\">...歳</a>.</div>\r\n","<div class=\"hw jl\">年</div><div class=\"def\">annus.</div><div class=\"def\">▼<b>1～間</b> annuum spatium.</div><div class=\"def\">▼<b>2～間</b> biennium.</div><div class=\"def\">▼<b>3～間</b> triennium.</div><div class=\"def\">▼<b>来～</b><span class=\"pos3\">[名]</span> insequens annus. <span class=\"pos3\">[副]</span> anno sequente [postero].</div><div class=\"def\">▼<b>昨～</b> superiore anno.</div><div class=\"def\">▼<b>毎～</b> quotannis, singulis annis.</div><div class=\"ex2\">8～間(に)<span class=\"ext\">per octo annos.</span></div><div class=\"ex2\">西暦1973～に<span class=\"ext\">anno post Christum natum milesimo nongentesimo tertio et septuagesimo.</span></div><div class=\"def\">⇒<a href=\"entry://年\">年<SUB>とし</SUB></a>,<a href=\"entry://新年\">新年</a>.</div>\r\n","<div class=\"hw jl\">年ごろ</div><div class=\"def\">(=一人前の年齢)pubertas.</div><div class=\"def\">▼<b>～の</b> pubes.</div><div class=\"def\">⇒<a href=\"entry://年齢\">年齢</a>.</div>\r\n","<div class=\"hw jl\">年上</div><div class=\"def\">▼<b>～の</b>(natu)major.</div><div class=\"def\">▼<b>最も～の</b> natu maximus.</div><div class=\"ex2\">私たちより二つ～の<span class=\"ext\">major quam nos biennio.</span></div>\r\n","<div class=\"hw jl\">年下</div><div class=\"def\">▼<b>～の</b> natu minor, junior.</div><div class=\"def\">▼<b>最も～の</b> natu minimus.</div>\r\n","<div class=\"hw jl\">年代記</div><div class=\"def\">annales(<i>pl</i>), narratio secundum temporum ordines.</div>\r\n","<div class=\"hw jl\">年金</div><div class=\"def\">tributa beneficia, pensio, beneficium annuum.</div><div class=\"def\">▼<b>～生活者</b> beneficiis tributis fruens.</div>\r\n","<div class=\"hw jl\">年齢</div><div class=\"def\">aetas.</div><div class=\"def\">▼(人と)<b> 同～の</b> 〈alcis〉 aequalis.</div><div class=\"def\">▼<b>同～であること</b> aequalitas.</div>\r\n","<div class=\"hw jl\">幸せ</div><div class=\"def\">⇒<a href=\"entry://幸福\">幸福</a>.</div>\r\n","<div class=\"hw jl\">幸福</div><div class=\"def\">felicitas, beatum, faustitas.</div><div class=\"def\">▼<b>～な</b> felix, beatus, faustus.</div><div class=\"def\">▼<b>～に</b> feliciter, beate, fauste.</div>\r\n","<div class=\"hw jl\">幸運</div><div class=\"def\">(secunda)fortuna, felicitas.</div><div class=\"def\">▼<b>～な</b> fortunatus, felix, prosperus, faustus.</div><div class=\"def\">▼<b>～に</b> fortunate, feliciter, fauste.</div><div class=\"def\">▼<b>～の女神</b>(Fors)Fortuna.</div><div class=\"def\">⇒<a href=\"entry://運\">運</a>,<a href=\"entry://運命\">運命</a>.</div>\r\n","<div class=\"hw jl\">幹</div><div class=\"def\">truncus, stipes, stirps, scapus.</div>\r\n","<div class=\"hw jl\">幻</div><div class=\"def\">(=幻影)umbra, (falsa)imago, simulacrum.</div>\r\n","<div class=\"hw jl\">幻影</div><div class=\"def\">simulacrum, visio, mendacium, phantasma, falsa imago;(実体がなく空虚な存在がわれわれの恐怖のせいで姿を取って現われること)inania et vana ex metu nostro imaginem accipere.</div>\r\n","<div class=\"hw jl\">幻想</div><div class=\"def\">somnium, phantasia, phantasma, res vana, falsa [vana] species.</div><div class=\"def\">⇒<a href=\"entry://妄想\">妄想</a>,<a href=\"entry://幻影\">幻影</a>.</div>\r\n","<div class=\"hw jl\">幻覚</div><div class=\"def\">visio, mendacium.</div><div class=\"def\">⇒<a href=\"entry://幻影\">幻影</a>.</div>\r\n","<div class=\"hw jl\">幼い</div><div class=\"def\">parvus, parvulus;(=幼稚な, 未熟な)puerilis.</div>\r\n","<div class=\"hw jl\">幼児</div><div class=\"def\">infans(<i>m</i>, <i>f</i>), infantulus(<i>m</i>), infantula(<i>f</i>), parvus puer(<i>m</i>), parvulus(<i>m</i>).</div>\r\n","<div class=\"hw jl\">幼年</div><div class=\"def\">▼<b>～(期)</b> infantia, prima aetas, aetas tenera.</div><div class=\"def\">▼<b>～期から</b> ab infante, a tenero, a primo tempore aetatis.</div><div class=\"def\">⇒<a href=\"entry://少年\">少年</a>.</div>\r\n","<div class=\"hw jl\">幼稚</div><div class=\"def\">▼<b>～(さ)</b> puerilitas.</div><div class=\"def\">▼<b>～な</b> puerilis.</div>\r\n","<div class=\"hw jl\">幽霊</div><div class=\"def\">(=死者の魂, 亡霊)phantasma, simulacrum, larva, umbra, manes(<i>pl</i>), lemures(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">幾何学</div><div class=\"def\">geometria.</div><div class=\"def\">▼<b>～の</b> geometrius.</div>\r\n","<div class=\"hw jl\">広い</div><div class=\"def\">(幅が)latus;(=広大な)amplus, spatiosus, magnus, laxus.</div><div class=\"def\">▼<b>広さ</b> latitudo;(=広大さ)magnitudo, amplitudo, laxitas.</div><div class=\"def\">▼<b>広く</b> late, laxe, spatiose, vulgo.</div>\r\n","<div class=\"hw jl\">広がる</div><div class=\"def\">se extendere(← extendo), se pandere(← pando), extendor(<i>pass</i>), pandor(<i>pass</i>), mano.</div><div class=\"ex2\">ティベリス川とローマの城壁の間に～平野<span class=\"ext\">campus interjacens Tiberi ac moenibus Romanis.</span></div>\r\n","<div class=\"hw jl\">広げる</div><div class=\"def\">extendo, pando, dilato, explico, laxo, amplifico.</div>\r\n","<div class=\"hw jl\">広まる</div><div class=\"def\">fundor(<i>pass</i>), disseminor(<i>pass</i>), dissipor(<i>pass</i>), increbresco, diffundor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">広告</div><div class=\"def\">⇒<a href=\"entry://宣伝\">宣伝</a>.</div>\r\n","<div class=\"hw jl\">広報</div><div class=\"def\">⇒<a href=\"entry://宣伝\">宣伝</a>.</div>\r\n","<div class=\"hw jl\">広場</div><div class=\"def\">campus, forum.</div>\r\n","<div class=\"hw jl\">広大</div><div class=\"def\">magnitudo, vastitas, latitudo.</div><div class=\"def\">▼<b>～な</b> magnus, vastus, latus.</div>\r\n","<div class=\"hw jl\">床</div><div class=\"def\">solum. </div><div class=\"ex2\">婚礼の～<span class=\"ext\">lectus genialis.</span></div><div class=\"def\">⇒<a href=\"entry://寝床\">寝床</a>.</div>\r\n","<div class=\"hw jl\">床</div><div class=\"def\">(梁に板を敷いた)contabulatio.</div>\r\n","<div class=\"hw jl\">床屋</div><div class=\"def\">(=理髪師)tonsor.</div><div class=\"def\">▼<b>～の</b> tonsorius.</div>\r\n","<div class=\"hw jl\">底</div><div class=\"def\">fundus, ima pars, imum, profundum.</div><div class=\"ex2\">海の～に沈む<span class=\"ext\">in imo mari summergor(<i>pass</i>).</span></div>\r\n","<div class=\"hw jl\">店</div><div class=\"def\">taberna.</div><div class=\"def\">▼<b>小さな～</b> tabernula.</div>\r\n","<div class=\"hw jl\">度</div><div class=\"def\">▼<b>1～(だけ)</b> semel(tantum);<b>2～</b> bis;<b>3～</b> ter;<b>4～</b> quater.</div><div class=\"def\">⇒<a href=\"entry://回\">回</a>,<a href=\"entry://程度\">程度</a>.</div>\r\n","<div class=\"hw jl\">度胸</div><div class=\"def\">⇒<a href=\"entry://勇気\">勇気</a>.</div>\r\n","<div class=\"hw jl\">座席</div><div class=\"def\">sedes, sedile;(劇場等の)locus.</div><div class=\"def\">⇒<a href=\"entry://椅子\">椅子</a>,<a href=\"entry://腰掛け\">腰掛け</a>,<a href=\"entry://ソファー\">ソファー</a>.</div>\r\n","<div class=\"hw jl\">庭</div><div class=\"def\">hortus;(=庭園)viridarium.</div><div class=\"def\">▼<b>小さな～</b> hortulus.</div><div class=\"ex2\">～いじり<span class=\"ext\">horti cultura [cultus].</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">菜園<span class=\"ext\">holitorius hortus.</span></div><div class=\"cf\">果樹園<span class=\"ext\">pomarium.</span></div>\r\n","<div class=\"hw jl\">庭園</div><div class=\"def\">hortus;(小さな)hortulus.</div><div class=\"def\">▼<b>～の</b> hortensis, hortensius.</div>\r\n","<div class=\"hw jl\">庶民</div><div class=\"def\">vulgus.</div><div class=\"def\">⇒<a href=\"entry://大衆\">大衆</a>,<a href=\"entry://民衆\">民衆</a>.</div>\r\n","<div class=\"hw jl\">廃棄</div><div class=\"def\">abolitio, dissolutio.</div><div class=\"def\">⇒<a href=\"entry://廃止\">廃止</a>,<a href=\"entry://捨てる\">捨てる</a>.</div>\r\n","<div class=\"hw jl\">廃止</div><div class=\"def\">abolitio, dissolutio, desuetudo.</div><div class=\"def\">▼<b>～する</b> aboleo, tollo, dissolvo.</div>\r\n","<div class=\"hw jl\">廃虚</div><div class=\"def\">ruinae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">延ばす</div><div class=\"def\">(=長くする)(alqd)longiorem facio, extento, extendo, porrigo, produco.</div><div class=\"def\">▼<b>延ばした</b> extentus, porrectus, productus.</div>\r\n","<div class=\"hw jl\">延びる・伸びる</div><div class=\"def\">(=長くなる)longior fio, in longitudinem cresco, extendor(<i>pass</i>), porrigor(<i>pass</i>);(音節が)producor(<i>pass</i>).</div><div class=\"ex2\">(カタツムリの)角が～<span class=\"ext\">cornua praetenduntur(<i>pass</i>).</span></div>\r\n","<div class=\"hw jl\">延期</div><div class=\"def\">prolatio, prodictio, procrastinatio.</div><div class=\"def\">▼<b>～する</b> differo, profero, prodico, procrastino.</div>\r\n","<div class=\"hw jl\">延長</div><div class=\"def\">(時間の)prolatio, temporis productio;(空間・物体の)extensio.</div><div class=\"def\">▼<b>～する</b> produco, profero.</div>\r\n","<div class=\"hw jl\">建てる</div><div class=\"def\">construo, exstruo, statuo, constituo, condo, aedifico, erigo.</div><div class=\"def\">⇒<a href=\"entry://建築\">建築</a>,<a href=\"entry://建設\">建設</a>.</div>\r\n","<div class=\"hw jl\">建物</div><div class=\"def\">aedificium, aedificatio.</div><div class=\"def\">⇒<a href=\"entry://建築\">建築</a>,<a href=\"entry://建設\">建設</a>.</div>\r\n","<div class=\"hw jl\">建築</div><div class=\"def\">constructio, aedificatio.</div><div class=\"def\">▼<b>～物</b> aedificium, aedificatio.</div><div class=\"def\">▼<b>～術</b> architectura, architectonice.</div><div class=\"def\">▼<b>～家</b> architectus, architecton.</div><div class=\"def\">▼<b>～の</b> architectonicus.</div><div class=\"def\">▼<b>～する</b> aedifico, architector(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">建設</div><div class=\"def\">exstructio, aedificatio.</div><div class=\"def\">▼<b>～する</b> construo, exstruo, aedifico.</div><div class=\"def\">⇒<a href=\"entry://建築\">建築</a>,<a href=\"entry://建てる\">建てる</a>.</div>\r\n","<div class=\"hw jl\">建造</div><div class=\"def\">⇒<a href=\"entry://建設\">建設</a>.</div>\r\n","<div class=\"hw jl\">弁償</div><div class=\"def\">(=賠償)pensatio, compensatio.</div><div class=\"def\">▼(人の)<b> 損害を～する</b>(=賠償する)〈alcis〉 damnum dissolvo, noxiam sarcio [resarcio], jacturam restituo.</div><div class=\"def\">⇒<a href=\"entry://あがなう\">あがなう</a>,<a href=\"entry://償う\">償う</a>.</div>\r\n","<div class=\"hw jl\">弁明</div><div class=\"def\">(=弁護)defensio, purgatio, apologia, causae dictio.</div><div class=\"def\">▼<b>～する</b> defendo, purgo.</div><div class=\"def\">⇒<a href=\"entry://弁解\">弁解</a>,<a href=\"entry://言い訳\">言い訳</a>.</div>\r\n","<div class=\"hw jl\">弁解</div><div class=\"def\">excusatio, purgatio.</div><div class=\"def\">▼<b>～する</b> se excusare(← excuso), purgo.</div><div class=\"def\">⇒<a href=\"entry://弁明\">弁明</a>,<a href=\"entry://謝罪\">謝罪</a>.</div>\r\n","<div class=\"hw jl\">弁論</div><div class=\"def\">oratio.</div><div class=\"def\">▼<b>～家</b> orator.</div><div class=\"def\">▼<b>～術</b> rhetorice, (ars)rhetorica [oratoria].</div><div class=\"def\">▼<b>～術教師</b> rhetor.</div><div class=\"def\">▼<b>～の</b> rhetoricus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">弁論の導入部, 序文<span class=\"ext\">exordium.</span></div><div class=\"cf\">陳述部<span class=\"ext\">narratio.</span></div><div class=\"cf\">論証<span class=\"ext\">confirmatio, probatio.</span></div><div class=\"cf\">反証<span class=\"ext\">refutatio.</span></div><div class=\"cf\">結論, 結びの文句<span class=\"ext\">peroratio.</span></div>\r\n","<div class=\"hw jl\">弁護</div><div class=\"def\">defensio, patrocinium.</div><div class=\"def\">▼<b>～する</b> defendo, patrocinor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">弁護士</div><div class=\"def\">advocatus, patronus;(しばしば軽蔑的に)causidicus.</div>\r\n","<div class=\"hw jl\">弊害</div><div class=\"def\">vitium, malum.</div><div class=\"def\">⇒<a href=\"entry://害\">害</a>,<a href=\"entry://損害\">損害</a>.</div>\r\n","<div class=\"hw jl\">式</div><div class=\"def\">⇒<a href=\"entry://儀式\">儀式</a>.</div>\r\n","<div class=\"hw jl\">弓</div><div class=\"def\">arcus.</div><div class=\"def\">▼<b>～の弦</b> nervus.</div><div class=\"def\">▼<b>～を引き絞る</b> arcum intendo [adduco].</div><div class=\"def\">▼<b>～で矢を射る</b> sagittam arcu emitto.</div><div class=\"def\">⇒<a href=\"entry://矢\">矢</a>.</div>\r\n","<div class=\"hw jl\">引きずる</div><div class=\"def\">traho.</div><div class=\"def\">▼<b>引きずり回す</b> tracto.</div><div class=\"def\">▼<b>～こと</b> tractus.</div>\r\n","<div class=\"hw jl\">引きつける</div><div class=\"def\">induco, traho.</div>\r\n","<div class=\"hw jl\">引き伸ばす</div><div class=\"def\">extendo, produco, profero.</div><div class=\"def\">⇒<a href=\"entry://拡大\">拡大</a>.</div>\r\n","<div class=\"hw jl\">引き受ける</div><div class=\"def\">suscipio, recipio, sumo, assumo, subeo, conscisco.</div>\r\n","<div class=\"hw jl\">引き抜く</div><div class=\"def\">vello, convello, subtraho.</div><div class=\"def\">⇒<a href=\"entry://抜く\">抜く</a>.</div>\r\n","<div class=\"hw jl\">引き渡す</div><div class=\"def\">trado, profero, dedo.</div><div class=\"def\">▼<b>～こと</b> traditio, deditio.</div>\r\n","<div class=\"hw jl\">引き裂く</div><div class=\"def\">lanio, discindo, dilanio, dilacero.</div><div class=\"def\">▼<b>～こと</b> laceratio, laniatus.</div>\r\n","<div class=\"hw jl\">引き返す</div><div class=\"def\">(=後戻りする)iter retro verto, recedo, regredior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://退却\">退却</a>.</div>\r\n","<div class=\"hw jl\">引き離す</div><div class=\"def\">subtraho.</div><div class=\"def\">⇒<a href=\"entry://離す\">離す</a>.</div>\r\n","<div class=\"hw jl\">引く</div><div class=\"def\">traho;(注意や関心を)converto;(=引き算する)deduco.</div><div class=\"def\">▼<b>～こと</b> tractus, ductus.</div><div class=\"def\">⇒<a href=\"entry://引用\">引用</a>.</div>\r\n","<div class=\"hw jl\">引っ張る</div><div class=\"def\">traho, duco.</div><div class=\"def\">▼<b>～こと</b> tractus.</div>\r\n","<div class=\"hw jl\">引っ掻く</div><div class=\"def\">rado, scalpo, scabo.</div><div class=\"ex2\">爪で～<span class=\"ext\">unguibus scalpo.</span></div><div class=\"def\">⇒<a href=\"entry://掻く\">掻く</a>.</div>\r\n","<div class=\"hw jl\">引っ越し</div><div class=\"def\">emigratio.</div><div class=\"def\">▼<b>引っ越す</b>(ex)domo emigro, ex domo in domum migro.</div>\r\n","<div class=\"hw jl\">引っ込める</div><div class=\"def\">retracto, retraho, reduco.</div>\r\n","<div class=\"hw jl\">引力</div><div class=\"def\">(=物体がお互いに引き合う力)vis gravitatis.</div>\r\n","<div class=\"hw jl\">引用</div><div class=\"def\">commemoratio, prolatio.</div><div class=\"def\">▼(ある箇所を)<b> ～する</b> cito, commemoro, commemini, profero.</div><div class=\"ex2\">～箇所<span class=\"ext\">locus citatus.</span></div><div class=\"ex2\">～に値する<span class=\"ext\">commemorandus.</span></div>\r\n","<div class=\"hw jl\">引退</div><div class=\"def\">▼(...から)<b>～する</b> 〈de re〉 recedo, decedo, 〈a re〉 se removere(← removeo).</div>\r\n","<div class=\"hw jl\">弟</div><div class=\"def\">(adulescentior)frater.</div><div class=\"def\">⇒<a href=\"entry://兄\">兄</a>,<a href=\"entry://兄弟\">兄弟</a>.</div>\r\n","<div class=\"hw jl\">弟子</div><div class=\"def\">discipulus.</div>\r\n","<div class=\"hw jl\">弦</div><div class=\"def\">(楽器の)nervus, chorda, fides.</div>\r\n","<div class=\"hw jl\">弱い</div><div class=\"def\">(=無力な, 衰弱した)infirmus, imbecillus, invalidus, debilis.</div><div class=\"def\">▼<b>～こと</b> infirmitas, imbecillitas, languor.</div>\r\n","<div class=\"hw jl\">弱み</div><div class=\"def\">(=弱点)vitium.</div>\r\n","<div class=\"hw jl\">弱る</div><div class=\"def\">(=弱くなる, 衰弱する)languesco, debilitor(<i>pass</i>), extenuor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://衰える\">衰える</a>.</div>\r\n","<div class=\"hw jl\">弱点</div><div class=\"def\">⇒<a href=\"entry://欠点\">欠点</a>.</div>\r\n","<div class=\"hw jl\">張る</div><div class=\"def\">tendo, intendo, expando.</div><div class=\"def\">▼<b>(ぴんと)張った</b> intentus.</div>\r\n","<div class=\"hw jl\">強い</div><div class=\"def\">fortis, firmus, validus, valens, robustus, potens.</div>\r\n","<div class=\"hw jl\">強いる</div><div class=\"def\">cogo.</div><div class=\"def\">⇒<a href=\"entry://強制\">強制</a>.</div>\r\n","<div class=\"hw jl\">強制</div><div class=\"def\">coactus, necessitas.</div><div class=\"def\">▼<b>～する</b>(=強要する)compello, cogo, subigo.</div><div class=\"def\">▼<b>～的に</b>(=無理やり)per vim, coactu.</div>\r\n","<div class=\"hw jl\">強力</div><div class=\"def\">▼<b>～な</b> potens, valens, opulentus.</div><div class=\"def\">▼<b>～に</b> potenter.</div>\r\n","<div class=\"hw jl\">強化</div><div class=\"def\">▼<b>～する</b> corroboro, confirmo.</div>\r\n","<div class=\"hw jl\">強固</div><div class=\"def\">firmitas.</div><div class=\"def\">▼<b>～な</b> confirmatus.</div><div class=\"def\">▼<b>～にする</b> firmo, confirmo.</div><div class=\"def\">▼<b>～にすること</b> confirmatio.</div>\r\n","<div class=\"hw jl\">強奪</div><div class=\"def\">▼<b>～する</b> extorqueo, exprimo, rapio.</div><div class=\"def\">⇒<a href=\"entry://略奪\">略奪</a>,<a href=\"entry://奪う\">奪う</a>.</div>\r\n","<div class=\"hw jl\">強引</div><div class=\"def\">▼<b>～に</b> per vim.</div><div class=\"def\">⇒<a href=\"entry://こじつけ\">こじつけ</a>.</div>\r\n","<div class=\"hw jl\">強情</div><div class=\"def\">pertinacia, obstinatio.</div><div class=\"def\">▼<b>～な</b> pertinax, obstinatus.</div><div class=\"def\">▼<b>～に</b> pertinaciter, obstinate.</div>\r\n","<div class=\"hw jl\">強盗</div><div class=\"def\">latro, praedo, praedator;(行為)latrocinium.</div><div class=\"def\">▼<b>～を働く</b> latrocinor(<i>dep</i>), praedor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://強奪\">強奪</a>.</div>\r\n","<div class=\"hw jl\">強行軍</div><div class=\"def\">magnum iter, citum agmen.</div><div class=\"ex2\">～で(...を)目指す<span class=\"ext\">magno itinere confecto 〈ad alqd〉 contendo.</span></div>\r\n","<div class=\"hw jl\">弾く</div><div class=\"def\">(楽器を)〈+<i>abl</i>〉 cano;(曲を)〈+<i>acc</i>〉 cano.</div>\r\n","<div class=\"hw jl\">当たり前</div><div class=\"def\">▼<b>～の</b>(=正当な)justus;(=普通の)solitus, ordinarius.</div><div class=\"def\">⇒<a href=\"entry://当然\">当然</a>,<a href=\"entry://もちろん\">もちろん</a>.</div>\r\n","<div class=\"hw jl\">当たる</div><div class=\"def\">(=ぶつかる)offendo, ferio;(日に)apricor(<i>dep</i>).</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">日当たりのよい<span class=\"ext\">apricus.</span></div>\r\n","<div class=\"hw jl\">当て</div><div class=\"def\">▼<b>～にする</b> fido, confido, nitor(<i>dep</i>).</div><div class=\"def\">▼<b>～にしない</b> insperans.</div><div class=\"ex2\">私は当てにしていなかったが, ...ということになった<span class=\"ext\">insperanti mihi cecidit ut....</span></div>\r\n","<div class=\"hw jl\">当てはまる</div><div class=\"def\">(...に)〈in+<i>acc</i>〉 accidit(<i>impers</i>), 〈ad+<i>acc</i>〉 pertineo, convenio, 〈in+<i>acc</i>〉 cado.</div>\r\n","<div class=\"hw jl\">当てる</div><div class=\"def\">(=あてがう)adhibeo;(=充当する)impendo;(=ぶつける)illido, infligo, ico;(推測によって)conjicio.</div>\r\n","<div class=\"hw jl\">当惑</div><div class=\"def\">confusio.</div><div class=\"def\">▼<b>～した</b> confusus.</div><div class=\"def\">⇒<a href=\"entry://狼狽\">狼狽</a>,<a href=\"entry://ためらう\">ためらう</a>.</div>\r\n","<div class=\"hw jl\">当然</div><div class=\"def\"><span class=\"pos3\">[副]</span> juste, suo jure.</div><div class=\"def\">▼<b>～の</b> justus.</div><div class=\"ex2\">～(...)すべきである<span class=\"ext\">〈+<i>inf</i>〉 oportet(<i>impers</i>).</span></div><div class=\"def\">⇒<a href=\"entry://もちろん\">もちろん</a>.</div>\r\n","<div class=\"hw jl\">当選</div><div class=\"def\">▼<b>～する</b>(=選挙で選ばれる)suffragio legi(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">彗星</div><div class=\"def\">cometes, stella cincinnata, stella crinita.</div><div class=\"def\">⇒<a href=\"entry://星\">星</a>.</div>\r\n","<div class=\"hw jl\">形</div><div class=\"def\">forma, figura, conformatio;(表面に現われた)facies.</div><div class=\"def\">⇒<a href=\"entry://形成\">形成</a>.</div>\r\n","<div class=\"hw jl\">形容詞</div><div class=\"def\">adjectivum(nomen), appositum.</div>\r\n","<div class=\"hw jl\">形式</div><div class=\"def\">(書類や手続きの)formula;(演説の)formae [figurae] dicendi.</div><div class=\"def\">▼<b>～主義, ～張っていること</b> nimia formulae observantia.</div><div class=\"def\">⇒<a href=\"entry://形\">形</a>.</div>\r\n","<div class=\"hw jl\">形態</div><div class=\"def\">⇒<a href=\"entry://形\">形</a>.</div>\r\n","<div class=\"hw jl\">形成</div><div class=\"def\">conformatio.</div><div class=\"def\">▼<b>～する</b> conformo, formo.</div>\r\n","<div class=\"hw jl\">形状</div><div class=\"def\">forma.</div><div class=\"def\">⇒<a href=\"entry://形\">形</a>.</div>\r\n","<div class=\"hw jl\">彩る</div><div class=\"def\">coloro, distinguo.</div>\r\n","<div class=\"hw jl\">彫る</div><div class=\"def\">sculpo, exsculpo.</div>\r\n","<div class=\"hw jl\">彫像</div><div class=\"def\">statua.</div>\r\n","<div class=\"hw jl\">彫刻</div><div class=\"def\">(芸術)sculptura, statuaria ars;(作品)res sculpta.</div><div class=\"def\">▼<b>～する</b> sculpo.</div><div class=\"def\">▼<b>～家</b> sculptor.</div><div class=\"def\">⇒<a href=\"entry://彫る\">彫る</a>,<a href=\"entry://彫像\">彫像</a>.</div>\r\n","<div class=\"hw jl\">影響</div><div class=\"def\">momentum;(=影響力)vis, potentia, auctoritas.</div><div class=\"ex2\">(...において)～力がある<span class=\"ext\">possum 〈+<i>abl</i>〉.</span></div><div class=\"ex2\">(...に)～を及ぼす<span class=\"ext\">〈ad alqd〉 momentum affero [habeo], valeo, 〈alqm〉 moveo.</span></div>\r\n","<div class=\"hw jl\">役</div><div class=\"def\">(芝居の)pars, persona.</div><div class=\"def\">⇒<a href=\"entry://演じる\">演じる</a>.</div>\r\n","<div class=\"hw jl\">役割</div><div class=\"def\">pars, persona</div>\r\n","<div class=\"hw jl\">役所</div><div class=\"def\">publica sedes, publica statio.</div>\r\n","<div class=\"hw jl\">役立つ</div><div class=\"def\"><span class=\"pos3\">[動]</span>(=有益である)(...に)〈alci〉 prosum, 〈alci;ad alqd〉 usui sum, 〈ad alqd〉 usum affero, utilitatem habeo, proficio.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> utilis.</div><div class=\"def\">▼<b>～こと</b> utilitas.</div><div class=\"ex2\">何の役にも立たない男<span class=\"ext\">homo ad nullam rem utilis.</span></div>\r\n","<div class=\"hw jl\">役者</div><div class=\"def\">actor, scaenicus, histrio.</div>\r\n","<div class=\"hw jl\">彼</div><div class=\"def\">(=その男, あの男, この男)is, ille, hic.</div><div class=\"def\">▼<b>～の</b> ejus.</div><div class=\"def\">▼<b>～らの</b> eorum.</div><div class=\"def\">▼(再帰的に)<b> ～(ら)の</b>(=自分の)suus.</div><div class=\"def\">⇒<a href=\"entry://彼女\">彼女</a>.</div>\r\n","<div class=\"hw jl\">彼女</div><div class=\"def\">ea(is の女性形), illa(ille の 女性形), haec(hic の女性形).</div><div class=\"def\">▼<b>～の</b> ejus.</div><div class=\"def\">▼<b>～らの</b> earum.</div><div class=\"def\">▼(再帰的に)<b> ～(ら)の</b>(=自分の)suus.</div><div class=\"def\">⇒<a href=\"entry://彼\">彼</a>.</div>\r\n","<div class=\"hw jl\">往復</div><div class=\"def\">itus et reditus.</div><div class=\"def\">▼<b>～する</b> eo et redeo [revenio].</div>\r\n","<div class=\"hw jl\">征服</div><div class=\"def\">▼<b>～する</b> vinco;(軍隊によって)(armis)subigo;(戦争によって)(bello)capio.</div><div class=\"def\">▼<b>～者</b> victor.</div>\r\n","<div class=\"hw jl\">待つ</div><div class=\"def\">(...を)〈+<i>acc</i>〉 opperior(<i>dep</i>), exspecto, 〈+<i>dat</i>〉 praestolor(<i>dep</i>).</div><div class=\"ex2\">しばらく待って下さい<span class=\"ext\">paulisper mane.</span></div><div class=\"ex2\">それはいつまで待っても無駄だ(=それはギリシアの朔日になされる)<span class=\"ext\">ad Kalendas Graecas id fiet.</span></div><div class=\"ex2\">私は待ちくたびれた<span class=\"ext\">lassus sum durando.</span></div>\r\n","<div class=\"hw jl\">待伏せ</div><div class=\"def\">insidiae(<i>pl</i>).</div><div class=\"def\">▼<b>～する者</b>(=伏兵)insidiator.</div><div class=\"def\">▼<b>～の</b> insidiosus.</div><div class=\"def\">▼<b>～する, ～している</b> in insidiis consisto [lateo], insidior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">待合わせ</div><div class=\"def\">(=約束)constitutum.</div><div class=\"def\">▼<b>～場所</b> locus ad conveniendum edictus.</div><div class=\"ex2\">彼は～の日にやって来た<span class=\"ext\">quo die ad conveniendum edixerat venit.</span></div><div class=\"ex2\">～の時間と場所を決める<span class=\"ext\">tempus locumque coeundi condico.</span></div><div class=\"ex2\">(人と)～がある<span class=\"ext\">〈cum alqo〉 constitutum habeo.</span></div><div class=\"ex2\">～に遅れてやって来る<span class=\"ext\">sero ad constitutum venio.</span></div>\r\n","<div class=\"hw jl\">待合室</div><div class=\"def\">(駅などの)oecus profectionem praestolantium, oecus exspectantium [proficiscentium].</div>\r\n","<div class=\"hw jl\">後</div><div class=\"def\">▼(...の[...した])<b>～で</b> postquam 〈+<i>ind</i>〉, posteaquam 〈+<i>ind</i>〉, cum 〈+<i>subj</i>〉.</div><div class=\"def\">▼<b>～で</b> post.</div><div class=\"def\">▼<b>その～で</b> postea.</div>\r\n","<div class=\"hw jl\">後</div><div class=\"def\">▼<b>～に</b> post, postea.</div><div class=\"def\">⇒<a href=\"entry://後\">後<SUB>あと</SUB></a>.</div>\r\n","<div class=\"hw jl\">後ろ</div><div class=\"def\">(...の)<b>～に</b> pone 〈+<i>acc</i>〉, post 〈+<i>acc</i>〉.</div><div class=\"def\">▼<b>～に</b> pone, post.</div><div class=\"def\">▼<b>～へ</b> rursum, rursus, retrorsum.</div><div class=\"def\">▼<b>～向きに</b> retro.</div><div class=\"ex2\">前にも～にも<span class=\"ext\">et ante et pone.</span></div><div class=\"def\">⇒<a href=\"entry://背後\">背後</a>.</div>\r\n","<div class=\"hw jl\">後世</div><div class=\"def\">▼<b>～(の人々)</b> posteritas, posteri(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">後半</div><div class=\"def\">posterior dimidia pars.</div><div class=\"def\">⇒<a href=\"entry://前半\">前半</a>.</div>\r\n","<div class=\"hw jl\">後回し</div><div class=\"def\">(=延期)dilatio, prolatio.</div><div class=\"def\">▼<b>～にする</b>(=延期する)differo, profero.</div>\r\n","<div class=\"hw jl\">後悔</div><div class=\"def\">paenitentia.</div><div class=\"def\">▼(人が...を)<b> ～する</b> 〈alqm alcis rei〉 paenitet(<i>impers</i>).</div>\r\n","<div class=\"hw jl\">後戻り</div><div class=\"def\">retrogradatio, retrogressus.</div><div class=\"def\">▼<b>～する</b> retrogradior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">後援</div><div class=\"def\">patrocinium.</div><div class=\"def\">⇒<a href=\"entry://支援\">支援</a>,<a href=\"entry://応援\">応援</a>,<a href=\"entry://援助\">援助</a>.</div>\r\n","<div class=\"hw jl\">後方</div><div class=\"def\">▼(...の)<b>～に</b> post 〈+<i>acc</i>〉, pone 〈+<i>acc</i>〉.</div><div class=\"def\">▼<b>～に</b> post.</div>\r\n","<div class=\"hw jl\">後期</div><div class=\"def\">(学校の)secundum semestre;(人生の)(vitae)extrema tempora.</div><div class=\"def\">⇒<a href=\"entry://前期\">前期</a>.</div>\r\n","<div class=\"hw jl\">後継</div><div class=\"def\">successio.</div><div class=\"def\">▼<b>～者</b> successor.</div>\r\n","<div class=\"hw jl\">後継ぎ</div><div class=\"def\">(=相続人, 後継者)heres, successor.</div><div class=\"def\">▼<b>後を継ぐ</b> succedo.</div><div class=\"def\">⇒<a href=\"entry://相続\">相続</a>.</div>\r\n","<div class=\"hw jl\">後衛</div><div class=\"def\">novissima [extrema] acies, novissimum [extremum] agmen.</div>\r\n","<div class=\"hw jl\">後退</div><div class=\"def\">regressus.</div><div class=\"def\">▼<b>～する</b> regredior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://退却\">退却</a>.</div>\r\n","<div class=\"hw jl\">後部</div><div class=\"def\">pars posterior.</div>\r\n","<div class=\"hw jl\">徐々に</div><div class=\"def\">gradatim, sensim, paulatim.</div>\r\n","<div class=\"hw jl\">徒歩</div><div class=\"def\">▼<b>～で</b> pedibus.</div><div class=\"def\">▼<b>～の</b> pedester.</div>\r\n","<div class=\"hw jl\">従う</div><div class=\"def\">oboedio, pareo, sequor(<i>dep</i>), obsequor(<i>dep</i>), obtempero.</div><div class=\"def\">⇒<a href=\"entry://従って\">従って</a>,<a href=\"entry://服従\">服従</a>.</div>\r\n","<div class=\"hw jl\">従って</div><div class=\"def\">(...に)secundum 〈+<i>acc</i>〉, ad 〈+<i>acc</i>〉.</div><div class=\"def\">▼<b>本性</b>(=自然)<b>に～</b> ad [secundum] naturam.</div><div class=\"def\">⇒<a href=\"entry://それゆえに\">それゆえに</a>.</div>\r\n","<div class=\"hw jl\">従業員</div><div class=\"def\">ministri(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">従順</div><div class=\"def\">oboedientia, obsequium.</div><div class=\"def\">▼<b>～な</b> oboediens, obsequens.</div><div class=\"def\">▼<b>～に</b> oboedienter, obsequenter.</div><div class=\"def\">⇒<a href=\"entry://従う\">従う</a>,<a href=\"entry://服従\">服従</a>.</div>\r\n","<div class=\"hw jl\">得</div><div class=\"def\">lucrum.</div><div class=\"def\">⇒<a href=\"entry://利益\">利益</a>,<a href=\"entry://もうける\">もうける</a>.</div>\r\n","<div class=\"hw jl\">得る</div><div class=\"def\">(=手に入れる)acquiro, potior(<i>dep</i>), mereo, mereor(<i>dep</i>), nanciscor(<i>dep</i>), comparo, paro;(努力して)assequor(<i>dep</i>).</div><div class=\"ex2\">(兵士として)報酬を～<span class=\"ext\">stipendia mereor.</span></div><div class=\"ex2\">熱心に得ようと努める<span class=\"ext\">peto.</span></div><div class=\"def\">⇒<a href=\"entry://獲得\">獲得</a>.</div>\r\n","<div class=\"hw jl\">得意</div><div class=\"def\">▼<b>～だ</b>(=熟達している)peritus, sciens, sollers.</div><div class=\"def\">⇒<a href=\"entry://苦手\">苦手</a>.</div>\r\n","<div class=\"hw jl\">復活</div><div class=\"def\">resurrectio.</div><div class=\"def\">▼<b>～する</b> resurgo.</div>\r\n","<div class=\"hw jl\">復讐</div><div class=\"def\">(=報復)ultio, vindicatio.</div><div class=\"def\">▼<b>～する</b> ulciscor, vindico.</div><div class=\"def\">▼<b>～者</b> ultor, vindex.</div>\r\n","<div class=\"hw jl\">循環</div><div class=\"def\">circulatio.</div><div class=\"def\">▼<b>血液～</b> sanguinis circulatio.</div><div class=\"ex2\">～論法を用いる<span class=\"ext\">quasi quodam gyro in argumento utor.</span></div>\r\n","<div class=\"hw jl\">微妙</div><div class=\"def\">subtilitas.</div><div class=\"def\">▼<b>～な</b> subtilis.</div><div class=\"def\">▼<b>～に</b> subtiliter.</div>\r\n","<div class=\"hw jl\">微生物</div><div class=\"def\">microbium.</div><div class=\"def\">▼<b>～学</b> microbiologia, de microbiis donctrina, de microbiorum vita scientia.</div><div class=\"def\">▼<b>～学の</b> microbiologicus, ad microbiologiam attinens.</div>\r\n","<div class=\"hw jl\">微笑</div><div class=\"def\">▼<b>～する</b> subrideo.</div><div class=\"def\">⇒<a href=\"entry://ほほえむ\">ほほえむ</a>.</div>\r\n","<div class=\"hw jl\">徳</div><div class=\"def\">(=美徳)virtus.</div>\r\n","<div class=\"hw jl\">徴兵</div><div class=\"def\">delectus.</div><div class=\"def\">▼<b>～する</b> delectum habeo, deligo.</div>\r\n","<div class=\"hw jl\">徹夜</div><div class=\"def\">vigilia, vigilantia.</div><div class=\"def\">▼<b>～の</b> vigilax, vigil.</div><div class=\"def\">▼<b>～する</b> vigilo.</div>\r\n","<div class=\"hw jl\">徹底的</div><div class=\"def\">▼<b>～に</b> funditus, penitus, radicitus, stirpitus.</div><div class=\"def\">⇒<a href=\"entry://根本\">根本</a>,<a href=\"entry://完全\">完全</a>.</div>\r\n","<div class=\"hw jl\">徹頭徹尾</div><div class=\"def\"><span class=\"pos3\">[副]</span> a terra ad caelum.</div>\r\n","<div class=\"hw jl\">心</div><div class=\"def\">animus, cor, pectus.</div><div class=\"def\">▼<b>～(の底)から</b> ex animo.</div>\r\n","<div class=\"hw jl\">心がける</div><div class=\"def\">curo, curam habeo.</div><div class=\"def\">⇒<a href=\"entry://努力\">努力</a>.</div>\r\n","<div class=\"hw jl\">心理学</div><div class=\"def\">de animo humano doctrina, psychologia.</div><div class=\"def\">▼<b>～者</b> humani animi investigator, psychologus, psychologiae studiosus.</div>\r\n","<div class=\"hw jl\">心臓</div><div class=\"def\">cor.</div>\r\n","<div class=\"hw jl\">心配</div><div class=\"def\">sollicitudo, cura, angor, anxietas.</div><div class=\"def\">▼<b>～する, ～している</b><span class=\"pos3\">[動]</span> curo, sollicito animo sum. <span class=\"pos3\">[形]</span> sollicitus.</div><div class=\"def\">▼<b>～して</b> anxie.</div><div class=\"def\">⇒<a href=\"entry://恐れ\">恐れ</a>,<a href=\"entry://悩む\">悩む</a>,<a href=\"entry://不安\">不安</a>.</div>\r\n","<div class=\"hw jl\">必ず</div><div class=\"def\">(=疑いなく)certe, certo, non dubie;(=必然的に)necessario, necessarie.</div><div class=\"ex2\">～...だ(=不可避的だ)<span class=\"ext\">necesse est 〈+<i>inf</i>;+<i>subj</i>〉, necessarium est 〈+<i>inf</i>〉.</span></div><div class=\"ex2\">～しも...ない(=いつも...であるとは限らない)<span class=\"ext\">non semper.</span></div>\r\n","<div class=\"hw jl\">必修</div><div class=\"def\">▼<b>～の</b> requisitus.</div>\r\n","<div class=\"hw jl\">必然</div><div class=\"def\">▼<b>～(性)</b> necessitas.</div><div class=\"def\">▼<b>～の</b> necessarius.</div><div class=\"def\">▼<b>～的である</b> necesse est.</div><div class=\"def\">▼<b>～的に</b> necessarie, necessario.</div>\r\n","<div class=\"hw jl\">必要</div><div class=\"def\">necessitas, necessitudo, usus.</div><div class=\"def\">▼(...が)<b> ～だ</b> necesse [necessarium] est, opus est 〈+<i>gen</i>;+<i>abl</i>;+<i>acc c. inf</i>〉.</div><div class=\"def\">▼<b>～な</b> necessarius.</div><div class=\"def\">▼<b>～とする</b> egeo.</div><div class=\"ex2\">もし～が生じたならば<span class=\"ext\">si usus veniat.</span></div><div class=\"ex2\">どれだけ～ですか<span class=\"ext\">quanto egeo?</span></div><div class=\"ex2\">(...には)時間が～だ<span class=\"ext\">temporis opus est 〈ad+<i>acc</i>〉.</span></div>\r\n","<div class=\"hw jl\">忍び寄る</div><div class=\"def\">obrepo.</div>\r\n","<div class=\"hw jl\">忍耐</div><div class=\"def\">patientia, tolerantia.</div><div class=\"def\">▼<b>～強い</b> patiens, tolerans, pertinax.</div>\r\n","<div class=\"hw jl\">志</div><div class=\"def\">⇒<a href=\"entry://好意\">好意</a>,<a href=\"entry://親切\">親切</a>,<a href=\"entry://贈物\">贈物</a>,<a href=\"entry://意志・意思\">意志</a>.</div>\r\n","<div class=\"hw jl\">志願</div><div class=\"def\">petitio.</div><div class=\"def\">▼<b>～者</b> petitor, candidatus.</div><div class=\"def\">▼<b>～する</b> peto.</div>\r\n","<div class=\"hw jl\">忘れる</div><div class=\"def\">(...を)〈+<i>acc</i>;+<i>gen</i>〉 obliviscor(<i>dep</i>), 〈+<i>acc</i>〉 ex memoria depono, 〈+<i>gen</i>〉 memoriam depono, 〈+<i>acc</i>〉 non recordor(<i>dep</i>).</div><div class=\"ex2\">私はそのことを忘れた<span class=\"ext\">haec res mea de memoria excidit / haec res meam memoriam fugit.</span></div>\r\n","<div class=\"hw jl\">忙しい</div><div class=\"def\">(=多忙な)negotiosus, operosus.</div>\r\n","<div class=\"hw jl\">応じて</div><div class=\"def\"><span class=\"pos3\">[前]</span>(...に)pro 〈+<i>abl</i>〉.</div><div class=\"ex2\">時と場合に～<span class=\"ext\">pro tempore et pro re.</span></div><div class=\"def\">━<span class=\"pos3\">[接]</span>(...に)prout.</div><div class=\"ex2\">状況の要請に～<span class=\"ext\">prout res postulat.</span></div><div class=\"def\">⇒<a href=\"entry://従って\">従って</a>.</div>\r\n","<div class=\"hw jl\">応じる</div><div class=\"def\">(要求に)respondeo.</div><div class=\"ex2\">(人の)夕食の誘いに～(=誘いを受諾する)<span class=\"ext\">ad cenam promitto 〈alci〉.</span></div>\r\n","<div class=\"hw jl\">応接間</div><div class=\"def\">exedra, salutatorium.</div>\r\n","<div class=\"hw jl\">応援</div><div class=\"def\">(=援助, 支援)auxilium, subsidium;(=声援などによる心理的な励まし)hortatio, exhortatio.</div><div class=\"def\">▼<b>～する</b>(=援助する, 支援する)auxilium fero, subsidium fero;(=鼓舞する, 励ます)hortor(<i>dep</i>), cohortor(<i>dep</i>).</div><div class=\"ex2\">(...を...に)～として送る<span class=\"ext\">submitto 〈alci alqm〉.</span></div>\r\n","<div class=\"hw jl\">応用</div><div class=\"def\">(=適用, 実用, 実践)usus.</div><div class=\"def\">▼<b>～する</b>(=適用する)adhibeo, accommodo.</div><div class=\"ex2\">知識と～<span class=\"ext\">scientia et usus.</span></div>\r\n","<div class=\"hw jl\">忠告</div><div class=\"def\">monitio, monitus, admonitio, consilium.</div><div class=\"def\">▼<b>～する</b> moneo, consilior(<i>dep</i>).</div><div class=\"def\">▼(...に)<b>～を与える</b> 〈alci〉 consilium do.</div><div class=\"def\">▼<b>～者</b> consiliator, consiliarius, monitor.</div><div class=\"ex2\">きみの～どおりに私はしよう<span class=\"ext\">faciam ut mones.</span></div>\r\n","<div class=\"hw jl\">忠実</div><div class=\"def\">fidelitas.</div><div class=\"def\">▼<b>～な</b> fidelis, fidus.</div><div class=\"def\">▼<b>～に</b> fideliter.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">不忠<span class=\"ext\">infidelitas.</span></div><div class=\"cf\">不忠な<span class=\"ext\">infidelis, infidus.</span></div><div class=\"cf\">不忠にも<span class=\"ext\">infideliter.</span></div>\r\n","<div class=\"hw jl\">快い</div><div class=\"def\">suavis, jucundus.</div><div class=\"def\">▼<b>快く</b> libenter, (sua)spontate, (sua)sponte.</div><div class=\"def\">⇒<a href=\"entry://気持\">気持</a>,<a href=\"entry://自発的\">自発的</a>.</div>\r\n","<div class=\"hw jl\">快感</div><div class=\"def\">(=心地よさ)suavitas;(肉体的な)(=快楽)(corporis)voluptas, voluptates(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">快適</div><div class=\"def\">jucunditas.</div><div class=\"def\">▼<b>～な</b> jucundus, commodus.</div><div class=\"def\">▼<b>～に</b> commode.</div>\r\n","<div class=\"hw jl\">念入り</div><div class=\"def\">▼<b>～に</b> diligenter, accurate.</div>\r\n","<div class=\"hw jl\">怒り</div><div class=\"def\">(=立腹)ira, iracundia, stomachus;(=激怒)furor;(=不機嫌)bilis, fel.</div><div class=\"def\">▼<b>怒る</b> irascor(<i>dep</i>), stomachor(<i>dep</i>);(=激怒する)furo.</div><div class=\"def\">▼<b>怒った</b> iratus.</div>\r\n","<div class=\"hw jl\">怒る</div><div class=\"def\">(...に)〈+<i>dat</i>〉 irascor(<i>dep</i>), suscenseo.</div><div class=\"def\">▼<b>怒って</b> irate, cum ira.</div><div class=\"def\">▼<b>怒っている</b> iratus.</div>\r\n","<div class=\"hw jl\">怖い</div><div class=\"def\"><span class=\"pos3\">[形]</span> terribilis, horribilis, horrendus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(=恐れる)timeo.</div><div class=\"def\">⇒<a href=\"entry://恐ろしい\">恐ろしい</a>,<a href=\"entry://恐れる\">恐れる</a>.</div>\r\n","<div class=\"hw jl\">怖がらせる</div><div class=\"def\">terreo.</div><div class=\"def\">▼<b>怖がる</b> terreor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://恐れ\">恐れ</a>,<a href=\"entry://恐怖\">恐怖</a>,<a href=\"entry://驚く\">驚く</a>.</div>\r\n","<div class=\"hw jl\">思いとどまる</div><div class=\"def\">supersedeo.</div>\r\n","<div class=\"hw jl\">思い出</div><div class=\"def\">(=記憶, 回想)memoria, reminiscentia, recordatio.</div>\r\n","<div class=\"hw jl\">思い出す</div><div class=\"def\">reminiscor(<i>dep</i>), recordor(<i>dep</i>).</div><div class=\"def\">▼<b>思い出させる</b> memoro, moneo, admoneo.</div>\r\n","<div class=\"hw jl\">思い込み</div><div class=\"def\">opinio.</div>\r\n","<div class=\"hw jl\">思う</div><div class=\"def\">cogito, arbitror(<i>dep</i>), puto, censeo, reor(<i>dep</i>), habeo, opinor(<i>dep</i>), autumo, credo.</div><div class=\"def\">▼(...と)<b>思われる</b>(=...のようだ)videtur 〈+<i>inf</i>〉, creditur 〈+<i>inf</i>〉.</div><div class=\"def\">⇒<a href=\"entry://期待\">期待</a>,<a href=\"entry://恐れる\">恐れる</a>,<a href=\"entry://みなす\">みなす</a>.</div>\r\n","<div class=\"hw jl\">思わず</div><div class=\"def\">(=うっかり, 軽率にも)imprudenter.</div>\r\n","<div class=\"hw jl\">思想</div><div class=\"def\">sententia.</div><div class=\"def\">▼<b>～家</b> philosophus.</div><div class=\"def\">⇒<a href=\"entry://考え\">考え</a>.</div>\r\n","<div class=\"hw jl\">思春期</div><div class=\"def\">pubertas.</div>\r\n","<div class=\"hw jl\">思案</div><div class=\"def\">cogitatio, commentatio, deliberatio, consilium.</div><div class=\"def\">⇒<a href=\"entry://思考\">思考</a>,<a href=\"entry://熟慮\">熟慮</a>.</div>\r\n","<div class=\"hw jl\">思考</div><div class=\"def\">cogitatio.</div><div class=\"def\">▼<b>～する</b> cogito.</div><div class=\"def\">⇒<a href=\"entry://考える\">考える</a>.</div>\r\n","<div class=\"hw jl\">怠ける</div><div class=\"def\">cesso.</div><div class=\"def\">▼<b>怠け者</b> cessator.</div><div class=\"def\">⇒<a href=\"entry://怠惰\">怠惰</a>,<a href=\"entry://無精\">無精</a>.</div>\r\n","<div class=\"hw jl\">怠る</div><div class=\"def\">neglego.</div><div class=\"ex2\">気をつけるべきことを怠り, ～べきことを行なう<span class=\"ext\">quaedam custodienda omittit, facit omittenda.</span></div>\r\n","<div class=\"hw jl\">怠惰</div><div class=\"def\">pigritia, pigrities, ignavia, inertia, desidia, cessatio.</div><div class=\"def\">▼<b>～な</b> piger, ignavus, iners, desidiosus.</div><div class=\"def\">⇒<a href=\"entry://怠ける\">怠ける</a>.</div>\r\n","<div class=\"hw jl\">怠慢</div><div class=\"def\">⇒<a href=\"entry://怠惰\">怠惰</a>.</div>\r\n","<div class=\"hw jl\">急</div><div class=\"def\">▼<b>～な</b>(=切迫した, 緊急の)subitus, urgens;(=不意な, 突然の)repentinus, repens;(=急斜面の)abruptus, praeruptus, arduus.</div><div class=\"def\">▼<b>～死</b> repentina mors.</div><div class=\"def\">⇒<a href=\"entry://急いで\">急いで</a>,<a href=\"entry://急ぐ\">急ぐ</a>.</div>\r\n","<div class=\"hw jl\">急いで</div><div class=\"def\">cito, festinanter, properanter, raptim, rapte, rapide, cum celeritate.</div><div class=\"def\">⇒<a href=\"entry://速い\">速い</a>.</div>\r\n","<div class=\"hw jl\">急ぐ</div><div class=\"def\">festino, propero;(=急行する)contendo, advolo.</div><div class=\"def\">▼<b>急がせる</b> maturo.</div><div class=\"def\">▼<b>～こと</b> festinatio, properatio.</div><div class=\"def\">▼<b>大急ぎで</b> summa celeritate.</div><div class=\"def\">⇒<a href=\"entry://急\">急</a>.</div>\r\n","<div class=\"hw jl\">急性</div><div class=\"def\">▼<b>～の</b> acutus.</div><div class=\"def\">▼<b>～の病気</b> morbus acutus.</div>\r\n","<div class=\"hw jl\">性</div><div class=\"def\">▼(自分の)<b> ～に合わない</b> non convenire(← convenio)suis moribus.</div><div class=\"def\">⇒<a href=\"entry://性格\">性格</a>.</div>\r\n","<div class=\"hw jl\">性</div><div class=\"def\">sexus.</div><div class=\"def\">▼<b>～の</b> sexualis.</div>\r\n","<div class=\"hw jl\">性交</div><div class=\"def\">concubitus, nuptiae(<i>pl</i>), nuptus, venus, coitus, coitio.</div>\r\n","<div class=\"hw jl\">性格</div><div class=\"def\">ingenium, mos, animus.</div>\r\n","<div class=\"hw jl\">性質</div><div class=\"def\">habitus, natura.</div><div class=\"def\">▼<b>そのような～の</b> talis.</div><div class=\"def\">▼<b>どのような～の</b> qualis.</div>\r\n","<div class=\"hw jl\">怪しい</div><div class=\"def\">suspiciosus, suspectus, ambiguus, incertus.</div>\r\n","<div class=\"hw jl\">怪我</div><div class=\"def\">vulnus, sauciatio.</div><div class=\"def\">▼(肩を)<b>～した</b> vulneratus(umerum).</div><div class=\"def\">▼<b>～をする</b> se vulnerare(← vulnero), saucior(<i>pass</i>).</div><div class=\"def\">▼(人に)<b>～をさせる</b> 〈alqm〉 vulnero, saucio, 〈alci〉 vulnus infligo.</div><div class=\"def\">⇒<a href=\"entry://傷\">傷</a>.</div>\r\n","<div class=\"hw jl\">怪物</div><div class=\"def\">monstrum, prodigium, corpus prodigiosum, belua;(海の)cetus.</div>\r\n","<div class=\"hw jl\">怪獣</div><div class=\"def\">⇒<a href=\"entry://怪物\">怪物</a>.</div>\r\n","<div class=\"hw jl\">恋</div><div class=\"def\">amor.</div><div class=\"def\">▼<b>～をする</b> amo, amore capior(<i>pass</i>).</div><div class=\"def\">▼<b>～の炎</b> ardor, flamma.</div><div class=\"ex2\">～のために狂う<span class=\"ext\">ex amore insano.</span></div><div class=\"def\">⇒<a href=\"entry://恋愛\">恋愛</a>,<a href=\"entry://愛\">愛</a>.</div>\r\n","<div class=\"hw jl\">恋人</div><div class=\"def\">⇒<a href=\"entry://愛人\">愛人</a>.</div>\r\n","<div class=\"hw jl\">恋愛</div><div class=\"def\">amor.</div><div class=\"def\">▼<b>～関係</b> necessitudo amatoria.</div>\r\n","<div class=\"hw jl\">恍惚</div><div class=\"def\">exstasis.</div>\r\n","<div class=\"hw jl\">恐れ</div><div class=\"def\">formido, metus, timor.</div><div class=\"def\">⇒<a href=\"entry://心配\">心配</a>.</div>\r\n","<div class=\"hw jl\">恐れる</div><div class=\"def\">paveo, formido, reformido, horreo, vereor(<i>dep</i>), metuo, timeo.</div><div class=\"ex2\">死は～べきではない<span class=\"ext\">mors non metuenda est.</span></div>\r\n","<div class=\"hw jl\">恐ろしい</div><div class=\"def\">terribilis, terrificus, formidabilis, horribilis, horridus, horrificus.</div>\r\n","<div class=\"hw jl\">恐怖</div><div class=\"def\">timor, terror, pavor, metus, formido.</div><div class=\"def\">⇒<a href=\"entry://恐れる\">恐れる</a>,<a href=\"entry://恐ろしい\">恐ろしい</a>.</div>\r\n","<div class=\"hw jl\">恒例</div><div class=\"def\">▼<b>～の</b> consuetus.</div>\r\n","<div class=\"hw jl\">恥</div><div class=\"def\">(=恥辱, 不名誉)dedecus, flagitium, probrum, labes, macula, ignominia, infamia;(=廉恥心, 羞恥心)pudor, verecundia.</div><div class=\"def\">▼<b>～を知る</b>(=慎み深い)pudicus.</div><div class=\"def\">⇒<a href=\"entry://不名誉\">不名誉</a>.</div>\r\n","<div class=\"hw jl\">恥じる</div><div class=\"def\">pudeo;(...することを)erubesco 〈+<i>inf</i>〉;(...が)(...を)〈alqm alcis rei〉 pudet(<i>impers</i>).</div><div class=\"ex2\">彼らは自分たちの不名誉を恥じていない<span class=\"ext\">eos infamiae suae non pudet.</span></div>\r\n","<div class=\"hw jl\">恥ずかしい</div><div class=\"def\"><span class=\"pos3\">[形]</span>(=恥ずべき)turpis, deformis, pudendus, erubescendus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(人にとってある物事が)〈alqm alcis rei;+<i>inf</i>〉 pudet(<i>impers</i>).</div><div class=\"ex2\">言うのも～こと<span class=\"ext\">quod pudet dicere.</span></div><div class=\"def\">⇒<a href=\"entry://恥じる\">恥じる</a>.</div>\r\n","<div class=\"hw jl\">恥ずかしがり</div><div class=\"def\">▼<b>～の</b> pudibundus.</div>\r\n","<div class=\"hw jl\">恥知らず</div><div class=\"def\">▼<b>～な</b> impudens.</div><div class=\"def\">▼<b>～である</b> non erubesco.</div><div class=\"def\">⇒<a href=\"entry://厚かましい\">厚かましい</a>.</div>\r\n","<div class=\"hw jl\">恨み</div><div class=\"def\">(=隠された憎しみ)simultas.</div>\r\n","<div class=\"hw jl\">恨む</div><div class=\"def\">(...を)habeo simultatem 〈cum+<i>abl</i>〉.</div>\r\n","<div class=\"hw jl\">恩寵</div><div class=\"def\">gratia.</div>\r\n","<div class=\"hw jl\">恩恵</div><div class=\"def\">beneficium.</div><div class=\"ex2\">(...から)多くの～をこうむる<span class=\"ext\">〈ab+<i>abl</i>〉 multa beneficia accipio.</span></div>\r\n","<div class=\"hw jl\">息</div><div class=\"def\">spiritus, halitus, flatus.</div><div class=\"def\">▼<b>～をする</b> spiro.</div>\r\n","<div class=\"hw jl\">息切れ</div><div class=\"def\">anhelitus, anhelatio.</div><div class=\"def\">▼<b>～した</b> anhelans.</div><div class=\"ex2\">走って～した<span class=\"ext\">cursu exanimatus.</span></div>\r\n","<div class=\"hw jl\">息子</div><div class=\"def\">filius.</div><div class=\"ex2\">それは私の～ではない, 兄弟の～だ<span class=\"ext\">ex me hic natus est sed ex fratre.</span></div>\r\n","<div class=\"hw jl\">恵み</div><div class=\"def\">(=施し, あわれみ)eleemosyna;(=恩恵)beneficium, gratia;(=祝福)benedictio.</div><div class=\"def\">⇒<a href=\"entry://恩寵\">恩寵</a>,<a href=\"entry://祝福\">祝福</a>.</div>\r\n","<div class=\"hw jl\">悔しさ</div><div class=\"def\">(=後悔)paenitentia.</div>\r\n","<div class=\"hw jl\">悔やみ</div><div class=\"def\">consolatio.</div><div class=\"ex2\">～の手紙(=弔文)<span class=\"ext\">consolatoriae litterae.</span></div>\r\n","<div class=\"hw jl\">悔やむ</div><div class=\"def\">(=悔しい思いをする)〈alqm〉 paenitet(<i>impers</i>).</div><div class=\"def\">⇒<a href=\"entry://後悔\">後悔</a>.</div>\r\n","<div class=\"hw jl\">患者</div><div class=\"def\">aeger, is qui curatur(<i>m</i>), is qui laborat(<i>m</i>).</div>\r\n","<div class=\"hw jl\">悩む</div><div class=\"def\">doleo, laboro.</div><div class=\"def\">▼<b>悩み</b> dolor, molestia.</div><div class=\"def\">⇒<a href=\"entry://心配\">心配</a>.</div>\r\n","<div class=\"hw jl\">悪</div><div class=\"def\">(=害悪)malum;(=悪行)scelus.</div><div class=\"def\">⇒<a href=\"entry://悪い\">悪い</a>.</div>\r\n","<div class=\"hw jl\">悪い</div><div class=\"def\">(=卑劣な, 劣悪な)malus, improbus, pravus.</div><div class=\"def\">⇒<a href=\"entry://悪\">悪</a>.</div>\r\n","<div class=\"hw jl\">悪化</div><div class=\"def\">▼(病気が)<b> ～する</b> ingravesco.</div>\r\n","<div class=\"hw jl\">悪口</div><div class=\"def\">(=誹謗)maledictum, maledictio, convicium, contumelia.</div><div class=\"def\">▼(人の)<b> ～を言う</b>(=誹謗する)〈alci〉 male dico, convicior(<i>dep</i>), 〈in alqm〉 maledicta facio [confero], contumeliam jacio.</div>\r\n","<div class=\"hw jl\">悪夢</div><div class=\"def\">nocturna suppressio.</div>\r\n","<div class=\"hw jl\">悪徳</div><div class=\"def\">vitium.</div><div class=\"def\">⇒<a href=\"entry://美徳\">美徳</a>.</div>\r\n","<div class=\"hw jl\">悪意</div><div class=\"def\">malevolentia, invidia.</div>\r\n","<div class=\"hw jl\">悪用</div><div class=\"def\">abusus.</div><div class=\"def\">▼<b>～する</b> deutor(<i>dep</i>), abutor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">悪臭</div><div class=\"def\">▼<b>～を発する</b><span class=\"pos3\">[動]</span> puteo, foeteo.</div><div class=\"def\"><span class=\"pos3\">[形]</span> puter.</div><div class=\"def\">⇒<a href=\"entry://臭い\">臭い</a>.</div>\r\n","<div class=\"hw jl\">悪魔</div><div class=\"def\">diabolus, daemonium, satan, daemon.</div><div class=\"ex2\">～を祓うこと<span class=\"ext\">exorcismus.</span></div>\r\n","<div class=\"hw jl\">悲しい</div><div class=\"def\">tristis, maestus.</div><div class=\"def\">▼<b>非常に～</b> pertristis.</div><div class=\"def\">▼<b>悲しみ</b>(=悲哀)tristitia, maestitia, maeror.</div><div class=\"def\">▼(...を)<b>悲しむ</b> 〈+<i>acc</i>;+<i>inf</i>〉 maereo, lugeo, doleo.</div><div class=\"def\">⇒<a href=\"entry://寂しい\">寂しい</a>,<a href=\"entry://嘆く\">嘆く</a>.</div>\r\n","<div class=\"hw jl\">悲劇</div><div class=\"def\">tragoedia.</div><div class=\"def\">▼<b>～作家, ～詩人</b> tragicus.</div><div class=\"def\">▼<b>～俳優</b> tragoedus.</div><div class=\"def\">▼<b>～の</b> tragicus.</div>\r\n","<div class=\"hw jl\">悲惨</div><div class=\"def\">miseria.</div><div class=\"def\">▼<b>～な</b> miser, miserabilis.</div>\r\n","<div class=\"hw jl\">悲観</div><div class=\"def\">▼(すべてを)<b> ～する</b>(omnia)in pejorem partem capio.</div>\r\n","<div class=\"hw jl\">情け</div><div class=\"def\">(=同情)misericordia;(=容赦, お情け)venia;(=慈愛)caritas;(=慈悲)benignitas.</div><div class=\"def\">⇒<a href=\"entry://感情\">感情</a>,<a href=\"entry://同情\">同情</a>.</div>\r\n","<div class=\"hw jl\">情けない</div><div class=\"def\">miser, misellus.</div><div class=\"def\">⇒<a href=\"entry://みじめ\">みじめ</a>.</div>\r\n","<div class=\"hw jl\">情け深い</div><div class=\"def\">(=慈悲深い)benevolens, benignus.</div><div class=\"def\">▼<b>情け深さ</b> benevolentia, benignitas.</div>\r\n","<div class=\"hw jl\">情報</div><div class=\"def\">⇒<a href=\"entry://知らせる\">知らせる</a>.</div>\r\n","<div class=\"hw jl\">情熱</div><div class=\"def\">calor, ardor.</div><div class=\"def\">⇒<a href=\"entry://熱意\">熱意</a>.</div>\r\n","<div class=\"hw jl\">惑わす</div><div class=\"def\">in errorem induco, fascino, effascino, perturbo.</div>\r\n","<div class=\"hw jl\">惑星</div><div class=\"def\">stella errans [errantica], astrum errans.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">月<span class=\"ext\">luna.</span></div><div class=\"cf\">火星<span class=\"ext\">Martis stella.</span></div><div class=\"cf\">水星<span class=\"ext\">Mercurii stella.</span></div><div class=\"cf\">木星<span class=\"ext\">Juppiter.</span></div><div class=\"cf\">金星<span class=\"ext\">Veneris stella, Hesperus, vesperugo, vesper.</span></div><div class=\"cf\">土星<span class=\"ext\">Saturnia stella.</span></div><div class=\"def\">⇒<a href=\"entry://星\">星</a>.</div>\r\n","<div class=\"hw jl\">惚れ薬</div><div class=\"def\">amatorium(medicamentum), philtrum.</div>\r\n","<div class=\"hw jl\">惜しむ</div><div class=\"def\">(=大切にする, 節約する)(...を)parco 〈+<i>dat</i>〉;(人の不在などを)desidero.</div><div class=\"def\">▼<b>～こと</b>(=物惜しみ, 節約, 倹約, けち)parsimonia.</div><div class=\"def\">▼(人の不在などを)<b>～気持</b> desiderium.</div><div class=\"ex2\">労力を惜しまない<span class=\"ext\">non parco labori.</span></div><div class=\"def\">⇒<a href=\"entry://倹約\">倹約</a>,<a href=\"entry://節約\">節約</a>.</div>\r\n","<div class=\"hw jl\">惨事</div><div class=\"def\">calamitas, clades.</div><div class=\"def\">▼<b>大～</b> magna clades.</div><div class=\"def\">⇒<a href=\"entry://災難\">災難</a>,<a href=\"entry://災い\">災い</a>.</div>\r\n","<div class=\"hw jl\">想像</div><div class=\"def\">▼<b>～する</b> commentor(<i>dep</i>), imaginor(<i>dep</i>), fingo.</div><div class=\"def\">▼<b>～上の</b> commenticius.</div><div class=\"def\">⇒<a href=\"entry://虚構\">虚構</a>.</div>\r\n","<div class=\"hw jl\">愉快</div><div class=\"def\">▼<b>～な</b>(=楽しい, 陽気な)laetus, hilarus, hilaris, festivus.</div>\r\n","<div class=\"hw jl\">意に反した</div><div class=\"def\">invitus.</div><div class=\"def\">▼(私の)<b> 意に反して</b> me invito.</div>\r\n","<div class=\"hw jl\">意味</div><div class=\"def\">significatio.</div><div class=\"def\">▼<b>ことばの～</b> vis verborum.</div><div class=\"def\">▼<b>～する</b> significo, sono.</div><div class=\"def\">▼<b>～深い</b> significans.</div><div class=\"ex2\">このことばの～は何ですか<span class=\"ext\">quid haec vox sonat?</span></div>\r\n","<div class=\"hw jl\">意図</div><div class=\"def\">consilium, propositum, mens, sententia.</div>\r\n","<div class=\"hw jl\">意地</div><div class=\"def\">▼<b>～になる</b>(=意地を張る)se offirmare(← offirmo), in sententia persto [permaneo].</div><div class=\"ex2\">～を張るのをやめる<span class=\"ext\">pertinaciā desisto.</span></div><div class=\"def\">⇒<a href=\"entry://頑固\">頑固</a>.</div>\r\n","<div class=\"hw jl\">意地悪</div><div class=\"def\">malevolentia.</div><div class=\"def\">▼<b>～な</b> malevolens, malevolus.</div>\r\n","<div class=\"hw jl\">意外</div><div class=\"def\">▼<b>～な</b>(=思いがけない, 不測の)inexspectatus, inopinatus, inopinus, improvisus.</div><div class=\"def\">▼<b>～に</b>(=予期に反して)ex inopinato, de [ex] improviso.</div>\r\n","<div class=\"hw jl\">意志・意思</div><div class=\"def\">(=自由な意志)voluntas, spons;(=考え, 意図)consilium, animus.</div><div class=\"def\">⇒<a href=\"entry://考え\">考え</a>.</div>\r\n","<div class=\"hw jl\">意欲</div><div class=\"def\">studium.</div><div class=\"def\">▼<b>～的な</b> studiosus.</div><div class=\"def\">▼<b>～的に</b> studiose.</div><div class=\"def\">⇒<a href=\"entry://意志・意思\">意志</a>.</div>\r\n","<div class=\"hw jl\">意気</div><div class=\"def\">animus.</div><div class=\"ex2\">(人の)～をくじく<span class=\"ext\">〈alcis〉 animum affligo [frango, infringo, demitto].</span></div><div class=\"def\">⇒<a href=\"entry://気力\">気力</a>.</div>\r\n","<div class=\"hw jl\">意気消沈</div><div class=\"def\">animi debilitatio [infractio].</div><div class=\"def\">▼<b>～する</b> animo frangor(<i>pass</i>).</div><div class=\"def\">▼<b>～した</b> afflictus, tristis.</div>\r\n","<div class=\"hw jl\">意見</div><div class=\"def\">opinio, sententia.</div><div class=\"ex2\">私の～<span class=\"ext\">id quod sentio.</span></div><div class=\"ex2\">(人に)～を求める<span class=\"ext\">sententiam rogo 〈alqm〉.</span></div><div class=\"ex2\">彼(女)は私の～を尋ねた<span class=\"ext\">quaesivit quidnam mihi videretur.</span></div>\r\n","<div class=\"hw jl\">意識</div><div class=\"def\">conscientia, animus.</div><div class=\"ex2\">～を失う(=気絶する)<span class=\"ext\">animo linquor(<i>pass</i>).</span></div><div class=\"ex2\">～を取り戻す<span class=\"ext\">animum recipio.</span></div>\r\n","<div class=\"hw jl\">愚か</div><div class=\"def\">▼<b>～な</b> stultus, insipiens.</div><div class=\"def\">▼<b>～さ</b> stultitia, insipientia.</div><div class=\"def\">▼<b>～にも</b> stulte, insipienter.</div>\r\n","<div class=\"hw jl\">愚痴</div><div class=\"def\">questus inutilis [inanis, vanus].</div><div class=\"def\">▼<b>～をこぼす</b> murmuro.</div><div class=\"def\">⇒<a href=\"entry://苦情\">苦情</a>,<a href=\"entry://不平\">不平</a>,<a href=\"entry://ぼやく\">ぼやく</a>.</div>\r\n","<div class=\"hw jl\">愛</div><div class=\"def\">amor, caritas;(特に両親や祖国への)pietas 〈in [erga]+<i>acc</i>;+<i>gen</i>〉.</div><div class=\"ex2\">私たちのあなたへの～<span class=\"ext\">noster in te amor.</span></div><div class=\"ex2\">兄弟～, 同胞～<span class=\"ext\">fraternus amor.</span></div><div class=\"def\">⇒<a href=\"entry://愛する\">愛する</a>,<a href=\"entry://愛情\">愛情</a>,<a href=\"entry://恋\">恋</a>,<a href=\"entry://愛着\">愛着</a>,<a href=\"entry://友情\">友情</a>.</div>\r\n","<div class=\"hw jl\">愛する</div><div class=\"def\"><span class=\"pos3\">[動]</span> amo, diligo, in amore habeo, caritate complector(<i>dep</i>).</div><div class=\"ex2\">愛される, 愛されている<span class=\"ext\">in amore sum.</span></div><div class=\"def\">━<span class=\"pos3\">[形]</span>(=大切な, 親愛な)carus, dilectus;(=いとしい)dulcis.</div><div class=\"ex2\">～人よ, 僕はきみから甘いアンブロシアよりも甘い口づけを盗んだ<span class=\"ext\">subripui tibi, mellite, suaviolum dulci dulcius ambrosia.</span></div><div class=\"def\">⇒<a href=\"entry://好き\">好き</a>,<a href=\"entry://大切\">大切</a>.</div>\r\n","<div class=\"hw jl\">愛の神</div><div class=\"def\">Amor;Cupido;Venus.</div>\r\n","<div class=\"hw jl\">愛人</div><div class=\"def\">(=愛している人)amans, amator;(=愛されている人)amatus(<i>m</i>), amata(<i>f</i>);(=情夫・情婦, 姦夫・姦婦)adulter(<i>m</i>), adultera(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://姦夫・姦婦\">姦夫</a>.</div>\r\n","<div class=\"hw jl\">愛嬌</div><div class=\"def\">⇒<a href=\"entry://魅力\">魅力</a>.</div>\r\n","<div class=\"hw jl\">愛情</div><div class=\"def\">amor, caritas, dilectio.</div><div class=\"def\">⇒<a href=\"entry://愛\">愛</a>.</div>\r\n","<div class=\"hw jl\">愛想</div><div class=\"def\">▼<b>～がいい</b> affabilis, civilis, blandus, comis, facilis.</div><div class=\"def\">▼<b>～のよさ</b> affabilitas, blanditia, comitas.</div><div class=\"def\">▼<b>～よく</b>(もてなす)comiter(accipio).</div><div class=\"ex2\">～よく笑う<span class=\"ext\">blandum rideo.</span></div>\r\n","<div class=\"hw jl\">愛着</div><div class=\"def\">studium.</div><div class=\"def\">⇒<a href=\"entry://愛\">愛</a>,<a href=\"entry://愛情\">愛情</a>.</div>\r\n","<div class=\"hw jl\">愛読書</div><div class=\"def\">dilectus inter ceteros liber.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">(愛読書として)枕の下に本を置いている<span class=\"ext\">suppositos capiti libros habeo.</span></div><div class=\"cf\">(座右の書として)いつもあなたのものであるデモステネス<span class=\"ext\">Demosthenes semper tuus.</span></div>\r\n","<div class=\"hw jl\">感じ</div><div class=\"def\">sensus.</div><div class=\"def\">▼<b>～のいい</b> placens.</div><div class=\"def\">⇒<a href=\"entry://感じる\">感じる</a>.</div>\r\n","<div class=\"hw jl\">感じる</div><div class=\"def\">sentio, percipio.</div><div class=\"def\">⇒<a href=\"entry://感じ\">感じ</a>,<a href=\"entry://知覚\">知覚</a>.</div>\r\n","<div class=\"hw jl\">感動</div><div class=\"def\">animi commotio.</div><div class=\"def\">▼<b>～する</b> commoveor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">感嘆</div><div class=\"def\">admiratio.</div><div class=\"def\">▼<b>～すべき</b> admirabilis.</div><div class=\"def\">▼<b>～する</b> admiror(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">感心</div><div class=\"def\">⇒<a href=\"entry://感嘆\">感嘆</a>.</div>\r\n","<div class=\"hw jl\">感情</div><div class=\"def\">(animi)motus, affectio, affectus.</div>\r\n","<div class=\"hw jl\">感想</div><div class=\"def\">sententia.</div>\r\n","<div class=\"hw jl\">感染</div><div class=\"def\">(=伝染)contagio, contactus.</div><div class=\"ex2\">～によって広まる<span class=\"ext\">contagione vulgor(<i>pass</i>).</span></div>\r\n","<div class=\"hw jl\">感激</div><div class=\"def\">⇒<a href=\"entry://感動\">感動</a>.</div>\r\n","<div class=\"hw jl\">感覚</div><div class=\"def\">sensus.</div><div class=\"def\">⇒<a href=\"entry://感じる\">感じる</a>,<a href=\"entry://気持\">気持</a>.</div>\r\n","<div class=\"hw jl\">感謝</div><div class=\"def\">gratia.</div><div class=\"def\">▼(人に)(あることで)<b>～する</b> 〈alci〉 〈pro re〉 gratias do [ago, habeo], 〈alci〉 gratum se praebere(← praebeo).</div>\r\n","<div class=\"hw jl\">慈善</div><div class=\"def\">caritas, beneficentia, benefactio.</div><div class=\"def\">▼<b>～家</b> benefactor(<i>m</i>), benefactrix(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://親切\">親切</a>.</div>\r\n","<div class=\"hw jl\">慈愛</div><div class=\"def\">caritas, beneficentia.</div><div class=\"def\">⇒<a href=\"entry://親切\">親切</a>,<a href=\"entry://慈善\">慈善</a>.</div>\r\n","<div class=\"hw jl\">態度</div><div class=\"def\">▼(...に対して)<b> 傲慢な～を取る</b> 〈in alqm〉 superbe consulo.</div><div class=\"def\">▼<b>そのような～を取る</b> 〈adversus alqm〉 tali modo se gerere(← gero).</div><div class=\"def\">⇒<a href=\"entry://ふるまう\">ふるまう</a>.</div>\r\n","<div class=\"hw jl\">慎む</div><div class=\"def\">supersedeo.</div>\r\n","<div class=\"hw jl\">慎重</div><div class=\"def\">▼<b>～な</b> consideratus, cautus, prudens, accuratus.</div><div class=\"def\">▼<b>～に</b> considerate, caute, prudenter, pedetentim, sensim.</div>\r\n","<div class=\"hw jl\">慢性</div><div class=\"def\">▼<b>～の</b> chronius, chronicus, vetus.</div><div class=\"def\">▼<b>～の病気</b> morbus diutinus [vetus].</div><div class=\"def\">▼<b>～化する</b> inveterasco.</div>\r\n","<div class=\"hw jl\">慣れる</div><div class=\"def\">assuesco.</div><div class=\"def\">▼<b>慣らす</b> assuefacio.</div><div class=\"def\">▼<b>慣れ</b> assuetudo.</div><div class=\"def\">▼<b>慣れた</b> assuetus.</div>\r\n","<div class=\"hw jl\">慰め</div><div class=\"def\">consolatio, solacium, levatio.</div><div class=\"ex2\">これは私にとって大きな～だ<span class=\"ext\">hoc mihi magno consolatio est.</span></div>\r\n","<div class=\"hw jl\">慰める</div><div class=\"def\">consolor(<i>dep</i>), solor(<i>dep</i>), mulceo, mitigo.</div>\r\n","<div class=\"hw jl\">慰安</div><div class=\"def\">consolatio, solacium, lenimen.</div><div class=\"def\">⇒<a href=\"entry://慰め\">慰め</a>.</div>\r\n","<div class=\"hw jl\">憂鬱</div><div class=\"def\">tristitia, maestitia, atra bilis, bilis nigra.</div><div class=\"def\">▼<b>～な</b> tristis, maestus, melancholicus.</div><div class=\"def\">⇒<a href=\"entry://悲しい\">悲しい</a>.</div>\r\n","<div class=\"hw jl\">憎い</div><div class=\"def\">invisus, invidiosus.</div>\r\n","<div class=\"hw jl\">憎む</div><div class=\"def\">(...を)〈+<i>acc</i>〉 odi, odio habeo.</div><div class=\"def\">▼(...に)<b>憎まれている</b> in odio sum 〈+<i>dat</i>〉.</div><div class=\"def\">▼<b>～べき</b> detestabilis, odiosus, exsecrandus, invisus.</div>\r\n","<div class=\"hw jl\">憤慨</div><div class=\"def\">indignatio.</div><div class=\"def\">▼<b>～する</b> indignor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">憲法</div><div class=\"def\">charta civitatis constitutiva, formae civitatis charta, civitatis forma, rei publicae constitutio.</div>\r\n","<div class=\"hw jl\">憲章</div><div class=\"def\">charta.</div><div class=\"ex2\">大～(マグナカルタ)<span class=\"ext\">Magna Carta [Charta].</span></div>\r\n","<div class=\"hw jl\">憶測</div><div class=\"def\">(=推測)conjectura.</div><div class=\"def\">▼<b>～する</b>(=推測する)conjecto.</div><div class=\"def\">⇒<a href=\"entry://推測\">推測</a>.</div>\r\n","<div class=\"hw jl\">懇願</div><div class=\"def\">prex, obsecratio.</div><div class=\"def\">▼<b>～する</b> imploro, precor(<i>dep</i>), obsecro, oro, obtestor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://嘆願\">嘆願</a>.</div>\r\n","<div class=\"hw jl\">懐かしむ</div><div class=\"def\">desidero.</div>\r\n","<div class=\"hw jl\">懸命</div><div class=\"def\">▼<b>～に</b> enixe.</div>\r\n","<div class=\"hw jl\">懸念</div><div class=\"def\">metus.</div><div class=\"def\">⇒<a href=\"entry://恐れ\">恐れ</a>.</div>\r\n","<div class=\"hw jl\">懸案</div><div class=\"def\">res suspensa.</div><div class=\"def\">▼<b>～の</b> suspensus.</div>\r\n","<div class=\"hw jl\">成り行き</div><div class=\"def\">(事の)cursus(rerum).</div>\r\n","<div class=\"hw jl\">成人</div><div class=\"def\">▼<b>～(の)</b> adultus.</div><div class=\"def\">⇒<a href=\"entry://大人\">大人</a>.</div>\r\n","<div class=\"hw jl\">成分</div><div class=\"def\">pars, res.</div><div class=\"ex2\">薬品の～は以下の通り(...)<span class=\"ext\">medicamentum in quo sunt haec:(...).</span></div>\r\n","<div class=\"hw jl\">成功</div><div class=\"def\">processus, exitus bonus [felix], eventus prosper [bonus], res bene gesta, auctus, prosperitas.</div><div class=\"def\">▼(人が...において)<b>～する</b> 〈alqd〉 bene [prospere] gero;(事が)prospere cedo [procedo, succedo, evenio], bene succedo [cedo], feliciter evenio, bonos exitus habeo.</div><div class=\"ex2\">事業に～する<span class=\"ext\">suum negotium praeclare gerere(← gero).</span></div>\r\n","<div class=\"hw jl\">成年</div><div class=\"def\">⇒<a href=\"entry://成人\">成人</a>.</div>\r\n","<div class=\"hw jl\">成果</div><div class=\"def\">fructus, exitus, effectus.</div><div class=\"def\">⇒<a href=\"entry://結果\">結果</a>,<a href=\"entry://達成\">達成</a>.</div>\r\n","<div class=\"hw jl\">成熟</div><div class=\"def\">maturitas.</div><div class=\"def\">▼<b>～する</b> maturesco.</div><div class=\"def\">▼<b>～させる</b> maturo.</div><div class=\"def\">▼<b>～した</b> maturus.</div>\r\n","<div class=\"hw jl\">成長</div><div class=\"def\">auctus, incrementum.</div><div class=\"def\">▼<b>～する</b> adolesco, cresco, incresco, augesco.</div><div class=\"def\">▼<b>～させる</b> augeo.</div>\r\n","<div class=\"hw jl\">我慢</div><div class=\"def\">patientia.</div><div class=\"def\">▼<b>～する</b> patior(<i>dep</i>), perpetior(<i>dep</i>), sustineo, duro, perduro, fero, perfero.</div><div class=\"def\">⇒<a href=\"entry://根気\">根気</a>,<a href=\"entry://忍耐\">忍耐</a>.</div>\r\n","<div class=\"hw jl\">戦う</div><div class=\"def\">pugno, proelior(<i>dep</i>), dimico, proelium [pugnam] committo.</div><div class=\"def\">▼<b>戦い</b> pugna, dimicatio, proelium, certamen.</div><div class=\"def\">⇒<a href=\"entry://争う\">争う</a>,<a href=\"entry://戦争\">戦争</a>.</div>\r\n","<div class=\"hw jl\">戦争</div><div class=\"def\">bellum, arma(<i>pl</i>), certamen.</div><div class=\"def\">▼<b>～の</b> bellicus.</div><div class=\"def\">▼<b>～犯罪</b> injuria bellica.</div><div class=\"ex2\">～を準備する<span class=\"ext\">bellum paro.</span></div><div class=\"ex2\">～を始める<span class=\"ext\">belli initium facio.</span></div><div class=\"ex2\">～を行なう<span class=\"ext\">bellum gero.</span></div><div class=\"ex2\">～を長引かせる<span class=\"ext\">bellum traho.</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">海戦<span class=\"ext\">bellum navale [maritimum].</span></div><div class=\"cf\">第2次世界大戦<span class=\"ext\">bellum alterum mundanum</span></div><div class=\"def\">⇒<a href=\"entry://宣戦布告\">宣戦布告</a>,<a href=\"entry://内戦\">内戦</a>.</div>\r\n","<div class=\"hw jl\">戦列</div><div class=\"def\">acies.</div>\r\n","<div class=\"hw jl\">戦場</div><div class=\"def\">locus pugnae.</div>\r\n","<div class=\"hw jl\">戦術</div><div class=\"def\">res militaris, ratio [artes] rei militaris [belli], astutia.</div>\r\n","<div class=\"hw jl\">戦闘</div><div class=\"def\">proelium, pugna, certamen.</div><div class=\"def\">▼<b>～隊形</b> acies.</div><div class=\"ex2\">～を交える<span class=\"ext\">certamina [proelia] sero.</span></div><div class=\"def\">⇒<a href=\"entry://戦争\">戦争</a>,<a href=\"entry://戦う\">戦う</a>.</div>\r\n","<div class=\"hw jl\">戯曲</div><div class=\"def\">(=劇)fabula, scaenica fabula.</div>\r\n","<div class=\"hw jl\">戸</div><div class=\"def\">(=戸口)porta, janua, ostium, foris;(=開き戸)fores(<i>pl</i>), valvae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://門\">門</a>,<a href=\"entry://敷居\">敷居</a>,<a href=\"entry://入口\">入口</a>,<a href=\"entry://出口\">出口</a>.</div>\r\n","<div class=\"hw jl\">戸棚</div><div class=\"def\">⇒<a href=\"entry://棚\">棚</a>.</div>\r\n","<div class=\"hw jl\">戻す</div><div class=\"def\">repono, restituo.</div><div class=\"ex2\">旧状に～<span class=\"ext\">in antiquum statum restituo.</span></div>\r\n","<div class=\"hw jl\">戻る</div><div class=\"def\">(...に)〈ad+<i>acc</i>〉 redeo;(...から...へ)se 〈ex re in alqd〉 recipere(← recipio).</div>\r\n","<div class=\"hw jl\">所得</div><div class=\"def\">reditus, quaestus, fructus, merces.</div><div class=\"def\">⇒<a href=\"entry://収入\">収入</a>,<a href=\"entry://もうける\">もうける</a>,<a href=\"entry://給料\">給料</a>.</div>\r\n","<div class=\"hw jl\">所有</div><div class=\"def\">possessio.</div><div class=\"def\">▼<b>～者</b> possessor.</div><div class=\"def\">▼<b>～する, ～している</b> potior(<i>dep</i>), possideo.</div>\r\n","<div class=\"hw jl\">扇</div><div class=\"def\">flabellum.</div><div class=\"def\">▼<b>小さな～</b> flabellulum.</div>\r\n","<div class=\"hw jl\">扇子</div><div class=\"def\">flabellum.</div>\r\n","<div class=\"hw jl\">手</div><div class=\"def\">manus.</div><div class=\"def\">▼<b>右～</b>(manus)dextra.</div><div class=\"def\">▼<b>左～</b>(manus)sinistra.</div><div class=\"def\">▼<b>両～</b> ambae manus.</div>\r\n","<div class=\"hw jl\">手ごろ</div><div class=\"def\">▼<b>～な</b> habilis.</div>\r\n","<div class=\"hw jl\">手伝う</div><div class=\"def\">(...を)〈ad alqd faciendam〉 adjuvo, sublevo.</div><div class=\"def\">⇒<a href=\"entry://助ける\">助ける</a>.</div>\r\n","<div class=\"hw jl\">手入れ</div><div class=\"def\">cura.</div>\r\n","<div class=\"hw jl\">手前</div><div class=\"def\">⇒<a href=\"entry://こちら\">こちら</a>.</div>\r\n","<div class=\"hw jl\">手品</div><div class=\"def\">praestigiae(<i>pl</i>).</div><div class=\"def\">▼<b>～師</b> praestigiator(<i>m</i>).</div>\r\n","<div class=\"hw jl\">手帳</div><div class=\"def\">liber commentarius, memorialis libellus;(=アジェンダ)commentarium;(=日記帳)adversaria(<i>pl</i>);(=片手で持てる書板)pugillares(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://日記\">日記</a>.</div>\r\n","<div class=\"hw jl\">手当て</div><div class=\"def\">cura.</div><div class=\"def\">⇒<a href=\"entry://治療\">治療</a>.</div>\r\n","<div class=\"hw jl\">手本</div><div class=\"def\">exemplum, exemplar.</div>\r\n","<div class=\"hw jl\">手段</div><div class=\"def\">ratio, via, modus, facultas.</div>\r\n","<div class=\"hw jl\">手紙</div><div class=\"def\">epistula, litterae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">手続き</div><div class=\"def\">(正式な)ritus;(法的な)formula.</div><div class=\"def\">▼(正式な)<b>～を踏んで</b> rite.</div>\r\n","<div class=\"hw jl\">手術</div><div class=\"def\">curatio manūs [ex manu].</div>\r\n","<div class=\"hw jl\">手袋</div><div class=\"def\">manuum tegumenta(<i>pl</i>), (tegumenta)digitalia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">手首</div><div class=\"def\">prima palmae pars, carpus.</div>\r\n","<div class=\"hw jl\">才能</div><div class=\"def\">ingenium.</div><div class=\"def\">▼<b>～ある</b> ingeniosus, idoneus.</div><div class=\"def\">⇒<a href=\"entry://能力\">能力</a>.</div>\r\n","<div class=\"hw jl\">打ち上げる</div><div class=\"def\">ad caelum extollo.</div>\r\n","<div class=\"hw jl\">打ち明ける</div><div class=\"def\">(=告白する)confiteor(<i>dep</i>).</div><div class=\"def\">▼<b>打ち明け話</b>(=告白)confessio.</div>\r\n","<div class=\"hw jl\">打ち消す</div><div class=\"def\">(=否定する)nego.</div><div class=\"def\">▼<b>打消し</b>(=否定)negatio.</div><div class=\"def\">▼<b>打消しの</b> negans.</div>\r\n","<div class=\"hw jl\">打ち解ける</div><div class=\"def\">(=慣れ親しむ)(...と)familiariter ago 〈cum+<i>abl</i>〉.</div>\r\n","<div class=\"hw jl\">打つ</div><div class=\"def\">(=叩く)pulso, caedo, ferio;(強く)percutio;(鞭で)verbero.</div><div class=\"def\">▼<b>～こと</b> pulsus, pulsatio.</div><div class=\"ex2\">釘を～(=打ち込む)<span class=\"ext\">clavum pango.</span></div>\r\n","<div class=\"hw jl\">打撃</div><div class=\"def\">ictus.</div><div class=\"def\">⇒<a href=\"entry://損害\">損害</a>.</div>\r\n","<div class=\"hw jl\">払う</div><div class=\"def\">(=支払う)solvo, dissolvo.</div><div class=\"ex2\">(...に)努力を～<span class=\"ext\">〈in alqd〉 operam impendo.</span></div>\r\n","<div class=\"hw jl\">扱う</div><div class=\"def\">(物事を)utor(<i>dep</i>), tracto;(人を...として)(=みなす)(alqm)habeo 〈+<i>adv</i>;pro+<i>abl</i>〉.</div>\r\n","<div class=\"hw jl\">批評</div><div class=\"def\">critica, criticismus.</div><div class=\"def\">▼<b>～家</b> criticus.</div>\r\n","<div class=\"hw jl\">承知</div><div class=\"def\">⇒<a href=\"entry://許す・赦す\">許す</a>,<a href=\"entry://認める\">認める</a>.</div>\r\n","<div class=\"hw jl\">承認</div><div class=\"def\">probatio.</div><div class=\"def\">▼<b>～する人</b> probator.</div><div class=\"def\">▼<b>～する</b> probo, comprobo, agnosco.</div><div class=\"def\">⇒<a href=\"entry://是認\">是認</a>.</div>\r\n","<div class=\"hw jl\">技</div><div class=\"def\">ars.</div><div class=\"def\">▼<b>～に関する</b> ad artem pertinens.</div>\r\n","<div class=\"hw jl\">技術</div><div class=\"def\">ars.</div><div class=\"def\">▼<b>科学～</b> technologia.</div><div class=\"ex2\">～は長く人生は短い<span class=\"ext\">ars longa vita brevis.</span></div><div class=\"ex2\">～の進歩<span class=\"ext\">artium progressus [profectus].</span></div>\r\n","<div class=\"hw jl\">抑制</div><div class=\"def\">coercitio, modus, moderatio.</div><div class=\"def\">▼<b>～する</b> coerceo, freno, moderor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://控えめ\">控えめ</a>.</div>\r\n","<div class=\"hw jl\">抑圧</div><div class=\"def\">oppressio, oppressus.</div><div class=\"def\">▼<b>～する</b> opprimo.</div>\r\n","<div class=\"hw jl\">抒情詩</div><div class=\"def\">lyrica(<i>pl</i>).</div><div class=\"def\">▼<b>～人</b> melicus.</div><div class=\"def\">▼<b>～の</b> lyricus, melicus.</div>\r\n","<div class=\"hw jl\">投げる</div><div class=\"def\">jacio, mitto;(幾度も)jacto;(外へ)eicio, emitto.</div><div class=\"def\">▼<b>投げ込む</b> inicio.</div><div class=\"def\">▼<b>投げ捨てる</b> abicio.</div><div class=\"def\">▼<b>投げ落とす</b> deicio.</div><div class=\"def\">▼<b>投げつける</b> obicio.</div>\r\n","<div class=\"hw jl\">投票</div><div class=\"def\">suffragium, sententia, suffragii latio.</div><div class=\"def\">▼<b>～権</b> suffragium.</div><div class=\"def\">▼<b>～場</b> ovile.</div><div class=\"def\">▼(人に)<b> ～する</b> 〈alci〉 suffragor(<i>dep</i>), suffragium fero [ineo].</div><div class=\"ex2\">～で選出する<span class=\"ext\">suffragio lego [creo].</span></div><div class=\"ex2\">～に行く<span class=\"ext\">ad urnas accedo.</span></div><div class=\"ex2\">大統領選挙の～が行なわれた<span class=\"ext\">suffragium praesidenti creando habitum est.</span></div><div class=\"def\">⇒<a href=\"entry://選挙\">選挙</a>.</div>\r\n","<div class=\"hw jl\">投資</div><div class=\"def\">pecuniae collocatio [occupatio].</div><div class=\"def\">▼<b>～する</b> pecuniam colloco [occupo], pecuniam 〈in alqd;alci rei〉 destino, pecuniae vim 〈in alqd〉 erogo.</div>\r\n","<div class=\"hw jl\">抗争</div><div class=\"def\">conflictio, conflictus.</div><div class=\"def\">▼<b>～する</b> confligo.</div><div class=\"def\">⇒<a href=\"entry://争う\">争う</a>,<a href=\"entry://戦う\">戦う</a>.</div>\r\n","<div class=\"hw jl\">抗生物質</div><div class=\"def\">antibioticum(medicamentum).</div>\r\n","<div class=\"hw jl\">抗議</div><div class=\"def\">reclamatio.</div><div class=\"def\">▼<b>～する</b> reclamo, reclamito.</div><div class=\"def\">⇒<a href=\"entry://異議\">異議</a>,<a href=\"entry://反対\">反対</a>,<a href=\"entry://拒否\">拒否</a>.</div>\r\n","<div class=\"hw jl\">折</div><div class=\"def\">(=機会)occasio.</div>\r\n","<div class=\"hw jl\">折りたたむ</div><div class=\"def\">⇒<a href=\"entry://たたむ\">たたむ</a>.</div>\r\n","<div class=\"hw jl\">折る</div><div class=\"def\">(=曲げて壊す)frango.</div><div class=\"def\">▼<b>骨を～</b>(=努力する)laboro, operor(<i>dep</i>), operam do.</div><div class=\"def\">▼<b>骨を折って</b>(=努力して)operose.</div>\r\n","<div class=\"hw jl\">抜く</div><div class=\"def\">(毛を)(capillos)vello, evello;(歯を)(dentes)eximo, extraho, eruo;(剣を鞘から)(gladium e vagina)educo, destringo.</div>\r\n","<div class=\"hw jl\">抜粋</div><div class=\"def\">excerptio, excerptum, exscripta(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b> excerpo.</div>\r\n","<div class=\"hw jl\">抱く</div><div class=\"def\">(=抱きしめる)complector(<i>dep</i>), amplector(<i>dep</i>), suo complexu tenere(← teneo).</div>\r\n","<div class=\"hw jl\">抵抗</div><div class=\"def\">obstantia, renisus, renitentia.</div><div class=\"def\">▼<b>～する</b> resisto, sisto, obsisto, repugno, obsto, renitor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">押さえる・抑える</div><div class=\"def\">premo;(=捉えて放さない, 止める)retineo;(=抑制する)deprimo, compesco, freno, supprimo, coerceo;(=押さえつける)deprimo.</div><div class=\"ex2\">声を～<span class=\"ext\">vocem supprimo.</span></div>\r\n","<div class=\"hw jl\">押し付ける</div><div class=\"def\">apprimo;(望まないものを)(=負わす)impono, injungo.</div>\r\n","<div class=\"hw jl\">押す</div><div class=\"def\">(=圧力を加える)premo;(=押しつぶす)opprimo;(=力を加えて前進させる, 突き動かす)trudo, pello, impello.</div>\r\n","<div class=\"hw jl\">抽選</div><div class=\"def\">sortitio.</div><div class=\"def\">⇒<a href=\"entry://くじ\">くじ</a>.</div>\r\n","<div class=\"hw jl\">担保</div><div class=\"def\">pignus, cautio.</div><div class=\"def\">▼<b>～に入れる</b> pignero.</div><div class=\"def\">⇒<a href=\"entry://保証\">保証</a>.</div>\r\n","<div class=\"hw jl\">担架</div><div class=\"def\">lectica, lecticula.</div>\r\n","<div class=\"hw jl\">拍子</div><div class=\"def\">modus, modulus, modulatio, numerus.</div><div class=\"def\">▼<b>～に合わせる</b> modulor(<i>dep</i>).</div><div class=\"def\">▼<b>～に合わせて</b> modulate.</div><div class=\"def\">▼<b>～を取って</b> numerose.</div>\r\n","<div class=\"hw jl\">拍手</div><div class=\"def\">(=拍手喝采)plausus, sophos.</div><div class=\"def\">▼<b>～する</b> plaudo.</div><div class=\"def\">▼<b>～する人</b> plausor.</div>\r\n","<div class=\"hw jl\">拒む</div><div class=\"def\">abnuo, nego, recuso.</div><div class=\"def\">⇒<a href=\"entry://断る\">断る</a>,<a href=\"entry://拒絶\">拒絶</a>,<a href=\"entry://拒否\">拒否</a>.</div>\r\n","<div class=\"hw jl\">拒否</div><div class=\"def\">negatio, detrectatio, repudiatio, recusatio.</div><div class=\"def\">▼<b>～する</b> nego, abnego, denego, detrecto, abdico, repudio, recuso, renuo.</div>\r\n","<div class=\"hw jl\">拒絶</div><div class=\"def\">repudiatio, abnuentia, detrectatio.</div><div class=\"def\">▼<b>～する</b> repudio, repello, abnuo, detrecto.</div><div class=\"def\">⇒<a href=\"entry://拒否\">拒否</a>,<a href=\"entry://否定\">否定</a>.</div>\r\n","<div class=\"hw jl\">拘束</div><div class=\"def\">⇒<a href=\"entry://束縛\">束縛</a>,<a href=\"entry://縛る\">縛る</a>.</div>\r\n","<div class=\"hw jl\">招く</div><div class=\"def\">(=招待する)invito, arcesso, voco, devoco, rogo.</div><div class=\"ex2\">昼食に～<span class=\"ext\">ad prandium invito.</span></div>\r\n","<div class=\"hw jl\">招待</div><div class=\"def\">invitatio.</div><div class=\"def\">▼<b>～する</b> invito.</div>\r\n","<div class=\"hw jl\">招集</div><div class=\"def\">convocatio.</div><div class=\"def\">▼<b>～する</b> convoco.</div>\r\n","<div class=\"hw jl\">拡大</div><div class=\"def\">▼<b>～する</b>(=広げる)dilato, extendo, amplio.</div>\r\n","<div class=\"hw jl\">拭く</div><div class=\"def\">(=拭き取る)tergeo, extergeo, detergeo, abstergeo.</div>\r\n","<div class=\"hw jl\">拳</div><div class=\"def\">pugnus, manus in pugnum compressa.</div>\r\n","<div class=\"hw jl\">拳銃</div><div class=\"def\">manuballistula(ignivoma), pistolium.</div><div class=\"def\">⇒<a href=\"entry://銃\">銃</a>.</div>\r\n","<div class=\"hw jl\">拷問</div><div class=\"def\">cruciatus, cruciamentum, tormentum.</div><div class=\"def\">▼<b>～具</b> tormentum.</div><div class=\"def\">▼<b>～にかける</b> crucio.</div>\r\n","<div class=\"hw jl\">拾う</div><div class=\"def\">(=拾い上げる)tollo, sublego;(=拾い集める)colligo.</div>\r\n","<div class=\"hw jl\">持ち上げる</div><div class=\"def\">sublevo.</div>\r\n","<div class=\"hw jl\">持ち主</div><div class=\"def\">(=所有者)possessor(<i>m</i>), possestrix(<i>f</i>), dominus(<i>m</i>), domina(<i>f</i>).</div>\r\n","<div class=\"hw jl\">持ち出す</div><div class=\"def\">effero, egero.</div>\r\n","<div class=\"hw jl\">持ち歩く</div><div class=\"def\">mecum porto.</div>\r\n","<div class=\"hw jl\">持ち物</div><div class=\"def\">(=所有物, 財産)res(propria), proprium, bona(<i>pl</i>);(=荷物, 携行物)sarcinae(<i>pl</i>), impedimenta(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">持ち込む</div><div class=\"def\">importo.</div>\r\n","<div class=\"hw jl\">持ってくる</div><div class=\"def\">affero, adveho.</div>\r\n","<div class=\"hw jl\">持つ</div><div class=\"def\">habeo.</div><div class=\"def\">⇒<a href=\"entry://所有\">所有</a>.</div>\r\n","<div class=\"hw jl\">指</div><div class=\"def\">digitus.</div><div class=\"def\">▼<b>～で数える</b> computo digitis, computo per digitos.</div><div class=\"def\">▼<b>親～</b>(digitus)pollex.</div><div class=\"def\">▼<b>人さし～</b> index(digitus).</div><div class=\"def\">▼<b>中～</b> medius digitus.</div><div class=\"def\">▼<b>薬～</b> anularius digitus.</div><div class=\"def\">▼<b>小～</b> auricularis digitus.</div>\r\n","<div class=\"hw jl\">指さす</div><div class=\"def\">demonstro digito.</div><div class=\"def\">⇒<a href=\"entry://示す\">示す</a>.</div>\r\n","<div class=\"hw jl\">指す</div><div class=\"def\">⇒<a href=\"entry://指さす\">指さす</a>.</div>\r\n","<div class=\"hw jl\">指名</div><div class=\"def\">nominatio, designatio.</div><div class=\"def\">▼<b>～する</b> nomino.</div><div class=\"def\">⇒<a href=\"entry://任命\">任命</a>.</div>\r\n","<div class=\"hw jl\">指図</div><div class=\"def\">dictum.</div><div class=\"def\">▼<b>～する</b> dicto.</div><div class=\"def\">⇒<a href=\"entry://命令\">命令</a>,<a href=\"entry://指示\">指示</a>.</div>\r\n","<div class=\"hw jl\">指定</div><div class=\"def\">designatio.</div><div class=\"def\">▼<b>～する</b> designo.</div>\r\n","<div class=\"hw jl\">指導</div><div class=\"def\">gubernatio, moderatio, administratio.</div><div class=\"def\">▼<b>～者</b> gubernator(<i>m</i>), gubernatrix(<i>f</i>), moderator(<i>m</i>), moderatrix(<i>f</i>).</div><div class=\"def\">▼<b>～する</b> guberno, moderor(<i>dep</i>), administro, praesum.</div><div class=\"def\">⇒<a href=\"entry://指揮\">指揮</a>.</div>\r\n","<div class=\"hw jl\">指揮</div><div class=\"def\">gubernaculum.</div><div class=\"def\">▼<b>～者</b> dux, ductor, administrator, praefectus.</div><div class=\"def\">▼<b>～する</b> duco, ducto, rego, impero, praesum.</div><div class=\"def\">⇒<a href=\"entry://導く\">導く</a>,<a href=\"entry://指導\">指導</a>.</div>\r\n","<div class=\"hw jl\">指摘</div><div class=\"def\">admonitio.</div><div class=\"def\">▼<b>～する</b> admoneo.</div>\r\n","<div class=\"hw jl\">指示</div><div class=\"def\">designatio, indicium, index.</div><div class=\"def\">▼<b>～する</b>(=指し示す)(digito)demonstro, designo;(=命令する)mando.</div><div class=\"def\">⇒<a href=\"entry://指図\">指図</a>,<a href=\"entry://命令\">命令</a>.</div>\r\n","<div class=\"hw jl\">指紋</div><div class=\"def\">impressio digitalis.</div>\r\n","<div class=\"hw jl\">指輪</div><div class=\"def\">anulus.</div><div class=\"def\">▼<b>結婚～</b> anulus nuptialis.</div><div class=\"def\">▼<b>～をはめる</b> anulum induo [digito apto].</div>\r\n","<div class=\"hw jl\">挑戦</div><div class=\"def\">provocatio.</div><div class=\"def\">▼<b>～者</b> provocator.</div><div class=\"def\">▼<b>～する</b> provoco(in pugnam).</div>\r\n","<div class=\"hw jl\">挨拶</div><div class=\"def\">salutatio, salus.</div><div class=\"def\">▼<b>～する</b> saluto, salvere jubeo, consaluto, salutem do [dico].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">(出会ったときに)こんにちは, ごきげんよう<span class=\"ext\">salve, salvus sis(2<i>sg</i>), salvete(2<i>pl</i>)(あるいは別れるときと同じ表現で).</span></div><div class=\"cf\">(別れ際に)さようなら, ごきげんよう, おたっしゃで<span class=\"ext\">vale(2<i>sg</i>), valete(<i>pl</i>)(あるいは出会ったときと同じ表現で).</span></div><div class=\"cf\">(手紙の冒頭で, 書き手が読み手に)挨拶いたします(=こんにちは, 拝啓)<span class=\"ext\">S. P. D.(salutem plurimam dicit の略).</span></div><div class=\"cf\">ガイウス・プリニウスが親愛なるコルネリウス・タキトゥスにご挨拶を<span class=\"ext\">C. Plinius Cornelio Tacito suo s(alutem).</span></div><div class=\"cf\">(手紙末尾で)ごきげんよう(=お体に気をつけて, ご自愛なさいますよう)<span class=\"ext\">vale, bene valeas, valeas(quam)optime, cura ut valeas.</span></div><div class=\"cf\">(歓迎の挨拶)ようこそ, よくいらしてくださいました<span class=\"ext\">carus et exspectatusque venisti.</span></div>\r\n","<div class=\"hw jl\">挫折</div><div class=\"def\">incommodum.</div><div class=\"def\">▼<b>～する</b> non succedo.</div><div class=\"def\">⇒<a href=\"entry://失敗\">失敗</a>,<a href=\"entry://敗北\">敗北</a>.</div>\r\n","<div class=\"hw jl\">振り込む</div><div class=\"def\">(金を)(=支払う)(pecuniam)solvo [numero].</div>\r\n","<div class=\"hw jl\">振り返る</div><div class=\"def\">(=後ろを見る)respicio.</div>\r\n","<div class=\"hw jl\">振る</div><div class=\"def\">quatio, quasso, moveo, agito.</div><div class=\"def\">▼<b>首を～</b>(=拒む)renuo.</div><div class=\"def\">⇒<a href=\"entry://揺する\">揺する</a>.</div>\r\n","<div class=\"hw jl\">振動</div><div class=\"def\">tremor.</div><div class=\"def\">▼<b>～する</b> tremo.</div><div class=\"def\">▼<b>～させる</b> vibro.</div>\r\n","<div class=\"hw jl\">振替</div><div class=\"def\">▼<b>～口座</b> pecuniae depositae circumlatio.</div>\r\n","<div class=\"hw jl\">挽く</div><div class=\"def\">molo.</div>\r\n","<div class=\"hw jl\">挿入</div><div class=\"def\">interpositio.</div><div class=\"def\">▼<b>～する</b> interpono, insero, inserto, immitto.</div>\r\n","<div class=\"hw jl\">捕虜</div><div class=\"def\">captivus(<i>m</i>), captiva(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> captivus.</div>\r\n","<div class=\"hw jl\">捕鯨</div><div class=\"def\">balaenarum venatio.</div><div class=\"def\">▼<b>～船</b> balaenarum venatrix(navis).</div>\r\n","<div class=\"hw jl\">捧げる</div><div class=\"def\">(神々に)consecro, voveo;(人に)offero, praebeo, dedico.</div><div class=\"def\">▼(人に)<b>身を～</b> 〈alci〉 se dedere(← dedo), se addicere(← addico).</div>\r\n","<div class=\"hw jl\">捨てる</div><div class=\"def\">abicio, depono;(子を)(puerum)expono.</div>\r\n","<div class=\"hw jl\">掃く</div><div class=\"def\">verro.</div>\r\n","<div class=\"hw jl\">掃除</div><div class=\"def\">purgatio.</div><div class=\"def\">▼<b>～する</b> purgo.</div><div class=\"def\">▼<b>電気～機</b> pulveris hauritorium.</div>\r\n","<div class=\"hw jl\">授業</div><div class=\"def\">dictata(<i>pl</i>), auditio, praelectio.</div><div class=\"def\">⇒<a href=\"entry://講義\">講義</a>.</div>\r\n","<div class=\"hw jl\">排他的</div><div class=\"def\">▼<b>～な</b> exclusus, exclusivus.</div>\r\n","<div class=\"hw jl\">排斥</div><div class=\"def\">exclusio, anathema.</div><div class=\"def\">▼<b>～する</b> excludo, anathematizo.</div><div class=\"def\">⇒<a href=\"entry://破門\">破門</a>,<a href=\"entry://追放\">追放</a>.</div>\r\n","<div class=\"hw jl\">排泄物</div><div class=\"def\">fimus, fimum, stercus, retrimentum, merda.</div><div class=\"def\">⇒<a href=\"entry://尿\">尿</a>,<a href=\"entry://糞\">糞</a>.</div>\r\n","<div class=\"hw jl\">掘る</div><div class=\"def\">fodio.</div><div class=\"def\">⇒<a href=\"entry://くりぬく\">くりぬく</a>.</div>\r\n","<div class=\"hw jl\">掛かっている</div><div class=\"def\">(=ぶら下がっている)pendeo;(=次第である)(...に)〈in re〉 consto.</div>\r\n","<div class=\"hw jl\">掛ける・架ける</div><div class=\"def\">(鉤などに)(=つるす)suspendo;(壁などに)(=釘で固定する)figo;(布団や布を)(=かぶせる)tego, velo;(海峡に橋を)(freto pontem)impono;(川に橋を)(pontem in flumine)facio;(=かけ算をする)multiplico. </div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">2×2<span class=\"ext\">bis bini(<i>pl</i>).</span></div><div class=\"cf\">7×4<span class=\"ext\">quater septini(<i>pl</i>).</span></div><div class=\"cf\">50×3<span class=\"ext\">quinquaginta ter multiplicati(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">採用</div><div class=\"def\">assumptio.</div><div class=\"def\">▼<b>～する</b> assumo, adopto.</div>\r\n","<div class=\"hw jl\">採集</div><div class=\"def\">▼<b>～する</b> colligo, lego.</div>\r\n","<div class=\"hw jl\">探す</div><div class=\"def\">requiro, quaero, exquiro, vestigo, investigo.</div><div class=\"def\">⇒<a href=\"entry://求める\">求める</a>.</div>\r\n","<div class=\"hw jl\">探偵</div><div class=\"def\">indagator, vestigator.</div><div class=\"def\">▼<b>～小説</b> fabula criminalis.</div><div class=\"def\">⇒<a href=\"entry://刑事\">刑事</a>.</div>\r\n","<div class=\"hw jl\">探査</div><div class=\"def\">investigatio.</div><div class=\"def\">▼<b>～する</b> investigo.</div><div class=\"def\">▼<b>～する人</b> investigator(<i>m</i>), investigatrix(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://調査\">調査</a>,<a href=\"entry://探索\">探索</a>.</div>\r\n","<div class=\"hw jl\">探検</div><div class=\"def\">⇒<a href=\"entry://探索\">探索</a>.</div>\r\n","<div class=\"hw jl\">探求</div><div class=\"def\">quaestio, inquisitio, indagatio, disquisitio.</div><div class=\"def\">▼<b>～する</b> quaero, inquiro, indago, disquiro, reperio.</div><div class=\"def\">▼<b>～する人</b> inquisitor.</div><div class=\"def\">⇒<a href=\"entry://研究\">研究</a>.</div>\r\n","<div class=\"hw jl\">探索</div><div class=\"def\">exploratio.</div><div class=\"def\">▼<b>～者</b> explorator.</div><div class=\"def\">▼<b>～する</b> exploro.</div>\r\n","<div class=\"hw jl\">接する</div><div class=\"def\">(境を)<span class=\"pos3\">[動]</span> contingo. <span class=\"pos3\">[形]</span> contiguus.</div><div class=\"def\">⇒<a href=\"entry://隣接\">隣接</a>,<a href=\"entry://隣りあう\">隣りあう</a>.</div>\r\n","<div class=\"hw jl\">接合</div><div class=\"def\">coagmentum.</div><div class=\"def\">▼<b>～する</b> coagmento.</div>\r\n","<div class=\"hw jl\">接触</div><div class=\"def\">contactus, contagio, contagium.</div>\r\n","<div class=\"hw jl\">接近</div><div class=\"def\">adventus, accessus.</div><div class=\"def\">▼<b>～する</b> advento, contingo, accedo.</div><div class=\"def\">⇒<a href=\"entry://近づく\">近づく</a>.</div>\r\n","<div class=\"hw jl\">控えめ</div><div class=\"def\">(=節度)modestia, temperantia, verecundia.</div><div class=\"def\">▼<b>～な</b>(=節度ある, 慎みある)modestus, moderatus, temperatus, pudens, verecundus, modicus, tenuis.</div><div class=\"def\">▼<b>～に</b> modeste, modice, temperate, verecunde, pudenter.</div>\r\n","<div class=\"hw jl\">推定</div><div class=\"def\">⇒<a href=\"entry://推測\">推測</a>.</div>\r\n","<div class=\"hw jl\">推測</div><div class=\"def\">conjectura, conjectio.</div><div class=\"def\">▼<b>～する</b> conjecto, auguro, praesumo.</div><div class=\"ex2\">私の～する限り<span class=\"ext\">quantum ego auguro.</span></div>\r\n","<div class=\"hw jl\">推理小説</div><div class=\"def\">fabula criminalis.</div>\r\n","<div class=\"hw jl\">推薦</div><div class=\"def\">commendatio.</div><div class=\"def\">▼<b>～された</b> commendatus.</div><div class=\"def\">▼<b>～する</b> commendo.</div>\r\n","<div class=\"hw jl\">掲示</div><div class=\"def\">libellus.</div><div class=\"def\">▼<b>～板</b> titulus, tabula.</div><div class=\"def\">▼<b>～する</b> proscribo.</div><div class=\"def\">⇒<a href=\"entry://提示\">提示</a>.</div>\r\n","<div class=\"hw jl\">掻く</div><div class=\"def\">scabo, scalpo, rado.</div><div class=\"def\">⇒<a href=\"entry://こする\">こする</a>,<a href=\"entry://削る\">削る</a>.</div>\r\n","<div class=\"hw jl\">描く</div><div class=\"def\">describo, effingo.</div>\r\n","<div class=\"hw jl\">描写</div><div class=\"def\">descriptio.</div><div class=\"def\">▼<b>～する</b> describo, exprimo, deformo.</div>\r\n","<div class=\"hw jl\">提供</div><div class=\"def\">▼<b>～する</b> do, fero, offero, suffero.</div>\r\n","<div class=\"hw jl\">提出</div><div class=\"def\">▼<b>～する</b> do, ostendo.</div><div class=\"ex2\">彼は人質600人の～を命じる<span class=\"ext\">sescentos obsides dari jubet.</span></div><div class=\"def\">⇒<a href=\"entry://与える\">与える</a>,<a href=\"entry://提供\">提供</a>.</div>\r\n","<div class=\"hw jl\">提案</div><div class=\"def\">propositum, mentio.</div><div class=\"def\">▼<b>～者</b> auctor, lator.</div><div class=\"def\">▼<b>～する</b> fero, propono.</div>\r\n","<div class=\"hw jl\">提示</div><div class=\"def\">propositio.</div><div class=\"def\">▼<b>～する</b> propono.</div><div class=\"def\">⇒<a href=\"entry://掲示\">掲示</a>,<a href=\"entry://示す\">示す</a>.</div>\r\n","<div class=\"hw jl\">揚げる</div><div class=\"def\">(油で)frigo(ex oleo).</div>\r\n","<div class=\"hw jl\">揚げ足</div><div class=\"def\">▼(人の)<b> ～を取る</b>(=失敗を利用する)errore alcis utor [fruor](<i>dep</i>).</div>\r\n","<div class=\"hw jl\">換える</div><div class=\"def\">⇒<a href=\"entry://交換\">交換</a>.</div>\r\n","<div class=\"hw jl\">換気</div><div class=\"def\">ventilatio.</div><div class=\"def\">▼<b>～扇</b> apparatus ventilationis, ventigenum instrumentum.</div>\r\n","<div class=\"hw jl\">握る</div><div class=\"def\">comprehendo, prehendo.</div>\r\n","<div class=\"hw jl\">握手</div><div class=\"def\">▼<b>～する</b> dextras jungere(← jungo).</div>\r\n","<div class=\"hw jl\">援助</div><div class=\"def\">auxilium, adjumentum, ops, suppetiae(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[動]</span> auxilior(<i>dep</i>), adjuvo, auxilium [opem, suppetias] fero. <span class=\"pos3\">[形]</span> auxiliarius, auxiliaris.</div>\r\n","<div class=\"hw jl\">援護</div><div class=\"def\">praesidium.</div><div class=\"def\">▼<b>～する</b> praesideo.</div><div class=\"ex2\">...の～となる<span class=\"ext\">praesidio alci sum.</span></div><div class=\"def\">⇒<a href=\"entry://護衛\">護衛</a>.</div>\r\n","<div class=\"hw jl\">援軍</div><div class=\"def\">auxilia(<i>pl</i>), auxiliares(<i>pl</i>).</div><div class=\"ex2\">彼は第10軍団を～として我が軍に送った<span class=\"ext\">decimam legionem subsidio nostris misit.</span></div><div class=\"def\">⇒<a href=\"entry://援助\">援助</a>.</div>\r\n","<div class=\"hw jl\">揺する</div><div class=\"def\">(=揺り動かす, 振動させる)quatio, quasso, concutio, conquasso.</div>\r\n","<div class=\"hw jl\">揺れる</div><div class=\"def\">(=振動する, 震える)tremo, contremo;(=ぐらぐらする)se jactare(← jacto), jactor(<i>pass</i>), vacillo, nuto.</div>\r\n","<div class=\"hw jl\">損</div><div class=\"def\">⇒<a href=\"entry://損害\">損害</a>,<a href=\"entry://損失\">損失</a>.</div>\r\n","<div class=\"hw jl\">損失</div><div class=\"def\">damnum, amissio, amissus, impendium.</div><div class=\"def\">⇒<a href=\"entry://損害\">損害</a>,<a href=\"entry://収益\">収益</a>.</div>\r\n","<div class=\"hw jl\">損害</div><div class=\"def\">jactura, damnum, detrimentum, incommodum, noxia, noxa, injuria.</div><div class=\"def\">▼<b>～をもたらす</b><span class=\"pos3\">[形]</span> damnosus.</div><div class=\"def\">▼<b>～を与える</b> noceo, damnum facio.</div><div class=\"def\">▼<b>～をこうむる</b> offendo.</div><div class=\"def\">⇒<a href=\"entry://損失\">損失</a>.</div>\r\n","<div class=\"hw jl\">携帯</div><div class=\"def\">▼<b>～の</b> qui facile portari potest.</div><div class=\"def\">▼<b>～電話</b> telephonum [telephonulum] gestabile.</div>\r\n","<div class=\"hw jl\">摩擦</div><div class=\"def\">frictio, fricatio.</div><div class=\"def\">▼<b>～する</b> frico.</div>\r\n","<div class=\"hw jl\">撃つ</div><div class=\"def\">(飛び道具等で)ferio, ico, percutio.</div><div class=\"ex2\">敵を～<span class=\"ext\">adversarium ferio.</span></div>\r\n","<div class=\"hw jl\">撃退</div><div class=\"def\">propulsatio.</div><div class=\"def\">▼<b>～する</b> propulso, repello.</div>\r\n","<div class=\"hw jl\">撤回</div><div class=\"def\">receptus.</div><div class=\"def\">▼<b>～する</b> revoco.</div>\r\n","<div class=\"hw jl\">撤廃</div><div class=\"def\">⇒<a href=\"entry://廃止\">廃止</a>.</div>\r\n","<div class=\"hw jl\">撮影</div><div class=\"def\">▼<b>～する</b> photographice reddo [exprimo], pellicula imprimo.</div><div class=\"def\">⇒<a href=\"entry://写真\">写真</a>,<a href=\"entry://映画\">映画</a>,<a href=\"entry://フィルム\">フィルム</a>.</div>\r\n","<div class=\"hw jl\">操縦</div><div class=\"def\">gubernatio, gubernaculum, regimen.</div><div class=\"def\">▼<b>～する</b> rego, guberno.</div><div class=\"def\">▼<b>～士</b> gubernator.</div><div class=\"def\">▼<b>～室</b> aeronavis scapha, gubernatoris cellula.</div><div class=\"ex2\">飛行機を～する<span class=\"ext\">aeronavem guberno.</span></div><div class=\"def\">⇒<a href=\"entry://運転\">運転</a>.</div>\r\n","<div class=\"hw jl\">支え</div><div class=\"def\">fultura, adminiculum, firmamentum.</div>\r\n","<div class=\"hw jl\">支える</div><div class=\"def\">fulcio, adminiculo, sustineo, sustento.</div>\r\n","<div class=\"hw jl\">支出</div><div class=\"def\">impensa, sumptus, impendium.</div><div class=\"def\">⇒<a href=\"entry://支払い\">支払い</a>.</div>\r\n","<div class=\"hw jl\">支店</div><div class=\"def\">domus domui principali subjecta.</div>\r\n","<div class=\"hw jl\">支度</div><div class=\"def\">⇒<a href=\"entry://準備\">準備</a>.</div>\r\n","<div class=\"hw jl\">支払い</div><div class=\"def\">solutio;(金額)pensio;(完全な)exsolutio;(現金による)repraesentatio.</div>\r\n","<div class=\"hw jl\">支払う</div><div class=\"def\">solvo, pendo, impendo.</div><div class=\"def\">⇒<a href=\"entry://支出\">支出</a>.</div>\r\n","<div class=\"hw jl\">支援</div><div class=\"def\">subsidium, adminiculum.</div><div class=\"def\">▼<b>～する</b> subsidior(<i>dep</i>), adminiculo.</div><div class=\"def\">⇒<a href=\"entry://後援\">後援</a>,<a href=\"entry://援助\">援助</a>.</div>\r\n","<div class=\"hw jl\">支給</div><div class=\"def\">⇒<a href=\"entry://与える\">与える</a>.</div>\r\n","<div class=\"hw jl\">支配</div><div class=\"def\">dominatio, dominatus, potentatus, regnum, moderatio, moderamen.</div><div class=\"def\">▼<b>～力</b> potestas.</div><div class=\"def\">▼<b>～する</b> dominor(<i>dep</i>), potior(<i>dep</i>), occupo;(王として)regno.</div>\r\n","<div class=\"hw jl\">支障</div><div class=\"def\">impedimentum.</div><div class=\"def\">⇒<a href=\"entry://障害\">障害</a>,<a href=\"entry://不都合\">不都合</a>.</div>\r\n","<div class=\"hw jl\">改める</div><div class=\"def\">(=変える)muto, commuto;(=改良する, 改善する)emendo, meliorem facio [reddo], corrigo.</div>\r\n","<div class=\"hw jl\">改善</div><div class=\"def\">correctio, emendatio.</div><div class=\"def\">▼<b>～する</b> corrigo, 〈alqd〉 meliorem facio [reddo].</div>\r\n","<div class=\"hw jl\">改正</div><div class=\"def\">correctio.</div><div class=\"def\">▼<b>～者</b> corrector.</div><div class=\"def\">▼<b>～する</b> corrigo.</div>\r\n","<div class=\"hw jl\">改築</div><div class=\"def\">▼<b>～する</b> reficio.</div><div class=\"ex2\">私はケレス神殿をよりりっぱにより大きく～しなければならない<span class=\"ext\">reficienda est mihi aedes Cereris in melius et in majus.</span></div>\r\n","<div class=\"hw jl\">改良</div><div class=\"def\">emendatio, correctio.</div><div class=\"def\">▼<b>～する</b> emendo, corrigo, (alqd)meliorem facio.</div>\r\n","<div class=\"hw jl\">改造</div><div class=\"def\">▼<b>～する</b> reficio, immuto.</div>\r\n","<div class=\"hw jl\">改革</div><div class=\"def\">(=改正)correctio, emendatio.</div><div class=\"def\">▼<b>～者</b>(=改正者)corrector, emdendator.</div><div class=\"def\">⇒<a href=\"entry://改正\">改正</a>.</div>\r\n","<div class=\"hw jl\">攻める</div><div class=\"def\">⇒<a href=\"entry://攻撃\">攻撃</a>,<a href=\"entry://襲う\">襲う</a>.</div>\r\n","<div class=\"hw jl\">攻撃</div><div class=\"def\">impetus, impugnatio, congressus.</div><div class=\"def\">▼<b>～する</b> oppugno, impugno, invado, impeto, aggredior(<i>dep</i>);(投石機で)(tormentis)verbero.</div>\r\n","<div class=\"hw jl\">攻略</div><div class=\"def\">oppugnatio, expugnatio.</div><div class=\"def\">▼<b>～する</b> oppugno, expugno.</div><div class=\"def\">⇒<a href=\"entry://征服\">征服</a>.</div>\r\n","<div class=\"hw jl\">放す</div><div class=\"def\">(手から物を)(alqd manibus)emitto;(=解放する)remitto.</div>\r\n","<div class=\"hw jl\">放免</div><div class=\"def\">absolutio.</div><div class=\"def\">▼<b>～する</b> absolvo.</div>\r\n","<div class=\"hw jl\">放射</div><div class=\"def\">(光の)radiatio.</div><div class=\"def\">▼<b>～線</b> radiatio, radiorum emissio et propagatio, radiationis quantitas.</div><div class=\"def\">▼<b>～状の</b> radiatus.</div><div class=\"def\">▼(光が)<b> ～する</b><span class=\"pos3\">[動]</span> radio. <span class=\"pos3\">[形]</span> radians.</div>\r\n","<div class=\"hw jl\">放射能</div><div class=\"def\">irradians vis, vis radiis agens.</div><div class=\"def\">▼<b>～の</b> radiante vi agens [praeditus].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">放射性元素<span class=\"ext\">elementa radioactiva(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">放棄</div><div class=\"def\">relictio, derelictio, desertio.</div><div class=\"def\">▼<b>～する</b> relinquo, depono, desero.</div>\r\n","<div class=\"hw jl\">放浪</div><div class=\"def\">(生活)vagatio, vagandi mos.</div><div class=\"def\">▼<b>～者</b> vagus(<i>m</i>).</div><div class=\"def\">▼<b>～する</b> vagor(<i>dep</i>), peragro.</div>\r\n","<div class=\"hw jl\">放送</div><div class=\"def\">(番組)emissio.</div><div class=\"def\">▼<b>テレビ[ラジオ]～</b> televisifica [radiophonica] divulgatio.</div><div class=\"def\">▼<b>テレビ[ラジオ]～局</b> statio televisifica [radiophonica] emissoria.</div><div class=\"def\">▼<b>～する</b> divulgo.</div>\r\n","<div class=\"hw jl\">政党</div><div class=\"def\">⇒<a href=\"entry://党派\">党派</a>.</div>\r\n","<div class=\"hw jl\">政治</div><div class=\"def\">res publica, res publicae(<i>pl</i>), res politica.</div><div class=\"def\">▼<b>～学</b> civilis prudentia, civilis scientia, ars politica.</div><div class=\"def\">▼<b>～(上)の, ～的な</b> politicus.</div><div class=\"def\">⇒<a href=\"entry://政策\">政策</a>.</div>\r\n","<div class=\"hw jl\">政策</div><div class=\"def\">consilium, ratio, ratio politica, ratio rei publicae gerendae, in re politica consilia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">故人</div><div class=\"def\">(homo)mortuus(<i>m</i>), (femina)mortua(<i>f</i>), defunctus(<i>m</i>).</div>\r\n","<div class=\"hw jl\">故国</div><div class=\"def\">⇒<a href=\"entry://祖国\">祖国</a>,<a href=\"entry://故郷\">故郷</a>.</div>\r\n","<div class=\"hw jl\">故郷</div><div class=\"def\">patria.</div><div class=\"def\">▼<b>～の</b> patrius.</div><div class=\"def\">⇒<a href=\"entry://祖国\">祖国</a>.</div>\r\n","<div class=\"hw jl\">故障</div><div class=\"def\">(車の)vitium machinamenti motorii.</div><div class=\"def\">⇒<a href=\"entry://修理\">修理</a>.</div>\r\n","<div class=\"hw jl\">敏感</div><div class=\"def\">subtilitas.</div><div class=\"def\">▼<b>～な</b> subtilis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">過敏な<span class=\"ext\">irritabilis.</span></div>\r\n","<div class=\"hw jl\">救う</div><div class=\"def\">servo, conservo.</div><div class=\"def\">▼<b>救い</b> salus.</div><div class=\"def\">⇒<a href=\"entry://救助\">救助</a>,<a href=\"entry://救援\">救援</a>.</div>\r\n","<div class=\"hw jl\">救助</div><div class=\"def\">salus.</div><div class=\"def\">▼<b>～する</b>(=救う)servo, conservo.</div><div class=\"ex2\">(人を)危険から～する<span class=\"ext\">〈alqm〉 e periculo servo [eripio].</span></div><div class=\"def\">⇒<a href=\"entry://助け\">助け</a>.</div>\r\n","<div class=\"hw jl\">救急車</div><div class=\"def\">arcera automataria, autoarcera, currus aegrotis [sauciatis, infirmis] in valetudinaria festinanter vectandis.</div>\r\n","<div class=\"hw jl\">救援</div><div class=\"def\">(=援助, 救助)adjumentum, auxilium, subsidium, praesidium.</div><div class=\"def\">⇒<a href=\"entry://助ける\">助ける</a>,<a href=\"entry://援助\">援助</a>.</div>\r\n","<div class=\"hw jl\">敗北</div><div class=\"def\">clades, detrimentum, incommodum.</div><div class=\"def\">▼<b>～する</b> devincor(<i>pass</i>), incommodum [cladem] accipio.</div>\r\n","<div class=\"hw jl\">教え</div><div class=\"def\">praeceptum, institutum, doctrina, disciplina.</div><div class=\"ex2\">(講義等に出席し)クラティッポスの～を聞く<span class=\"ext\">audio Cratippum.</span></div>\r\n","<div class=\"hw jl\">教える</div><div class=\"def\">doceo, edoceo;(=知らせる)indico, (alqm)certiorem facio.</div><div class=\"def\">⇒<a href=\"entry://知らせる\">知らせる</a>.</div>\r\n","<div class=\"hw jl\">教会</div><div class=\"def\">(キリスト教の)ecclesia.</div><div class=\"def\">▼<b>～の</b> ecclesiasticus.</div><div class=\"def\">⇒<a href=\"entry://モスク\">モスク</a>.</div>\r\n","<div class=\"hw jl\">教官</div><div class=\"def\">⇒<a href=\"entry://教師\">教師</a>.</div>\r\n","<div class=\"hw jl\">教室</div><div class=\"def\">auditorium.</div>\r\n","<div class=\"hw jl\">教師</div><div class=\"def\">magister, doctor, praeceptor(<i>m</i>), praeceptrix(<i>f</i>), paedagogus;(読み書きの)grammatista;(弁論術の)rhetor;(より専門的な)(=教授)professor.</div>\r\n","<div class=\"hw jl\">教授</div><div class=\"def\">professor.</div><div class=\"def\">⇒<a href=\"entry://教師\">教師</a>.</div>\r\n","<div class=\"hw jl\">教皇</div><div class=\"def\">papa, pontifex maximus [summus].</div>\r\n","<div class=\"hw jl\">教科書</div><div class=\"def\">liber scholaris.</div>\r\n","<div class=\"hw jl\">教育</div><div class=\"def\">educatio, institutio.</div><div class=\"def\">▼<b>～者</b> educator.</div><div class=\"def\">▼<b>～する</b> educo, instituo.</div><div class=\"def\">⇒<a href=\"entry://教養\">教養</a>,<a href=\"entry://教え\">教え</a>,<a href=\"entry://学識\">学識</a>,<a href=\"entry://学問\">学問</a>.</div>\r\n","<div class=\"hw jl\">教訓</div><div class=\"def\">praeceptum, praeceptio, documentum.</div>\r\n","<div class=\"hw jl\">教養</div><div class=\"def\">humanitas, disciplina, cultura, cultus.</div><div class=\"def\">▼<b>～のある</b> humanus, litteratus, doctus.</div>\r\n","<div class=\"hw jl\">散る</div><div class=\"def\">dissipor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">散文</div><div class=\"def\">oratio soluta [pedestris], prosa(oratio), verba soluta.</div><div class=\"def\">▼<b>～の</b> pedester.</div><div class=\"def\">⇒<a href=\"entry://韻文\">韻文</a>.</div>\r\n","<div class=\"hw jl\">散歩</div><div class=\"def\">ambulatio.</div><div class=\"def\">▼<b>～する</b> ambulo, spatior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">散髪</div><div class=\"def\">⇒<a href=\"entry://髪\">髪</a>,<a href=\"entry://理髪\">理髪</a>.</div>\r\n","<div class=\"hw jl\">敬意</div><div class=\"def\">reverentia, observantia, honor.</div><div class=\"def\">⇒<a href=\"entry://尊敬\">尊敬</a>.</div>\r\n","<div class=\"hw jl\">敬礼</div><div class=\"def\">salutatio.</div><div class=\"def\">▼<b>～する</b> saluto.</div>\r\n","<div class=\"hw jl\">数</div><div class=\"def\">numerus.</div><div class=\"def\">⇒<a href=\"entry://数\">数<SUB>すう</SUB></a>.</div>\r\n","<div class=\"hw jl\">数</div><div class=\"def\">numerus.</div><div class=\"def\">▼<b>偶～</b> numerus par.</div><div class=\"def\">▼<b>奇～</b> numerus impar.</div>\r\n","<div class=\"hw jl\">数えきれない</div><div class=\"def\">innumerabilis.</div>\r\n","<div class=\"hw jl\">数える</div><div class=\"def\">numero, dinumero, computo.</div><div class=\"def\">▼<b>数え上げる</b> enumero.</div>\r\n","<div class=\"hw jl\">数字</div><div class=\"def\">littera rationalis.</div><div class=\"ex2\">～を用いて計算する<span class=\"ext\">numerorum notis computo.</span></div><div class=\"def\">⇒<a href=\"entry://数\">数<SUB>すう</SUB></a>.</div>\r\n","<div class=\"hw jl\">数学</div><div class=\"def\">mathematica(studia)(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">整える</div><div class=\"def\">ordino, compono, dispono.</div><div class=\"def\">▼<b>～こと</b> compositio.</div>\r\n","<div class=\"hw jl\">整理</div><div class=\"def\">compositio, rerum in ordinem distributio.</div><div class=\"def\">▼<b>～する</b> ordino, dispono.</div><div class=\"def\">▼<b>～された</b> compositus.</div><div class=\"def\">▼<b>～されていない</b> incompositus.</div><div class=\"def\">▼<b>～されて</b> composite.</div>\r\n","<div class=\"hw jl\">敵</div><div class=\"def\">inimicus(<i>m</i>), hostis, adversarius.</div><div class=\"def\">▼<b>～の</b> inimicus, hostilis, adversarius.</div><div class=\"def\">▼<b>～のように</b> hostiliter, inimice.</div><div class=\"def\">⇒<a href=\"entry://敵意\">敵意</a>,<a href=\"entry://敵対\">敵対</a>.</div>\r\n","<div class=\"hw jl\">敵対</div><div class=\"def\">inimicitiae(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[形]</span> adversus.</div><div class=\"def\">▼<b>～して</b> hostiliter, inimice.</div><div class=\"def\">⇒<a href=\"entry://敵\">敵</a>.</div>\r\n","<div class=\"hw jl\">敵意</div><div class=\"def\">inimicitiae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">敷居</div><div class=\"def\">limen.</div>\r\n","<div class=\"hw jl\">文</div><div class=\"def\">sensus, sententia.</div><div class=\"ex2\">～の始めと終わり<span class=\"ext\">sententiarum initia et clausurae(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://文体\">文体</a>.</div>\r\n","<div class=\"hw jl\">文体</div><div class=\"def\">stilus, (scribendi [dicendi, orationis, sermonis])genus.</div><div class=\"ex2\">優雅な～で書く<span class=\"ext\">eleganter scribo.</span></div>\r\n","<div class=\"hw jl\">文化</div><div class=\"def\">cultus, cultura.</div><div class=\"def\">⇒<a href=\"entry://文明\">文明</a>.</div>\r\n","<div class=\"hw jl\">文句</div><div class=\"def\">(=語句)dictum.</div><div class=\"def\">▼<b>決まり～</b> loci communes(<i>pl</i>), formulae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://苦情\">苦情</a>.</div>\r\n","<div class=\"hw jl\">文字</div><div class=\"def\">littera, litterarum formae [notae](<i>pl</i>).</div><div class=\"def\">▼<b>～どおりに</b> ad verbum.</div><div class=\"def\">⇒<a href=\"entry://アルファベット\">アルファベット</a>.</div>\r\n","<div class=\"hw jl\">文学</div><div class=\"def\">litterae(<i>pl</i>).</div><div class=\"def\">▼<b>～研究</b> litterarum [humanitatis] studia(<i>pl</i>), cultus litterarum.</div>\r\n","<div class=\"hw jl\">文房具</div><div class=\"def\">supellex scriptoria.</div><div class=\"def\">▼<b>～屋</b> chartopola.</div>\r\n","<div class=\"hw jl\">文明</div><div class=\"def\">(vitae)cultus, humanus cultus, vita humanitate perpolita, cultior vitae usus.</div>\r\n","<div class=\"hw jl\">文書</div><div class=\"def\">scriptum, scriptura, scriptio, tabula, tabella, litterae(<i>pl</i>), liber.</div><div class=\"def\">▼<b>公～</b> tabulae publicae.</div>\r\n","<div class=\"hw jl\">文法</div><div class=\"def\">▼<b>～(学)</b>(ars)grammatica.</div><div class=\"def\">▼<b>～家</b> grammaticus(<i>m</i>).</div><div class=\"def\">▼<b>～教師</b> grammaticus professor.</div><div class=\"def\">▼<b>～(学)の, ～的な</b> grammaticus.</div>\r\n","<div class=\"hw jl\">文献学</div><div class=\"def\">philologia, disciplina philologa.</div><div class=\"def\">▼<b>～者</b> philologus(<i>m</i>).</div><div class=\"def\">▼<b>～の</b> philologus.</div>\r\n","<div class=\"hw jl\">文章</div><div class=\"def\">oratio, sermo.</div><div class=\"def\">⇒<a href=\"entry://文\">文</a>.</div>\r\n","<div class=\"hw jl\">文語</div><div class=\"def\">sermo litteratus.</div>\r\n","<div class=\"hw jl\">文通</div><div class=\"def\">epistularum consuetudo [commercium].</div><div class=\"def\">▼<b>頻繁な～</b> epistularum frequentia, epistulae crebrae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">料理</div><div class=\"def\">(技術)ars coquinaria, coquina;(=食事, 食物)culina, cena, victus.</div><div class=\"def\">▼<b>～人</b> coquus(<i>m</i>), coqua(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> coquinarius.</div><div class=\"def\">▼<b>～する</b> coquo, coquino.</div><div class=\"def\">⇒<a href=\"entry://台所\">台所</a>.</div>\r\n","<div class=\"hw jl\">料金</div><div class=\"def\">pretium(impositum).</div><div class=\"def\">▼<b>～表</b> pretiorum index.</div><div class=\"def\">▼<b>通行～</b>(=通行税)portorium, vectigal transitioni impositum.</div><div class=\"def\">▼<b>賃貸～</b>(=レンタル料)locationis pretium;(=家賃)merces [pecunia] habitationis, conductionis pretium, tributum inquilini.</div><div class=\"def\">▼(タクシーの)<b>～メーター</b> mercedis vectationis index.</div><div class=\"ex2\">～(=授業料)を取って教える<span class=\"ext\">mercede doceo.</span></div>\r\n","<div class=\"hw jl\">斜め</div><div class=\"def\">▼<b>～の</b> obliquus.</div><div class=\"def\">▼<b>～に</b> oblique.</div><div class=\"def\">▼<b>～の方向に</b> in obliquum.</div><div class=\"def\">▼<b>～(であること)</b> obliquitas.</div><div class=\"def\">▼<b>～にする</b> obliquo.</div>\r\n","<div class=\"hw jl\">斜面</div><div class=\"def\">⇒<a href=\"entry://傾斜\">傾斜</a>.</div>\r\n","<div class=\"hw jl\">斡旋</div><div class=\"def\">(=仲を取り持つこと)conciliatio.</div><div class=\"def\">▼<b>～人</b> conciliator(<i>m</i>), conciliatrix(<i>f</i>).</div><div class=\"def\">▼<b>～する</b> interpretor(<i>dep</i>), concilio.</div><div class=\"def\">⇒<a href=\"entry://仲介\">仲介</a>.</div>\r\n","<div class=\"hw jl\">断る</div><div class=\"def\">(=拒絶する, 拒む)nego, denego, abnuo.</div><div class=\"def\">⇒<a href=\"entry://拒否\">拒否</a>,<a href=\"entry://拒絶\">拒絶</a>.</div>\r\n","<div class=\"hw jl\">断固</div><div class=\"def\">▼<b>～たる</b> firmus.</div><div class=\"def\">⇒<a href=\"entry://不動\">不動</a>.</div>\r\n","<div class=\"hw jl\">断定</div><div class=\"def\">⇒<a href=\"entry://断言\">断言</a>.</div>\r\n","<div class=\"hw jl\">断片</div><div class=\"def\">fragmentum.</div>\r\n","<div class=\"hw jl\">断罪</div><div class=\"def\">▼<b>～する</b> damno, condemno.</div><div class=\"def\">⇒<a href=\"entry://判決\">判決</a>,<a href=\"entry://有罪\">有罪</a>.</div>\r\n","<div class=\"hw jl\">断言</div><div class=\"def\">affirmatio, asseveratio.</div><div class=\"def\">▼<b>～する</b> affirmo, enuntio, autumo, confirmo, assevero, aio.</div>\r\n","<div class=\"hw jl\">断食</div><div class=\"def\">inedia, abstinentia, jejunium, jejunitas.</div><div class=\"def\">▼<b>～する</b>(cibo)se abstinere, (cibo)abstineo, jejuno, jejunium servio.</div><div class=\"def\">⇒<a href=\"entry://飢える\">飢える</a>.</div>\r\n","<div class=\"hw jl\">新しい</div><div class=\"def\">novus, recens, novellus.</div><div class=\"def\">▼<b>新しさ</b> novitas.</div><div class=\"def\">▼<b>新しくする</b> novo.</div>\r\n","<div class=\"hw jl\">新た</div><div class=\"def\">▼<b>～に</b> denuo, de integro.</div>\r\n","<div class=\"hw jl\">新年</div><div class=\"def\">novus [incipiens] annus.</div>\r\n","<div class=\"hw jl\">新聞</div><div class=\"def\">(日刊の)diarium, acta diurna(<i>pl</i>), ephemeris, commentarii diurni(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://記者\">記者</a>.</div>\r\n","<div class=\"hw jl\">新鮮</div><div class=\"def\">▼<b>～な</b> viridis, recens, novus.</div>\r\n","<div class=\"hw jl\">方</div><div class=\"def\">▼(...の)<b> ～へ(向かって)</b> ad 〈+<i>acc</i>〉, in 〈+<i>acc</i>〉, versus 〈+<i>acc</i>〉, ad 〈+<i>acc</i>〉 versus, in 〈+<i>acc</i>〉 versus.</div><div class=\"ex2\">町の～へ<span class=\"ext\">ad oppidum.</span></div>\r\n","<div class=\"hw jl\">方向</div><div class=\"def\">pars.</div><div class=\"ex2\">反対の～に行く<span class=\"ext\">in contrariam partem eo.</span></div><div class=\"ex2\">シチリア島は全～海に囲まれている<span class=\"ext\">Sicilia ab omnibus partibus mari cingitur.</span></div><div class=\"ex2\">彼らは恐れおののいてそれぞれ別々の～に散っていった<span class=\"ext\">alii aliam in partem perterriti ferebantur.</span></div><div class=\"def\">⇒<a href=\"entry://方角\">方角</a>.</div>\r\n","<div class=\"hw jl\">方法</div><div class=\"def\">ratio, via, via ratioque, ratio et via, methodus.</div><div class=\"def\">▼<b>あらゆる～で</b> omni ratione [modo], omnibus modis.</div><div class=\"def\">▼<b>多くの～で</b> multis modis.</div>\r\n","<div class=\"hw jl\">方程式</div><div class=\"def\">aequatio.</div>\r\n","<div class=\"hw jl\">方角</div><div class=\"def\">pars, regio.</div><div class=\"def\">⇒<a href=\"entry://東\">東</a>,<a href=\"entry://西\">西</a>,<a href=\"entry://南\">南</a>,<a href=\"entry://北\">北</a>.</div>\r\n","<div class=\"hw jl\">方言</div><div class=\"def\">dialectos, dialectus, lingua.</div>\r\n","<div class=\"hw jl\">方針</div><div class=\"def\">secta.</div>\r\n","<div class=\"hw jl\">施設</div><div class=\"def\">domus publico usui destinata.</div>\r\n","<div class=\"hw jl\">旅</div><div class=\"def\">iter, via;(外国への)peregrinatio.</div><div class=\"ex2\">～をする<span class=\"ext\">iter facio.</span></div><div class=\"ex2\">外国を～する<span class=\"ext\">peregrinor(<i>dep</i>).</span></div><div class=\"def\">⇒<a href=\"entry://旅行\">旅行</a>.</div>\r\n","<div class=\"hw jl\">旅人</div><div class=\"def\">viator(<i>m</i>).</div>\r\n","<div class=\"hw jl\">旅行</div><div class=\"def\">periegesis.</div><div class=\"def\">▼<b>～者</b> periegetes, peregrinator [peregrinus] voluptarius.</div><div class=\"def\">▼<b>～する</b> peregrinor(<i>dep</i>).</div><div class=\"ex2\">～中である<span class=\"ext\">peregre sum.</span></div><div class=\"ex2\">スイスを～する<span class=\"ext\">Helveticam lustro.</span></div><div class=\"def\">⇒<a href=\"entry://旅\">旅</a>,<a href=\"entry://観光\">観光</a>.</div>\r\n","<div class=\"hw jl\">旗</div><div class=\"def\">mappa, signum;(=軍旗)vexillum, signum.</div>\r\n","<div class=\"hw jl\">日</div><div class=\"def\">▼<b>一～</b> dies.</div><div class=\"def\">▼<b>一～に三度</b> ter in die.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">2日(間)<span class=\"ext\">biduum.</span></div><div class=\"cf\">(彼は)3日(間)で到着した<span class=\"ext\">tribus diebus pervenit.</span></div><div class=\"def\">⇒<a href=\"entry://日\">日<SUB>ひ</SUB></a>.</div>\r\n","<div class=\"hw jl\">日</div><div class=\"def\">(=24時間, 一日)dies;(=日付)dies;(=太陽)sol;(=日光)lux.</div><div class=\"def\">▼<b>～の出</b> solis ortus, oriens sol.</div><div class=\"def\">▼<b>～の出</b>(=夜明け)<b>に</b> prima luce.</div><div class=\"def\">▼<b>～の出とともに</b> orto sole.</div><div class=\"def\">▼<b>～の入り</b> solis occasus, occidens sol.</div><div class=\"def\">▼<b>～に～に</b> in dies singlos, in dies privos.</div><div class=\"def\">⇒<a href=\"entry://日\">日<SUB>にち</SUB></a>.</div>\r\n","<div class=\"hw jl\">日付</div><div class=\"def\">dies.</div><div class=\"ex2\">手紙の～<span class=\"ext\">dies ascripta litteris.</span></div><div class=\"ex2\">手紙に～を付ける<span class=\"ext\">ascribo diem in epistula.</span></div>\r\n","<div class=\"hw jl\">日光</div><div class=\"def\">lux(solis).</div>\r\n","<div class=\"hw jl\">日常</div><div class=\"def\">▼<b>～の</b> cottidianus, vulgaris.</div><div class=\"def\">▼<b>～会話</b> sermo cottidianus [vulgaris].</div><div class=\"def\">▼<b>～的に</b> cottidie.</div>\r\n","<div class=\"hw jl\">日暮れ</div><div class=\"def\">(=たそがれ時)crepusculum.</div>\r\n","<div class=\"hw jl\">日本</div><div class=\"def\">Japonia.</div><div class=\"def\">▼<b>～(人)の</b> Japonis.</div><div class=\"def\">▼<b>～人</b> Japones(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">日記</div><div class=\"def\">ephemeris, commentarius diurnus.</div><div class=\"def\">▼<b>～帳</b> adversaria(<i>pl</i>), diurnum.</div>\r\n","<div class=\"hw jl\">日食</div><div class=\"def\">solis defectus [defectio, eclipsis].</div><div class=\"def\">⇒<a href=\"entry://月食\">月食</a>.</div>\r\n","<div class=\"hw jl\">早い</div><div class=\"def\">(時期が)maturus.</div><div class=\"def\">▼<b>早く</b> mature, celeriter;(...より)maturius quam ..., prius quam ....</div><div class=\"def\">▼<b>思ったより早く</b> spe celerius.</div><div class=\"def\">▼<b>できるだけ早く</b> quam primum fieri potest, primo quoque tempore.</div>\r\n","<div class=\"hw jl\">早熟</div><div class=\"def\">▼<b>～な</b> praecox.</div>\r\n","<div class=\"hw jl\">早起き</div><div class=\"def\">▼<b>～の</b> matutinus.</div><div class=\"def\">▼<b>～する</b> mane [cum ipso die] surgo.</div>\r\n","<div class=\"hw jl\">昆虫</div><div class=\"def\">bestiola, insectum.</div><div class=\"def\">▼<b>～学</b> insectorum doctrina, entomologia.</div><div class=\"def\">▼<b>～学の</b> entomologicus.</div>\r\n","<div class=\"hw jl\">昇進</div><div class=\"def\">promotio, incrementum, ascensus.</div><div class=\"def\">▼<b>～させる</b> produco, promoveo(in ampliorem gradum).</div><div class=\"def\">▼<b>～する</b>(honoribus)procedo.</div>\r\n","<div class=\"hw jl\">明かり</div><div class=\"def\">lux, lumen.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">ランプ<span class=\"ext\">lucerna.</span></div><div class=\"cf\">ランタン<span class=\"ext\">lanterna, laterna.</span></div><div class=\"cf\">松明<span class=\"ext\">lampas.</span></div>\r\n","<div class=\"hw jl\">明ける</div><div class=\"def\">(夜が)lucescit(<i>impers</i>), dilucescit(<i>impers</i>), illucescit(<i>impers</i>).</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">夜明け<span class=\"ext\">diluculum, aurora.</span></div><div class=\"cf\">夜明け(と共)に<span class=\"ext\">prima luce.</span></div>\r\n","<div class=\"hw jl\">明け渡す</div><div class=\"def\">trado.</div><div class=\"def\">▼<b>～こと</b> traditio.</div>\r\n","<div class=\"hw jl\">明らか</div><div class=\"def\">▼<b>～な</b> apertus, manifestus, perspicuus.</div><div class=\"def\">▼<b>～に</b> aperte, manifeste, perspicue, videlicet.</div><div class=\"ex2\">～に示す<span class=\"ext\">manifesto.</span></div><div class=\"ex2\">(...が...であることは)～である<span class=\"ext\">apparet 〈+<i>acc c. inf</i>〉.</span></div><div class=\"def\">⇒<a href=\"entry://明白\">明白</a>.</div>\r\n","<div class=\"hw jl\">明るい</div><div class=\"def\">clarus, lucidus.</div><div class=\"def\">▼<b>明るさ</b> claritas.</div><div class=\"def\">▼<b>明るくなる</b> luceo.</div><div class=\"def\">▼<b>明るくなり始める</b> lucesco.</div>\r\n","<div class=\"hw jl\">明後日</div><div class=\"def\"><span class=\"pos3\">[副]</span> perendie.</div><div class=\"def\">▼<b>～の</b> perendinus.</div>\r\n","<div class=\"hw jl\">明快</div><div class=\"def\">▼<b>～な</b>(=明瞭な, 明晰な)dilucidus, lucidus, illustris, perspicuus, apertus.</div><div class=\"def\">▼<b>単純～な</b> subtilis.</div><div class=\"def\">⇒<a href=\"entry://明瞭\">明瞭</a>,<a href=\"entry://明白\">明白</a>.</div>\r\n","<div class=\"hw jl\">明日</div><div class=\"def\"><span class=\"pos3\">[名]</span> crastinum.</div><div class=\"def\">━<span class=\"pos3\">[副]</span> cras.</div><div class=\"def\">▼<b>～の</b> crastinus.</div><div class=\"ex2\">～の朝<span class=\"ext\">cras mane.</span></div><div class=\"ex2\">ではまた～<span class=\"ext\">vale in crastinum.</span></div><div class=\"def\">⇒<a href=\"entry://翌日\">翌日</a>.</div>\r\n","<div class=\"hw jl\">明白</div><div class=\"def\">▼<b>～(さ)</b> evidentia, perspicuitas, claritas.</div><div class=\"def\">▼<b>～な</b> manifestus, evidens, dilucidus, lucidus, definitus, expressus, perspicuus, clarus, apertus, planus.</div><div class=\"def\">▼<b>～である</b> apparet(<i>impers</i>), propalam esse(← sum).</div><div class=\"def\">▼<b>～に</b> perspicue, manifesto, manifeste, clare, lucide, aperte, plane, evidenter, expresse, dilucide.</div><div class=\"def\">⇒<a href=\"entry://明らか\">明らか</a>,<a href=\"entry://明瞭\">明瞭</a>.</div>\r\n","<div class=\"hw jl\">明瞭</div><div class=\"def\">▼<b>～な</b> clarus, explicatus, expressus, explanatus.</div><div class=\"def\">⇒<a href=\"entry://明白\">明白</a>,<a href=\"entry://明快\">明快</a>.</div>\r\n","<div class=\"hw jl\">明確</div><div class=\"def\">▼<b>～な</b> certus, exploratus, definitus.</div><div class=\"def\">⇒<a href=\"entry://確か\">確か</a>.</div>\r\n","<div class=\"hw jl\">明言</div><div class=\"def\">declaratio.</div><div class=\"def\">▼<b>～する</b> declaro, profiteor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://断言\">断言</a>.</div>\r\n","<div class=\"hw jl\">昏睡</div><div class=\"def\">lethargia, lethargus.</div><div class=\"def\">▼<b>～状態の人</b> lethargicus.</div>\r\n","<div class=\"hw jl\">昔</div><div class=\"def\"><span class=\"pos3\">[名]</span>(=過去, 前の時代)(tempus)praeteritum, tempus pristinum, aetas praeterita, ea quae fuerunt(<i>pl</i>).</div><div class=\"def\">━<span class=\"pos3\">[副]</span>(=かつて, 以前に)olim, quondam, prius, antea.</div><div class=\"def\">▼<b>～から</b> antiquitus.</div>\r\n","<div class=\"hw jl\">昔話</div><div class=\"def\">fabula.</div>\r\n","<div class=\"hw jl\">星</div><div class=\"def\">stella, astrum, aster, sidus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">惑星<span class=\"ext\">stella errans.</span></div><div class=\"cf\">土星<span class=\"ext\">Saturnia stella.</span></div><div class=\"def\">⇒<a href=\"entry://星座\">星座</a>,<a href=\"entry://惑星\">惑星</a>,<a href=\"entry://彗星\">彗星</a>.</div>\r\n","<div class=\"hw jl\">星占い</div><div class=\"def\">(=占星術)astrologia divinans, chaldaicum praedicendi genus, siderum scientia, astrorum cognitio, sideralis scientia, mathematica, horoscopia.</div><div class=\"def\">▼<b>～の</b> mathematicus, horoscopius.</div><div class=\"def\">⇒<a href=\"entry://占星術\">占星術</a>.</div>\r\n","<div class=\"hw jl\">星印</div><div class=\"def\">asteriscus.</div>\r\n","<div class=\"hw jl\">星座</div><div class=\"def\">sidus, sidera(<i>pl</i>), signum.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">牡羊座<span class=\"ext\">aries.</span></div><div class=\"cf\">牡牛座<span class=\"ext\">taurus.</span></div><div class=\"cf\">双子座<span class=\"ext\">gemini(<i>pl</i>), geminum astrum.</span></div><div class=\"cf\">蟹座<span class=\"ext\">cancer.</span></div><div class=\"cf\">獅子座<span class=\"ext\">leo.</span></div><div class=\"cf\">乙女座<span class=\"ext\">virgo.</span></div><div class=\"cf\">天秤座<span class=\"ext\">libra.</span></div><div class=\"cf\">さそり座<span class=\"ext\">scorpio, scorpius.</span></div><div class=\"cf\">射手座<span class=\"ext\">sagittarius.</span></div><div class=\"cf\">山羊座<span class=\"ext\">capricornus.</span></div><div class=\"cf\">水瓶座<span class=\"ext\">aquarius.</span></div><div class=\"cf\">魚座<span class=\"ext\">pisces(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">映す</div><div class=\"ex2\">鏡に自分の姿を～<span class=\"ext\">in speculo tueor(<i>dep</i>)/ se speculo videre(← video).</span></div><div class=\"ex2\">映画を(スクリーンに)～(=映して見る)<span class=\"ext\">taeniam cinematographicam viso.</span></div>\r\n","<div class=\"hw jl\">映る</div><div class=\"def\">reddor(<i>pass</i>).</div><div class=\"ex2\">姿が鏡に～<span class=\"ext\">imago a speculo redditur.</span></div>\r\n","<div class=\"hw jl\">映像</div><div class=\"def\">imago, simulacrum, forma.</div>\r\n","<div class=\"hw jl\">映画</div><div class=\"def\">(=映画フィルム)spectaculum cinematographicum.</div><div class=\"def\">▼<b>～の</b> cinematographicus.</div><div class=\"def\">▼<b>～館</b> cinematographeum, locus ubi spectacula cinematographica eduntur.</div><div class=\"ex2\">カンヌ～祭<span class=\"ext\">festum cinematographicum Cannesianum.</span></div>\r\n","<div class=\"hw jl\">春</div><div class=\"def\">ver.</div><div class=\"def\">▼<b>～の(ような)</b> vernus.</div><div class=\"def\">▼<b>～に</b> vere.</div><div class=\"def\">⇒<a href=\"entry://季節\">季節</a>.</div>\r\n","<div class=\"hw jl\">昨日</div><div class=\"def\"><span class=\"pos3\">[名]</span> hesternus dies.</div><div class=\"def\">━<span class=\"pos3\">[副]</span> heri, here, hesterno die.</div><div class=\"def\">▼<b>～の</b> hesternus.</div><div class=\"def\">⇒<a href=\"entry://一昨日\">一昨日<SUB>おととい</SUB></a>.</div>\r\n","<div class=\"hw jl\">是認</div><div class=\"def\">probatio.</div><div class=\"def\">▼<b>～する</b> probo, comprobo.</div><div class=\"def\">▼<b>～された</b> probatus.</div><div class=\"def\">⇒<a href=\"entry://承認\">承認</a>.</div>\r\n","<div class=\"hw jl\">昼</div><div class=\"def\">(=正午)meridies;(=日の出から日没まで)dies.</div><div class=\"def\">▼<b>～の</b>(=昼間の, 日中の)diurnus.</div><div class=\"def\">▼<b>～に</b>(=昼間に, 日中に)diu.</div><div class=\"def\">▼<b>～も夜も</b> diem noctemque, dies noctesque, nocte et die.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">真昼間に<span class=\"ext\">multo die.</span></div><div class=\"def\">⇒<a href=\"entry://正午\">正午</a>,<a href=\"entry://午後\">午後</a>,<a href=\"entry://午前\">午前</a>,<a href=\"entry://夜\">夜</a>.</div>\r\n","<div class=\"hw jl\">昼食</div><div class=\"def\">prandium, cibus meridianus.</div><div class=\"ex2\">～を取る<span class=\"ext\">prandeo.</span></div><div class=\"def\">⇒<a href=\"entry://食事\">食事</a>.</div>\r\n","<div class=\"hw jl\">...時</div><div class=\"def\">hora.</div><div class=\"ex2\">何時ですか<span class=\"ext\">hora quota est? / quid horae est?</span></div><div class=\"ex2\">3時です<span class=\"ext\">tertia(hora)est.</span></div><div class=\"ex2\">3時10分です<span class=\"ext\">decem minutae nunc sunt post tertiam(horam).</span></div><div class=\"ex2\">2時2分前です<span class=\"ext\">duae minutae nunc est ante secundam.</span></div><div class=\"ex2\">午後8時です<span class=\"ext\">octava a meridie(hora)est.</span></div>\r\n","<div class=\"hw jl\">時</div><div class=\"def\">tempus, temporis spatium;(=瞬間)temporis punctum [momentum].</div><div class=\"def\">▼<b>今こそ</b>(...すべき)<b>～だ</b> nunc est tempus 〈+<i>inf</i>〉.</div><div class=\"def\">▼<b>その～</b> tum, illo [eo] tempore, id temporis.</div><div class=\"def\">▼<b>～には</b> interdum.</div><div class=\"def\">▼(...する)<b> ～(に)</b> cum 〈+<i>ind</i>;+<i>subj</i>〉, quando 〈+<i>ind</i>〉.</div><div class=\"ex2\">(絶対的奪格の構文で)タルクイニウスが支配している～<span class=\"ext\">Tarquinio regnante.</span></div><div class=\"ex2\">キケロが執政官の～(=年)に<span class=\"ext\">Cicerone consule.</span></div>\r\n","<div class=\"hw jl\">時々</div><div class=\"def\">nonnumquam, interdum, aliquando, per intervallum, ex intervallo.</div>\r\n","<div class=\"hw jl\">時代</div><div class=\"def\">tempus, aetas.</div><div class=\"def\">▼<b>同～人</b> aequales(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">時刻</div><div class=\"def\">hora, (diei)tempus.</div><div class=\"ex2\">その～<span class=\"ext\">id temporis.</span></div><div class=\"ex2\">(人に)～を尋ねる<span class=\"ext\">quaero horas 〈ab alqo〉.</span></div><div class=\"ex2\">～を知らせる<span class=\"ext\">horas nuntio.</span></div><div class=\"ex2\">今の正しい～を教えて下さい<span class=\"ext\">poterisne quo momento temporis simus pro certo dicere?</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">何時ですか<span class=\"ext\">hora quota est?</span></div><div class=\"def\">⇒<a href=\"entry://...時\">...時</a>.</div>\r\n","<div class=\"hw jl\">時効</div><div class=\"def\">praescriptio.</div><div class=\"ex2\">1年の[2年の, 3年の]～<span class=\"ext\">praescriptio annalis [biennalis, triennalis].</span></div>\r\n","<div class=\"hw jl\">時期</div><div class=\"def\">tempus, aetas, opportunitas.</div><div class=\"def\">⇒<a href=\"entry://期間\">期間</a>.</div>\r\n","<div class=\"hw jl\">時機</div><div class=\"def\">opportunum tempus, temporis opportunitas.</div>\r\n","<div class=\"hw jl\">時計</div><div class=\"def\">horologium.</div><div class=\"def\">▼<b>日～</b> solarium.</div><div class=\"def\">▼<b>水～</b> clepsydra.</div><div class=\"def\">▼<b>懐中～</b> horologium portabile.</div><div class=\"def\">⇒<a href=\"entry://腕時計\">腕時計</a>.</div>\r\n","<div class=\"hw jl\">時間</div><div class=\"def\">tempus, hora;(=60分)hora.</div><div class=\"ex2\">～を惜しめ<span class=\"ext\">tempori parce.</span></div><div class=\"ex2\">今私には～(=暇)がありません<span class=\"ext\">in praesentia non mihi est otium / nunc mihi haud vacat.</span></div><div class=\"def\">⇒<a href=\"entry://暇\">暇</a>.</div>\r\n","<div class=\"hw jl\">晩</div><div class=\"def\">vesper, verspera.</div><div class=\"def\">▼<b>昨日の～に</b> heri vesperi.</div><div class=\"def\">▼<b>～の</b> vespertinus.</div><div class=\"def\">⇒<a href=\"entry://夕方\">夕方</a>.</div>\r\n","<div class=\"hw jl\">晩餐</div><div class=\"def\">cena.</div><div class=\"def\">▼<b>～をする</b> ceno.</div>\r\n","<div class=\"hw jl\">普及</div><div class=\"def\">▼<b>～する</b> increbresco.</div><div class=\"def\">⇒<a href=\"entry://広まる\">広まる</a>.</div>\r\n","<div class=\"hw jl\">普段</div><div class=\"def\">▼<b>～の</b> solitus, cottidianus, consuetus.</div><div class=\"def\">▼<b>～は</b> plerumque.</div>\r\n","<div class=\"hw jl\">普通</div><div class=\"def\">▼<b>～の</b>(=通常の)usitatus, usualis, ordinarius, solitus, pervulgatus, consuetus, assuetus;(=並の)mediocris.</div><div class=\"def\">⇒<a href=\"entry://通常\">通常</a>.</div>\r\n","<div class=\"hw jl\">景品</div><div class=\"def\">⇒<a href=\"entry://贈物\">贈物</a>.</div>\r\n","<div class=\"hw jl\">景気</div><div class=\"def\">▼<b>好～</b> incrementum oeconomicum.</div><div class=\"def\">▼<b>不～</b> mercatura jacens.</div>\r\n","<div class=\"hw jl\">景色</div><div class=\"def\">prospectus.</div><div class=\"def\">⇒<a href=\"entry://風景\">風景</a>.</div>\r\n","<div class=\"hw jl\">晴れ</div><div class=\"def\">(=晴天)bona tempestas, (caeli)serenitas, sudum, tempestas secunda [serena].</div><div class=\"def\">⇒<a href=\"entry://曇る\">曇る</a>,<a href=\"entry://雨\">雨</a>,<a href=\"entry://天気\">天気</a>.</div>\r\n","<div class=\"hw jl\">暇</div><div class=\"def\">otium.</div><div class=\"def\">▼<b>～な</b> otiosus, vacuus.</div><div class=\"def\">▼<b>～がある</b> vaco.</div><div class=\"ex2\">手紙を書く～<span class=\"ext\">otium ad scribendum.</span></div>\r\n","<div class=\"hw jl\">暖房</div><div class=\"def\">calefactio.</div><div class=\"def\">▼<b>～装置</b> instrumentum calorificum [calefactorium], apparatus calorificus.</div>\r\n","<div class=\"hw jl\">暖炉</div><div class=\"def\">caminus, focus.</div>\r\n","<div class=\"hw jl\">暗い</div><div class=\"def\">tenebrosus, caliginosus, ater, obscurus, opacus, umbrosus;(=薄暗い)umbrosus, sublustris.</div><div class=\"def\">⇒<a href=\"entry://暗闇\">暗闇</a>.</div>\r\n","<div class=\"hw jl\">暗がり</div><div class=\"def\">obscuritas.</div><div class=\"def\">⇒<a href=\"entry://暗い\">暗い</a>.</div>\r\n","<div class=\"hw jl\">暗号</div><div class=\"def\">cryptographia.</div><div class=\"def\">▼<b>～の</b> cryptographicus.</div>\r\n","<div class=\"hw jl\">暗殺</div><div class=\"def\">(per insidias)caedes [occisio, homicidium].</div><div class=\"def\">▼<b>～する</b> per insidias occido.</div>\r\n","<div class=\"hw jl\">暗礁</div><div class=\"def\">saxa latentia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">暗示</div><div class=\"def\">significatio.</div><div class=\"def\">▼<b>～する</b> significo.</div>\r\n","<div class=\"hw jl\">暗記</div><div class=\"def\">▼<b>～する</b> commendo memoriae.</div><div class=\"ex2\">(彼は)全市民の名前を～していた(=覚えて知っていた)<span class=\"ext\">omnium civium nomina perceperat.</span></div><div class=\"def\">⇒<a href=\"entry://記憶\">記憶</a>.</div>\r\n","<div class=\"hw jl\">暗闇</div><div class=\"def\">tenebrae(<i>pl</i>), caligo.</div>\r\n","<div class=\"hw jl\">暮らす</div><div class=\"def\">vivo, vitam ago [duco, dego].</div><div class=\"def\">▼<b>暮らし</b> vita.</div>\r\n","<div class=\"hw jl\">暮れる</div><div class=\"def\">(日が)vesperascit(<i>impers</i>).</div>\r\n","<div class=\"hw jl\">暴力</div><div class=\"def\">vis, violentia.</div><div class=\"def\">▼<b>～的な</b> violentus, violens.</div><div class=\"def\">▼<b>～的に</b> per vim, violenter.</div><div class=\"def\">▼<b>～をふるう</b> vim affero.</div><div class=\"def\">⇒<a href=\"entry://暴行\">暴行</a>.</div>\r\n","<div class=\"hw jl\">暴動</div><div class=\"def\">concitatio, seditio, turba, tumultus.</div><div class=\"def\">▼<b>～を起こす</b> tumultuor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">暴行</div><div class=\"def\">injuria, vis, manus.</div><div class=\"def\">▼(...に)<b> ～を働く</b>(=暴力を用いる)〈alci〉 vim facio [infero, adhibeo], violo.</div><div class=\"def\">⇒<a href=\"entry://暴力\">暴力</a>.</div>\r\n","<div class=\"hw jl\">暴露</div><div class=\"def\">patefactio, revelatio.</div><div class=\"def\">▼<b>～する</b>(=漏らす)patefacio, palam facio, revelo;(=漏れる)propalam fio.</div>\r\n","<div class=\"hw jl\">暴風雨</div><div class=\"def\">tempestas, procella.</div>\r\n","<div class=\"hw jl\">曇る</div><div class=\"def\">(=天気が曇る, 曇っている)nubilat(nubilo の 3<i>sg act</i>), nubilatur(nubilo の 3<i>sg</i><i>pass</i>).</div><div class=\"def\">▼<b>曇った</b> nubilus, nebulosus, obscurus.</div><div class=\"def\">▼<b>曇り</b> caelum nubilum [obscurum], nubilum.</div><div class=\"def\">⇒<a href=\"entry://雲\">雲</a>.</div>\r\n","<div class=\"hw jl\">曜日</div><div class=\"def\">▼<b>日～</b> dies Solis [Dominicus];<b>月～</b> dies Lunae;<b>火～</b> dies Martis;<b>水～</b> dies Mercurii;<b>木～</b> dies Jovis;<b>金～</b> dies Veneris;<b>土～</b> dies Saturni.</div><div class=\"def\">▼<b>日～に</b> die Solis(<i>etc</i>).</div><div class=\"def\">⇒<a href=\"entry://週\">週</a>.</div>\r\n","<div class=\"hw jl\">曲</div><div class=\"def\">(=作品)opus;(=旋律, 歌, メロディー)modus, melos.</div>\r\n","<div class=\"hw jl\">曲がった</div><div class=\"def\">curvus, sinuosus.</div>\r\n","<div class=\"hw jl\">曲がりくねった</div><div class=\"def\">sinuosus, flexus, tortuosus, flexuosus.</div>\r\n","<div class=\"hw jl\">曲がる</div><div class=\"def\">flector(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://曲げる\">曲げる</a>.</div>\r\n","<div class=\"hw jl\">曲げる</div><div class=\"def\">(=たわませる)curvo, flecto, sinuo.</div><div class=\"def\">⇒<a href=\"entry://曲がる\">曲がる</a>.</div>\r\n","<div class=\"hw jl\">曲線</div><div class=\"def\">linea curva.</div><div class=\"def\">⇒<a href=\"entry://直線\">直線</a>.</div>\r\n","<div class=\"hw jl\">更新</div><div class=\"def\">renovatio.</div><div class=\"def\">▼<b>～する</b> renovo.</div>\r\n","<div class=\"hw jl\">書く・描く</div><div class=\"def\">scribo, exaro;(絵を)pingo.</div><div class=\"def\">▼<b>書き写す</b> describo, transcribo.</div><div class=\"def\">▼<b>書き加える</b> ascribo.</div>\r\n","<div class=\"hw jl\">書店</div><div class=\"def\">libraria(taberna).</div>\r\n","<div class=\"hw jl\">書類</div><div class=\"def\">libelli(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">最も</div><div class=\"def\">maxime.</div>\r\n","<div class=\"hw jl\">最中</div><div class=\"def\">(...の)<b>～に</b> inter 〈+<i>acc</i>〉.</div><div class=\"ex2\">宴の～に<span class=\"ext\">inter epulas.</span></div>\r\n","<div class=\"hw jl\">最低</div><div class=\"def\">▼<b>～の</b> infimus, imus;(=最も値が小さい)minimus;(=最も卑しい)pessimus.</div>\r\n","<div class=\"hw jl\">最初</div><div class=\"def\">(=最初の部分)prima pars, initium.</div><div class=\"def\">▼<b>～の</b> primus, princeps.</div><div class=\"def\">▼<b>～に</b> primum, primo.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">(列挙する際)最初に(=第1に)primo, 次に(=第2に)secundo, 第3に tertio.</div><div class=\"def\">⇒<a href=\"entry://まず\">まず</a>,<a href=\"entry://先に\">先に</a>,<a href=\"entry://始め\">始め</a>.</div>\r\n","<div class=\"hw jl\">最大</div><div class=\"def\">▼<b>～の</b> maximus.</div><div class=\"def\">⇒<a href=\"entry://大きい\">大きい</a>.</div>\r\n","<div class=\"hw jl\">最小</div><div class=\"def\">▼<b>～の</b> minimus.</div><div class=\"def\">⇒<a href=\"entry://小さい\">小さい</a>.</div>\r\n","<div class=\"hw jl\">最後</div><div class=\"def\">extrema pars, finis.</div><div class=\"def\">▼<b>～の</b> postremus, extremus, novissimus.</div><div class=\"def\">▼<b>～に</b> extremo, postremo, postremum, novissime, denique.</div><div class=\"def\">⇒<a href=\"entry://終わり\">終わり</a>,<a href=\"entry://ついに\">ついに</a>.</div>\r\n","<div class=\"hw jl\">最新</div><div class=\"def\">▼<b>～の</b> novissimus.</div><div class=\"def\">⇒<a href=\"entry://新しい\">新しい</a>.</div>\r\n","<div class=\"hw jl\">最良</div><div class=\"def\">▼<b>～の</b> optimus.</div>\r\n","<div class=\"hw jl\">最近</div><div class=\"def\"><span class=\"pos3\">[副]</span> nuper, recens, proxime.</div><div class=\"def\">▼<b>つい～</b> nuperrime.</div>\r\n","<div class=\"hw jl\">最高</div><div class=\"def\">▼<b>～の</b> summus.</div>\r\n","<div class=\"hw jl\">最高峰</div><div class=\"def\">▼<b>アルプスの～</b> alpium culmen.</div><div class=\"def\">⇒<a href=\"entry://頂上\">頂上</a>.</div>\r\n","<div class=\"hw jl\">月</div><div class=\"def\">(暦の)mensis;(天体の)luna.</div><div class=\"def\">▼<b>～の</b> lunaris.</div><div class=\"ex2\">～のない夜<span class=\"ext\">nox illunis.</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">満月<span class=\"ext\">plena [tota] luna.</span></div><div class=\"cf\">半月<span class=\"ext\">luna dimidiata [dimidia].</span></div><div class=\"cf\">新月<span class=\"ext\">luna nova.</span></div><div class=\"cf\">三日月<span class=\"ext\">luna crescens;(非常に細い)luna cava [bicornis, in cornua carvata].</span></div>\r\n","<div class=\"hw jl\">月末</div><div class=\"def\">▼<b>～に</b> ultimo mense, mense exeunte.</div>\r\n","<div class=\"hw jl\">月桂樹</div><div class=\"def\">laurus.</div><div class=\"def\">▼<b>月桂冠</b> laurea.</div><div class=\"def\">▼<b>～の</b> laureus.</div>\r\n","<div class=\"hw jl\">月経</div><div class=\"def\">menstruatio, menstrua(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> menstrualis, menstruatus.</div>\r\n","<div class=\"hw jl\">月賦</div><div class=\"def\">(=分割払い金)rata pars, pensio.</div><div class=\"def\">▼<b>～払い</b>(=分割払い)solutio in ratas partes divisa, solutio in ratas pensiones divisa.</div><div class=\"def\">▼<b>～で</b>(支払う)per partes ratas(solvo).</div>\r\n","<div class=\"hw jl\">月食</div><div class=\"def\">lunae defectus [defectio, eclipsis].</div><div class=\"def\">▼<b>皆既～</b> lunae perfecta defectio.</div><div class=\"def\">⇒<a href=\"entry://日食\">日食</a>.</div>\r\n","<div class=\"hw jl\">有利</div><div class=\"def\">(=利益があること)⇒ <a href=\"entry://利益\">利益</a>;(=好都合)opportunitas.</div><div class=\"def\">▼<b>～である</b>(=利益がある)in lucro esse(← sum).</div><div class=\"def\">▼<b>～な</b>(=利益を生む)quaestuosus, fructuosus, lucrosus, lucrificabilis;(=好都合な)opportunus, commodus, aequus.</div><div class=\"def\">▼<b>～に</b> utiliter, quaestuose, fructuose.</div><div class=\"def\">⇒<a href=\"entry://役立つ\">役立つ</a>,<a href=\"entry://有益\">有益</a>.</div>\r\n","<div class=\"hw jl\">有力</div><div class=\"def\">▼<b>～な</b>(=影響力のある, 勢力のある)potens, valens, validus, auctoritate gravis.</div><div class=\"def\">▼<b>～者</b> homo maga auctoritate.</div><div class=\"def\">▼<b>～である</b>(auctoritae)valeo.</div>\r\n","<div class=\"hw jl\">有効</div><div class=\"def\">efficacitas, validitas.</div><div class=\"def\">▼<b>～な</b> efficax, validus.</div><div class=\"def\">▼<b>～である</b> valeo.</div>\r\n","<div class=\"hw jl\">有名</div><div class=\"def\">celebritas, nobilitas, claritas.</div><div class=\"def\">▼<b>～な</b>(=著名な, 高名な)praeclarus, nobilis, illustris, clarus, celeber, luculentus.</div><div class=\"ex2\">同じ行為でも, する人が～か無名かによって, 非常に高く持ち上げられたり非常に低くおとしめられたりする<span class=\"ext\">eadem facta claritate uel obscuritate facientium aut tolluntur altissime aut humillime deprimuntur.</span></div><div class=\"def\">⇒<a href=\"entry://無名\">無名</a>.</div>\r\n","<div class=\"hw jl\">有害</div><div class=\"def\">▼<b>～な</b> noxius, nocens, damnosus, perniciosus.</div><div class=\"def\">⇒<a href=\"entry://害\">害</a>,<a href=\"entry://毒\">毒</a>.</div>\r\n","<div class=\"hw jl\">有毒</div><div class=\"def\">▼<b>～な</b> venenifer, venenatus, toxicus, noxius.</div><div class=\"def\">⇒<a href=\"entry://毒\">毒</a>.</div>\r\n","<div class=\"hw jl\">有益</div><div class=\"def\">utilitas, commodum.</div><div class=\"def\">▼<b>～な</b>(=有用な, 役に立つ)utilis, salutaris, fructuosus.</div><div class=\"def\">▼(人にとって)<b>～である</b> 〈alci〉 prosum, utilitati sum.</div>\r\n","<div class=\"hw jl\">有罪</div><div class=\"def\">peccatum, culpa, noxia.</div><div class=\"def\">▼<b>～の</b>(=罪のある)noxius, nocens, obnoxius.</div><div class=\"def\">▼<b>～である</b> in noxia [culpa] sum.</div><div class=\"def\">▼<b>～とする</b>(=有罪判決を下す)condemno, damno.</div><div class=\"def\">⇒<a href=\"entry://無罪\">無罪</a>.</div>\r\n","<div class=\"hw jl\">有能</div><div class=\"def\">▼<b>～な</b> validus, peritus, satis doctus, idoneus, sollers.</div><div class=\"def\">⇒<a href=\"entry://能力\">能力</a>.</div>\r\n","<div class=\"hw jl\">服</div><div class=\"def\">(=衣服)vestis, vestimentum, vestitus.</div><div class=\"def\">▼<b>～を着せる</b> vestio.</div><div class=\"def\">⇒<a href=\"entry://着る\">着る</a>.</div>\r\n","<div class=\"hw jl\">服従</div><div class=\"def\">oboedientia, obtemperatio, obsequium.</div><div class=\"def\">▼<b>～する</b> oboedio, pareo, obtempero.</div><div class=\"def\">⇒<a href=\"entry://従順\">従順</a>.</div>\r\n","<div class=\"hw jl\">服装</div><div class=\"def\">habitus, cultus.</div><div class=\"def\">⇒<a href=\"entry://服\">服</a>.</div>\r\n","<div class=\"hw jl\">朗読</div><div class=\"def\">▼<b>～する</b> recito.</div><div class=\"def\">▼<b>～者</b> recitator.</div>\r\n","<div class=\"hw jl\">望み</div><div class=\"def\">spes.</div>\r\n","<div class=\"hw jl\">望む</div><div class=\"def\">opto, spero;(=欲する)volo.</div><div class=\"def\">▼<b>望まない</b>(=欲しない)nolo.</div><div class=\"def\">⇒<a href=\"entry://欲しい\">欲しい</a>.</div>\r\n","<div class=\"hw jl\">望遠鏡</div><div class=\"def\">telescopium.</div>\r\n","<div class=\"hw jl\">朝</div><div class=\"def\"><span class=\"pos3\">[名]</span>(=午前)matutinum tempus, matutinum, mane.</div><div class=\"def\">━<span class=\"pos3\">[副]</span> mane.</div><div class=\"def\">▼<b>～の</b> matutinus, antemeridianus.</div><div class=\"def\">▼<b>～早く</b> prima luce, multo mane, bene mane</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">今朝<span class=\"ext\">hodie mane.</span></div><div class=\"cf\">翌朝<span class=\"ext\">postridie mane.</span></div><div class=\"cf\">明日の朝<span class=\"ext\">cras mane.</span></div><div class=\"cf\">昨日の朝<span class=\"ext\">heri mane.</span></div>\r\n","<div class=\"hw jl\">朝寝坊</div><div class=\"def\">▼<b>～する</b> mane totum dormio.</div>\r\n","<div class=\"hw jl\">朝日</div><div class=\"def\">sol oriens.</div><div class=\"def\">⇒<a href=\"entry://日\">日<SUB>ひ</SUB></a>.</div>\r\n","<div class=\"hw jl\">朝食</div><div class=\"def\">jentaculum.</div><div class=\"ex2\">～を取る<span class=\"ext\">jento.</span></div><div class=\"def\">⇒<a href=\"entry://昼食\">昼食</a>,<a href=\"entry://食事\">食事</a>.</div>\r\n","<div class=\"hw jl\">期待</div><div class=\"def\">spes, exspectatio.</div><div class=\"def\">▼<b>～する</b> spero, exspecto, confido.</div><div class=\"ex2\">すべての人の～を裏切って<span class=\"ext\">contra omnium opinionem.</span></div><div class=\"def\">⇒<a href=\"entry://希望\">希望</a>.</div>\r\n","<div class=\"hw jl\">期間</div><div class=\"def\">temporis spatium.</div><div class=\"ex2\">30日の～<span class=\"ext\">spatium dierum triginta.</span></div>\r\n","<div class=\"hw jl\">期限</div><div class=\"ex2\">各人が(...を)すべき～を定める<span class=\"ext\">constituo quod ante tempus quisque efficiat 〈alqd〉.</span></div>\r\n","<div class=\"hw jl\">木</div><div class=\"def\">arbor.</div><div class=\"def\">▼<b>～の</b> arboreus.</div>\r\n","<div class=\"hw jl\">木炭</div><div class=\"def\">carbo.</div><div class=\"def\">⇒<a href=\"entry://石炭\">石炭</a>.</div>\r\n","<div class=\"hw jl\">木立</div><div class=\"def\">silvula.</div><div class=\"def\">⇒<a href=\"entry://森\">森</a>,<a href=\"entry://林\">林</a>.</div>\r\n","<div class=\"hw jl\">未亡人</div><div class=\"def\">viro privata(<i>f</i>), vidua(<i>f</i>);(状態)viduitas.</div>\r\n","<div class=\"hw jl\">未婚</div><div class=\"def\">▼<b>～の</b>(=独身の)caelebs;(男性が)qui nondum uxorem habet;(女性が)non nupta, quae nondum maritum habet.</div><div class=\"def\">⇒<a href=\"entry://独身\">独身</a>.</div>\r\n","<div class=\"hw jl\">未来</div><div class=\"def\">(=将来)futura, futurum.</div><div class=\"def\">▼<b>～の</b>(=将来の)futurus.</div>\r\n","<div class=\"hw jl\">未熟</div><div class=\"def\">▼<b>～な</b> crudus, immaturus, immitis, rudis, acerbus.</div>\r\n","<div class=\"hw jl\">未知</div><div class=\"def\">▼<b>～の</b>(adhuc)ignotus, incognitus, ignarus, inexploratus.</div>\r\n","<div class=\"hw jl\">未開</div><div class=\"def\">▼<b>～の</b> incultus, silvestris, silvester.</div><div class=\"def\">▼<b>～人</b> homines silvestres(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://野蛮\">野蛮</a>.</div>\r\n","<div class=\"hw jl\">本</div><div class=\"def\">liber.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">巻本(=巻物)<span class=\"ext\">volumen.</span></div><div class=\"cf\">綴本<span class=\"ext\">codex.</span></div><div class=\"cf\">絵本<span class=\"ext\">liber imaginibus ornatus.</span></div><div class=\"def\">⇒<a href=\"entry://本屋\">本屋</a>,<a href=\"entry://作品\">作品</a>.</div>\r\n","<div class=\"hw jl\">本屋</div><div class=\"def\">(=書店)taberna libraria;(=書籍商)bibliopola, librarius.</div>\r\n","<div class=\"hw jl\">本当</div><div class=\"def\">▼<b>～の</b> verus.</div><div class=\"def\">▼<b>～に</b> vere, reipsa, revera.</div><div class=\"def\">⇒<a href=\"entry://真理\">真理</a>.</div>\r\n","<div class=\"hw jl\">本性</div><div class=\"def\">natura.</div><div class=\"def\">▼<b>～上</b> naturaliter.</div>\r\n","<div class=\"hw jl\">本棚</div><div class=\"def\">foruli(<i>pl</i>), bibliotheca, armarium.</div>\r\n","<div class=\"hw jl\">本気</div><div class=\"def\">⇒<a href=\"entry://真剣\">真剣</a>.</div>\r\n","<div class=\"hw jl\">本物</div><div class=\"def\">▼<b>～の</b>(=真正の)verus, merus.</div>\r\n","<div class=\"hw jl\">本社</div><div class=\"def\">primaria sedes.</div>\r\n","<div class=\"hw jl\">本能</div><div class=\"def\">ingenium, motus naturalis.</div><div class=\"def\">▼<b>～的な</b> naturalis, ingenitus, insitus, innatus, naturae consentaneus, incogitatus.</div>\r\n","<div class=\"hw jl\">本質</div><div class=\"def\">essentia.</div><div class=\"ex2\">自由であること, それが国家の～である<span class=\"ext\">id est proprium civitatis ut sit libera.</span></div><div class=\"def\">⇒<a href=\"entry://本性\">本性</a>.</div>\r\n","<div class=\"hw jl\">札</div><div class=\"def\">(=小さな木片[紙片])chartula, tabella, tessera.</div>\r\n","<div class=\"hw jl\">机</div><div class=\"def\">(書くための)mensa(scriptoria).</div><div class=\"def\">⇒<a href=\"entry://台\">台</a>.</div>\r\n","<div class=\"hw jl\">杏</div><div class=\"def\">(実)malum armeniacum.</div>\r\n","<div class=\"hw jl\">材料</div><div class=\"def\">materia, materies.</div>\r\n","<div class=\"hw jl\">村</div><div class=\"def\">pagus, vicus.</div><div class=\"def\">▼<b>小さな～</b> viculus.</div><div class=\"def\">▼<b>～人</b> rusticus(<i>m</i>), vicanus(<i>m</i>), paganus(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://田舎\">田舎</a>.</div>\r\n","<div class=\"hw jl\">杖</div><div class=\"def\">baculum, baculus, bacillum, fustis.</div><div class=\"def\">⇒<a href=\"entry://棒\">棒</a>.</div>\r\n","<div class=\"hw jl\">束縛</div><div class=\"def\">▼<b>～する</b> astringo, constringo.</div>\r\n","<div class=\"hw jl\">条件</div><div class=\"def\">condicio.</div><div class=\"ex2\">...という～で<span class=\"ext\">(sub)ea condicione ut 〈+<i>subj</i>〉.</span></div><div class=\"ex2\">...しないという～で<span class=\"ext\">(sub)ea condicione ne 〈+<i>subj</i>〉.</span></div><div class=\"ex2\">公平な[不公平な]～で戦う<span class=\"ext\">in loco aequo [iniquo] pugno.</span></div>\r\n","<div class=\"hw jl\">条約</div><div class=\"def\">foedus, pactio.</div><div class=\"def\">▼<b>～を結ぶ</b> foedus facio, paciscor(<i>dep</i>).</div><div class=\"def\">▼<b>～を破る</b> foedus rumpo.</div>\r\n","<div class=\"hw jl\">来る</div><div class=\"def\">venio;(=やって来る)advenio.</div><div class=\"ex2\">(私は)来た, 見た, 勝った<span class=\"ext\">veni, vidi, vici.</span></div>\r\n","<div class=\"hw jl\">来年</div><div class=\"def\">annus sequens [insequens, posterus].</div><div class=\"def\">⇒<a href=\"entry://年\">年<SUB>ねん</SUB></a>.</div>\r\n","<div class=\"hw jl\">東</div><div class=\"def\">oriens, solis ortus.</div><div class=\"def\">▼<b>～の</b> orientalis.</div><div class=\"def\">⇒<a href=\"entry://西\">西</a>.</div>\r\n","<div class=\"hw jl\">東洋</div><div class=\"def\">Oriens, orientis solis partes(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://西洋\">西洋</a>.</div>\r\n","<div class=\"hw jl\">松葉杖</div><div class=\"def\">baculum orthopaedicum, subalare baculum.</div>\r\n","<div class=\"hw jl\">板</div><div class=\"def\">(木の)tabula;(金属の, 薄い)lamina.</div><div class=\"def\">▼<b>小さな～</b> tabella.</div>\r\n","<div class=\"hw jl\">枕</div><div class=\"def\">pulvinus, pulvillus, cervical;(羽毛の)pluma.</div>\r\n","<div class=\"hw jl\">林</div><div class=\"def\">silva, nemus.</div><div class=\"def\">▼<b>～におおわれた</b> silvestris.</div><div class=\"def\">⇒<a href=\"entry://森\">森</a>.</div>\r\n","<div class=\"hw jl\">果たす</div><div class=\"def\">praesto, perago, fungor(<i>dep</i>), perficio.</div><div class=\"def\">⇒<a href=\"entry://義務\">義務</a>.</div>\r\n","<div class=\"hw jl\">果樹</div><div class=\"def\">pomifer [frugifer] arbor.</div><div class=\"def\">▼<b>～園</b> pomarium.</div><div class=\"def\">▼<b>～の</b> pomarius.</div>\r\n","<div class=\"hw jl\">果汁</div><div class=\"def\">sucus.</div>\r\n","<div class=\"hw jl\">果物</div><div class=\"def\">fructus.</div>\r\n","<div class=\"hw jl\">枝</div><div class=\"def\">ramus.</div><div class=\"def\">▼<b>小～</b> ramulus.</div><div class=\"def\">▼<b>～の(ある)</b> rameus.</div><div class=\"def\">▼<b>～の多い, ～分かれした</b> ramosus.</div>\r\n","<div class=\"hw jl\">枠</div><div class=\"def\">margo;(木製の)(lignea)forma.</div>\r\n","<div class=\"hw jl\">枯れる・涸れる</div><div class=\"ex2\">木が～<span class=\"ext\">arbor moritur.</span></div><div class=\"ex2\">涙が～<span class=\"ext\">arescit lacrima.</span></div><div class=\"def\">⇒<a href=\"entry://乾く\">乾く</a>,<a href=\"entry://しおれる\">しおれる</a>.</div>\r\n","<div class=\"hw jl\">架空</div><div class=\"def\">▼<b>～の</b> fictus, commenticius.</div>\r\n","<div class=\"hw jl\">柄</div><div class=\"def\">(=取っ手)manubrium.</div>\r\n","<div class=\"hw jl\">染める</div><div class=\"def\">inficio, tingo, coloro, fuco.</div>\r\n","<div class=\"hw jl\">染色体</div><div class=\"def\">chromosoma.</div>\r\n","<div class=\"hw jl\">柔らかい</div><div class=\"def\">tener, mollis.</div><div class=\"def\">▼<b>柔らかさ</b> teneritas, mollitia, mollities.</div>\r\n","<div class=\"hw jl\">柔軟</div><div class=\"def\">▼<b>～(性)</b> mollitia, mollities, mollitudo, lentitudo.</div><div class=\"def\">▼<b>～な</b> flexibilis, mollis, lentus.</div><div class=\"def\">▼<b>～に</b> molliter.</div><div class=\"def\">▼<b>～にする</b> mollio.</div><div class=\"def\">▼<b>～になる</b> mollesco.</div>\r\n","<div class=\"hw jl\">柱</div><div class=\"def\">pila.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">円柱<span class=\"ext\">columna.</span></div>\r\n","<div class=\"hw jl\">柱廊</div><div class=\"def\">porticus.</div>\r\n","<div class=\"hw jl\">柵</div><div class=\"def\">saeptum, cancelli(<i>pl</i>).</div><div class=\"def\">▼<b>～で囲む</b> saepio.</div>\r\n","<div class=\"hw jl\">栄える</div><div class=\"def\">(=栄えている)vigeo.</div>\r\n","<div class=\"hw jl\">栄光</div><div class=\"def\">(=名誉, ほまれ)gloria, splendor, laus, fama.</div><div class=\"def\">▼<b>小さな～</b> gloriola.</div><div class=\"def\">▼<b>～ある</b> gloriosus, illustris, splendidus, eximius.</div><div class=\"def\">▼<b>～とともに</b> gloriose.</div>\r\n","<div class=\"hw jl\">栄誉</div><div class=\"def\">honestas, honor, gloria.</div>\r\n","<div class=\"hw jl\">栄養</div><div class=\"def\">(=栄養(物))alimentum, nutrimentum, alimonia, alimonium.</div>\r\n","<div class=\"hw jl\">栓</div><div class=\"def\">obturamentum, obturaculum.</div><div class=\"def\">▼(...に)<b> ～をする</b> 〈alqd〉 obturo.</div>\r\n","<div class=\"hw jl\">栗</div><div class=\"def\">(実, 木)castanea.</div><div class=\"def\">▼<b>～の</b> castaneus.</div>\r\n","<div class=\"hw jl\">株</div><div class=\"def\">(=株券)collocatae pecuniae syngrapha, collatae pecuniae syngrapha.</div><div class=\"def\">▼<b>～主</b>(=共同出資者)sodales consociati(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">核</div><div class=\"def\">nucleus.</div><div class=\"def\">▼<b>～の</b>(=原子核の)atomicus.</div><div class=\"def\">⇒<a href=\"entry://原子\">原子</a>.</div>\r\n","<div class=\"hw jl\">核兵器</div><div class=\"def\">apparatus atomicus, arma atomica, arma nuclearia.</div><div class=\"def\">▼<b>～禁止</b> atomicorum armamentorum interdictio.</div><div class=\"def\">▼<b>～廃絶</b> atomicorum armamentorum amotio.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">核軍縮協議<span class=\"ext\">consilium arma atomica contrahendi.</span></div><div class=\"cf\">核軍縮協定<span class=\"ext\">pactum arma atomica non propagandi.</span></div>\r\n","<div class=\"hw jl\">根</div><div class=\"def\">radix, stirps.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">根元から<span class=\"ext\">radicitus.</span></div>\r\n","<div class=\"hw jl\">根底</div><div class=\"def\">fundamentum.</div><div class=\"def\">▼<b>～から</b> funditus.</div>\r\n","<div class=\"hw jl\">根拠</div><div class=\"def\">(=理由)ratio, causa;(=よりどころ)fundamentum;(=証拠)argumentum.</div><div class=\"ex2\">～のない噂<span class=\"ext\">opinio sine auctore.</span></div><div class=\"def\">⇒<a href=\"entry://証拠\">証拠</a>.</div>\r\n","<div class=\"hw jl\">根本</div><div class=\"def\">fundamentum.</div><div class=\"def\">▼<b>～的に</b> radicitus.</div><div class=\"def\">⇒<a href=\"entry://根底\">根底</a>.</div>\r\n","<div class=\"hw jl\">根気</div><div class=\"def\">patientia.</div><div class=\"def\">▼<b>～ある</b> patiens.</div><div class=\"def\">⇒<a href=\"entry://我慢\">我慢</a>,<a href=\"entry://忍耐\">忍耐</a>.</div>\r\n","<div class=\"hw jl\">根源</div><div class=\"def\">radix, stirps.</div><div class=\"def\">⇒<a href=\"entry://起源\">起源</a>.</div>\r\n","<div class=\"hw jl\">根絶</div><div class=\"def\">exstirpatio.</div><div class=\"def\">▼<b>～する</b> exstirpo.</div>\r\n","<div class=\"hw jl\">格好</div><div class=\"def\">(=身体の美しさ)forma;(=身なり)vestitus.</div><div class=\"def\">▼<b>～の良い[悪い]</b>(=美しい[不細工な])formosus [informis];(身なりが)bene [male] vestitus.</div>\r\n","<div class=\"hw jl\">格子</div><div class=\"def\">cancelli(<i>pl</i>), clatri(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">格言</div><div class=\"def\">⇒<a href=\"entry://諺\">諺</a>.</div>\r\n","<div class=\"hw jl\">格闘</div><div class=\"def\">luctatio.</div><div class=\"def\">▼<b>～者</b> luctator.</div><div class=\"def\">▼<b>～する</b> luctor(<i>dep</i>), pugno.</div>\r\n","<div class=\"hw jl\">栽培</div><div class=\"def\">cultura, satus, plantatio.</div>\r\n","<div class=\"hw jl\">桃</div><div class=\"def\">malum persicum.</div>\r\n","<div class=\"hw jl\">案</div><div class=\"def\">consilium, ratio, institutum.</div><div class=\"def\">⇒<a href=\"entry://計画\">計画</a>.</div>\r\n","<div class=\"hw jl\">案内</div><div class=\"def\">▼<b>～すること</b> ductus, ductio.</div><div class=\"def\">▼<b>～人</b> dux, ductor.</div><div class=\"def\">▼<b>～する</b>(=導く)duco, ducto.</div>\r\n","<div class=\"hw jl\">桜</div><div class=\"def\">(木)cerasus;(実, サクランボ)cerasum.</div>\r\n","<div class=\"hw jl\">桶</div><div class=\"def\">cupa, solium, ligneum vas circulis cinctum;(大きな)labrum, lacus.</div><div class=\"def\">⇒<a href=\"entry://樽\">樽</a>,<a href=\"entry://バケツ\">バケツ</a>.</div>\r\n","<div class=\"hw jl\">梅</div><div class=\"def\">prunum.</div><div class=\"def\">▼<b>～の木</b> prunus.</div>\r\n","<div class=\"hw jl\">梅毒</div><div class=\"def\">syphilis, lues.</div>\r\n","<div class=\"hw jl\">梨</div><div class=\"def\">(実)pirum;(木)pirus.</div>\r\n","<div class=\"hw jl\">梯子</div><div class=\"def\">scalae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">棒</div><div class=\"def\">baculum, fustis, pertica.</div><div class=\"def\">▼<b>小さな～</b> bacillum.</div><div class=\"def\">⇒<a href=\"entry://杖\">杖</a>.</div>\r\n","<div class=\"hw jl\">棚</div><div class=\"def\">(=書棚)pluteus, pegma, armarium, loculamenta(<i>pl</i>);(=飾り棚)armarium;(=食堂の側壁の豪華な食器棚)abacus.</div>\r\n","<div class=\"hw jl\">森</div><div class=\"def\">silva, nemus.</div><div class=\"def\">▼<b>～の</b> silvestris.</div><div class=\"def\">▼<b>～の多い</b> silvestris, silvosus.</div>\r\n","<div class=\"hw jl\">森林</div><div class=\"def\">silva, silvae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">棺桶</div><div class=\"def\">⇒<a href=\"entry://ひつぎ\">ひつぎ</a>.</div>\r\n","<div class=\"hw jl\">椅子</div><div class=\"def\">(背もたれ・肘掛けのない)sella;(=座)sedes;(=肘掛け椅子)cathedra.</div><div class=\"def\">⇒<a href=\"entry://座席\">座席</a>,<a href=\"entry://腰掛け\">腰掛け</a>,<a href=\"entry://ソファー\">ソファー</a>.</div>\r\n","<div class=\"hw jl\">植える</div><div class=\"def\">sero, planto.</div><div class=\"def\">▼<b>～こと</b>(=植え付け)plantatio.</div>\r\n","<div class=\"hw jl\">植物</div><div class=\"def\">herba, res quae e terra gignuntur.</div>\r\n","<div class=\"hw jl\">検事</div><div class=\"def\">(=検察官)causae criminalis actor.</div>\r\n","<div class=\"hw jl\">検挙</div><div class=\"def\">⇒<a href=\"entry://逮捕\">逮捕</a>.</div>\r\n","<div class=\"hw jl\">検査</div><div class=\"def\">experimentum, probatio, periculum, periclitatio, recensio, inspectus.</div><div class=\"def\">▼<b>血液～</b> sanguinis probatio.</div><div class=\"def\">▼<b>適性～</b> idoneitatis periculum.</div><div class=\"def\">▼<b>～する</b> recenseo, inspicio, recognosco.</div><div class=\"def\">⇒<a href=\"entry://吟味\">吟味</a>,<a href=\"entry://監査\">監査</a>.</div>\r\n","<div class=\"hw jl\">検疫</div><div class=\"def\">quadragenaria, mora quadragenaria in statione propter pestem [suspectam valetudinem].</div><div class=\"def\">▼<b>～を行なう</b> quadragenariam ago.</div><div class=\"def\">▼(...に)<b>～を施す</b> 〈+<i>dat</i>〉 quadragenariam infero [facio, impono].</div>\r\n","<div class=\"hw jl\">検索</div><div class=\"def\">investigatio, inquisitio, exploratio.</div><div class=\"def\">▼<b>～する</b> investigo, inquiro, exploro.</div>\r\n","<div class=\"hw jl\">検討</div><div class=\"def\">⇒<a href=\"entry://検査\">検査</a>,<a href=\"entry://調査\">調査</a>,<a href=\"entry://審査\">審査</a>,<a href=\"entry://吟味\">吟味</a>,<a href=\"entry://討議\">討議</a>,<a href=\"entry://熟慮\">熟慮</a>.</div>\r\n","<div class=\"hw jl\">検閲</div><div class=\"def\">▼<b>～する</b> censuram facio, recognosco, inspicio.</div><div class=\"def\">▼<b>～された</b>(a obscenis loci)purgatus.</div>\r\n","<div class=\"hw jl\">極</div><div class=\"def\">polus, axis, (caeli)vertex.</div><div class=\"def\">▼<b>～の</b> ad polum pertinens, caeli vertecem pertinens, polaris.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">北極<span class=\"ext\">arctos, vertex(terrae)septentrionalis.</span></div><div class=\"cf\">南極<span class=\"ext\">polus australis, vertex austrinus, meridianus axis.</span></div><div class=\"cf\">地球の両極<span class=\"ext\">ultimae Aquilonis Austrive partes(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://北極\">北極</a>,<a href=\"entry://南極\">南極</a>.</div>\r\n","<div class=\"hw jl\">極上</div><div class=\"def\">⇒<a href=\"entry://最高\">最高</a>.</div>\r\n","<div class=\"hw jl\">極意</div><div class=\"def\">ars secreta.</div>\r\n","<div class=\"hw jl\">極端</div><div class=\"def\">▼<b>～な</b> immoderatus, extremus.</div><div class=\"def\">▼<b>～に</b> immodeste, immodice.</div>\r\n","<div class=\"hw jl\">楽しい</div><div class=\"def\">jucundus, ludicer, ludibundus, laetus.</div><div class=\"def\">▼<b>楽しく</b> jucunde.</div><div class=\"def\">▼<b>楽しさ</b> jucunditas.</div><div class=\"def\">⇒<a href=\"entry://おかしい\">おかしい</a>,<a href=\"entry://陽気\">陽気</a>.</div>\r\n","<div class=\"hw jl\">楽しませる</div><div class=\"def\">delecto, oblecto.</div>\r\n","<div class=\"hw jl\">楽しみ</div><div class=\"def\">delectatio, oblectatio, delectamentum, oblectamentum.</div><div class=\"def\">⇒<a href=\"entry://喜ぶ\">喜ぶ</a>.</div>\r\n","<div class=\"hw jl\">楽しむ</div><div class=\"def\">se oblectare(← oblecto), oblector(<i>pass</i>), delector(<i>pass</i>), fruor(<i>dep</i>), laetor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://喜ぶ\">喜ぶ</a>.</div>\r\n","<div class=\"hw jl\">楽な</div><div class=\"def\">(=易しい)facilis.</div><div class=\"def\">▼<b>楽に</b>(=苦労なしに)facile, sine(ullo)labore.</div>\r\n","<div class=\"hw jl\">楽器</div><div class=\"def\">organum, instrumentum musicum.</div>\r\n","<div class=\"hw jl\">楽園</div><div class=\"def\">paradisus.</div><div class=\"def\">▼<b>～の</b> paradisiacus.</div>\r\n","<div class=\"hw jl\">楽観</div><div class=\"def\">bona spes.</div><div class=\"def\">▼<b>～主義</b> optimismus.</div><div class=\"def\">▼<b>～主義者</b> optimismi fautor(<i>m</i>), melioris partis conspector(<i>m</i>), in meliorem partem acceptor(<i>m</i>).</div><div class=\"def\">▼(何事につけ)<b> ～する</b>(omnia)in optimam partem accipio.</div>\r\n","<div class=\"hw jl\">概念</div><div class=\"def\">conceptio, conceptus, imago, notio, notitia.</div>\r\n","<div class=\"hw jl\">構想</div><div class=\"def\">consilium.</div><div class=\"ex2\">新たな中東和平～<span class=\"ext\">novum de pace in Proximo Oriente facienda consilium.</span></div><div class=\"def\">⇒<a href=\"entry://計画\">計画</a>.</div>\r\n","<div class=\"hw jl\">構成</div><div class=\"def\">constructio, compositio.</div><div class=\"def\">▼<b>～する</b> compono.</div><div class=\"def\">⇒<a href=\"entry://構造\">構造</a>.</div>\r\n","<div class=\"hw jl\">構造</div><div class=\"def\">structura.</div><div class=\"def\">⇒<a href=\"entry://構成\">構成</a>.</div>\r\n","<div class=\"hw jl\">槍</div><div class=\"def\">lancea.</div><div class=\"def\">▼<b>小さな～</b> lanceola.</div><div class=\"def\">▼<b>投げ～</b> jaculum.</div><div class=\"def\">▼<b>～を投げる人</b> jaculator(<i>m</i>), jaculatrix(<i>f</i>).</div><div class=\"def\">▼<b>～を投げる</b> jaculor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">様子</div><div class=\"def\">(=外見, 見かけ)aspectus, species, facies;(=情勢, 状態)status, habitus, condicio.</div>\r\n","<div class=\"hw jl\">標準</div><div class=\"def\">norma, regula.</div>\r\n","<div class=\"hw jl\">標準時</div><div class=\"def\">hora legitima [lege statuta](⇔地方時 hora loci propria).</div>\r\n","<div class=\"hw jl\">標識</div><div class=\"def\">indicium, signum.</div><div class=\"def\">▼<b>交通～</b> indicia [signa] viaria(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">模倣</div><div class=\"def\">▼(手本を)<b> ～する</b>(exemplum)imitor(<i>dep</i>), assimulo.</div>\r\n","<div class=\"hw jl\">模型</div><div class=\"def\">(=雛形)praestituta forma, specimen praestitutum.</div>\r\n","<div class=\"hw jl\">模様</div><div class=\"def\">▼<b>(花)～</b> signa(florum)(<i>pl</i>), (florum)lineamenta(<i>pl</i>), picta(florum)species.</div>\r\n","<div class=\"hw jl\">模範</div><div class=\"def\">exemplum, exemplar, exempla ad imitandum.</div><div class=\"def\">▼<b>～的な</b> imitatione dignus.</div>\r\n","<div class=\"hw jl\">権利</div><div class=\"def\">jus.</div>\r\n","<div class=\"hw jl\">権力</div><div class=\"def\">potestas, potentia.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">三権分立の原理<span class=\"ext\">axioma divisionis potestatum.</span></div>\r\n","<div class=\"hw jl\">権威</div><div class=\"def\">auctoritas, dignitas.</div>\r\n","<div class=\"hw jl\">権限</div><div class=\"def\">auctoritas, potestas.</div>\r\n","<div class=\"hw jl\">横</div><div class=\"def\">(=幅)latitudo;(=側面)latus.</div><div class=\"def\">▼<b>～に広い</b>(=幅広い)latus.</div><div class=\"def\">▼(...の)<b> ～に</b>(=...の側に)ad 〈+<i>acc</i>〉, propter 〈+<i>acc</i>〉, apud 〈+<i>acc</i>〉, ad latus 〈+<i>gen</i>〉.</div><div class=\"def\">⇒<a href=\"entry://幅\">幅</a>,<a href=\"entry://側\">側<SUB>そば</SUB></a>.</div>\r\n","<div class=\"hw jl\">横たわる</div><div class=\"def\">jaceo, cubo.</div>\r\n","<div class=\"hw jl\">横になる</div><div class=\"def\">(寝床などに)incumbo, recumbo, decumbo.</div>\r\n","<div class=\"hw jl\">横切る</div><div class=\"def\">(=通り過ぎる, 渡る, 越える)transeo, transgredior(<i>dep</i>), transmeo, transcurro, trajicio, transmitto, transcendo.</div><div class=\"def\">⇒<a href=\"entry://越える・超える\">越える</a>,<a href=\"entry://渡る\">渡る</a>.</div>\r\n","<div class=\"hw jl\">横断</div><div class=\"def\">transitus, transmissio, transmissus, trajectio, trajectus.</div><div class=\"def\">⇒<a href=\"entry://渡る\">渡る</a>.</div>\r\n","<div class=\"hw jl\">横暴</div><div class=\"def\">vis, violentia.</div><div class=\"def\">▼<b>～な</b> violentus, vi factus, imperiosus, superbus, tyrannicus.</div>\r\n","<div class=\"hw jl\">横領</div><div class=\"def\">suppressio.</div><div class=\"def\">▼<b>～者</b> interceptor.</div><div class=\"def\">▼<b>～する</b> supprimo, averto, interverto.</div><div class=\"ex2\">公金を～する<span class=\"ext\">pecunias e publico intercipio.</span></div>\r\n","<div class=\"hw jl\">樽</div><div class=\"def\">cupa, dolium.</div><div class=\"def\">⇒<a href=\"entry://桶\">桶</a>.</div>\r\n","<div class=\"hw jl\">橋</div><div class=\"def\">pons.</div><div class=\"def\">▼<b>小さな～</b> ponticulus.</div><div class=\"ex2\">(川に)～をかける<span class=\"ext\">facio pontem(in flumine).</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">つり橋<span class=\"ext\">pons pensilis.</span></div>\r\n","<div class=\"hw jl\">機会</div><div class=\"def\">facultas, occasio, opportunitas, copia.</div>\r\n","<div class=\"hw jl\">機械</div><div class=\"def\">machina.</div><div class=\"def\">⇒<a href=\"entry://器具\">器具</a>.</div>\r\n","<div class=\"hw jl\">機知</div><div class=\"def\">sal, urbanitas.</div><div class=\"def\">▼<b>～のある</b> salsus.</div>\r\n","<div class=\"hw jl\">機能</div><div class=\"def\">agendi ratio [modus, ordo].</div>\r\n","<div class=\"hw jl\">機関車</div><div class=\"def\">currus tractorius, machina vectoria, vectorius currus ferriviarius.</div>\r\n","<div class=\"hw jl\">檻</div><div class=\"def\">saeptum, cavea.</div><div class=\"ex2\">～に閉じ込める<span class=\"ext\">in caevam includo.</span></div>\r\n","<div class=\"hw jl\">櫂</div><div class=\"def\">remus.</div><div class=\"def\">⇒<a href=\"entry://こぐ\">こぐ</a>.</div>\r\n","<div class=\"hw jl\">欄</div><div class=\"def\">locus;(=新聞や写本などの縦欄)columna.</div><div class=\"def\">▼<b>～外</b> margo.</div>\r\n","<div class=\"hw jl\">欠く</div><div class=\"def\">(...を)〈re〉 careo.</div>\r\n","<div class=\"hw jl\">欠ける</div><div class=\"def\">(皿などが)(=割れる)frangor(<i>pass</i>).</div><div class=\"def\">▼<b>欠けている</b>(=足りない)desum, absum.</div>\r\n","<div class=\"hw jl\">欠乏</div><div class=\"def\">inopia, egestas, penuria.</div><div class=\"def\">▼<b>～している</b> egeo.</div><div class=\"def\">⇒<a href=\"entry://乏しい\">乏しい</a>,<a href=\"entry://欠如\">欠如</a>.</div>\r\n","<div class=\"hw jl\">欠勤</div><div class=\"def\">⇒<a href=\"entry://欠席\">欠席</a>.</div>\r\n","<div class=\"hw jl\">欠如</div><div class=\"def\">absentia.</div><div class=\"def\">⇒<a href=\"entry://欠乏\">欠乏</a>,<a href=\"entry://不足\">不足</a>.</div>\r\n","<div class=\"hw jl\">欠席</div><div class=\"def\">absentia.</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[形]</span> absens. <span class=\"pos3\">[動]</span> absum, desum.</div>\r\n","<div class=\"hw jl\">欠点</div><div class=\"def\">vitium.</div><div class=\"def\">▼<b>～をもつ</b> vitiosus.</div><div class=\"ex2\">愚か者は一つの～を避けているうちに反対の～に至る<span class=\"ext\">dum vitant stulti vitia, in contraria currunt.</span></div>\r\n","<div class=\"hw jl\">欠陥</div><div class=\"def\">vitium.</div><div class=\"def\">▼<b>～のある</b> vitiosus.</div><div class=\"def\">⇒<a href=\"entry://不完全\">不完全</a>,<a href=\"entry://欠点\">欠点</a>.</div>\r\n","<div class=\"hw jl\">次</div><div class=\"def\">▼<b>～の</b> proximus, posterior, posterus, sequens.</div><div class=\"def\">▼<b>～に</b> deinde, deinceps.</div><div class=\"def\">▼<b>～にくる</b><span class=\"pos3\">[動]</span> insequor(<i>dep</i>).</div><div class=\"ex2\">その～の日[夜]に<span class=\"ext\">die [nocte] insequenti.</span></div><div class=\"ex2\">～の機会に<span class=\"ext\">proxime.</span></div><div class=\"def\">⇒<a href=\"entry://明日\">明日</a>,<a href=\"entry://翌日\">翌日</a>.</div>\r\n","<div class=\"hw jl\">次々</div><div class=\"def\">▼<b>～と</b>(=順番に)deinceps.</div><div class=\"ex2\">疲れた兵士たちに～と元気のよい兵士たちが交代する<span class=\"ext\">defatigatis in vicem integri succedunt.</span></div>\r\n","<div class=\"hw jl\">次いで</div><div class=\"def\">(...に)secundum 〈+<i>acc</i>〉.</div><div class=\"ex2\">神々に～<span class=\"ext\">secundum deos.</span></div>\r\n","<div class=\"hw jl\">次元</div><div class=\"def\">mensura, dimensio.</div><div class=\"def\">▼<b>二～の</b> bimensuralis.</div><div class=\"def\">▼<b>三～の</b> tribus mensuris praeditus.</div><div class=\"def\">▼<b>四～の</b> in quadrifariam mensuram extentus.</div>\r\n","<div class=\"hw jl\">次第</div><div class=\"def\">⇒<a href=\"entry://掛かっている\">掛かっている</a>,<a href=\"entry://事情\">事情</a>,<a href=\"entry://否や\">否や</a>.</div>\r\n","<div class=\"hw jl\">次第に</div><div class=\"def\">paulatim.</div>\r\n","<div class=\"hw jl\">欧州</div><div class=\"def\">Europa.</div><div class=\"def\">▼<b>～連合</b> Unio Europae.</div><div class=\"def\">▼<b>～諸国</b> nationes Europaeae.</div><div class=\"def\">▼<b>～議会</b> parlamentum Europaeum.</div><div class=\"def\">▼<b>～(人)の</b> Europaeus.</div><div class=\"def\">▼<b>～人</b> Europaei(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">欲</div><div class=\"def\">(=貪欲)aviditas, fames;(=欲望)cupiditas, cupido, libido.</div><div class=\"def\">▼<b>食～</b> cupiditas edendi.</div><div class=\"def\">▼<b>金～</b> pecuniae cupiditas.</div><div class=\"def\">▼<b>復讐～</b> libido ulciscendi.</div><div class=\"def\">▼<b>知識～</b> cupiditas cognitionis.</div><div class=\"def\">▼<b>淫～</b> concupiscentia.</div>\r\n","<div class=\"hw jl\">欲しい</div><div class=\"def\">(=欲する, 望む)cupio, appeto, volo, studeo.</div><div class=\"def\">▼<b>むしろ...が～</b> malo.</div><div class=\"def\">▼<b>欲しくない</b> nolo.</div><div class=\"def\">⇒<a href=\"entry://望む\">望む</a>,<a href=\"entry://熱望\">熱望</a>.</div>\r\n","<div class=\"hw jl\">欲望</div><div class=\"def\">cupiditas, cupido, libido, desiderium.</div>\r\n","<div class=\"hw jl\">欲求</div><div class=\"def\">cupiditas, desiderium.</div><div class=\"ex2\">飲食の～<span class=\"ext\">cibi potionisque desiderium.</span></div><div class=\"def\">⇒<a href=\"entry://欲望\">欲望</a>,<a href=\"entry://欲\">欲</a>.</div>\r\n","<div class=\"hw jl\">欺く</div><div class=\"def\"><span class=\"pos3\">[動]</span>(=だます)fallo, decipio, deludo, fraudo, illudo.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> fallax.</div><div class=\"def\">▼<b>～こと</b> fraus.</div><div class=\"def\">▼<b>～者</b> deceptor.</div><div class=\"def\">⇒<a href=\"entry://詐欺\">詐欺</a>.</div>\r\n","<div class=\"hw jl\">歌</div><div class=\"def\">cantus, cantio, canticum, carmen.</div><div class=\"def\">⇒<a href=\"entry://歌手\">歌手</a>.</div>\r\n","<div class=\"hw jl\">歌う</div><div class=\"def\">cano, canto.</div><div class=\"ex2\">一斉に～<span class=\"ext\">concino.</span></div>\r\n","<div class=\"hw jl\">歌手</div><div class=\"def\">cantor(<i>m</i>), cantrix(<i>f</i>), cantator(<i>m</i>), cantatrix(<i>f</i>).</div>\r\n","<div class=\"hw jl\">歓迎</div><div class=\"def\">▼<b>～の挨拶</b> advenientis salutatio.</div><div class=\"def\">▼<b>～する</b>(=喜んで受け入れる)benigne accipio, benigno vultu excipio.</div><div class=\"def\">▼<b>一斉に(皆で)～する</b> consaluto.</div><div class=\"def\">⇒<a href=\"entry://挨拶\">挨拶</a>.</div>\r\n","<div class=\"hw jl\">止まる</div><div class=\"def\">▼(私の時計は)<b> 止まっている</b>(meum horologium)substitit(<i>pf</i>).</div>\r\n","<div class=\"hw jl\">正しい</div><div class=\"def\">(=間違いがない, 真正の, 正確な)rectus, verus, emendatus;(=公正な, 正当な, 正義にかなった)justus, aequus, bonus.</div><div class=\"def\">▼<b>正しく</b>(=正確に)recte, vere;(=正当に)juste.</div><div class=\"def\">⇒<a href=\"entry://正確\">正確</a>.</div>\r\n","<div class=\"hw jl\">正午</div><div class=\"def\">meridies.</div><div class=\"def\">▼<b>～に</b> meridie.</div><div class=\"def\">▼<b>～の</b> meridianus.</div>\r\n","<div class=\"hw jl\">正式</div><div class=\"def\">▼<b>～な</b> justus, legitimus.</div>\r\n","<div class=\"hw jl\">正当</div><div class=\"def\">▼<b>～な</b> justus, rectus.</div><div class=\"def\">▼<b>～に, ～にも</b> juste, (justo)jure, merito, haud immerito, recte.</div>\r\n","<div class=\"hw jl\">正月</div><div class=\"def\">(=一年の最初の月)primus incipientis anni mensis.</div>\r\n","<div class=\"hw jl\">正気</div><div class=\"def\">sanitas.</div><div class=\"def\">▼<b>～の</b> sanus.</div>\r\n","<div class=\"hw jl\">正直</div><div class=\"def\">probitas, sinceritas.</div><div class=\"def\">▼<b>～な</b> probus, sincerus, frugi.</div><div class=\"def\">▼<b>～に</b> sincere.</div>\r\n","<div class=\"hw jl\">正確</div><div class=\"def\">▼<b>～(さ)</b> subtilitas;(証言や記述の)fides.</div><div class=\"def\">▼<b>～な</b> exactus, examinatus, subtilis, fidelis.</div><div class=\"def\">▼<b>～に</b> subtiliter, accurate, fideliter, recte.</div>\r\n","<div class=\"hw jl\">正規</div><div class=\"def\">▼<b>～の</b> justus, legitimus, regulam servans, rectus.</div>\r\n","<div class=\"hw jl\">正面</div><div class=\"def\">(建物等の)frons.</div><div class=\"def\">▼<b>～に</b> contra.</div><div class=\"def\">▼(...の)<b> ～に</b> pro 〈+<i>abl</i>〉.</div><div class=\"def\">⇒<a href=\"entry://向かい合って\">向かい合って</a>.</div>\r\n","<div class=\"hw jl\">武器</div><div class=\"def\">arma(<i>pl</i>), telum.</div><div class=\"def\">▼<b>～を持った</b>(=武装した)armatus.</div><div class=\"def\">▼<b>～をとる</b> arma capio.</div>\r\n","<div class=\"hw jl\">武装</div><div class=\"def\">armatus, armatura.</div><div class=\"def\">▼<b>～した</b> armatus, armifer, armiger.</div><div class=\"def\">▼<b>～させる</b> armo.</div><div class=\"def\">⇒<a href=\"entry://武器\">武器</a>.</div>\r\n","<div class=\"hw jl\">歩く</div><div class=\"def\">gradior(<i>dep</i>), ingredior(<i>dep</i>).</div><div class=\"def\">▼<b>歩いて</b> pedibus.</div>\r\n","<div class=\"hw jl\">歩兵</div><div class=\"def\">pedes.</div><div class=\"def\">▼<b>～隊</b> peditatus, pedites(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">歩道</div><div class=\"def\">crepido viae [semitae], viae margo, via peditibus destinata.</div>\r\n","<div class=\"hw jl\">歯</div><div class=\"def\">dens.</div><div class=\"def\">▼<b>～の</b> dentarius.</div><div class=\"def\">▼<b>～を抜く</b> edento.</div><div class=\"def\">▼<b>～の生えた</b> dentatus.</div><div class=\"def\">▼<b>～のない</b> edentulus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">乳歯<span class=\"ext\">dentes priores(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">歯茎</div><div class=\"def\">gingiva.</div>\r\n","<div class=\"hw jl\">...歳</div><div class=\"ex2\">あの30歳の男<span class=\"ext\">ille vir triginta annos natus.</span></div><div class=\"ex2\">私は14歳でギリシア語の悲劇を書いた<span class=\"ext\">quattuordecim natus annos Graecam tragoediam scripsi.</span></div><div class=\"ex2\">彼女は101歳で亡くなった<span class=\"ext\">de vita decessit centum et unum annos nata.</span></div><div class=\"ex2\">24歳の若い女性<span class=\"ext\">puella viginti quattuor annorum.</span></div><div class=\"ex2\">私は10歳である<span class=\"ext\">annum decimum ago.</span></div><div class=\"def\">⇒<a href=\"entry://年齢\">年齢</a>.</div>\r\n","<div class=\"hw jl\">歴史</div><div class=\"def\">(学問としての)historia;(できごととしての)res gestae(<i>pl</i>).</div><div class=\"def\">▼<b>～家</b> rerum scriptor [auctor], historicus, historiae auctor, historiarum scriptor, ei qui res gestas scripserunt.</div><div class=\"ex2\">～(書)を書く<span class=\"ext\">historiam scribo.</span></div>\r\n","<div class=\"hw jl\">死</div><div class=\"def\">mors, decessus, obitus;(不慮の)interitus.</div><div class=\"def\">⇒<a href=\"entry://死ぬ\">死ぬ</a>,<a href=\"entry://死すべき\">死すべき</a>.</div>\r\n","<div class=\"hw jl\">死すべき</div><div class=\"def\">mortalis.</div><div class=\"def\">▼<b>～運命</b> mortalitas.</div><div class=\"def\">⇒<a href=\"entry://死ぬ\">死ぬ</a>.</div>\r\n","<div class=\"hw jl\">死ぬ</div><div class=\"def\">morior(<i>dep</i>), emorior(<i>dep</i>), decedo, exstinguor(<i>pass</i>), pereo, obeo, intereo, vitam amitto, animam abicio, diem supremum obeo, e vita excedo.</div><div class=\"ex2\">プラトンは書きながら死んだ<span class=\"ext\">Plato scribens est mortuus.</span></div><div class=\"ex2\">ウェルギリウスは51歳で死んだ<span class=\"ext\">Vergilius decessit annos unum et quinquaginta natus.</span></div>\r\n","<div class=\"hw jl\">死亡</div><div class=\"def\">mors, decessus.</div><div class=\"def\">▼<b>～する</b> vitam amitto.</div><div class=\"def\">⇒<a href=\"entry://死\">死</a>,<a href=\"entry://死ぬ\">死ぬ</a>.</div>\r\n","<div class=\"hw jl\">死体</div><div class=\"def\">cadaver, corpus(exanime).</div>\r\n","<div class=\"hw jl\">死刑</div><div class=\"def\">capitis [capitalis] poena, poena mortis [vitae], (ultimum)supplicium, ultima poena.</div><div class=\"def\">▼<b>～の, ～に値する</b> capitalis.</div><div class=\"ex2\">(人を)～にする<span class=\"ext\">〈alqm〉 supplicio afficio.</span></div><div class=\"ex2\">(人に)～を宣告する<span class=\"ext\">alqm capite damno.</span></div><div class=\"ex2\">～の宣告を受けた<span class=\"ext\">capitis damnatus.</span></div>\r\n","<div class=\"hw jl\">死者</div><div class=\"def\">(homo)mortuus(<i>m</i>), (femina)mortua(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://故人\">故人</a>.</div>\r\n","<div class=\"hw jl\">残す</div><div class=\"def\">(後に)linquo, relinquo, derelinquo.</div>\r\n","<div class=\"hw jl\">残っている</div><div class=\"def\">supersum, resto.</div>\r\n","<div class=\"hw jl\">残り</div><div class=\"def\">reliquia, reliquum, residuum.</div><div class=\"def\">▼<b>～の</b>(=残った)reliquus, residuus.</div>\r\n","<div class=\"hw jl\">残る</div><div class=\"def\">(=留まる, 居残る, 居続ける)maneo, remaneo, se retinere(← retineo), se continere(← contineo), resideo.</div>\r\n","<div class=\"hw jl\">残忍</div><div class=\"def\">crudelitas, saevitia, ferocitas.</div><div class=\"def\">▼<b>～な</b> crudelis, saevus, ferus.</div><div class=\"def\">▼<b>～に</b> ferociter.</div><div class=\"def\">⇒<a href=\"entry://残酷\">残酷</a>.</div>\r\n","<div class=\"hw jl\">残念</div><div class=\"def\">paenitentia.</div><div class=\"def\">▼<b>～な</b> dolendus, odiosus.</div><div class=\"ex2\">(人に)～だと思わせる<span class=\"ext\">〈alqm〉 paenitet(<i>impers</i>).</span></div><div class=\"ex2\">(...が)非常に～だ<span class=\"ext\">accidit perincommode quod(...)/ molestissime fero quod(...).</span></div><div class=\"def\">⇒<a href=\"entry://後悔\">後悔</a>.</div>\r\n","<div class=\"hw jl\">残酷</div><div class=\"def\">crudelitas, diritas.</div><div class=\"def\">▼<b>～な</b> crudelis, dirus.</div><div class=\"def\">▼<b>～に</b> crudeliter.</div><div class=\"def\">⇒<a href=\"entry://残忍\">残忍</a>.</div>\r\n","<div class=\"hw jl\">残高</div><div class=\"def\">(pecuniae)residuum, reliqua pecunia [summa].</div>\r\n","<div class=\"hw jl\">殴る</div><div class=\"def\">ferio, icio;(拳で)(pugnis)caedo.</div><div class=\"def\">⇒<a href=\"entry://たたく\">たたく</a>,<a href=\"entry://打つ\">打つ</a>.</div>\r\n","<div class=\"hw jl\">段</div><div class=\"def\">gradus.</div><div class=\"def\">⇒<a href=\"entry://段落\">段落</a>,<a href=\"entry://階段\">階段</a>.</div>\r\n","<div class=\"hw jl\">段落</div><div class=\"def\">caput.</div>\r\n","<div class=\"hw jl\">段階</div><div class=\"def\">ordo.</div><div class=\"def\">▼<b>～をなして</b> gradatim.</div><div class=\"def\">⇒<a href=\"entry://段\">段</a>.</div>\r\n","<div class=\"hw jl\">殺す</div><div class=\"def\">interficio, neco, occido.</div><div class=\"def\">⇒<a href=\"entry://殺害\">殺害</a>,<a href=\"entry://殺人\">殺人</a>.</div>\r\n","<div class=\"hw jl\">殺人</div><div class=\"def\">homicidium.</div><div class=\"def\">⇒<a href=\"entry://殺害\">殺害</a>.</div>\r\n","<div class=\"hw jl\">殺害</div><div class=\"def\">nex, caedes, occisio, homicidium.</div><div class=\"def\">▼<b>～者</b> interfector, homicida.</div><div class=\"def\">▼<b>～する</b> neco, trucido, interficio, caedo, occido.</div><div class=\"def\">⇒<a href=\"entry://殺人\">殺人</a>,<a href=\"entry://殺す\">殺す</a>.</div>\r\n","<div class=\"hw jl\">殺戮</div><div class=\"def\">caedes, trucidatio, strages, occisio.</div><div class=\"def\">⇒<a href=\"entry://殺害\">殺害</a>.</div>\r\n","<div class=\"hw jl\">殺虫剤</div><div class=\"def\">venenum insectis internecivum.</div>\r\n","<div class=\"hw jl\">殻</div><div class=\"def\">(=貝殻)concha, testa.</div>\r\n","<div class=\"hw jl\">毅然</div><div class=\"def\">▼<b>～とした態度</b> constantia.</div>\r\n","<div class=\"hw jl\">母</div><div class=\"def\">mater, genetrix.</div><div class=\"def\">▼<b>～(方)の</b> maternus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">乳母<span class=\"ext\">nutrix.</span></div><div class=\"cf\">継母<span class=\"ext\">noverca.</span></div><div class=\"def\">⇒<a href=\"entry://父\">父</a>,<a href=\"entry://両親\">両親</a>.</div>\r\n","<div class=\"hw jl\">母乳</div><div class=\"def\">lac muliebre.</div>\r\n","<div class=\"hw jl\">母性</div><div class=\"def\">(=母であること)maternitas.</div>\r\n","<div class=\"hw jl\">毎年</div><div class=\"def\"><span class=\"pos3\">[副]</span> quotannis.</div><div class=\"def\">▼<b>～の</b> annuus.</div>\r\n","<div class=\"hw jl\">毎日</div><div class=\"def\"><span class=\"pos3\">[名]</span> omnis dies.</div><div class=\"def\">━<span class=\"pos3\">[副]</span> cottidie, in dies, singulis diebus.</div><div class=\"def\">▼<b>～の</b> cottidianus.</div>\r\n","<div class=\"hw jl\">毎月</div><div class=\"def\"><span class=\"pos3\">[副]</span> singulis mensibus.</div>\r\n","<div class=\"hw jl\">毒</div><div class=\"def\">venenum.</div><div class=\"def\">▼<b>～の</b> veneficus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">有毒な<span class=\"ext\">nocens, venenatus, venenifer.</span></div><div class=\"def\">⇒<a href=\"entry://毒殺\">毒殺</a>,<a href=\"entry://有害\">有害</a>,<a href=\"entry://消毒\">消毒</a>,<a href=\"entry://中毒\">中毒</a>,<a href=\"entry://盛る\">盛る</a>.</div>\r\n","<div class=\"hw jl\">毒殺</div><div class=\"def\">veneficium.</div><div class=\"def\">▼<b>～する</b> veneno, veneno tollo [occido, neco].</div><div class=\"def\">⇒<a href=\"entry://毒\">毒</a>.</div>\r\n","<div class=\"hw jl\">比べる</div><div class=\"def\">comparo, confero.</div><div class=\"def\">▼<b>～こと</b> comparatio.</div><div class=\"def\">⇒<a href=\"entry://比較\">比較</a>.</div>\r\n","<div class=\"hw jl\">比例</div><div class=\"def\">proportio, proportionalitas.</div><div class=\"def\">▼<b>～した</b> proportionalis, proportinatus.</div><div class=\"def\">▼<b>～して</b> proportionaliter.</div>\r\n","<div class=\"hw jl\">比喩</div><div class=\"def\">translatio.</div><div class=\"def\">▼<b>～的な</b> translativus.</div><div class=\"def\">▼<b>～的に</b> translative.</div><div class=\"def\">▼<b>～的な表現</b> verba quae transferuntur.</div>\r\n","<div class=\"hw jl\">比肩</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[動]</span> aequo. <span class=\"pos3\">[形]</span> aequabilis.</div>\r\n","<div class=\"hw jl\">比較</div><div class=\"def\">comparatio, contentio, collatio, compositio.</div><div class=\"def\">▼<b>～する</b> comparo, contendo, confero, compono, aequo, adaequo.</div><div class=\"def\">▼<b>～的(に), ～によって</b> comparate, per comparationem, ex comparatione.</div>\r\n","<div class=\"hw jl\">毛</div><div class=\"def\">pilus, villus;(=羊毛)ovium villi(<i>pl</i>), lana;(=髪の毛, 頭髪)crinis, capillus, coma.</div>\r\n","<div class=\"hw jl\">毛布</div><div class=\"def\">lodix, lodex.</div><div class=\"def\">▼<b>小さな～</b> lodicula.</div><div class=\"def\">⇒<a href=\"entry://布\">布</a>.</div>\r\n","<div class=\"hw jl\">毛深い</div><div class=\"def\">(=毛むくじゃらの)pilosus, villosus.</div>\r\n","<div class=\"hw jl\">毛皮</div><div class=\"def\">pellis, tergum.</div>\r\n","<div class=\"hw jl\">毛穴</div><div class=\"def\">(=皮膚の小さな穴)porus, invisibilia corporis foramina(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">氏名</div><div class=\"def\">(=姓)nomen gentile [gentilicium, paternum];(=姓と個人名)nomen(gentilicium)atque praenomen.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">(古代ローマの)家名 cognomen, 氏族名 nomen gentile, 個人名 praenomen.</div><div class=\"def\">⇒<a href=\"entry://名前\">名前</a>.</div>\r\n","<div class=\"hw jl\">民主主義</div><div class=\"def\">▼<b>～(政治)</b> democratia.</div><div class=\"def\">▼<b>～(政治)の</b> democraticus.</div><div class=\"def\">▼<b>民主化する</b> democratiam induco, democraticis rationibus instituo, rem publicam populari rationi constituo, ad popularis civitatis formam adduco.</div>\r\n","<div class=\"hw jl\">民族</div><div class=\"def\">gens, genus, natio.</div><div class=\"def\">▼<b>～の</b> gentilicus.</div>\r\n","<div class=\"hw jl\">民衆</div><div class=\"def\">populus, plebs.</div><div class=\"def\">▼<b>～の, ～派の</b> popularis.</div><div class=\"ex2\">～の声は神の声(=天声人語)<span class=\"ext\">vox populi vox dei.</span></div><div class=\"def\">⇒<a href=\"entry://大衆\">大衆</a>.</div>\r\n","<div class=\"hw jl\">民間</div><div class=\"def\">▼<b>～の</b>(=民営の, 公的機関に属さない)privatus;(=通俗の, 人々の間に広まった)popularis, vulgaris.</div>\r\n","<div class=\"hw jl\">気</div><div class=\"ex2\">～が小さい(=臆病な)<span class=\"ext\">timidus, formidolosus.</span></div><div class=\"ex2\">～が狂う<span class=\"ext\">insanio.</span></div><div class=\"ex2\">～に入られる<span class=\"ext\">placeo, libet(<i>impers</i>).</span></div><div class=\"ex2\">～に入られた<span class=\"ext\">gratus, jucundus, dilectus, gratiosus.</span></div><div class=\"ex2\">～の狂った<span class=\"ext\">amens, demens, furiosus, insanus.</span></div><div class=\"ex2\">～を失う<span class=\"ext\">animo linquor(<i>pass</i>).</span></div><div class=\"def\">⇒<a href=\"entry://お気に入り\">お気に入り</a>,<a href=\"entry://性格\">性格</a>,<a href=\"entry://狂う\">狂う</a>,<a href=\"entry://狂気\">狂気</a>.</div>\r\n","<div class=\"hw jl\">気がかり</div><div class=\"def\">anxietas, cura, sollicitudo.</div><div class=\"def\">▼<b>～な</b> anxius.</div>\r\n","<div class=\"hw jl\">気づく</div><div class=\"def\">animadverto, sentio, conspicor(<i>dep</i>), conspicio.</div>\r\n","<div class=\"hw jl\">気まぐれ</div><div class=\"def\">levitas, ingenii mobilitas, (mentis)inconstantia.</div><div class=\"def\">▼<b>～な</b> libidinosus, levis, inconstans, mobilis, mutabilis, varius.</div><div class=\"def\">▼<b>～に</b> libidinose, mobiliter, inconstanter.</div>\r\n","<div class=\"hw jl\">気体</div><div class=\"def\">(=ガス)aeriformis substantia, vaporalis substantia, aeria substantia, gasium.</div><div class=\"def\">▼<b>～の</b>(=ガス状の)flabilis, aeriformis, aeriam naturam habens, gasiosus.</div><div class=\"def\">⇒<a href=\"entry://空気\">空気</a>.</div>\r\n","<div class=\"hw jl\">気候</div><div class=\"def\">caelum, caeli status, caeli positio.</div>\r\n","<div class=\"hw jl\">気分</div><div class=\"def\">animi affectio, animi habitus, animus.</div><div class=\"ex2\">～はいかがですか<span class=\"ext\">quid tibi animi est? / Quomodo vales?</span></div>\r\n","<div class=\"hw jl\">気前</div><div class=\"def\">▼<b>～のよい</b> largus, munificus, liberalis.</div><div class=\"def\">▼<b>～のよさ</b> largitas, munificentia, liberalitas.</div><div class=\"def\">▼<b>～よく</b> large, munifice, liberaliter.</div>\r\n","<div class=\"hw jl\">気力</div><div class=\"def\">nervus, animi vis, animi robur, animi vigor.</div><div class=\"def\">▼<b>無～</b>(animi)inertia, (animi)ignavia, (animi)mollitia, veternus.</div>\r\n","<div class=\"hw jl\">気味の悪い</div><div class=\"def\">foedus.</div>\r\n","<div class=\"hw jl\">気持</div><div class=\"def\">(=感情)animus, mens, sensus, affectus, animi affectus [motus], mentis affectus.</div><div class=\"def\">▼<b>～がいい</b> jucundus, suavis.</div><div class=\"def\">▼<b>～がいいこと</b> jucunditas, suavitas.</div><div class=\"def\">⇒<a href=\"entry://考え\">考え</a>,<a href=\"entry://意識\">意識</a>,<a href=\"entry://気分\">気分</a>.</div>\r\n","<div class=\"hw jl\">気晴らし</div><div class=\"def\">oblectamen, oblectamentum, oblectatio, delectatio, delectamentum, (animi)remissio, jocus.</div><div class=\"def\">⇒<a href=\"entry://娯楽\">娯楽</a>.</div>\r\n","<div class=\"hw jl\">気温</div><div class=\"def\">aeris temperies.</div><div class=\"def\">⇒<a href=\"entry://温度\">温度</a>.</div>\r\n","<div class=\"hw jl\">気象</div><div class=\"def\">(=天気, 天候)tempestas, caelum;(=大気中の諸現象)(caeli)phaenomena(<i>pl</i>), phaenomena caelestia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">気質</div><div class=\"def\">mentis habitus.</div>\r\n","<div class=\"hw jl\">気配</div><div class=\"def\">odor.</div><div class=\"ex2\">いくらか独裁官の～がする<span class=\"ext\">est non nullus odor dictaturae.</span></div><div class=\"def\">⇒<a href=\"entry://兆候\">兆候</a>,<a href=\"entry://前兆\">前兆</a>.</div>\r\n","<div class=\"hw jl\">気配り</div><div class=\"def\">cura.</div>\r\n","<div class=\"hw jl\">気長</div><div class=\"def\">longanimitas.</div><div class=\"def\">▼<b>～な</b> longanimis.</div><div class=\"def\">▼<b>～に</b> longanimiter.</div>\r\n","<div class=\"hw jl\">気高い</div><div class=\"def\">generosus.</div><div class=\"def\">▼<b>気高さ</b> nobilitas.</div><div class=\"def\">▼<b>気高く</b> honeste.</div><div class=\"def\">⇒<a href=\"entry://高貴\">高貴</a>.</div>\r\n","<div class=\"hw jl\">水</div><div class=\"def\">aqua.</div><div class=\"def\">▼<b>～の</b> aquarius, aqualis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">真水<span class=\"ext\">aqua dulcis.</span></div><div class=\"cf\">海水<span class=\"ext\">aqua marina.</span></div><div class=\"cf\">雨水<span class=\"ext\">aqua pluvia [pluvialis].</span></div><div class=\"cf\">川の水<span class=\"ext\">aqua fluvialis [ex flumine].</span></div><div class=\"cf\">井戸水<span class=\"ext\">aqua ex puteo.</span></div>\r\n","<div class=\"hw jl\">水たまり</div><div class=\"def\">lacuna.</div><div class=\"def\">⇒<a href=\"entry://ぬかるみ\">ぬかるみ</a>.</div>\r\n","<div class=\"hw jl\">水中</div><div class=\"def\">▼<b>～の</b> aquaticus, aquatilis.</div>\r\n","<div class=\"hw jl\">水平</div><div class=\"def\">libramentum.</div><div class=\"def\">▼<b>～な</b> libratus, planus.</div><div class=\"def\">▼<b>～にする</b> aequo, coaequo.</div><div class=\"def\">▼<b>～に保つ</b> libro.</div>\r\n","<div class=\"hw jl\">水族館</div><div class=\"def\">domus beluis marinis asservandis.</div>\r\n","<div class=\"hw jl\">水星</div><div class=\"def\">Mercurius, Mercurii stella.</div>\r\n","<div class=\"hw jl\">水晶</div><div class=\"def\">crystallum, crystallus.</div><div class=\"def\">▼<b>～の(ような)</b> crystallinus.</div>\r\n","<div class=\"hw jl\">水泳</div><div class=\"def\">natatio, ars nandi.</div><div class=\"def\">⇒<a href=\"entry://泳ぐ\">泳ぐ</a>.</div>\r\n","<div class=\"hw jl\">水着</div><div class=\"def\">vesticula balnearis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">水泳パンツ<span class=\"ext\">subligaculum balneare.</span></div><div class=\"cf\">ビキニ<span class=\"ext\">vesticula balnearis Bikiniana.</span></div>\r\n","<div class=\"hw jl\">水道</div><div class=\"def\">aquae ductus.</div>\r\n","<div class=\"hw jl\">氷</div><div class=\"def\">glacies, aqua concreta.</div><div class=\"def\">▼<b>～の</b> glacialis.</div><div class=\"def\">▼<b>～のような</b> gelidus.</div>\r\n","<div class=\"hw jl\">氷山</div><div class=\"def\">natans mons glacialis [glaciata].</div>\r\n","<div class=\"hw jl\">氷河</div><div class=\"def\">glaciata moles.</div>\r\n","<div class=\"hw jl\">永続</div><div class=\"def\">▼<b>～的な</b> mansurus, perpetuus.</div><div class=\"def\">▼<b>～させる</b> perpetuo.</div><div class=\"def\">▼<b>～的に</b> perpetuo.</div><div class=\"def\">⇒<a href=\"entry://永遠\">永遠</a>.</div>\r\n","<div class=\"hw jl\">永遠</div><div class=\"def\">(=永久)aeternitas, aeternum, perpetuitas, sempiternitas.</div><div class=\"def\">▼<b>～の</b> aeternus, sempiternus.</div><div class=\"def\">▼<b>～に</b>(in)aeternum, ad perpetuitatem, in sempiternum, semper, sempiterne.</div><div class=\"def\">⇒<a href=\"entry://永続\">永続</a>.</div>\r\n","<div class=\"hw jl\">氾濫</div><div class=\"def\">abundatio, inundatio, diluvies, diluvium.</div><div class=\"def\">▼<b>～する</b> abundo, inundo.</div>\r\n","<div class=\"hw jl\">汁</div><div class=\"def\">(肉の)jus, jusculum;(果物の)sucus.</div>\r\n","<div class=\"hw jl\">求める</div><div class=\"def\">(=要求する, 願い求める)peto, appeto, posco, exigo, rogo, postulo, quaeso, cupio;(...を)(熱心に)studeo 〈alci rei〉;(=探し求める, 得ようとする)affecto.</div><div class=\"ex2\">あなたは私がご兄弟の娘さんに夫を探すことを求めている<span class=\"ext\">petis ut fratris tui filiae prospiciam maritum.</span></div>\r\n","<div class=\"hw jl\">汗</div><div class=\"def\">sudor.</div><div class=\"def\">▼<b>～をかく</b> sudo.</div><div class=\"ex2\">ひどく～をかく(=大変な苦労をする)<span class=\"ext\">desudo.</span></div><div class=\"ex2\">～だくになる<span class=\"ext\">desudasco.</span></div>\r\n","<div class=\"hw jl\">汚染</div><div class=\"def\">inquinatio, deterioratio, pollutio, contactus.</div><div class=\"def\">▼<b>環境～</b> circumjacentiorum inquinatio.</div><div class=\"def\">▼<b>～された</b> inquinatus, pollutus.</div><div class=\"def\">▼<b>～する</b> inquino, polluo.</div>\r\n","<div class=\"hw jl\">汚点</div><div class=\"def\">macula.</div><div class=\"def\">▼<b>～をつける</b> maculo.</div>\r\n","<div class=\"hw jl\">汚物</div><div class=\"def\">fimus, fimum, merda.</div><div class=\"def\">⇒<a href=\"entry://排泄物\">排泄物</a>,<a href=\"entry://ごみ\">ごみ</a>.</div>\r\n","<div class=\"hw jl\">汚職</div><div class=\"def\">corruptio.</div><div class=\"def\">⇒<a href=\"entry://買収\">買収</a>.</div>\r\n","<div class=\"hw jl\">池</div><div class=\"def\">stagnum, lacus, piscina.</div><div class=\"def\">⇒<a href=\"entry://プール\">プール</a>.</div>\r\n","<div class=\"hw jl\">汲む</div><div class=\"def\">(水などの液体を)(=汲みあげる)haurio.</div><div class=\"def\">▼<b>～こと</b> haustus.</div>\r\n","<div class=\"hw jl\">決して</div><div class=\"def\">▼<b>～...ない</b> numquam, non [ne, nec(neque), nihil, nemo, nullus] ... unquam, haud, nullo modo.</div>\r\n","<div class=\"hw jl\">決まる</div><div class=\"def\">(=決定される)placet(<i>impers</i>).</div><div class=\"def\">⇒<a href=\"entry://決める\">決める</a>.</div>\r\n","<div class=\"hw jl\">決める</div><div class=\"def\">(=決心する, 決議する, 決定する)statuo, decerno, constituo.</div>\r\n","<div class=\"hw jl\">決定</div><div class=\"def\">decretum.</div><div class=\"def\">▼<b>～する</b> finio, definio, statuo, constituo, decerno, determino.</div><div class=\"def\">⇒<a href=\"entry://決心\">決心</a>.</div>\r\n","<div class=\"hw jl\">決心</div><div class=\"def\">decretum, sententia.</div><div class=\"def\">▼<b>～する</b> decerno, statuo, consilium capio.</div><div class=\"def\">▼<b>～した</b> certus.</div>\r\n","<div class=\"hw jl\">決意</div><div class=\"def\">⇒<a href=\"entry://決心\">決心</a>.</div>\r\n","<div class=\"hw jl\">決議</div><div class=\"def\">decretum.</div><div class=\"def\">▼<b>～する</b> decerno.</div>\r\n","<div class=\"hw jl\">沈める</div><div class=\"def\">demergo, immergo.</div><div class=\"def\">⇒<a href=\"entry://潜る\">潜る</a>.</div>\r\n","<div class=\"hw jl\">沈没</div><div class=\"def\">submersio.</div><div class=\"def\">▼<b>～する</b> submergor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">沈黙</div><div class=\"def\">silentium, taciturnitas.</div><div class=\"def\">▼<b>～する</b> silentium facio, sileo, conticesco, taceo.</div>\r\n","<div class=\"hw jl\">沖</div><div class=\"def\">altum.</div><div class=\"def\">▼<b>～へ</b> in altum.</div><div class=\"def\">▼<b>～から</b> ex alto.</div>\r\n","<div class=\"hw jl\">没収</div><div class=\"def\">publicatio, confiscatio.</div><div class=\"def\">▼<b>～する</b> publico, in publicum addico [redigo], confisco.</div>\r\n","<div class=\"hw jl\">没頭</div><div class=\"def\">▼(...に)<b> ～する</b> 〈alci rei〉 se dare(← do)[dedere(← dedo)], se 〈re〉 collocare(← colloco).</div><div class=\"ex2\">きみはますます閑暇に～する<span class=\"ext\">te magis ac magis otio involvis.</span></div>\r\n","<div class=\"hw jl\">河口</div><div class=\"def\">ostium.</div>\r\n","<div class=\"hw jl\">沸く</div><div class=\"def\">(=沸騰する)bullio, ferveo.</div>\r\n","<div class=\"hw jl\">沸騰</div><div class=\"def\">fervor.</div><div class=\"def\">▼<b>～する</b> effervesco.</div><div class=\"def\">▼<b>～している</b> ferveo.</div><div class=\"def\">▼<b>～させる</b> fervefacio.</div>\r\n","<div class=\"hw jl\">油・脂</div><div class=\"def\">(植物性の)oleum;(調理油・整髪油・軟膏など油性物質としての)unguen;(車軸用の)(=グリス)axungia;(=動物性の脂肪)adeps.</div><div class=\"def\">▼<b>～を塗る</b> ungo.</div><div class=\"def\">⇒<a href=\"entry://脂肪\">脂肪</a>.</div>\r\n","<div class=\"hw jl\">油断</div><div class=\"def\">▼<b>～する</b> non caveo.</div><div class=\"def\">▼<b>～している</b> incautus.</div><div class=\"def\">▼<b>～して</b> incaute.</div>\r\n","<div class=\"hw jl\">治す・直す</div><div class=\"def\">(=治療する)sano, reficio, ad salutem reduco, 〈alci〉 medeor(<i>dep</i>), medico, medicor(<i>dep</i>);(=正す)corrigo, emendo.</div><div class=\"def\">⇒<a href=\"entry://治療\">治療</a>,<a href=\"entry://癒す\">癒す</a>.</div>\r\n","<div class=\"hw jl\">治める</div><div class=\"def\">(=行政的に管理する)administro.</div><div class=\"def\">⇒<a href=\"entry://支配\">支配</a>.</div>\r\n","<div class=\"hw jl\">治る</div><div class=\"def\">(=回復する, 治癒する)sanor(<i>pass</i>), sanesco, consanesco, convalesco.</div>\r\n","<div class=\"hw jl\">治安</div><div class=\"def\">pax civilis.</div><div class=\"def\">⇒<a href=\"entry://秩序\">秩序</a>,<a href=\"entry://警察\">警察</a>.</div>\r\n","<div class=\"hw jl\">治療</div><div class=\"def\">sanatio, curatio, medicamen, medicamentum, medicatio.</div><div class=\"def\">▼<b>～術</b> medicina.</div><div class=\"def\">▼<b>～できる, ～の見込みのある</b> sanabilis.</div><div class=\"def\">▼<b>～する</b> sano, curo, medicor(<i>dep</i>), 〈+<i>dat</i>〉 medeor(<i>dep</i>).</div><div class=\"ex2\">病人に～を施す<span class=\"ext\">aegro medicinam adhibeo.</span></div>\r\n","<div class=\"hw jl\">沼</div><div class=\"def\">palus;(=湖沼)stagnum, lacus.</div><div class=\"def\">▼<b>～(地)の</b> paluster, palustris.</div><div class=\"def\">▼<b>～地</b> ager paluster [palustris].</div>\r\n","<div class=\"hw jl\">沿う</div><div class=\"def\">▼(...に)<b> 沿って</b> secundum 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">沿岸</div><div class=\"def\">litora(<i>pl</i>), ora.</div>\r\n","<div class=\"hw jl\">泉</div><div class=\"def\">fons.</div><div class=\"def\">▼<b>小さな～</b> fonticulus.</div>\r\n","<div class=\"hw jl\">泊まる</div><div class=\"def\">(宿に)(in taberna [cauponem])deversor(<i>dep</i>)[deverto];(...宅に)〈apud alqm〉 devertor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">法</div><div class=\"def\">(=法律)lex;(総体的に)jus.</div><div class=\"def\">▼<b>～学</b> juris prudentia.</div><div class=\"def\">▼<b>～学者</b> juris consultus(<i>m</i>), jurisperitus, juris legumque peritus(<i>m</i>).</div><div class=\"def\">▼<b>成文～</b> lex scripta.</div><div class=\"def\">▼<b>自然～</b> lex naturalis.</div><div class=\"def\">▼<b>刑～</b> jus criminale.</div><div class=\"def\">▼<b>民～</b> jus civile.</div><div class=\"def\">▼<b>商～</b> jus commercii.</div><div class=\"def\">▼<b>国際～</b> jus gentium.</div><div class=\"def\">⇒<a href=\"entry://法律\">法律</a>.</div>\r\n","<div class=\"hw jl\">法則</div><div class=\"def\">lex.</div>\r\n","<div class=\"hw jl\">法外</div><div class=\"def\">▼<b>～な</b>(=限度を超えた)immoderatus, nimius, immodicus, intemperatus.</div>\r\n","<div class=\"hw jl\">法廷</div><div class=\"def\">(=裁判所)tribunal, judicium.</div><div class=\"def\">▼<b>～の</b>(=裁判の)tribunalis, judicialis, judiciarius, forensis.</div><div class=\"def\">▼<b>～に召喚する</b> in judicium voco.</div>\r\n","<div class=\"hw jl\">法律</div><div class=\"def\">lex.</div><div class=\"ex2\"> ～を起草する<span class=\"ext\">legem scribo.</span></div>\r\n","<div class=\"hw jl\">法案</div><div class=\"def\">(=法案提議)rogatio.</div><div class=\"ex2\">民衆に～を可決するよう勧める<span class=\"ext\">populum ad rogationem accipiendam cohortor.</span></div><div class=\"ex2\">～の推進者<span class=\"ext\">legis suasor.</span></div><div class=\"ex2\">～を提出する<span class=\"ext\">rogationem fero.</span></div><div class=\"ex2\">～を通過させる<span class=\"ext\">rogationem [legem] perfero.</span></div><div class=\"ex2\">～を承認する<span class=\"ext\">legem probo.</span></div><div class=\"ex2\">～を却下[否決]する<span class=\"ext\">rogationem antiquo / legem repudio.</span></div><div class=\"def\">⇒<a href=\"entry://法律\">法律</a>.</div>\r\n","<div class=\"hw jl\">泡</div><div class=\"def\">bulla, bullula, spuma.</div>\r\n","<div class=\"hw jl\">波</div><div class=\"def\">(海の)unda, fluctus.</div><div class=\"def\">▼<b>～打つ, ～立つ</b> fluctuo.</div><div class=\"def\">⇒<a href=\"entry://音波\">音波</a>,<a href=\"entry://電波\">電波</a>.</div>\r\n","<div class=\"hw jl\">泣き声</div><div class=\"def\">(=悲鳴)ejulatio, ploratus;(特に女性の)ululatus.</div><div class=\"def\">⇒<a href=\"entry://うめく\">うめく</a>.</div>\r\n","<div class=\"hw jl\">泣く</div><div class=\"def\">(人間が)lacrimo, lacrimor(<i>dep</i>), fleo;(=泣き叫ぶ)ploro;(=号泣する)ejulo.</div><div class=\"def\">⇒<a href=\"entry://叫ぶ\">叫ぶ</a>,<a href=\"entry://涙\">涙</a>.</div>\r\n","<div class=\"hw jl\">泥</div><div class=\"def\">lutum, limus.</div><div class=\"def\">▼<b>～沼</b> caenum.</div><div class=\"def\">▼<b>～の</b> luteus.</div><div class=\"def\">▼<b>～だらけの, ～でいっぱいの</b> lutosus, lutulentus, luteus, caenosus.</div>\r\n","<div class=\"hw jl\">泥棒</div><div class=\"def\">fur.</div><div class=\"def\">⇒<a href=\"entry://盗む\">盗む</a>.</div>\r\n","<div class=\"hw jl\">注ぐ</div><div class=\"def\">fundo, effundo.</div>\r\n","<div class=\"hw jl\">注射</div><div class=\"def\">(in venas)infusio [injectio].</div>\r\n","<div class=\"hw jl\">注意</div><div class=\"def\">(=警告)monitio;(=意識の集中)(animi)attentio, (animi [mentis])intentio, animadversio;(細心の)scrupulus.</div><div class=\"def\">▼<b>～する</b>(=警告する)moneo, admoneo;(=気をつける)animadverto, animum attendo [adverto];(=警戒する)custodio, caveo.</div><div class=\"def\">▼<b>～深い</b> diligens, attentus, curiosus.</div><div class=\"def\">▼<b>～深く</b> diligenter, attente, curiose.</div><div class=\"ex2\">細心の～を払う<span class=\"ext\">magna cura utor(<i>dep</i>).</span></div><div class=\"ex2\">犬にご～<span class=\"ext\">cave canem.</span></div><div class=\"def\">⇒<a href=\"entry://警告\">警告</a>,<a href=\"entry://入念\">入念</a>,<a href=\"entry://警戒\">警戒</a>.</div>\r\n","<div class=\"hw jl\">注文</div><div class=\"def\">locatio, mandatum.</div><div class=\"def\">▼(人に物を)<b> ～する</b> 〈alci alqd〉 mando.</div><div class=\"ex2\">(人に)ベッドを～する<span class=\"ext\">〈alci〉 lectulos faciendos do.</span></div><div class=\"ex2\">彫像を～する<span class=\"ext\">statuam faciendam loco.</span></div>\r\n","<div class=\"hw jl\">注目</div><div class=\"def\">oculus.</div><div class=\"def\">⇒<a href=\"entry://注意\">注意</a>.</div>\r\n","<div class=\"hw jl\">注釈</div><div class=\"def\">commentarius, commentarium, annotatio.</div><div class=\"def\">▼<b>～する</b> commentor(<i>dep</i>), annoto.</div><div class=\"def\">▼<b>～者</b> commentator.</div><div class=\"def\">⇒<a href=\"entry://解説\">解説</a>.</div>\r\n","<div class=\"hw jl\">泳ぐ</div><div class=\"def\">no, nato;(=泳ぎ渡る)transno, transnato.</div><div class=\"def\">▼<b>～こと</b>(=水泳)natatio.</div>\r\n","<div class=\"hw jl\">洗う</div><div class=\"def\">lavo;(=洗い落とす, 洗い流す)abluo.</div><div class=\"def\">⇒<a href=\"entry://洗濯\">洗濯</a>.</div>\r\n","<div class=\"hw jl\">洗剤</div><div class=\"def\">detergens smegma.</div>\r\n","<div class=\"hw jl\">洗濯</div><div class=\"def\">lavatio.</div><div class=\"def\">▼<b>～する</b> lavo, eluo.</div><div class=\"def\">▼<b>～室, ～場</b> lavatorium.</div><div class=\"def\">▼<b>～機</b> machina linteorum lavatoria, machina linteis lavandis, machina linteis eluendis.</div><div class=\"def\">⇒<a href=\"entry://洗う\">洗う</a>,<a href=\"entry://クリーニング\">クリーニング</a>.</div>\r\n","<div class=\"hw jl\">洗礼</div><div class=\"def\">baptisma, baptismus, baptismum.</div><div class=\"def\">▼<b>～者</b> baptizator.</div><div class=\"def\">▼<b>～を受けさせる</b> baptizo.</div>\r\n","<div class=\"hw jl\">洗練</div><div class=\"def\">subtilitas, munditia, urbanitas.</div><div class=\"def\">▼<b>～された</b> subtilis, mundus, urbanus, lautus, politus, limatus, excultus.</div><div class=\"def\">▼<b>きわめて～された人々</b> lautissimi.</div>\r\n","<div class=\"hw jl\">洗面器</div><div class=\"def\">pelvis, trulleus, trulleum.</div>\r\n","<div class=\"hw jl\">洗面所</div><div class=\"def\">cellula lavatoria, lavatorium.</div>\r\n","<div class=\"hw jl\">洞穴</div><div class=\"def\">⇒<a href=\"entry://洞窟\">洞窟</a>.</div>\r\n","<div class=\"hw jl\">洞窟</div><div class=\"def\">spelunca, specus, spelaeum, caverna, antrum.</div>\r\n","<div class=\"hw jl\">洪水</div><div class=\"def\">diluvies, inundatio, diluvium.</div><div class=\"def\">▼<b>～にする</b> inundo.</div>\r\n","<div class=\"hw jl\">活動</div><div class=\"def\">actio, agitatio.</div><div class=\"def\">▼<b>～的な</b> actuosus.</div>\r\n","<div class=\"hw jl\">活気</div><div class=\"def\">(=元気, 活発)vigor, alacritas.</div><div class=\"def\">▼<b>～がある</b> vigeo.</div><div class=\"def\">▼<b>～ある</b> vivax, alacer;(町などが)(=にぎやかな)celeber.</div><div class=\"def\">⇒<a href=\"entry://元気\">元気</a>,<a href=\"entry://にぎやか\">にぎやか</a>.</div>\r\n","<div class=\"hw jl\">活用</div><div class=\"def\">(動詞の)conjugatio.</div><div class=\"def\">⇒<a href=\"entry://使用\">使用</a>,<a href=\"entry://利用\">利用</a>.</div>\r\n","<div class=\"hw jl\">活発</div><div class=\"def\">strenuitas, alacritas, vivacitas. </div><div class=\"def\">▼<b>～な</b> strenuus, vivus, industrius, alacer.</div><div class=\"def\">▼<b>～に</b> strenue, vivaciter, alacriter, vehementer.</div>\r\n","<div class=\"hw jl\">活躍</div><div class=\"def\">▼<b>～している</b> actuosus.</div>\r\n","<div class=\"hw jl\">派手</div><div class=\"def\">▼<b>～な</b> conspicuus.</div><div class=\"def\">▼<b>～な色</b> color conspicuus [floridus].</div><div class=\"def\">⇒<a href=\"entry://目立つ\">目立つ</a>.</div>\r\n","<div class=\"hw jl\">派遣</div><div class=\"def\">missio, missus.</div><div class=\"def\">▼<b>～する</b> mitto, dimitto, missito.</div>\r\n","<div class=\"hw jl\">流す</div><div class=\"def\">emitto, mano.</div><div class=\"def\">⇒<a href=\"entry://流れる\">流れる</a>.</div>\r\n","<div class=\"hw jl\">流れる</div><div class=\"def\">fluo, fluito, mano, liquor(<i>dep</i>).</div><div class=\"def\">▼<b>流れ</b> flumen.</div>\r\n","<div class=\"hw jl\">流暢</div><div class=\"def\">facundia, verborum copia, profluentia.</div><div class=\"def\">▼<b>～な</b> disertus, profluens.</div><div class=\"def\">▼<b>～に</b> diserte, profluenter.</div>\r\n","<div class=\"hw jl\">流産</div><div class=\"def\">abortus, abortio.</div><div class=\"def\">▼<b>～の</b> abortivus.</div><div class=\"def\">▼<b>～する</b> aborior(<i>dep</i>), abortum patior(<i>dep</i>)[facio].</div>\r\n","<div class=\"hw jl\">流行</div><div class=\"def\">(=モード, ファッション)habitus novus, mos recentissimus, novus vestium mos.</div><div class=\"def\">▼<b>～する</b>(=人気がある)plurimum valeo apud omnes, jactationem habeo in populo, floreo;(病気が)evagor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://伝染\">伝染</a>.</div>\r\n","<div class=\"hw jl\">流行る</div><div class=\"def\">(衣装や思想が)in morem venio.</div><div class=\"def\">▼<b>流行っている</b> vigeo.</div><div class=\"def\">⇒<a href=\"entry://流行\">流行</a>.</div>\r\n","<div class=\"hw jl\">流通</div><div class=\"def\">(貨幣などの)usus.</div><div class=\"def\">▼<b>～している</b> in usu esse(← sum).</div><div class=\"def\">▼<b>～する</b> in usum venire(← venio).</div>\r\n","<div class=\"hw jl\">浅い</div><div class=\"def\">(川や海が)vadosus, tenuis.</div><div class=\"def\">▼<b>～水</b> vadum.</div><div class=\"def\">⇒<a href=\"entry://浅瀬\">浅瀬</a>.</div>\r\n","<div class=\"hw jl\">浅はか</div><div class=\"def\">(=軽率, 無思慮)incosideratio, inconsiderantia, imprudentia.</div><div class=\"def\">▼<b>～な</b> inconsiderans, inconsideratus, imprudens.</div><div class=\"def\">▼<b>～に</b> inconsiderate, imprudenter.</div><div class=\"def\">⇒<a href=\"entry://軽率\">軽率</a>.</div>\r\n","<div class=\"hw jl\">浅瀬</div><div class=\"def\">(海や川の)vadum, brevia(<i>pl</i>);(海の)vadosum mare.</div>\r\n","<div class=\"hw jl\">浪費</div><div class=\"def\">prodigentia, sumptus, dissipatio.</div><div class=\"def\">▼<b>～家</b> dissipator.</div><div class=\"def\">▼<b>～的な</b> sumptuosus.</div><div class=\"def\">▼<b>～する</b><span class=\"pos3\">[動]</span> dissipo, prodigo. <span class=\"pos3\">[形]</span> prodigus.</div>\r\n","<div class=\"hw jl\">浮かぶ</div><div class=\"def\">(=水上に漂う)fluito;(=浮かび上がる)emergo.</div><div class=\"ex2\">老年について何か書こうと思った時, きみのことが頭に浮かんだ<span class=\"ext\">mihi, cum de senectute vellem aliquid scribere, tu occurebas.</span></div>\r\n","<div class=\"hw jl\">浮かれる</div><div class=\"def\">hilaresco, hilaror(<i>pass</i>);(祭りなどで)(=騒ぎ歩く)comissor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">浮気</div><div class=\"def\">(=不貞)infidelitas.</div>\r\n","<div class=\"hw jl\">浴びせる</div><div class=\"def\">spargo.</div>\r\n","<div class=\"hw jl\">浴びる</div><div class=\"def\">(=入浴する)lavor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">浴室</div><div class=\"def\">balneum, balnearia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">海</div><div class=\"def\">mare;(=大海, 深い海)pontus;(=大洋)oceanus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">アドリア海<span class=\"ext\">mare Hadriaticum.</span></div><div class=\"cf\">エーゲ海<span class=\"ext\">mare Aegaeum.</span></div><div class=\"cf\">カスピ海<span class=\"ext\">mare Caspium.</span></div><div class=\"cf\">黒海<span class=\"ext\">pontus Euxinus.</span></div><div class=\"cf\">大西洋<span class=\"ext\">oeanus Atlanticus.</span></div><div class=\"cf\">地中海<span class=\"ext\">mare Internum [Mediterraneum].</span></div><div class=\"cf\">バルト海<span class=\"ext\">fretum Balticum.</span></div>\r\n","<div class=\"hw jl\">海外</div><div class=\"def\">⇒<a href=\"entry://外国\">外国</a>.</div>\r\n","<div class=\"hw jl\">海岸</div><div class=\"def\">litus, ora(maritima).</div>\r\n","<div class=\"hw jl\">海峡</div><div class=\"def\">fretum, (maris)angustiae(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> fretensis.</div>\r\n","<div class=\"hw jl\">海底</div><div class=\"def\">fundus maris.</div><div class=\"def\">⇒<a href=\"entry://底\">底</a>.</div>\r\n","<div class=\"hw jl\">海水</div><div class=\"def\">(=海の水)aqua marina, aqua maris.</div>\r\n","<div class=\"hw jl\">海水浴</div><div class=\"def\">▼<b>～をする</b>(=海で水浴する)in mari lavo, in mari lavor(<i>pass</i>);(=海で泳ぐ)in mari nato.</div>\r\n","<div class=\"hw jl\">海産物</div><div class=\"def\">ea quae gignuntur e mari.</div>\r\n","<div class=\"hw jl\">海藻</div><div class=\"def\">alga.</div>\r\n","<div class=\"hw jl\">海賊</div><div class=\"def\">pirata, praedo.</div><div class=\"def\">▼<b>～行為</b> piratica, latrocinium maritimum.</div><div class=\"def\">▼<b>～の</b> piraticus.</div><div class=\"ex2\">～行為を働く<span class=\"ext\">latrocinor(<i>dep</i>).</span></div>\r\n","<div class=\"hw jl\">海面</div><div class=\"def\">(maris)aequor.</div>\r\n","<div class=\"hw jl\">浸す</div><div class=\"def\">demergo, mergo, tingo, intingo.</div>\r\n","<div class=\"hw jl\">消える</div><div class=\"def\">(=消滅する, 消えてなくなる)evanesco, pereo, decedo;(視界から)ex oculis abeo;(火が)exstinguor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">消しゴム</div><div class=\"def\">cummis deletilis.</div>\r\n","<div class=\"hw jl\">消す</div><div class=\"def\">(火を)exstinguo;(書いたものを)deleo, erado.</div>\r\n","<div class=\"hw jl\">消化</div><div class=\"def\">concoctio.</div><div class=\"def\">▼<b>～する</b> concoquo.</div>\r\n","<div class=\"hw jl\">消息</div><div class=\"ex2\">アッティクスの～が知りたい<span class=\"ext\">scire cupio quid agat Atticus.</span></div><div class=\"ex2\">(...は)～不明だ<span class=\"ext\">〈de alqo〉 nihil audimus.</span></div>\r\n","<div class=\"hw jl\">消極的</div><div class=\"def\">▼<b>～な</b> iners, nihil agens.</div>\r\n","<div class=\"hw jl\">消毒</div><div class=\"def\">bacillorum purgatura.</div><div class=\"def\">▼<b>～剤</b> medicamentum sterilitatem inducens, bacillorum purgatorium.</div><div class=\"def\">▼<b>～する</b> purgo.</div>\r\n","<div class=\"hw jl\">消耗</div><div class=\"def\">intertrimentum.</div><div class=\"def\">⇒<a href=\"entry://すりへらす\">すりへらす</a>.</div>\r\n","<div class=\"hw jl\">消費</div><div class=\"def\">impensa, impendium, consumptio.</div><div class=\"def\">▼<b>～する</b> impendo, consumo.</div>\r\n","<div class=\"hw jl\">涙</div><div class=\"def\">lacrima, fletus.</div><div class=\"def\">▼<b>～を流す</b> ⇒ <a href=\"entry://泣く\">泣く</a>.</div>\r\n","<div class=\"hw jl\">液体</div><div class=\"def\">humor, liquor.</div><div class=\"def\">▼<b>～の</b> liquidus, fluidus.</div><div class=\"def\">▼<b>～となる</b> liquesco.</div><div class=\"def\">⇒<a href=\"entry://気体\">気体</a>.</div>\r\n","<div class=\"hw jl\">液化</div><div class=\"def\">liquefactio.</div><div class=\"def\">▼<b>～する</b> liquesco.</div><div class=\"def\">▼<b>～させる</b> liquefacio.</div>\r\n","<div class=\"hw jl\">液晶</div><div class=\"def\">crystallum liquidum.</div>\r\n","<div class=\"hw jl\">涼しい</div><div class=\"def\">frigidus.</div><div class=\"def\">▼<b>涼しくする</b> refrigero.</div>\r\n","<div class=\"hw jl\">深い</div><div class=\"def\">profundus, altus.</div><div class=\"def\">▼<b>深さ</b> altitudo.</div><div class=\"def\">▼<b>深く</b> alte, penitus.</div><div class=\"def\">▼<b>～所, 深み</b> profundum, altum.</div>\r\n","<div class=\"hw jl\">深夜</div><div class=\"def\">media nox.</div><div class=\"def\">▼<b>～まで</b> ad multam noctem.</div>\r\n","<div class=\"hw jl\">混じる</div><div class=\"def\">misceor(<i>pass</i>), confundor(<i>pass</i>), se immiscere(← immisceo).</div><div class=\"def\">⇒<a href=\"entry://混ぜる\">混ぜる</a>.</div>\r\n","<div class=\"hw jl\">混ぜる</div><div class=\"def\">misceo, commisceo, immisceo, admisceo, confundo.</div><div class=\"def\">▼<b>程よく混ぜ合わせる</b> tempero.</div>\r\n","<div class=\"hw jl\">混乱</div><div class=\"def\">confusio, perturbatio, turbatio, turba.</div><div class=\"def\">▼<b>～した</b> confusus, perturbatus, turbatus.</div><div class=\"def\">▼<b>～させる</b> turbo, misceo, commisceo, confundo.</div><div class=\"def\">⇒<a href=\"entry://乱す\">乱す</a>.</div>\r\n","<div class=\"hw jl\">混合</div><div class=\"def\">mixtura, admixtio, temperatio.</div><div class=\"def\">▼<b>～する</b> misceo, admisceo, permisceo, tempero.</div>\r\n","<div class=\"hw jl\">混同</div><div class=\"def\">▼<b>～する</b> commisceo.</div>\r\n","<div class=\"hw jl\">混血</div><div class=\"def\">▼<b>～(児)</b> hybrida.</div><div class=\"def\">▼<b>～の</b> ex diverso genere natus.</div>\r\n","<div class=\"hw jl\">混雑</div><div class=\"def\">▼(...で)<b>～した</b> 〈+<i>abl</i>〉 refertus.</div>\r\n","<div class=\"hw jl\">清涼</div><div class=\"def\">refrigeratio.</div><div class=\"def\">▼<b>～な</b> refrigerans.</div>\r\n","<div class=\"hw jl\">清潔</div><div class=\"def\">munditia.</div><div class=\"def\">▼<b>～な</b> mundus, tersus.</div><div class=\"def\">⇒<a href=\"entry://きれい\">きれい</a>.</div>\r\n","<div class=\"hw jl\">渇き</div><div class=\"def\">(のどの)sitis.</div><div class=\"def\">▼<b>のどが渇いた</b> sitiens, siccus, aridus.</div><div class=\"def\">▼<b>のどが渇く</b> sitio.</div>\r\n","<div class=\"hw jl\">渋い</div><div class=\"def\">acerbus.</div><div class=\"def\">⇒<a href=\"entry://地味\">地味</a>,<a href=\"entry://質素\">質素</a>,<a href=\"entry://苦い\">苦い</a>.</div>\r\n","<div class=\"hw jl\">渋滞</div><div class=\"def\">(交通などの)obstructae viae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">渓谷</div><div class=\"def\">convallis.</div><div class=\"def\">⇒<a href=\"entry://谷\">谷</a>.</div>\r\n","<div class=\"hw jl\">減らす</div><div class=\"def\">deminuo, minuo.</div><div class=\"def\">⇒<a href=\"entry://減少\">減少</a>.</div>\r\n","<div class=\"hw jl\">減る</div><div class=\"def\">minuor(<i>pass</i>), deminuor(<i>pass</i>), decresco.</div><div class=\"def\">⇒<a href=\"entry://減少\">減少</a>.</div>\r\n","<div class=\"hw jl\">減少</div><div class=\"def\">deminutio, minutio.</div><div class=\"def\">▼<b>～する</b> deminuor(<i>pass</i>), minuor(<i>pass</i>), decresco.</div><div class=\"def\">⇒<a href=\"entry://減らす\">減らす</a>,<a href=\"entry://減る\">減る</a>.</div>\r\n","<div class=\"hw jl\">減税</div><div class=\"def\">⇒<a href=\"entry://税\">税</a>.</div>\r\n","<div class=\"hw jl\">渡す</div><div class=\"def\">(=渡らせる)traduco, trajicio;(=与える)do, reddo.</div>\r\n","<div class=\"hw jl\">渡る</div><div class=\"def\">transeo, transmitto, transmittor(<i>pass</i>), trajicio.</div><div class=\"def\">▼(...に)<b>渡って</b> in 〈+<i>acc</i>〉.</div><div class=\"ex2\">川を～<span class=\"ext\">flumen transgredior(<i>dep</i>)[transeo].</span></div><div class=\"ex2\">空を飛んで大海を～<span class=\"ext\">transvolo pontum.</span></div><div class=\"ex2\">多年に渡って<span class=\"ext\">in multos annos.</span></div>\r\n","<div class=\"hw jl\">渦</div><div class=\"def\">(=特に風の, 竜巻)turbo;(=特に水の, 渦巻)gurges;(=特に水・風・火の)vertex.</div><div class=\"def\">▼<b>～巻</b> spira.</div>\r\n","<div class=\"hw jl\">温かい・暖かい</div><div class=\"def\"><span class=\"pos3\">[形]</span>(風呂・ミルクが)tepidus;(気候が)(=温和な)temperatus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> tepeo.</div><div class=\"def\">▼<b>温かくなる</b> tepesco.</div><div class=\"def\">▼<b>温かさ</b>(=程よい熱さ)tepor.</div><div class=\"def\">⇒<a href=\"entry://温和\">温和</a>,<a href=\"entry://情け深い\">情け深い</a>.</div>\r\n","<div class=\"hw jl\">温まる・暖まる</div><div class=\"def\">(=熱くなる)calefio, calesco;(=暖かくなる, 程よい熱さになる)tepesco.</div>\r\n","<div class=\"hw jl\">温める</div><div class=\"def\">(=熱くする)calefacio;(=程よい熱さにする)tepefacio.</div>\r\n","<div class=\"hw jl\">温和</div><div class=\"def\">lenitas, temperatio.</div><div class=\"def\">▼<b>～な</b>(気候が)mitis, temperatus;(人柄が)(=優しい)placidus, mansuetus, clemens.</div>\r\n","<div class=\"hw jl\">温度</div><div class=\"def\">caloris gradus.</div><div class=\"def\">▼<b>～計</b> thermometrum.</div><div class=\"def\">⇒<a href=\"entry://気温\">気温</a>.</div>\r\n","<div class=\"hw jl\">温情</div><div class=\"def\">(=情け深さ)benevolentia, benignitas.</div><div class=\"def\">⇒<a href=\"entry://情け深い\">情け深い</a>,<a href=\"entry://温かい・暖かい\">温かい</a>.</div>\r\n","<div class=\"hw jl\">温泉</div><div class=\"def\">▼<b>～(場)</b> thermae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">測定</div><div class=\"def\">mensura.</div><div class=\"def\">▼<b>～する</b> dimetior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://計る\">計る</a>.</div>\r\n","<div class=\"hw jl\">港</div><div class=\"def\">portus.</div><div class=\"def\">▼<b>～の多い</b> portuosus.</div><div class=\"ex2\">～に入る[到着する]<span class=\"ext\">in portum pervenio [venio, invehor(<i>pass</i>)] / portum capio.</span></div>\r\n","<div class=\"hw jl\">湖</div><div class=\"def\">lacus.</div><div class=\"def\">▼<b>小さな～</b> lacusculus.</div>\r\n","<div class=\"hw jl\">湧く</div><div class=\"def\">(泉や温泉が)(=あふれ出る)scateo, emico, erumpo, exsilio;(虫などが)(=発生する)nascor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">湯</div><div class=\"def\">(温かい)(aqua)calida;(沸騰した)fervens aqua.</div>\r\n","<div class=\"hw jl\">湯気</div><div class=\"def\">vapor(aquae calidae).</div>\r\n","<div class=\"hw jl\">湾</div><div class=\"def\">sinus.</div>\r\n","<div class=\"hw jl\">湿る</div><div class=\"def\">madeo, madesco, umesco.</div><div class=\"def\">▼<b>湿った</b> umidus.</div><div class=\"def\">▼<b>湿っている</b> umeo.</div><div class=\"def\">▼<b>湿らせる</b> madefacio, umecto.</div>\r\n","<div class=\"hw jl\">湿度計</div><div class=\"def\">hydrometrum.</div>\r\n","<div class=\"hw jl\">湿気</div><div class=\"def\">umor.</div><div class=\"def\">▼<b>～のある</b> umidus.</div>\r\n","<div class=\"hw jl\">満たす</div><div class=\"def\">(...を...で)〈alqd re;alqd alcis rei〉 impleo, compleo, 〈alqd re〉 repleo, expleo;(欲望や期待を)(=満足させる)expleo, satisfacio.</div><div class=\"def\">⇒<a href=\"entry://満足\">満足</a>.</div>\r\n","<div class=\"hw jl\">満潮</div><div class=\"def\">aestus accessus, aestus(maritimus)accedens.</div><div class=\"def\">⇒<a href=\"entry://潮\">潮</a>.</div>\r\n","<div class=\"hw jl\">満足</div><div class=\"def\">expletio, satisfactio.</div><div class=\"def\">▼<b>～した</b> contentus.</div><div class=\"def\">▼<b>～させる</b> expleo, satisfacio.</div><div class=\"def\">▼<b>～している</b> satis habeo.</div><div class=\"def\">⇒<a href=\"entry://喜ぶ\">喜ぶ</a>.</div>\r\n","<div class=\"hw jl\">源泉</div><div class=\"def\">fons.</div>\r\n","<div class=\"hw jl\">準備</div><div class=\"def\">praeparatio.</div><div class=\"def\">▼<b>～する</b> praeparo.</div>\r\n","<div class=\"hw jl\">溝</div><div class=\"def\">fossa, sulcus;(水が流れる)incile, incilis fossa, sulcus aquarius.</div><div class=\"def\">▼<b>小さな～</b> fossula.</div><div class=\"ex2\">～を掘る<span class=\"ext\">fossam fodio [sulco].</span></div><div class=\"def\">⇒<a href=\"entry://穴\">穴</a>.</div>\r\n","<div class=\"hw jl\">溶かす</div><div class=\"def\">fundo, liquo, liquefacio.</div><div class=\"def\">⇒<a href=\"entry://溶ける\">溶ける</a>,<a href=\"entry://液体\">液体</a>.</div>\r\n","<div class=\"hw jl\">溶ける</div><div class=\"def\">liquesco, tabeo, fundor(<i>pass</i>), liquor(<i>dep</i>).</div><div class=\"def\">▼<b>溶けている</b> liqueo.</div><div class=\"def\">⇒<a href=\"entry://溶かす\">溶かす</a>,<a href=\"entry://液体\">液体</a>.</div>\r\n","<div class=\"hw jl\">溺れる</div><div class=\"def\">(=溺死する)in aqua pereo, in aqua vitam amitto;(=水中で窒息・気絶する)se aquā exanimare(← exanimo).</div><div class=\"ex2\">川で溺れ死ぬ<span class=\"ext\">in flumine pereo.</span></div>\r\n","<div class=\"hw jl\">滅びる</div><div class=\"def\">pereo, intereo, depereo, exstinguor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://死ぬ\">死ぬ</a>,<a href=\"entry://滅亡\">滅亡</a>.</div>\r\n","<div class=\"hw jl\">滅ぼす</div><div class=\"def\">deleo, perdo, destruo, everto, exstinguo, aboleo, fundo, rumpo, corrumpo.</div>\r\n","<div class=\"hw jl\">滅亡</div><div class=\"def\">perditio.</div><div class=\"def\">⇒<a href=\"entry://滅びる\">滅びる</a>,<a href=\"entry://滅ぼす\">滅ぼす</a>.</div>\r\n","<div class=\"hw jl\">滑稽</div><div class=\"def\">▼<b>～な</b> ridiculus, jocosus, jocularis.</div>\r\n","<div class=\"hw jl\">滝</div><div class=\"def\">aquae dejectus [projectio], unda cadens.</div><div class=\"def\">▼<b>大～</b> cataracta, cataractes.</div>\r\n","<div class=\"hw jl\">滞在</div><div class=\"def\">mansio, commoratio.</div><div class=\"def\">▼<b>～する</b> maneo, commoror(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">滴</div><div class=\"def\">gutta.</div><div class=\"ex2\">雨の～<span class=\"ext\">gutta imbris.</span></div>\r\n","<div class=\"hw jl\">漁</div><div class=\"def\">piscatus;(=漁労)piscatorium artificium.</div><div class=\"def\">▼<b>～師</b> piscator(<i>m</i>), piscarius(<i>m</i>), piscatrix(<i>f</i>).</div>\r\n","<div class=\"hw jl\">漁業</div><div class=\"def\">piscatus, piscatio.</div><div class=\"def\">▼<b>～の</b> piscatorius.</div><div class=\"def\">⇒<a href=\"entry://漁\">漁</a>.</div>\r\n","<div class=\"hw jl\">漂う</div><div class=\"def\">fluito, erro, vagor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://さまよう\">さまよう</a>.</div>\r\n","<div class=\"hw jl\">漏らす</div><div class=\"def\">(秘密を)patefacio.</div><div class=\"def\">⇒<a href=\"entry://暴露\">暴露</a>.</div>\r\n","<div class=\"hw jl\">漏れる</div><div class=\"def\">(液体が)(=漏る, こぼれる)fluo, defluo, perfluo, mano, emano.</div>\r\n","<div class=\"hw jl\">演じる</div><div class=\"def\">(役を)ago.</div><div class=\"ex2\">役を～<span class=\"ext\">personam gero [tracto].</span></div><div class=\"def\">⇒<a href=\"entry://演技\">演技</a>,<a href=\"entry://役\">役</a>.</div>\r\n","<div class=\"hw jl\">演劇</div><div class=\"def\">(作品)fabula, drama;(ジャンル)ars scaenica.</div><div class=\"def\">⇒<a href=\"entry://劇\">劇</a>.</div>\r\n","<div class=\"hw jl\">演壇</div><div class=\"def\">suggestum, suggestus, rostra(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">演奏</div><div class=\"def\">▼(楽器を)<b> ～する</b> cano 〈+<i>abl</i>〉.</div><div class=\"ex2\">竪琴を～する<span class=\"ext\">fidibus cano.</span></div><div class=\"ex2\">笛を～する<span class=\"ext\">tibiā cano.</span></div><div class=\"ex2\">彼は声を出さずに竪琴を～した<span class=\"ext\">citharā sine voce cecinit.</span></div>\r\n","<div class=\"hw jl\">演技</div><div class=\"def\">actio, actus.</div><div class=\"def\">⇒<a href=\"entry://演じる\">演じる</a>,<a href=\"entry://俳優\">俳優</a>.</div>\r\n","<div class=\"hw jl\">演説</div><div class=\"def\">oratio.</div><div class=\"def\">▼<b>～家</b>(=弁論家)orator.</div><div class=\"def\">▼<b>～する</b> orationem [contionem] habeo, verba facio.</div><div class=\"ex2\">彼は兵士を前に～をした<span class=\"ext\">contionem apud milites habuit.</span></div>\r\n","<div class=\"hw jl\">漠然</div><div class=\"def\">▼<b>～とした</b> vagus.</div><div class=\"def\">▼<b>～と</b>(=ぼんやりと)obscure.</div><div class=\"def\">⇒<a href=\"entry://あいまい\">あいまい</a>.</div>\r\n","<div class=\"hw jl\">漫画</div><div class=\"def\">imaguncula, lepidus imago, libellus pictographicus [scaenographicus].</div>\r\n","<div class=\"hw jl\">潔白</div><div class=\"def\">innocentia.</div><div class=\"def\">▼<b>～な</b> innocens.</div><div class=\"def\">▼<b>～で</b> innocenter.</div>\r\n","<div class=\"hw jl\">潜る</div><div class=\"def\">urinor(<i>dep</i>), inurino.</div><div class=\"def\">▼<b>～人</b> urinator.</div><div class=\"ex2\">水の中に～<span class=\"ext\">se in aquam immergere(← immergo).</span></div>\r\n","<div class=\"hw jl\">潜在的</div><div class=\"def\">▼<b>～な</b> potentialis.</div>\r\n","<div class=\"hw jl\">潜水夫</div><div class=\"def\">urinator(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://潜る\">潜る</a>.</div>\r\n","<div class=\"hw jl\">潜水艦</div><div class=\"def\">navis submarina.</div>\r\n","<div class=\"hw jl\">潤す</div><div class=\"def\">(=湿らせる)umecto, madefacio.</div><div class=\"def\">⇒<a href=\"entry://湿る\">湿る</a>.</div>\r\n","<div class=\"hw jl\">潮</div><div class=\"def\">aestus(maritimus).</div><div class=\"def\">⇒<a href=\"entry://満潮\">満潮</a>.</div>\r\n","<div class=\"hw jl\">澱粉</div><div class=\"def\">amylum.</div>\r\n","<div class=\"hw jl\">激しい</div><div class=\"def\">vehemens, violens, violentus, acer, concitatus, fervidus.</div><div class=\"def\">▼<b>激しさ</b> vehementia, violentia.</div><div class=\"def\">▼<b>激しく</b> vehementer, violenter, acriter, acerbe.</div>\r\n","<div class=\"hw jl\">激励</div><div class=\"def\">hortatio, hortatus.</div><div class=\"def\">⇒<a href=\"entry://励ます\">励ます</a>.</div>\r\n","<div class=\"hw jl\">激動</div><div class=\"def\">perturbatio.</div><div class=\"def\">⇒<a href=\"entry://騒動\">騒動</a>.</div>\r\n","<div class=\"hw jl\">激化</div><div class=\"def\">▼<b>～する</b> vehementesco, ingravesco.</div>\r\n","<div class=\"hw jl\">激情</div><div class=\"def\">impetus.</div>\r\n","<div class=\"hw jl\">濃い</div><div class=\"def\">spissus, fuscus, condensatus.</div><div class=\"def\">▼<b>濃く</b> spisse.</div><div class=\"def\">▼<b>濃くする</b> spisso, fusco.</div>\r\n","<div class=\"hw jl\">濃縮</div><div class=\"def\">▼<b>～する</b> denso, denseo, condenso.</div><div class=\"def\">▼<b>～された</b> condensus, densus.</div>\r\n","<div class=\"hw jl\">濾す</div><div class=\"def\">liquo, sacco, percolo, colo.</div><div class=\"def\">⇒<a href=\"entry://濾過\">濾過</a>.</div>\r\n","<div class=\"hw jl\">濾過</div><div class=\"def\">percolatio.</div><div class=\"def\">⇒<a href=\"entry://濾す\">濾す</a>.</div>\r\n","<div class=\"hw jl\">火</div><div class=\"def\">ignis.</div><div class=\"def\">▼<b>～の</b> igneus.</div><div class=\"def\">▼<b>～がつく</b>(=火事になる)ignem capio.</div><div class=\"def\">▼(...に)<b>～をつける</b> 〈+<i>dat</i>〉 ignem infero, accendo.</div><div class=\"def\">⇒<a href=\"entry://炎\">炎</a>.</div>\r\n","<div class=\"hw jl\">火事</div><div class=\"def\">⇒<a href=\"entry://火災\">火災</a>.</div>\r\n","<div class=\"hw jl\">火傷</div><div class=\"def\">(行為)adustio, ambustio;(症状)adusta(<i>pl</i>), inusta(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">火山</div><div class=\"def\">mons ignibus aeternis ardens, mons ignivomus.</div><div class=\"ex2\">～が噴火する<span class=\"ext\">mons ignivomus erumpit.</span></div>\r\n","<div class=\"hw jl\">火打石</div><div class=\"def\">silex.</div>\r\n","<div class=\"hw jl\">火災</div><div class=\"def\">incendium.</div>\r\n","<div class=\"hw jl\">火花</div><div class=\"def\">scintilla.</div><div class=\"def\">▼<b>～を散らす</b> scintillo.</div>\r\n","<div class=\"hw jl\">火薬</div><div class=\"def\">pulvis pyrius.</div>\r\n","<div class=\"hw jl\">灯台</div><div class=\"def\">pharus, pharos.</div>\r\n","<div class=\"hw jl\">灰</div><div class=\"def\">cinis;(まだ熱い)favilla.</div><div class=\"def\">▼<b>～の</b> cinerarius.</div><div class=\"def\">▼<b>～になる</b> cineresco.</div>\r\n","<div class=\"hw jl\">灰色</div><div class=\"def\">color cinereus [cineraceus].</div><div class=\"def\">▼<b>～の</b> cinereus, cineraceus.</div>\r\n","<div class=\"hw jl\">災い</div><div class=\"def\">malum, clades, calamitas, plaga, exitium, casus.</div>\r\n","<div class=\"hw jl\">災害</div><div class=\"def\">calamitas, plaga, exitium, casus.</div><div class=\"def\">⇒<a href=\"entry://災難\">災難</a>,<a href=\"entry://災い\">災い</a>.</div>\r\n","<div class=\"hw jl\">災難</div><div class=\"def\">clades, calamitas, exitium, casus, incommodum, malum, infortunium.</div><div class=\"def\">▼<b>～に苦しめられた</b> calamitosus.</div><div class=\"def\">⇒<a href=\"entry://災い\">災い</a>,<a href=\"entry://災害\">災害</a>.</div>\r\n","<div class=\"hw jl\">炎</div><div class=\"def\">flamma.</div><div class=\"def\">⇒<a href=\"entry://火\">火</a>.</div>\r\n","<div class=\"hw jl\">炎症</div><div class=\"def\">inflammatio.</div>\r\n","<div class=\"hw jl\">炒める</div><div class=\"def\">(フライパンで)frigo(in sartagine).</div>\r\n","<div class=\"hw jl\">炭</div><div class=\"def\">carbo.</div><div class=\"def\">▼<b>～の</b> carbonarius.</div><div class=\"def\">⇒<a href=\"entry://炭素\">炭素</a>.</div>\r\n","<div class=\"hw jl\">炭素</div><div class=\"def\">carboneum.</div>\r\n","<div class=\"hw jl\">点</div><div class=\"def\">(幾何学図形上の)punctum.</div><div class=\"ex2\">あらゆる～で<span class=\"ext\">ex [ab] omnibus partibus [omni parte].</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">地点<span class=\"ext\">locus.</span></div><div class=\"cf\">その地点<span class=\"ext\">id loci.</span></div>\r\n","<div class=\"hw jl\">点検</div><div class=\"def\">recognitio.</div><div class=\"def\">▼<b>～する</b> recognosco, inspicio.</div>\r\n","<div class=\"hw jl\">為替</div><div class=\"def\">nummarium mandatum.</div><div class=\"def\">▼<b>郵便～</b> nummarium publici cursus mandatum.</div>\r\n","<div class=\"hw jl\">烏賊</div><div class=\"def\">sepia.</div>\r\n","<div class=\"hw jl\">無</div><div class=\"def\">nihil, nihilum.</div><div class=\"ex2\">～からは何も生じない<span class=\"ext\">ex nihilo nihil fit.</span></div><div class=\"ex2\">～に帰す<span class=\"ext\">ad nihilum venio.</span></div>\r\n","<div class=\"hw jl\">無力</div><div class=\"def\">impotentia, infirmitas, imbecillitas.</div><div class=\"def\">▼<b>～な</b> invalidus, impotens, infirmus, imbecillus.</div>\r\n","<div class=\"hw jl\">無効</div><div class=\"def\">▼<b>～の</b> nullus, irritus.</div><div class=\"def\">▼<b>～である</b> nihil valeo.</div><div class=\"def\">▼<b>～になる</b> evanesco.</div><div class=\"def\">▼<b>～とみなす</b> pro irrito [infecto] habeo.</div>\r\n","<div class=\"hw jl\">無口</div><div class=\"def\">taciturnitas, silentium.</div><div class=\"def\">▼<b>～な</b> taciturnus, silens.</div><div class=\"def\">⇒<a href=\"entry://静か\">静か</a>.</div>\r\n","<div class=\"hw jl\">無名</div><div class=\"def\">ignobilitas, obscuritas.</div><div class=\"def\">▼<b>～の</b> ignobilis, obscurus.</div><div class=\"def\">⇒<a href=\"entry://有名\">有名</a>.</div>\r\n","<div class=\"hw jl\">無実</div><div class=\"def\">innocentia.</div><div class=\"def\">▼<b>～の</b> insons, innocens, culpae expers.</div><div class=\"def\">⇒<a href=\"entry://無罪\">無罪</a>.</div>\r\n","<div class=\"hw jl\">無害</div><div class=\"def\">innocentia.</div><div class=\"def\">▼<b>～の</b> innocens, innoxius.</div>\r\n","<div class=\"hw jl\">無差別</div><div class=\"def\">▼<b>～の</b> neglegens.</div><div class=\"def\">▼<b>～に</b> promiscue, sine discrimine, sine ullo delectu, omni discrimine remoto, delectu omni remoto.</div>\r\n","<div class=\"hw jl\">無意識</div><div class=\"def\">(心理学的な)subliminium, quod infra conscientiae limen fit, interior animus, recondita animi pars, animi profundum, irrationales animi motus.</div>\r\n","<div class=\"hw jl\">無数</div><div class=\"def\">innumerabilitas.</div><div class=\"def\">▼<b>～の</b> innumerus, innumerabilis.</div><div class=\"def\">▼<b>～に</b> innumerabiliter.</div><div class=\"def\">⇒<a href=\"entry://無限\">無限</a>.</div>\r\n","<div class=\"hw jl\">無料</div><div class=\"def\">▼<b>～の</b> gratuitus.</div><div class=\"def\">▼<b>～で</b> gratuito, gratiis.</div>\r\n","<div class=\"hw jl\">無断</div><div class=\"def\">▼<b>～で</b>(=承諾なく)sine permisso [permissione].</div>\r\n","<div class=\"hw jl\">無気力</div><div class=\"def\">veternus.</div><div class=\"def\">▼<b>～な</b> veternosus.</div><div class=\"def\">⇒<a href=\"entry://気力\">気力</a>,<a href=\"entry://怠惰\">怠惰</a>.</div>\r\n","<div class=\"hw jl\">無理</div><div class=\"def\">▼<b>～な</b>(=実現不可能な, 行ないえない)qui fieri non potest, qui effici non potest.</div>\r\n","<div class=\"hw jl\">無理やり</div><div class=\"def\">per vim.</div>\r\n","<div class=\"hw jl\">無用</div><div class=\"def\">▼<b>～な</b>(=役に立たない)inutilis;(=必要ない)non necessarius;(=余分な)supervacaneus, supervacuus.</div><div class=\"def\">▼(...は)<b>～です</b>(=...は重要でない, ...する必要はない)nihil attinet 〈+<i>inf</i>〉, supervacaneum est 〈+<i>inf</i>〉, nihil necesse est 〈+<i>inf</i>〉, nihil opus est 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw jl\">無益</div><div class=\"def\">(=役に立たないこと)inutilitas, inanitas, vanitas.</div><div class=\"def\">▼<b>～な</b>(=役に立たない, 空しい)inutilis, inanis, vanus.</div><div class=\"def\">▼<b>～に</b>(=無駄に, 空しく)inutiliter, inaniter, vane, frustra, nequiquam.</div>\r\n","<div class=\"hw jl\">無知</div><div class=\"def\">(=知らないこと)ignoratio, ignorantia, inscientia, inscitia, imprudentia;(=無学)imperitia, inscitia.</div><div class=\"def\">▼<b>～な</b>(=知らない)ignarus, inscius, inscitus, insciens, imprudens;(=無学な, 未熟な)imperitus, rudis, indoctus.</div><div class=\"def\">⇒<a href=\"entry://素人\">素人</a>.</div>\r\n","<div class=\"hw jl\">無礼</div><div class=\"def\">contumelia.</div><div class=\"def\">▼<b>～な</b> contumeliosus.</div><div class=\"def\">⇒<a href=\"entry://侮辱\">侮辱</a>.</div>\r\n","<div class=\"hw jl\">無精</div><div class=\"def\">▼<b>非常に筆～な</b> ad scribendas litteras pigerrimus.</div><div class=\"def\">⇒<a href=\"entry://怠惰\">怠惰</a>.</div>\r\n","<div class=\"hw jl\">無線</div><div class=\"def\">(=無線放送, 無線通信)nuntium radiophonice missum, aerium nuntium, nuntium per aetheris undas missum, radiotelegraphia, transmissio radiotelegraphica.</div><div class=\"def\">▼<b>～(通信)の</b> radiotelegraphicus.</div><div class=\"def\">▼<b>～局</b>(=無線放送局)radiophonica statio.</div><div class=\"def\">▼<b>～電話</b> radiotelephonium, radiotelephonum.</div>\r\n","<div class=\"hw jl\">無線技術</div><div class=\"def\">radiotechnice.</div><div class=\"def\">▼<b>～の</b> radiotechnicus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">無線技士<span class=\"ext\">radiotechnices peritus.</span></div>\r\n","<div class=\"hw jl\">無縁</div><div class=\"def\">▼<b>～な</b> alienus.</div><div class=\"ex2\">私は人間だ. 人間に関することは一切私と～とは考えない<span class=\"ext\">homo sum, humani nihil a me alienum puto.</span></div>\r\n","<div class=\"hw jl\">無罪</div><div class=\"def\">innocentia.</div><div class=\"def\">▼<b>～の</b> innocens, insons, innoxius, non culpabilis.</div><div class=\"def\">▼<b>～である</b> in culpa non sum, a culpa absum.</div><div class=\"def\">▼<b>～放免</b> absolutio, liberatio.</div><div class=\"def\">▼<b>～放免にする</b> absolvo, libero.</div>\r\n","<div class=\"hw jl\">無能</div><div class=\"def\">▼(...することに)<b> ～な</b>(=能力がない)inhabilis 〈alci rei;alci rei faciendae;ad alqd〉, invalidus.</div><div class=\"def\">▼<b>～な</b>(=知識がなくて無能な)inscitus, imperitus, ignarus;(=愚かな)hebes.</div><div class=\"def\">▼<b>～である</b>(=能力がない)non valeo.</div><div class=\"def\">⇒<a href=\"entry://無知\">無知</a>.</div>\r\n","<div class=\"hw jl\">無茶</div><div class=\"def\">(=無鉄砲)audacia.</div><div class=\"def\">▼<b>～な</b>(=無鉄砲な)audax;(=道理に適わない, 不条理な)insanus, rationis expers, male sanus, a ratione aversus, absurdus.</div><div class=\"def\">▼<b>～だ</b> nulla ratione est(← sum), minime rationis est.</div>\r\n","<div class=\"hw jl\">無視</div><div class=\"def\">praetermissio, omissio.</div><div class=\"def\">▼<b>～する</b> praetermitto, neglego.</div>\r\n","<div class=\"hw jl\">無言</div><div class=\"def\">silentium.</div><div class=\"def\">▼<b>～の</b> silens, silentiosus, taciturnus.</div><div class=\"def\">▼<b>～で</b> silentio, silentiose.</div><div class=\"def\">⇒<a href=\"entry://黙る\">黙る</a>.</div>\r\n","<div class=\"hw jl\">無責任</div><div class=\"def\">nulla responsabilitas, responsabilitas defecta, sui muneris officiique neglectio.</div><div class=\"def\">⇒<a href=\"entry://責任\">責任</a>.</div>\r\n","<div class=\"hw jl\">無邪気</div><div class=\"def\">▼<b>～な</b> puerilis, innocens, simplex.</div>\r\n","<div class=\"hw jl\">無関心</div><div class=\"def\">(=無頓着)neglectio, neglegentia, incuria.</div><div class=\"def\">▼<b>～な</b>(=無頓着な)neglegens, incuriosus.</div>\r\n","<div class=\"hw jl\">無限</div><div class=\"def\">infinitum, immensum.</div><div class=\"def\">▼<b>～性</b> infinitas, immensitas.</div><div class=\"def\">▼<b>～分割</b> sectio in infinitum.</div><div class=\"def\">▼<b>～の</b> infinitus, immensus.</div><div class=\"def\">▼<b>～に</b> infinite.</div><div class=\"def\">⇒<a href=\"entry://無数\">無数</a>.</div>\r\n","<div class=\"hw jl\">無難</div><div class=\"def\">▼<b>～な</b> moderatus, mediocris, modicus.</div>\r\n","<div class=\"hw jl\">無頓着</div><div class=\"def\">incultus, neglegentia, languor, indiligentia, segnitia.</div><div class=\"def\">▼<b>～な</b> neglegens, languidus.</div>\r\n","<div class=\"hw jl\">無駄</div><div class=\"def\">▼<b>～な</b> vanus, inanis, inutilis, incassus, supervacaneus, supervacuus.</div><div class=\"def\">▼<b>～に</b> inaniter, frustra, nequiquam, inutiliter, incassum.</div><div class=\"def\">▼<b>～にする</b>(=だいなしにする)perdo, disperdo, corrumpo, consumo.</div><div class=\"def\">▼<b>～になる</b> pereo.</div><div class=\"ex2\">～に骨を折る<span class=\"ext\">operam perdo.</span></div><div class=\"ex2\">一日を～にする<span class=\"ext\">diem perdo.</span></div><div class=\"ex2\">時間を～にする<span class=\"ext\">tempus perdo [tero].</span></div>\r\n","<div class=\"hw jl\">焦がす</div><div class=\"def\">aduro, uro.</div><div class=\"def\">▼<b>焦げた</b> adustus.</div><div class=\"def\">⇒<a href=\"entry://燃やす\">燃やす</a>.</div>\r\n","<div class=\"hw jl\">焦る</div><div class=\"def\">sollicitor(<i>pass</i>).</div><div class=\"def\">▼<b>焦っている</b> impatiens.</div>\r\n","<div class=\"hw jl\">然るべき</div><div class=\"def\">⇒<a href=\"entry://適切\">適切</a>,<a href=\"entry://ふさわしい\">ふさわしい</a>,<a href=\"entry://資格\">資格</a>.</div>\r\n","<div class=\"hw jl\">焼く</div><div class=\"def\">uro, aduro, torreo, coquo.</div>\r\n","<div class=\"hw jl\">煉瓦</div><div class=\"def\">later.</div><div class=\"def\">▼<b>小さな～</b> laterculus.</div><div class=\"def\">▼<b>～でつくられた</b> latericius.</div>\r\n","<div class=\"hw jl\">煙</div><div class=\"def\">fumus.</div><div class=\"def\">▼<b>～の多い, ～でいっぱいの</b> fumosus.</div>\r\n","<div class=\"hw jl\">煙突</div><div class=\"def\">fumi ductus, fumarium.</div>\r\n","<div class=\"hw jl\">煙草</div><div class=\"def\">tabacum, nicotiana herba.</div><div class=\"def\">▼<b>～の</b> tabacarius.</div><div class=\"def\">⇒<a href=\"entry://喫煙\">喫煙</a>.</div>\r\n","<div class=\"hw jl\">照らす</div><div class=\"def\">illumino, illustro, collustro.</div>\r\n","<div class=\"hw jl\">照る</div><div class=\"def\">(太陽や月が)luceo.</div><div class=\"def\">⇒<a href=\"entry://輝く\">輝く</a>.</div>\r\n","<div class=\"hw jl\">煩わしい</div><div class=\"def\">molestus.</div><div class=\"def\">▼<b>煩わしさ</b> molestia.</div>\r\n","<div class=\"hw jl\">煮る</div><div class=\"def\">coquo.</div><div class=\"def\">▼<b>よく～</b> concoquo;(=煮つめる)decoquo.</div><div class=\"def\">▼<b>～こと</b> coctio, coctura.</div>\r\n","<div class=\"hw jl\">煽動</div><div class=\"def\">▼<b>～する</b> concito, accendo.</div><div class=\"def\">▼<b>～者</b> concitor, concitator.</div>\r\n","<div class=\"hw jl\">熊</div><div class=\"def\">(雄の)ursus;(雌の)ursa.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">シロクマ(=北極熊)<span class=\"ext\">ursus marinus.</span></div>\r\n","<div class=\"hw jl\">熟す</div><div class=\"def\">maturesco, maturor(<i>pass</i>).</div><div class=\"def\">▼<b>熟した</b> maturus.</div><div class=\"def\">⇒<a href=\"entry://成熟\">成熟</a>.</div>\r\n","<div class=\"hw jl\">熟慮</div><div class=\"def\">cogitatio, meditatio, commentatio.</div><div class=\"def\">▼(...について)<b> ～する</b> 〈de re;alqd〉 meditor(<i>dep</i>), 〈de re;alqd〉 cogito, 〈alqd〉 in animo agito, 〈de re〉 secum commentari(← commentor), 〈alqd〉 se cum volutare(← voluto).</div>\r\n","<div class=\"hw jl\">熱</div><div class=\"def\">calor, aestus;(病時の)febris, aestus.</div><div class=\"def\">⇒<a href=\"entry://熱い・暑い\">熱い</a>.</div>\r\n","<div class=\"hw jl\">熱い・暑い</div><div class=\"def\"><span class=\"pos3\">[形]</span> calidus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> caleo.</div><div class=\"def\">▼<b>熱くなる</b> calesco.</div><div class=\"def\">▼<b>熱くする</b> calefacio, calefacto.</div><div class=\"def\">⇒<a href=\"entry://熱する\">熱する</a>,<a href=\"entry://沸騰\">沸騰</a>,<a href=\"entry://燃える\">燃える</a>.</div>\r\n","<div class=\"hw jl\">熱する</div><div class=\"def\">calefacio, calefacto;(沸騰するまで)fervefacio.</div><div class=\"def\">▼(激しく)<b>熱している</b> ferveo.</div>\r\n","<div class=\"hw jl\">熱中</div><div class=\"def\">studium.</div><div class=\"def\">▼(...に)<b> ～する</b> 〈in alqd〉 exardesco.</div><div class=\"def\">▼<b>～している</b><span class=\"pos3\">[形]</span> cupidus, studiosus.</div>\r\n","<div class=\"hw jl\">熱帯</div><div class=\"def\">▼<b>～(地方)の</b> tropicus.</div>\r\n","<div class=\"hw jl\">熱心</div><div class=\"def\">studium.</div><div class=\"def\">▼<b>～な</b> enixus, studiosus.</div><div class=\"def\">▼<b>～に</b> enixe, studiose.</div><div class=\"def\">▼<b>～に求める</b> ardeo, studeo.</div><div class=\"def\">⇒<a href=\"entry://熱意\">熱意</a>.</div>\r\n","<div class=\"hw jl\">熱意</div><div class=\"def\">studium, ardor, cupiditas, impetus.</div><div class=\"def\">⇒<a href=\"entry://情熱\">情熱</a>,<a href=\"entry://熱望\">熱望</a>.</div>\r\n","<div class=\"hw jl\">熱望</div><div class=\"def\">cupiditas, ardor, aviditas.</div><div class=\"def\">▼<b>～する</b> cupio, ardeo, desidero.</div>\r\n","<div class=\"hw jl\">熱烈</div><div class=\"def\">▼<b>～な</b> ardens.</div><div class=\"def\">▼<b>～に</b> ardenter.</div>\r\n","<div class=\"hw jl\">熱狂</div><div class=\"def\">insania, furor, ardor.</div><div class=\"def\">▼<b>～的な</b> ardens.</div><div class=\"def\">▼<b>～的に</b> ardenter.</div><div class=\"def\">▼<b>～する</b> insano, furo.</div>\r\n","<div class=\"hw jl\">燃える</div><div class=\"def\">(=燃焼する)flagro, conflagro, uror(<i>pass</i>);(炎や灯火が)ardeo, aestuo.</div>\r\n","<div class=\"hw jl\">燃やす</div><div class=\"def\">(=燃焼させる, 焼く)uro;(=火をつける, 焚き付ける)incendo, succendo.</div><div class=\"def\">▼<b>燃やし尽くす</b>(=焼き尽くす)exuro, peruro.</div>\r\n","<div class=\"hw jl\">燃料</div><div class=\"def\">ignis alimentum.</div>\r\n","<div class=\"hw jl\">燕</div><div class=\"def\">hirundo.</div>\r\n","<div class=\"hw jl\">爆弾</div><div class=\"def\">pyrobolus, pyrobolum, missile ignivomum.</div><div class=\"def\">⇒<a href=\"entry://原子\">原子</a>.</div>\r\n","<div class=\"hw jl\">爆撃</div><div class=\"def\">crebri tormentorum bellicorum ictus(<i>pl</i>), pyrobolorum conjectio [jactatio, jactus, dejectio].</div><div class=\"def\">▼<b>～する</b> pyrobolis quatio [everto, verbero].</div>\r\n","<div class=\"hw jl\">爆発</div><div class=\"def\">eruptio.</div><div class=\"def\">▼<b>～する</b> erumpo, displodo, displodor(<i>pass</i>).</div><div class=\"def\">▼<b>～性の</b> dirumpendi vim habens, displosivus, explosivus.</div><div class=\"def\">▼<b>～物</b>(=爆薬)materia displosiva [explosiva].</div>\r\n","<div class=\"hw jl\">爪</div><div class=\"def\">unguis;(小さな)unguiculus.</div>\r\n","<div class=\"hw jl\">爬虫類</div><div class=\"def\">▼<b>～(の動物)</b>(animal)reptile.</div>\r\n","<div class=\"hw jl\">爵位</div><div class=\"def\">tituli nobilitatis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">公爵<span class=\"ext\">dux.</span></div><div class=\"cf\">侯爵<span class=\"ext\">marchio, marquisus, marquisius.</span></div><div class=\"cf\">伯爵<span class=\"ext\">comes.</span></div><div class=\"cf\">子爵<span class=\"ext\">vicecomes.</span></div><div class=\"cf\">男爵<span class=\"ext\">baro.</span></div>\r\n","<div class=\"hw jl\">父</div><div class=\"def\">pater.</div><div class=\"def\">▼<b>～(方)の</b> paternus.</div><div class=\"def\">⇒<a href=\"entry://母\">母</a>,<a href=\"entry://両親\">両親</a>.</div>\r\n","<div class=\"hw jl\">片づける</div><div class=\"def\">(=整理する)ordino, dispono;(=終わらせる)conficio;(=取り除く)interimo;(=滅ぼす)interficio.</div>\r\n","<div class=\"hw jl\">片隅</div><div class=\"def\">angulus;(=へんぴな場所)locus remotus.</div>\r\n","<div class=\"hw jl\">版画</div><div class=\"def\">▼<b>銅～</b> chalcographica imago, imago chalcographice depicta.</div><div class=\"def\">▼<b>石～</b> lithographia, imago lithographica.</div>\r\n","<div class=\"hw jl\">牛</div><div class=\"def\">bos.</div><div class=\"def\">▼<b>牡～</b> taurus.</div><div class=\"def\">▼<b>牝～</b> vacca.</div><div class=\"def\">▼<b>子～</b> vitulus.</div><div class=\"def\">⇒<a href=\"entry://牛乳\">牛乳</a>.</div>\r\n","<div class=\"hw jl\">牛乳</div><div class=\"def\">lac bubulum, lac vaccinum.</div>\r\n","<div class=\"hw jl\">牡蠣</div><div class=\"def\">ostrea.</div>\r\n","<div class=\"hw jl\">牢</div><div class=\"def\">carcer.</div><div class=\"def\">▼<b>～に入れる</b> in vincula conjicio.</div><div class=\"def\">⇒<a href=\"entry://閉じ込める\">閉じ込める</a>.</div>\r\n","<div class=\"hw jl\">牢屋</div><div class=\"def\">⇒<a href=\"entry://牢\">牢</a>.</div>\r\n","<div class=\"hw jl\">牧畜</div><div class=\"def\">pastio.</div><div class=\"def\">▼<b>～の</b> pascuus.</div><div class=\"def\">▼<b>～する</b> pasco, pascor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">牧草地</div><div class=\"def\">pascuum, pastio, pratum.</div><div class=\"def\">⇒<a href=\"entry://草原\">草原</a>.</div>\r\n","<div class=\"hw jl\">物</div><div class=\"def\">res;(=物体)corpus;(=物質)materies, materia.</div>\r\n","<div class=\"hw jl\">物体</div><div class=\"def\">corpus.</div>\r\n","<div class=\"hw jl\">物価</div><div class=\"def\">pretium.</div><div class=\"def\">▼<b>～の上昇</b> pretii auctus, victualium caritas, caritas annonae.</div><div class=\"def\">▼<b>～が安いこと</b> vilitas.</div>\r\n","<div class=\"hw jl\">物理学</div><div class=\"def\">physice, physica(ratio), physica [naturalis] disciplina, physica(<i>pl</i>).</div><div class=\"def\">▼<b>～者</b> physicus.</div>\r\n","<div class=\"hw jl\">物語</div><div class=\"def\">fabula, narratio, historia.</div><div class=\"def\">▼<b>物語る</b> narro.</div>\r\n","<div class=\"hw jl\">物質</div><div class=\"def\">materia, materies.</div><div class=\"def\">▼<b>～の</b> materialis.</div>\r\n","<div class=\"hw jl\">物音</div><div class=\"def\">sonus, sonitus, crepitus, fremitus.</div>\r\n","<div class=\"hw jl\">特に</div><div class=\"def\">praesertim, maxime, in primo, unice, utique, in primis.</div>\r\n","<div class=\"hw jl\">特別</div><div class=\"def\">▼<b>～な, ～の</b> definitus, extraordinarius, praecipuus.</div><div class=\"def\">▼<b>～に</b> definite, praecipue, singulariter.</div>\r\n","<div class=\"hw jl\">特徴</div><div class=\"def\">proprietas, proprium;(顔の)lineamentum.</div>\r\n","<div class=\"hw jl\">特権</div><div class=\"def\">jus praecipium, privilegium.</div>\r\n","<div class=\"hw jl\">特殊</div><div class=\"def\">specialitas.</div><div class=\"def\">▼<b>～な</b> specialis.</div>\r\n","<div class=\"hw jl\">特許</div><div class=\"def\">diploma inventi [inventorum], inventoris privilegium, inventionis documentum [publicum diploma].</div>\r\n","<div class=\"hw jl\">犠牲</div><div class=\"def\">sacrificium, immolatio.</div><div class=\"def\">▼<b>～者</b>(=事故や災害の死者)victima, mortuus.</div><div class=\"def\">▼<b>～獣</b>(=いけにえ)victima, hostia.</div><div class=\"def\">▼<b>～を行なう, 神に～を捧げる</b> sacrifico, sacrificium facio [ago].</div><div class=\"def\">▼(...を)<b>～に捧げる</b> 〈+<i>acc</i>〉 sacrifico, immolo.</div>\r\n","<div class=\"hw jl\">犬</div><div class=\"def\">canis.</div><div class=\"def\">▼<b>子～</b> catulus.</div><div class=\"def\">▼<b>～のような</b> caninus.</div>\r\n","<div class=\"hw jl\">犯人</div><div class=\"def\">(homo)sceleratus [nefarius, scelestus].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">殺人犯<span class=\"ext\">homicida.</span></div><div class=\"def\">⇒<a href=\"entry://犯罪\">犯罪</a>.</div>\r\n","<div class=\"hw jl\">犯罪</div><div class=\"def\">scelus, facinus.</div><div class=\"def\">▼<b>～を犯した</b> sceleratus, facinorosus.</div><div class=\"def\">⇒<a href=\"entry://罪\">罪</a>.</div>\r\n","<div class=\"hw jl\">犯行</div><div class=\"def\">scelus, facinus.</div><div class=\"def\">▼<b>～の動機</b> causa facinoris.</div><div class=\"def\">⇒<a href=\"entry://犯罪\">犯罪</a>.</div>\r\n","<div class=\"hw jl\">状態</div><div class=\"def\">(=状況)habitus, status, condicio;(体の)affectus.</div>\r\n","<div class=\"hw jl\">状況</div><div class=\"def\">status, res, tempus, causa, condicio, locus.</div><div class=\"ex2\">～に応じて<span class=\"ext\">pro tempore.</span></div>\r\n","<div class=\"hw jl\">狂い</div><div class=\"def\">(機械や体の調子の)perturbatio.</div><div class=\"def\">⇒<a href=\"entry://混乱\">混乱</a>.</div>\r\n","<div class=\"hw jl\">狂う</div><div class=\"def\">(気が)insanio, deliro.</div><div class=\"def\">▼(気が)<b>狂った</b> insanus, furiosus, demens, amens, vecors, delirus.</div><div class=\"def\">▼(気が)<b>狂って</b> dementer, insane, furiose.</div><div class=\"def\">⇒<a href=\"entry://狂気\">狂気</a>,<a href=\"entry://狂乱\">狂乱</a>.</div>\r\n","<div class=\"hw jl\">狂わせる</div><div class=\"def\">(機械や体の調子を)(=混乱させる)turbo, conturbo, perturbo.</div>\r\n","<div class=\"hw jl\">狂乱</div><div class=\"def\">(状態)furor.</div><div class=\"def\">▼<b>～する</b>(=発狂する)furo.</div><div class=\"def\">▼<b>～した</b>(=発狂した)furiosus, demens, vecors, cerritus.</div><div class=\"def\">⇒<a href=\"entry://狂気\">狂気</a>.</div>\r\n","<div class=\"hw jl\">狂人</div><div class=\"def\">amens, demens.</div>\r\n","<div class=\"hw jl\">狂暴</div><div class=\"def\">furor, furia, ferocitas.</div><div class=\"def\">▼<b>～な</b> furiosus, furens, ferox.</div><div class=\"def\">▼<b>～に</b> furialiter, furenter, ferociter.</div>\r\n","<div class=\"hw jl\">狂気</div><div class=\"def\">insania, vesania, dementia, amentia.</div><div class=\"def\">▼<b>～の</b>(=気の狂った)insanus, demens, furiosus, furibundus.</div><div class=\"def\">⇒<a href=\"entry://狂う\">狂う</a>.</div>\r\n","<div class=\"hw jl\">狙う</div><div class=\"def\">destino, peto.</div>\r\n","<div class=\"hw jl\">狡猾</div><div class=\"def\">▼<b>～(さ)</b> calliditas, astutia, versutia, dolus.</div><div class=\"def\">▼<b>～な</b> callidus, astutus, dolosus, versutus.</div>\r\n","<div class=\"hw jl\">狩り</div><div class=\"def\">(=狩猟)venatio, venatus.</div><div class=\"def\">▼<b>～に用いられる</b> venaticus.</div><div class=\"def\">▼<b>～に行く, ～をする</b> venor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">狩人</div><div class=\"def\">venator(<i>m</i>), venatrix(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> venatorius.</div>\r\n","<div class=\"hw jl\">独力</div><div class=\"def\">▼<b>～で</b> per se, nullo adjuvante.</div>\r\n","<div class=\"hw jl\">独占</div><div class=\"def\">monopolium.</div><div class=\"def\">▼<b>～する</b> monopolium habeo.</div><div class=\"def\">▼<b>～する人</b> monopola.</div>\r\n","<div class=\"hw jl\">独特</div><div class=\"def\">▼<b>～の</b> peculiaris, singularis.</div><div class=\"def\">⇒<a href=\"entry://独自\">独自</a>.</div>\r\n","<div class=\"hw jl\">独立</div><div class=\"def\">libertas.</div><div class=\"def\">▼<b>～した</b> liber.</div>\r\n","<div class=\"hw jl\">独自</div><div class=\"def\">▼<b>～の</b> proprius.</div><div class=\"def\">⇒<a href=\"entry://固有\">固有</a>.</div>\r\n","<div class=\"hw jl\">独裁</div><div class=\"def\">dictatura.</div><div class=\"def\">▼<b>～者</b> dictator.</div><div class=\"def\">▼<b>～(者)の</b> dictatorius.</div>\r\n","<div class=\"hw jl\">独身</div><div class=\"def\">(状態)caelibatus.</div><div class=\"def\">▼<b>～生活</b> caelebs vita.</div><div class=\"def\">▼<b>～者</b> caelebs.</div><div class=\"def\">▼<b>～の</b> caelebs.</div>\r\n","<div class=\"hw jl\">狭い</div><div class=\"def\">angustus, artus;(非常に)perangustus.</div><div class=\"def\">▼<b>～場所</b> artum.</div>\r\n","<div class=\"hw jl\">狭める</div><div class=\"def\">angusto.</div>\r\n","<div class=\"hw jl\">狼</div><div class=\"def\">lupus;(雌の)lupa.</div><div class=\"def\">▼<b>～の, ～のような</b> lupinus.</div><div class=\"ex2\">人間は人間にとって～である<span class=\"ext\">homo homini lupus.</span></div>\r\n","<div class=\"hw jl\">狼狽</div><div class=\"def\">confusio, conturbatio.</div><div class=\"def\">▼<b>～させる</b> confundo, conturbo.</div>\r\n","<div class=\"hw jl\">猛烈</div><div class=\"def\">▼<b>～な</b> concitatus, vehemens, violens, violentus.</div><div class=\"def\">▼<b>～に</b> ferociter, concitate, vehementer, violenter.</div><div class=\"def\">⇒<a href=\"entry://激しい\">激しい</a>.</div>\r\n","<div class=\"hw jl\">猟</div><div class=\"def\">(=狩猟)venatio, venatus.</div><div class=\"def\">▼<b>～師</b> venator(<i>m</i>), venatrix(<i>f</i>).</div><div class=\"def\">▼<b>～の</b> venatorius.</div><div class=\"def\">▼<b>～をする, ～に行く</b> venor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">猥褻</div><div class=\"def\">obscenitas.</div><div class=\"def\">▼<b>～な</b> obscenus.</div>\r\n","<div class=\"hw jl\">猫</div><div class=\"def\">feles.</div><div class=\"def\">▼<b>～の</b> felinus.</div><div class=\"def\"></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">ヤマネコ<span class=\"ext\">lynx.</span></div>\r\n","<div class=\"hw jl\">献立</div><div class=\"def\">(=メニュー, お品書)escarum descriptio [index].</div>\r\n","<div class=\"hw jl\">献身</div><div class=\"def\">devotio, studium.</div><div class=\"def\">▼<b>～的な</b> devotus, studiosus.</div><div class=\"ex2\">私のきみに対する～<span class=\"ext\">mea in te pietas.</span></div>\r\n","<div class=\"hw jl\">猶予</div><div class=\"def\">dilatio, prolatio, procrastinatio.</div><div class=\"def\">▼<b>～する</b> differo, prolato.</div><div class=\"def\">⇒<a href=\"entry://延期\">延期</a>.</div>\r\n","<div class=\"hw jl\">猿</div><div class=\"def\">simia(<i>f</i>), simius(<i>m</i>).</div>\r\n","<div class=\"hw jl\">獣</div><div class=\"def\">bestia;(野生の)fera;(巨大な, 恐ろしい)belua.</div><div class=\"def\">▼<b>～の</b> bestiarius.</div><div class=\"def\">⇒<a href=\"entry://家畜\">家畜</a>.</div>\r\n","<div class=\"hw jl\">獣医</div><div class=\"def\">veterinarius.</div><div class=\"def\">▼<b>～学</b> medicina veterinaria.</div>\r\n","<div class=\"hw jl\">獰猛</div><div class=\"def\">feritas, ferocitas, saevitia, truculentia, immanitas.</div><div class=\"def\">▼<b>～な</b> ferus, saevus, truculentus, immanis.</div><div class=\"def\">▼<b>～に</b> ferociter.</div><div class=\"def\">▼<b>～にふるまう</b> saevio.</div><div class=\"def\">⇒<a href=\"entry://野蛮\">野蛮</a>,<a href=\"entry://残忍\">残忍</a>.</div>\r\n","<div class=\"hw jl\">獲得</div><div class=\"def\">▼<b>～する</b> adipiscor(<i>dep</i>), potior(<i>dep</i>), obtineo, impetro, fero, consequor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://得る\">得る</a>.</div>\r\n","<div class=\"hw jl\">獲物</div><div class=\"def\">(狩りの)venatio, praeda.</div>\r\n","<div class=\"hw jl\">玄関</div><div class=\"def\">vestibulum, ostium.</div>\r\n","<div class=\"hw jl\">率</div><div class=\"def\">(=割合)ratio.</div>\r\n","<div class=\"hw jl\">率いる</div><div class=\"def\">(=引率する)duco, deduco.</div><div class=\"def\">⇒<a href=\"entry://指揮\">指揮</a>.</div>\r\n","<div class=\"hw jl\">率直</div><div class=\"def\">libertas.</div><div class=\"def\">▼<b>～な</b> liber, explicatus.</div><div class=\"def\">▼<b>～に</b> libere, prorsum.</div>\r\n","<div class=\"hw jl\">王</div><div class=\"def\">rex.</div><div class=\"def\">▼<b>～の</b> regius.</div><div class=\"def\">▼<b>～である, ～として支配する</b> regno.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">女王<span class=\"ext\">regina.</span></div><div class=\"cf\">王位, 王権<span class=\"ext\">regnum.</span></div>\r\n","<div class=\"hw jl\">王国</div><div class=\"def\">regnum.</div>\r\n","<div class=\"hw jl\">王女</div><div class=\"def\">regis filia.</div>\r\n","<div class=\"hw jl\">王子</div><div class=\"def\">(=王の息子)regis filius, regulus.</div><div class=\"def\">⇒<a href=\"entry://皇太子\">皇太子</a>.</div>\r\n","<div class=\"hw jl\">王宮</div><div class=\"def\">regia.</div>\r\n","<div class=\"hw jl\">王朝</div><div class=\"def\">dynastia.</div>\r\n","<div class=\"hw jl\">珍しい</div><div class=\"def\">(=まれな)rarus, infrequens;(=奇異な, 特異な)insolitus, inusitatus, singularis.</div>\r\n","<div class=\"hw jl\">現に</div><div class=\"def\">⇒<a href=\"entry://実際\">実際</a>.</div>\r\n","<div class=\"hw jl\">現われる</div><div class=\"def\">appareo, prodeo.</div>\r\n","<div class=\"hw jl\">現世</div><div class=\"def\">▼<b>～の</b> terrestris.</div>\r\n","<div class=\"hw jl\">現代</div><div class=\"def\">⇒<a href=\"entry://現在\">現在</a>,<a href=\"entry://近代\">近代</a>,<a href=\"entry://古代\">古代</a>.</div>\r\n","<div class=\"hw jl\">現在</div><div class=\"def\"><span class=\"pos3\">[名]</span> praesens(tempus), praesentia.</div><div class=\"def\">━<span class=\"pos3\">[副]</span>(=今)nunc, in praesenti, in praesentia.</div><div class=\"def\">▼<b>～の</b> praesens.</div>\r\n","<div class=\"hw jl\">現地</div><div class=\"def\">▼<b>～の</b>(=ある土地の, その土地の)(alicujus [hujus])loci [regionis].</div><div class=\"def\">▼<b>～人</b> aborigines(<i>pl</i>), indigena, autochthon.</div>\r\n","<div class=\"hw jl\">現場</div><div class=\"def\">▼<b>～に行く</b> in rem praesentem venio.</div><div class=\"ex2\">彼は～にいた<span class=\"ext\">aderat praesens.</span></div>\r\n","<div class=\"hw jl\">現実</div><div class=\"def\">veritas, res vera.</div><div class=\"def\">⇒<a href=\"entry://事実\">事実</a>,<a href=\"entry://真実\">真実</a>.</div>\r\n","<div class=\"hw jl\">現役</div><div class=\"def\">▼<b>～である</b> munus obeo.</div>\r\n","<div class=\"hw jl\">現状</div><div class=\"def\">⇒<a href=\"entry://状態\">状態</a>.</div>\r\n","<div class=\"hw jl\">現行</div><div class=\"def\">▼<b>～の</b> praesens, qui nunc est, non obsoletus.</div>\r\n","<div class=\"hw jl\">現象</div><div class=\"def\">(=自然現象やできごと)res.</div><div class=\"ex2\">この～の原因<span class=\"ext\">hujus rei causa.</span></div><div class=\"ex2\">天体の～<span class=\"ext\">phaenomena(<i>pl</i>).</span></div><div class=\"ex2\">奇怪な～<span class=\"ext\">prodigium.</span></div>\r\n","<div class=\"hw jl\">現金</div><div class=\"def\">pecunia praesens [numerata, expedita], praesentes nummi(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> numeratus.</div><div class=\"def\">▼<b>～で</b> in nummo.</div><div class=\"def\">▼<b>～払い</b> repraesentatio.</div><div class=\"def\">▼(...に)<b>～で支払う</b> in pecunia 〈alci〉 satisfacio, pecuniam 〈alci〉 numero, repraesento.</div><div class=\"def\">⇒<a href=\"entry://金\">金<SUB>かね</SUB></a>.</div>\r\n","<div class=\"hw jl\">球技</div><div class=\"def\">ludus pilae [follis].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">クリケット<span class=\"ext\">ludus pilae et portae.</span></div><div class=\"cf\">ゴルフ<span class=\"ext\">pilae malleique ludus, pilamalleus.</span></div><div class=\"cf\">サッカー<span class=\"ext\">pediludium, pilae et pedumque ludus, folliludium.</span></div><div class=\"cf\">テニス<span class=\"ext\">manubriati reticuli ludus.</span></div><div class=\"cf\">バレーボール<span class=\"ext\">ludus pilae volaticae.</span></div><div class=\"cf\">バスケットボール<span class=\"ext\">pilae canistrique ludus, follis canistrique ludus.</span></div><div class=\"cf\">野球<span class=\"ext\">ludus pilae et basium, ludus basipilae.</span></div><div class=\"cf\">ラグビー<span class=\"ext\">ludus follis ovati.</span></div>\r\n","<div class=\"hw jl\">理屈</div><div class=\"def\">(=道理, 理論, 論証)ratio, ratiocinatio, argumentatio.</div><div class=\"def\">⇒<a href=\"entry://詭弁\">詭弁</a>,<a href=\"entry://理論\">理論</a>.</div>\r\n","<div class=\"hw jl\">理性</div><div class=\"def\">ratio.</div><div class=\"def\">▼<b>～的な</b> rationalis.</div><div class=\"def\">▼<b>～を備えた</b> ratione praeditus, rationis particeps.</div><div class=\"def\">▼<b>～を持たない</b> rationis expers.</div><div class=\"ex2\">人間には～が備わっているので物事の理由が分かる<span class=\"ext\">homo, quod rationis est particeps, causas rerum videt.</span></div><div class=\"def\">⇒<a href=\"entry://道理\">道理</a>.</div>\r\n","<div class=\"hw jl\">理想</div><div class=\"def\">(=考えうる限り最高の形)species eximia quaedam, imago perfectissima, perfecta et optima species.</div><div class=\"def\">▼<b>～的な</b>(=最高の, 完全な)optimus, summus, perfectissimus;(=事実ではなく想像や考えに基づく)animo comprehensus, in animo informatus.</div><div class=\"def\">⇒<a href=\"entry://空想\">空想</a>.</div>\r\n","<div class=\"hw jl\">理由</div><div class=\"def\">causa.</div><div class=\"ex2\">あなたには私に対して怒る～は何もない<span class=\"ext\">nullam habes causam irascendi mihi.</span></div>\r\n","<div class=\"hw jl\">理解</div><div class=\"def\">intellectus.</div><div class=\"def\">▼<b>～力</b> intellegentia.</div><div class=\"def\">▼<b>～力のある</b> intellegens.</div><div class=\"def\">▼<b>～する</b> intellego, (animo)percipio, teneo, capio, (animo)assequor(<i>dep</i>), mente complector(<i>dep</i>)[comprehendo].</div>\r\n","<div class=\"hw jl\">理論</div><div class=\"def\">ratio, ars, doctrina, theoria.</div><div class=\"def\">▼<b>～的な</b> rationalis, doctrinalis, theoreticus.</div><div class=\"ex2\">～と実践<span class=\"ext\">ratio atque usus.</span></div>\r\n","<div class=\"hw jl\">理髪</div><div class=\"def\">tonsus.</div><div class=\"def\">▼<b>～業</b> tonstrinum.</div><div class=\"def\">▼<b>～師</b> tonsor(<i>m</i>), tonstrix(<i>f</i>).</div><div class=\"def\">▼<b>～店</b> tonstrina.</div><div class=\"def\">▼<b>～師の</b> tonsorius.</div>\r\n","<div class=\"hw jl\">琴</div><div class=\"def\">(竪琴)cithara, lyra, barbitos.</div>\r\n","<div class=\"hw jl\">環境</div><div class=\"def\">locus, res externae(<i>pl</i>), circumjectus, vitae condicio, mundus ambiens, ambitus, quae nobis cirsumstant(<i>pl</i>).</div><div class=\"def\">▼<b>自然～</b> circumjacentia naturae loca(<i>pl</i>), natura circumjecta.</div><div class=\"def\">▼<b>～汚染</b> circumjacentiorum inquinatio.</div>\r\n","<div class=\"hw jl\">瓶</div><div class=\"def\">lagena, ampulla.</div><div class=\"def\">▼<b>小さな～</b> laguncula, ampullula.</div>\r\n","<div class=\"hw jl\">甘い</div><div class=\"def\">dulcis, suavis;(蜂蜜のように)mulsus.</div>\r\n","<div class=\"hw jl\">甘やかす</div><div class=\"def\">(nimium)indulgeo.</div><div class=\"ex2\">自分を～人たち<span class=\"ext\">sibi indulgentes.</span></div><div class=\"ex2\">(子供を)甘やかしてだめにする<span class=\"ext\">deliciis solvo.</span></div>\r\n","<div class=\"hw jl\">生</div><div class=\"def\">(=人生, 命)vita.</div>\r\n","<div class=\"hw jl\">生</div><div class=\"def\">▼<b>～の</b> crudus.</div><div class=\"def\">▼<b>半～の</b> semicrudus.</div><div class=\"def\">▼<b>～卵</b> crudum ovum.</div>\r\n","<div class=\"hw jl\">生える</div><div class=\"def\">(植物等が)nascor(<i>dep</i>), enascor(<i>dep</i>), cresco, prodeo.</div>\r\n","<div class=\"hw jl\">生かす・活かす</div><div class=\"def\">(=食物を与え維持する, 養う)alo, pasco, sustineo, sustento;(=命を救う)servo, conservo;(=活用する)⇒ <a href=\"entry://利用\">利用</a>.</div>\r\n","<div class=\"hw jl\">生きいき</div><div class=\"def\">▼<b>～とした</b> vivus, vividus.</div>\r\n","<div class=\"hw jl\">生きる</div><div class=\"def\">vivo.</div><div class=\"def\">▼<b>生きている</b><span class=\"pos3\">[動]</span> existo. <span class=\"pos3\">[形]</span> vivus.</div><div class=\"ex2\">～理由<span class=\"ext\">vivendi causa.</span></div><div class=\"ex2\">生き方<span class=\"ext\">via vivendi.</span></div>\r\n","<div class=\"hw jl\">生き残る</div><div class=\"def\">supersto, supersum.</div><div class=\"def\">▼<b>生き残った</b> superstes.</div><div class=\"def\">▼<b>生き残り</b> superstes.</div>\r\n","<div class=\"hw jl\">生き返る</div><div class=\"def\">(=よみがえる)resurgo 〈a [ex] mortuis;ab inferis〉, revivisco.</div>\r\n","<div class=\"hw jl\">生まれ</div><div class=\"def\">ortus, genus.</div><div class=\"ex2\">高貴な～の<span class=\"ext\">natus nobili genere.</span></div>\r\n","<div class=\"hw jl\">生まれつき</div><div class=\"def\">naturā.</div>\r\n","<div class=\"hw jl\">生まれる</div><div class=\"def\">nascor(<i>dep</i>), orior(<i>dep</i>), gignor(<i>pass</i>), in lucem prodeo.</div><div class=\"def\">▼<b>生まれた</b> natus.</div><div class=\"ex2\">愛は目から生まれて胸に落ちる<span class=\"ext\">amor ex oculis oriens in pectus cadit.</span></div>\r\n","<div class=\"hw jl\">生む・産む</div><div class=\"def\">(母が子を)pario;(双子を)geminum partum edo, uno partu edo;(男が)(=父となる)gigno.</div><div class=\"ex2\">子供を～<span class=\"ext\">partum enitor(<i>dep</i>)/ partum edo.</span></div>\r\n","<div class=\"hw jl\">生命</div><div class=\"def\">vita, anima.</div><div class=\"def\">⇒<a href=\"entry://命\">命</a>.</div>\r\n","<div class=\"hw jl\">生命工学</div><div class=\"def\">biotechnologia.</div>\r\n","<div class=\"hw jl\">生存</div><div class=\"def\">▼<b>～する</b>(=生きている)vivo;(=生き残る)supersum.</div><div class=\"def\">▼<b>～している</b>(=生き残っている)<span class=\"pos3\">[形]</span> superstes.</div><div class=\"def\">▼<b>～者</b> superstes.</div><div class=\"def\">⇒<a href=\"entry://生きる\">生きる</a>.</div>\r\n","<div class=\"hw jl\">生徒</div><div class=\"def\">discipulus(<i>m</i>), discipula(<i>f</i>).</div>\r\n","<div class=\"hw jl\">生得</div><div class=\"def\">⇒<a href=\"entry://先天的\">先天的</a>.</div>\r\n","<div class=\"hw jl\">生態学</div><div class=\"def\">(=エコロジー)oecologia, res oecologica.</div>\r\n","<div class=\"hw jl\">生殖</div><div class=\"def\">procreatio, genitura.</div>\r\n","<div class=\"hw jl\">生活</div><div class=\"def\">vita.</div><div class=\"def\">▼<b>～手段</b> victum.</div>\r\n","<div class=\"hw jl\">生涯</div><div class=\"def\">vita.</div><div class=\"ex2\">～において<span class=\"ext\">in vita.</span></div><div class=\"ex2\">彼は幸福な～を生きた<span class=\"ext\">vitam fortunatam vixit.</span></div>\r\n","<div class=\"hw jl\">生物</div><div class=\"def\">animal, animans.</div><div class=\"def\">▼<b>～の</b> animalis.</div>\r\n","<div class=\"hw jl\">生物学</div><div class=\"def\">biologia, de vitae ratione doctrina, de animantium vita disciplina.</div><div class=\"def\">▼<b>～者</b> biologus, de vitae ratione peritus.</div><div class=\"def\">▼<b>～の, ～的な</b> biologicus, ad biologiam pertinens.</div>\r\n","<div class=\"hw jl\">生理</div><div class=\"def\">⇒<a href=\"entry://月経\">月経</a>.</div>\r\n","<div class=\"hw jl\">生産</div><div class=\"def\">fructus.</div><div class=\"def\">▼<b>農業～</b> proventus agrorum.</div><div class=\"def\">▼<b>～する</b> efficio.</div><div class=\"def\">⇒<a href=\"entry://製造\">製造</a>.</div>\r\n","<div class=\"hw jl\">生簀</div><div class=\"def\">(=養殖池)piscina, vivarium.</div>\r\n","<div class=\"hw jl\">産業</div><div class=\"def\">quaestuosa industria.</div><div class=\"def\">⇒<a href=\"entry://工業\">工業</a>.</div>\r\n","<div class=\"hw jl\">産物</div><div class=\"def\">fructus, ea quae giguntur e terra.</div>\r\n","<div class=\"hw jl\">甥</div><div class=\"def\">(=兄弟の息子)fratris filius;(=姉妹の息子)sororis filius.</div>\r\n","<div class=\"hw jl\">用事</div><div class=\"def\">res, negotium, occupatio.</div>\r\n","<div class=\"hw jl\">用件</div><div class=\"def\">res, negotium.</div>\r\n","<div class=\"hw jl\">用心</div><div class=\"def\">cautio, provisio.</div><div class=\"def\">▼<b>～する</b> caveo, provideo.</div><div class=\"def\">⇒<a href=\"entry://警戒\">警戒</a>,<a href=\"entry://注意\">注意</a>.</div>\r\n","<div class=\"hw jl\">用意</div><div class=\"def\">praeparatio, comparatio.</div><div class=\"def\">▼<b>～する</b> praeparo, paro, comparo.</div><div class=\"def\">▼(...のために)<b> ～ができている</b> praeparatus, paratus 〈ad alqd〉.</div>\r\n","<div class=\"hw jl\">用語</div><div class=\"def\">(=ある分野に特有の語, 術語)propria verba 〈alcis rei〉(<i>pl</i>), propria vocabula 〈alcis rei〉(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://術語\">術語</a>.</div>\r\n","<div class=\"hw jl\">用途</div><div class=\"def\">(=使いみち)usus, utilitas.</div><div class=\"def\">⇒<a href=\"entry://使用\">使用</a>,<a href=\"entry://利用\">利用</a>.</div>\r\n","<div class=\"hw jl\">田園</div><div class=\"def\">⇒<a href=\"entry://田舎\">田舎</a>.</div>\r\n","<div class=\"hw jl\">田舎</div><div class=\"def\">rus, agri(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> rusticus, agrestis.</div><div class=\"def\">▼<b>～で</b> ruri.</div><div class=\"def\">▼<b>～風</b> rusticitas.</div><div class=\"def\">▼<b>～風に</b> rustice.</div><div class=\"ex2\">～暮らし<span class=\"ext\">rusticatio.</span></div><div class=\"ex2\">～暮らしをする<span class=\"ext\">rusticor(<i>dep</i>).</span></div>\r\n","<div class=\"hw jl\">甲</div><div class=\"def\">(亀の)testa.</div>\r\n","<div class=\"hw jl\">申し出る</div><div class=\"def\">se offerre(← offero), profiteor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">申し込み</div><div class=\"def\">inscriptio.</div>\r\n","<div class=\"hw jl\">申告</div><div class=\"def\">▼<b>～する</b> dedico, profiteor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">男</div><div class=\"def\">vir, mas.</div><div class=\"def\">▼<b>～らしさ</b> virilitas, virtus.</div><div class=\"def\">▼<b>～の</b> virilis, mas, masculinus, masculus.</div>\r\n","<div class=\"hw jl\">男性</div><div class=\"def\">vir, mas.</div><div class=\"def\">▼<b>～の</b> virilis, mas, masculus, masculinus.</div><div class=\"def\">⇒<a href=\"entry://男\">男</a>,<a href=\"entry://女\">女</a>,<a href=\"entry://女性\">女性</a>.</div>\r\n","<div class=\"hw jl\">男根</div><div class=\"def\">penis, cauda.</div>\r\n","<div class=\"hw jl\">町・街</div><div class=\"def\">oppidum, urbs;(小さな)oppidulum;(=都市の一部)regio.</div><div class=\"def\">⇒<a href=\"entry://都市\">都市</a>.</div>\r\n","<div class=\"hw jl\">画家</div><div class=\"def\">pictor.</div><div class=\"def\">⇒<a href=\"entry://絵\">絵</a>.</div>\r\n","<div class=\"hw jl\">画廊</div><div class=\"def\">pinacotheca.</div>\r\n","<div class=\"hw jl\">畑</div><div class=\"def\">(=耕地)ager, seges, arvum.</div><div class=\"def\">▼<b>～の</b> agrestis.</div>\r\n","<div class=\"hw jl\">留まる</div><div class=\"def\">maneo, commoror(<i>dep</i>);(=後に残る)remaneo.</div>\r\n","<div class=\"hw jl\">留保</div><div class=\"def\">retentio.</div>\r\n","<div class=\"hw jl\">留守</div><div class=\"def\">absentia.</div><div class=\"def\">▼<b>～の</b> absens.</div><div class=\"def\">▼<b>～にする</b> absum.</div>\r\n","<div class=\"hw jl\">略奪</div><div class=\"def\">direptio, rapina, spoliatio, vastatio, populatio.</div><div class=\"def\">▼<b>～物</b> praeda, spolia(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b> diripio, expilo, spolio, exspolio, devasto, populo.</div><div class=\"def\">⇒<a href=\"entry://誘拐\">誘拐</a>.</div>\r\n","<div class=\"hw jl\">番</div><div class=\"def\">(=順番)locus, ordo;(=見張り)custodia.</div><div class=\"def\">▼<b>～をする</b>(=見張る)custodio, advigilo.</div><div class=\"def\">▼<b>1～</b>(=第1位)primus locus.</div><div class=\"def\">▼<b>何～目の</b> quotus.</div><div class=\"ex2\">(順番を待っている人に向かって)あなたの～ですよ<span class=\"ext\">ordo te vocat.</span></div><div class=\"ex2\">今度はきみが話す～だ<span class=\"ext\">nunc tibi loquendum est.</span></div>\r\n","<div class=\"hw jl\">番号</div><div class=\"def\">numerus.</div>\r\n","<div class=\"hw jl\">番組</div><div class=\"def\">▼<b>テレビ～</b> spectaculum televisificum.</div><div class=\"def\">▼<b>テレビ～一覧</b> spectaculorum televisificorum index.</div>\r\n","<div class=\"hw jl\">異なる</div><div class=\"def\">(=異なった)dissimilis, dispar.</div><div class=\"def\">▼<b>相～</b> diversus.</div><div class=\"ex2\">人間と獣が非常に～のは以下の点である<span class=\"ext\">inter hominem et beluam hoc maxime interest quod(...).</span></div><div class=\"def\">⇒<a href=\"entry://違う\">違う</a>.</div>\r\n","<div class=\"hw jl\">異常</div><div class=\"def\">insolentia.</div><div class=\"def\">▼<b>～な</b> insolitus, insolens, enormis.</div><div class=\"def\">▼<b>～に</b> insolenter.</div>\r\n","<div class=\"hw jl\">異民族</div><div class=\"def\">externae gentes [nationes], aliae gentes [nationes];(ギリシア・ローマ以外の)barbari(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://外国人\">外国人</a>.</div>\r\n","<div class=\"hw jl\">異端</div><div class=\"def\">haeresis.</div><div class=\"def\">▼<b>～の</b> haereticus.</div>\r\n","<div class=\"hw jl\">異議</div><div class=\"def\">recusatio.</div><div class=\"def\">▼<b>～を唱える</b> recuso.</div><div class=\"def\">⇒<a href=\"entry://反論\">反論</a>.</div>\r\n","<div class=\"hw jl\">疑う</div><div class=\"def\">dubito, suspicor(<i>dep</i>), suspecto.</div><div class=\"def\">▼<b>疑わしい</b> dubius, incertus, suspiciosus, anceps.</div><div class=\"def\">▼<b>疑い</b> dubium, dubitatio, suspicio.</div><div class=\"ex2\">疑いもなく<span class=\"ext\">sine dubio.</span></div><div class=\"ex2\">(...ことを)誰が～だろうか<span class=\"ext\">quis dubitet quin ....</span></div><div class=\"ex2\">私は(...ことを)全く疑わない<span class=\"ext\">haud dubito quin ....</span></div><div class=\"ex2\">～余地がない(=確実に知っている)<span class=\"ext\">certo scio.</span></div><div class=\"ex2\">(...ことは)疑いない<span class=\"ext\">non dubium est quin ....</span></div><div class=\"def\">⇒<a href=\"entry://疑惑\">疑惑</a>,<a href=\"entry://不確か\">不確か</a>.</div>\r\n","<div class=\"hw jl\">疑問</div><div class=\"def\">(=疑うこと)dubitatio;(=疑わしいこと)dubium, incertum.</div><div class=\"def\">⇒<a href=\"entry://疑う\">疑う</a>,<a href=\"entry://質問\">質問</a>,<a href=\"entry://問題\">問題</a>.</div>\r\n","<div class=\"hw jl\">疑惑</div><div class=\"def\">(=疑い)suspicio.</div><div class=\"def\">▼(...に)<b>～をもつ</b>(=疑う)suspicor(<i>dep</i>), 〈alqm〉 suspectum habeo.</div><div class=\"def\">⇒<a href=\"entry://疑う\">疑う</a>.</div>\r\n","<div class=\"hw jl\">疲れる</div><div class=\"def\">se defatigare(← defatigo), fatigor(<i>pass</i>), fatiscor(<i>dep</i>), defatigor(<i>pass</i>), defetiscor(<i>dep</i>).</div><div class=\"def\">▼(...で)<b> 疲れた</b> 〈re〉 fessus, defessus, fatigatus, defatigatus, lassus.</div><div class=\"def\">▼<b>疲れさせる</b> lasso, fatigo, defatigo, delasso.</div><div class=\"def\">▼<b>疲れ</b> lassitudo, fatigatio, defatigatio.</div>\r\n","<div class=\"hw jl\">病人</div><div class=\"def\">aeger(<i>m</i>), aegrotus(<i>m</i>).</div>\r\n","<div class=\"hw jl\">病気</div><div class=\"def\">morbus, aegritudo;(=不健康)valetudo.</div><div class=\"def\">▼<b>～の</b> aeger, aegrotus.</div><div class=\"def\">▼<b>～になる</b> aegresco, morbo afficior(<i>pass</i>).</div><div class=\"def\">▼<b>～である</b> aegroto.</div>\r\n","<div class=\"hw jl\">病院</div><div class=\"def\">valetudinarium, nosocomium.</div>\r\n","<div class=\"hw jl\">症状</div><div class=\"def\">signum.</div>\r\n","<div class=\"hw jl\">痙攣</div><div class=\"def\">convulsio, spasmus.</div><div class=\"def\">▼<b>～する</b> spasmo vexor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">痛い</div><div class=\"def\"><span class=\"pos3\">[動]</span> doleo, habeo dolorem.</div><div class=\"ex2\">目が～<span class=\"ext\">doleo ab oculis.</span></div><div class=\"ex2\">体が～<span class=\"ext\">corpore doleo.</span></div><div class=\"ex2\">頭が～<span class=\"ext\">habeo capitis dolorem.</span></div><div class=\"ex2\">私は足が～<span class=\"ext\">dolet mihi pes.</span></div>\r\n","<div class=\"hw jl\">痛ましい</div><div class=\"def\">flebilis, lugubris, luctuosus, lamentabilis.</div>\r\n","<div class=\"hw jl\">痛み</div><div class=\"def\">(体の)dolor.</div><div class=\"def\">⇒<a href=\"entry://痛い\">痛い</a>,<a href=\"entry://苦痛\">苦痛</a>.</div>\r\n","<div class=\"hw jl\">癌</div><div class=\"def\">cancer.</div><div class=\"ex2\">肺～で死ぬ<span class=\"ext\">cancro pulmonis morior(<i>dep</i>).</span></div>\r\n","<div class=\"hw jl\">癒しがたい</div><div class=\"def\">insanabilis.</div>\r\n","<div class=\"hw jl\">癒す</div><div class=\"def\">sano.</div><div class=\"def\">⇒<a href=\"entry://慰める\">慰める</a>,<a href=\"entry://慰安\">慰安</a>,<a href=\"entry://治療\">治療</a>.</div>\r\n","<div class=\"hw jl\">癖</div><div class=\"def\">(=性癖, 性向)(animi)inclinatio, proclivitas, indoles.</div><div class=\"ex2\">嘘をつく～<span class=\"ext\">fallendi studium.</span></div><div class=\"def\">⇒<a href=\"entry://習慣\">習慣</a>,<a href=\"entry://傾向\">傾向</a>.</div>\r\n","<div class=\"hw jl\">発つ</div><div class=\"def\">⇒<a href=\"entry://出発\">出発</a>,<a href=\"entry://立ち去る\">立ち去る</a>.</div>\r\n","<div class=\"hw jl\">発作</div><div class=\"def\">(病気や怒りの)impetus, accessio, impulsus.</div>\r\n","<div class=\"hw jl\">発射</div><div class=\"def\">missus, jactus.</div><div class=\"def\">▼<b>～する</b> mitto, jacio, eicio.</div><div class=\"def\">▼<b>～される</b><span class=\"pos3\">[形]</span> missilis.</div>\r\n","<div class=\"hw jl\">発展</div><div class=\"def\">expansio, progressio, progressus.</div><div class=\"def\">▼<b>～させる</b> expando.</div><div class=\"def\">▼<b>～する</b> progredior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://発達\">発達</a>.</div>\r\n","<div class=\"hw jl\">発掘</div><div class=\"def\">fossio, fossura, suffossio.</div><div class=\"def\">▼<b>～する</b> fodio, rimor(<i>dep</i>), suffodio.</div><div class=\"def\">▼<b>～された</b> fossilis.</div>\r\n","<div class=\"hw jl\">発明</div><div class=\"def\">excogitatio, inventio, commentum, repertum, inventum.</div><div class=\"def\">▼<b>～する</b> excogito, invenio, reperio.</div><div class=\"def\">▼<b>～者</b> inventor(<i>m</i>), inventrix(<i>f</i>).</div>\r\n","<div class=\"hw jl\">発生</div><div class=\"def\">▼<b>～する</b> fio, evenio, exsisto.</div><div class=\"def\">⇒<a href=\"entry://できごと\">できごと</a>.</div>\r\n","<div class=\"hw jl\">発育</div><div class=\"def\">auctus, incrementum.</div><div class=\"def\">▼<b>～する</b> cresco, adolesco.</div><div class=\"ex2\">身体の～<span class=\"ext\">corporis auctus.</span></div><div class=\"def\">⇒<a href=\"entry://成長\">成長</a>.</div>\r\n","<div class=\"hw jl\">発行</div><div class=\"def\">editio.</div><div class=\"def\">▼<b>～する</b> edo;(=刊行する)publico.</div>\r\n","<div class=\"hw jl\">発表</div><div class=\"def\">denuntiatio, nuntiatio, divulgatio.</div><div class=\"def\">▼<b>～する</b> denuntio, nuntio, divulgo.</div><div class=\"def\">⇒<a href=\"entry://布告\">布告</a>.</div>\r\n","<div class=\"hw jl\">発見</div><div class=\"def\">inventio, inventus, inventum.</div><div class=\"def\">▼<b>～者</b> inventor(<i>m</i>), inventrix(<i>f</i>).</div><div class=\"def\">▼<b>～する</b> invenio, reperio.</div>\r\n","<div class=\"hw jl\">発言</div><div class=\"def\">ditio, dictum, sermo.</div><div class=\"def\">▼<b>～する</b> dico.</div>\r\n","<div class=\"hw jl\">発話</div><div class=\"def\">vox.</div><div class=\"def\">▼<b>～する</b> vocem mitto.</div>\r\n","<div class=\"hw jl\">発車</div><div class=\"def\">(=列車や車の出発)abitus, profectio.</div>\r\n","<div class=\"hw jl\">発送</div><div class=\"def\">missio, missus.</div><div class=\"def\">▼<b>～する</b> mitto.</div>\r\n","<div class=\"hw jl\">発達</div><div class=\"def\">(=増大, 成長)auctus, incrementum, progressus.</div><div class=\"def\">▼<b>～させる</b> augeo.</div><div class=\"def\">▼<b>～する</b> incresco, progredior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">発酵</div><div class=\"def\">fervor.</div><div class=\"def\">▼<b>～させる</b> fermento.</div><div class=\"def\">▼<b>～する</b> ferveo, effervesco, fermentesco.</div><div class=\"def\">⇒<a href=\"entry://酵母\">酵母</a>.</div>\r\n","<div class=\"hw jl\">発電所</div><div class=\"def\">ergasterium, electrificina.</div>\r\n","<div class=\"hw jl\">発音</div><div class=\"def\">pronuntiatio, appellatio, sonus.</div>\r\n","<div class=\"hw jl\">登山</div><div class=\"def\">montium lustratio [ascensus, escensus].</div><div class=\"def\">▼<b>～家</b> oribates(montium lustrator).</div>\r\n","<div class=\"hw jl\">登録</div><div class=\"def\">perscriptio, inscriptio.</div><div class=\"def\">▼<b>～する</b> perscribo, inscribo.</div>\r\n","<div class=\"hw jl\">白</div><div class=\"def\">(色)albus color;(=輝く白色, 純白)candidus color, candor.</div><div class=\"def\">▼<b>～い</b> albus;(髪が)canus;(=純白の)candidus.</div>\r\n","<div class=\"hw jl\">白人</div><div class=\"def\">(=金髪の男, 金髪の女)vir flavus(<i>m</i>), mulier flava(<i>f</i>).</div><div class=\"def\">▼<b>～の</b>(=金髪の)flavus.</div>\r\n","<div class=\"hw jl\">白状</div><div class=\"def\">confessio.</div><div class=\"def\">▼<b>～する</b> confiteor(<i>dep</i>), fateor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://告白\">告白</a>.</div>\r\n","<div class=\"hw jl\">白髪</div><div class=\"def\">cani crines(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> canus.</div><div class=\"def\">▼<b>～頭</b> caput canum.</div>\r\n","<div class=\"hw jl\">百</div><div class=\"def\">centum.</div>\r\n","<div class=\"hw jl\">百科事典</div><div class=\"def\">encyclopaedia, omnium doctrinarum thesaurus.</div>\r\n","<div class=\"hw jl\">百科学</div><div class=\"def\">encyclios(doctrinarum omnium)disciplina, universae doctrinae orbis, disciplinarum omnium summa [complexio, descriptio].</div>\r\n","<div class=\"hw jl\">百貨店</div><div class=\"def\">⇒<a href=\"entry://デパート\">デパート</a>,<a href=\"entry://マーケット\">マーケット</a>.</div>\r\n","<div class=\"hw jl\">的</div><div class=\"def\">(=目的)scopus, finis.</div>\r\n","<div class=\"hw jl\">的確</div><div class=\"def\">▼<b>～な</b> acutus.</div>\r\n","<div class=\"hw jl\">皇太子</div><div class=\"def\">princeps hereditarius.</div><div class=\"def\">▼<b>～妃</b> principissa hereditaria.</div><div class=\"def\">⇒<a href=\"entry://王子\">王子</a>.</div>\r\n","<div class=\"hw jl\">皇室</div><div class=\"def\">familia imperatoria.</div>\r\n","<div class=\"hw jl\">皇居</div><div class=\"def\">⇒<a href=\"entry://宮殿\">宮殿</a>.</div>\r\n","<div class=\"hw jl\">皇帝</div><div class=\"def\">imperator;(女帝)imperatrix.</div><div class=\"def\">▼<b>～の</b> imperatorius.</div>\r\n","<div class=\"hw jl\">皮肉</div><div class=\"def\">sal;(辛辣な)acerba cavillatio, acrimonia;(ソクラテス的な)ironia, dissimulantia.</div>\r\n","<div class=\"hw jl\">皮膚</div><div class=\"def\">cutis.</div>\r\n","<div class=\"hw jl\">皿</div><div class=\"def\">catinus, catinum, patina, lanx;(小さな)catillus, patella.</div>\r\n","<div class=\"hw jl\">盗む</div><div class=\"def\">furor(<i>dep</i>), subripio.</div><div class=\"def\">⇒<a href=\"entry://奪う\">奪う</a>,<a href=\"entry://強奪\">強奪</a>.</div>\r\n","<div class=\"hw jl\">盗難</div><div class=\"def\">⇒<a href=\"entry://盗む\">盗む</a>.</div>\r\n","<div class=\"hw jl\">盛り</div><div class=\"def\">▼<b>夏の～</b> caniculares dies(<i>pl</i>), aestus caniculae.</div>\r\n","<div class=\"hw jl\">盛る</div><div class=\"def\">(=積み上げる)coacervo, congero.</div><div class=\"def\">▼<b>毒を～</b>(物に)〈alqd〉 veneno inficio;(人に)〈alci〉 venenum praebeo [do].</div><div class=\"def\">⇒<a href=\"entry://毒\">毒</a>.</div>\r\n","<div class=\"hw jl\">盛大</div><div class=\"def\">⇒<a href=\"entry://ぜいたく\">ぜいたく</a>,<a href=\"entry://豪華\">豪華</a>.</div>\r\n","<div class=\"hw jl\">監査</div><div class=\"def\">recognitio, recensio, inspectio.</div><div class=\"def\">▼<b>会計～</b> calculorum [rationum] recognitio.</div><div class=\"def\">▼<b>～人</b> inspector, censor.</div><div class=\"def\">▼<b>～する</b> recognosco.</div><div class=\"def\">⇒<a href=\"entry://検査\">検査</a>.</div>\r\n","<div class=\"hw jl\">監督</div><div class=\"def\">(人)procurator, curator, magister, rector;(行為)procuratio.</div><div class=\"def\">▼<b>～する</b> procuro.</div>\r\n","<div class=\"hw jl\">監視</div><div class=\"def\">custodia.</div><div class=\"def\">▼<b>～人</b> custos.</div><div class=\"def\">▼<b>～する</b> custodio, observo, speculor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">目</div><div class=\"def\">oculus;(両方の)ambo oculi(<i>pl</i>).</div><div class=\"def\">▼<b>～玉</b> oculi globus.</div><div class=\"def\">▼<b>～が良い</b> claris oculis video.</div><div class=\"def\">▼<b>～が悪い</b> male oculatus.</div><div class=\"def\">▼<b>～をつぶす</b> oculum eruo.</div>\r\n","<div class=\"hw jl\">目つき</div><div class=\"def\">(=まなざし)oculi(<i>pl</i>), vultus, oculorum obtutus.</div>\r\n","<div class=\"hw jl\">目まい</div><div class=\"def\">vertigo.</div>\r\n","<div class=\"hw jl\">目上</div><div class=\"def\">▼<b>～の</b> superior.</div><div class=\"def\">⇒<a href=\"entry://目下\">目下</a>.</div>\r\n","<div class=\"hw jl\">目下</div><div class=\"def\">▼<b>～の</b> inferior.</div><div class=\"def\">⇒<a href=\"entry://目上\">目上</a>.</div>\r\n","<div class=\"hw jl\">目印</div><div class=\"def\">signum, nota.</div>\r\n","<div class=\"hw jl\">目指す</div><div class=\"def\">(=目標とする)destino;(=得ようと求める)peto, contendo.</div>\r\n","<div class=\"hw jl\">目撃</div><div class=\"def\">▼<b>～者</b> testis(ocularis), arbiter(<i>m</i>).</div><div class=\"def\">▼<b>～する</b> arbitror(<i>dep</i>), video, specto, cerno;(=...に居合わせる)(...を)intersum 〈alci rei〉.</div>\r\n","<div class=\"hw jl\">目的</div><div class=\"def\">finis, propositum, consilium, institutum, sententia, mens, studium, voluntas, destinatum, destinatio.</div>\r\n","<div class=\"hw jl\">目的論</div><div class=\"def\">▼<b>目的(原因)論</b> finalismus, teleologia.</div>\r\n","<div class=\"hw jl\">目立つ</div><div class=\"def\">(=際立つ, 突出する)emineo, exsto.</div>\r\n","<div class=\"hw jl\">目覚める</div><div class=\"def\">(e somno)expergiscor(<i>dep</i>), e somno suscitor(<i>pass</i>), somno solvor(<i>pass</i>), evigilo.</div>\r\n","<div class=\"hw jl\">盲目</div><div class=\"def\">caecitas.</div><div class=\"def\">▼<b>～の</b> caecus.</div><div class=\"def\">▼<b>～にする</b> caeco.</div><div class=\"def\">▼<b>～である</b> caligo.</div>\r\n","<div class=\"hw jl\">直ちに</div><div class=\"def\">ex tempore, continuo, protinus, statim, ilico, extemplo, confestim.</div><div class=\"ex2\">コッタは執政官を辞すと～ガリアへ向かった<span class=\"ext\">Cotta ex consulatu est profectus in Galliam.</span></div>\r\n","<div class=\"hw jl\">直感</div><div class=\"def\">percipiendi celeritas, celeris perceptio, sagacitas.</div>\r\n","<div class=\"hw jl\">直接</div><div class=\"def\">▼<b>～の</b> directus.</div><div class=\"def\">▼<b>～(に)</b> directo.</div>\r\n","<div class=\"hw jl\">直線</div><div class=\"def\">linea recta.</div><div class=\"def\">▼<b>～の</b> rectus.</div>\r\n","<div class=\"hw jl\">相互</div><div class=\"def\">▼<b>～の</b> mutuus.</div><div class=\"def\">▼<b>～に</b> mutuo, inter 〈+再帰・人称代名詞の <i>acc</i>〉.</div><div class=\"def\">⇒<a href=\"entry://互い\">互い</a>.</div>\r\n","<div class=\"hw jl\">相変わらず</div><div class=\"def\">(今も)etiam nunc, adhuc;(その時も)etiam tum.</div><div class=\"ex2\">きみは～だね<span class=\"ext\">ut semper tui similis es!</span></div><div class=\"def\">⇒<a href=\"entry://いつも\">いつも</a>,<a href=\"entry://常に\">常に</a>.</div>\r\n","<div class=\"hw jl\">相対的</div><div class=\"def\">▼<b>～な</b> qui ex comparatione spectatur.</div><div class=\"def\">▼<b>～に</b> comparate, ex comparatione.</div>\r\n","<div class=\"hw jl\">相性</div><div class=\"def\">(=性格の一致)morum congruentia.</div>\r\n","<div class=\"hw jl\">相手</div><div class=\"def\">(競争の)competitor, rivalis, aemulus(<i>m</i>), aemula(<i>f</i>).</div><div class=\"def\">▼<b>仕事～</b> laboris socius.</div><div class=\"def\">▼<b>遊び～</b> collusor.</div><div class=\"def\">⇒<a href=\"entry://連れ\">連れ</a>,<a href=\"entry://仲間\">仲間</a>,<a href=\"entry://道連れ\">道連れ</a>.</div>\r\n","<div class=\"hw jl\">相続</div><div class=\"def\">hereditas, successio.</div><div class=\"def\">▼<b>～人</b> heres, successor.</div><div class=\"def\">▼<b>～に関する, ～できる</b> hereditarius.</div><div class=\"def\">▼<b>～する</b> hereditatem capio [obeo].</div><div class=\"ex2\">彼は近親者から多大な遺産を～した<span class=\"ext\">hereditas a propinquo permagna ei venit.</span></div>\r\n","<div class=\"hw jl\">相談</div><div class=\"def\">consultatio, consilium.</div><div class=\"def\">▼(人に)<b> ～する</b> 〈alqm〉 consulo, consulto, 〈ab alqo〉 consilium peto.</div><div class=\"def\">⇒<a href=\"entry://討議\">討議</a>.</div>\r\n","<div class=\"hw jl\">省</div><div class=\"def\">publica sedes.</div><div class=\"ex2\">法務～<span class=\"ext\">sedes administri rei judiciariae praepositi.</span></div><div class=\"ex2\">外務～<span class=\"ext\">sedes administri exteris negotiis praepositi.</span></div>\r\n","<div class=\"hw jl\">省略</div><div class=\"def\">praetermissio.</div><div class=\"def\">▼<b>～記号</b> notae(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b> praetermitto.</div><div class=\"def\">⇒<a href=\"entry://縮める\">縮める</a>,<a href=\"entry://短縮\">短縮</a>.</div>\r\n","<div class=\"hw jl\">眉</div><div class=\"def\">supercilium.</div><div class=\"def\">▼<b>～をしかめる</b>(=額にしわを寄せる)supercilia [frontem] contraho.</div>\r\n","<div class=\"hw jl\">看板</div><div class=\"def\">signum.</div>\r\n","<div class=\"hw jl\">看病</div><div class=\"def\">aegrotum curatio, assidentis ministrae curatio.</div><div class=\"def\">⇒<a href=\"entry://看護\">看護</a>.</div>\r\n","<div class=\"hw jl\">看護</div><div class=\"def\">nutricium.</div><div class=\"def\">▼<b>～人</b> aegrorum minister.</div><div class=\"def\">▼<b>～婦</b> aegrorum minstra.</div><div class=\"def\">⇒<a href=\"entry://看病\">看病</a>.</div>\r\n","<div class=\"hw jl\">真ん中</div><div class=\"def\">▼<b>～の</b>(=中心の)medius, centralis.</div>\r\n","<div class=\"hw jl\">真似</div><div class=\"def\">imitatio.</div><div class=\"def\">▼(...の)<b>～をして</b>(=倣って)〈+<i>gen</i>〉 exemplo, ad exemplar.</div><div class=\"def\">▼<b>～する</b> imitor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">真剣</div><div class=\"def\">▼<b>～な</b> serius, intentus, enixus.</div><div class=\"def\">▼<b>～に</b> intente, enixe.</div>\r\n","<div class=\"hw jl\">真実</div><div class=\"def\">veritas, verum.</div><div class=\"def\">▼<b>～の</b> verus.</div><div class=\"def\">▼<b>～らしい</b> veri [vero] similis.</div><div class=\"def\">▼<b>～らしさ</b> verisimilitudo.</div>\r\n","<div class=\"hw jl\">真珠</div><div class=\"def\">margarita;(単独の大きな)unio.</div>\r\n","<div class=\"hw jl\">真理</div><div class=\"def\">veritas, verum.</div>\r\n","<div class=\"hw jl\">眠い</div><div class=\"def\">somni indigeo;(=眠気を催す)dormito.</div><div class=\"def\">▼<b>眠そうな</b> somniculosus.</div><div class=\"def\">▼<b>眠そうに</b> somniculose.</div>\r\n","<div class=\"hw jl\">眠る</div><div class=\"def\">(=睡眠を取る)dormio, somnum capio;(=熟睡する)condormio.</div><div class=\"def\">▼<b>眠り</b> somnus, sopor.</div><div class=\"def\">⇒<a href=\"entry://寝かす\">寝かす</a>.</div>\r\n","<div class=\"hw jl\">眠気</div><div class=\"def\">somni cupido, somnus.</div><div class=\"def\">▼<b>～に耐える</b> somnum teneo.</div>\r\n","<div class=\"hw jl\">眺める</div><div class=\"def\">prospicio, prospecto.</div><div class=\"def\">▼<b>眺め</b>(=眺望)prospectus.</div><div class=\"def\">⇒<a href=\"entry://見晴らし\">見晴らし</a>.</div>\r\n","<div class=\"hw jl\">着く</div><div class=\"def\">pervenio, pervehor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://到着\">到着</a>.</div>\r\n","<div class=\"hw jl\">着せる</div><div class=\"def\">vestio, induo, operio.</div><div class=\"def\">⇒<a href=\"entry://着る\">着る</a>.</div>\r\n","<div class=\"hw jl\">着る</div><div class=\"def\">(着物を)(vestem)induor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://着せる\">着せる</a>,<a href=\"entry://脱ぐ\">脱ぐ</a>.</div>\r\n","<div class=\"hw jl\">着手</div><div class=\"def\">ingressio, ingressus.</div><div class=\"def\">▼<b>～する</b> incipio, ingredior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">着陸</div><div class=\"def\">(飛行機の)aeroplanorum [aeronavium] appulsus, aeroplanorum descensus ad terram.</div>\r\n","<div class=\"hw jl\">睡眠</div><div class=\"def\">somnus, sopor.</div><div class=\"def\">▼<b>～薬</b> medicamentum somnificum.</div><div class=\"def\">⇒<a href=\"entry://眠る\">眠る</a>.</div>\r\n","<div class=\"hw jl\">瞑想</div><div class=\"def\">meditatio, cogitatio.</div><div class=\"def\">⇒<a href=\"entry://熟慮\">熟慮</a>.</div>\r\n","<div class=\"hw jl\">瞬き</div><div class=\"def\">nictatio, nictus.</div><div class=\"def\">▼<b>～をする</b> nicto, nictor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">瞬間</div><div class=\"def\">(temporis)punctum [momentum, vestigium].</div><div class=\"def\">⇒<a href=\"entry://一瞬\">一瞬</a>.</div>\r\n","<div class=\"hw jl\">瞳</div><div class=\"def\">pupula, pupilla, acies.</div>\r\n","<div class=\"hw jl\">矛盾</div><div class=\"def\">repugnantia, discrepantia, dissensio, contradictio.</div><div class=\"def\">▼<b>～する</b> repugno, discrepo, dissentio.</div>\r\n","<div class=\"hw jl\">矢</div><div class=\"def\">sagitta.</div><div class=\"def\">▼<b>小さな～</b> sagittula.</div><div class=\"def\">▼<b>～を射る</b> sagitto, sagittam conjicio [emitto].</div>\r\n","<div class=\"hw jl\">知らせる</div><div class=\"def\">nuntio, renuntio, affero, 〈alqm〉 certiorem facio, nuntium perfero.</div><div class=\"def\">▼<b>知らせ</b> nuntius.</div><div class=\"ex2\">これらのことがイタリアへとカエサルに知らされると<span class=\"ext\">his rebus in Italiam Caesari nuntiatis.</span></div>\r\n","<div class=\"hw jl\">知りあい</div><div class=\"def\">▼(...と)<b>～になる</b> 〈alqm〉 nosco, 〈cum alqo〉 consuetudinem jungo.</div>\r\n","<div class=\"hw jl\">知る</div><div class=\"def\">cognosco, nosco, comperio.</div><div class=\"def\">▼<b>知っている</b> scio, novi.</div><div class=\"def\">▼<b>知られている</b> notus.</div><div class=\"def\">▼<b>知らない</b> nescio.</div><div class=\"ex2\">ラテン語を知っている<span class=\"ext\">Latine(loqui)scio.</span></div><div class=\"ex2\">(...は)よく知られている<span class=\"ext\">satis notum est 〈+<i>inf</i>〉.</span></div><div class=\"ex2\">われわれは何一つ確実なことを知らないので<span class=\"ext\">quod nihil nobis constat.</span></div>\r\n","<div class=\"hw jl\">知事</div><div class=\"def\">(regionis)praefectus [gubernator].</div>\r\n","<div class=\"hw jl\">知人</div><div class=\"def\">notus(<i>m</i>).</div>\r\n","<div class=\"hw jl\">知性</div><div class=\"def\">mens, intellectus.</div>\r\n","<div class=\"hw jl\">知恵</div><div class=\"def\">sapientia, prudentia.</div><div class=\"def\">▼<b>～者</b> sapiens.</div><div class=\"def\">▼(深い)<b>～を持った</b> sapiens.</div><div class=\"def\">▼<b>～がある</b> sapio.</div><div class=\"def\">⇒<a href=\"entry://知識\">知識</a>.</div>\r\n","<div class=\"hw jl\">知能</div><div class=\"def\">⇒<a href=\"entry://知性\">知性</a>.</div>\r\n","<div class=\"hw jl\">知覚</div><div class=\"def\">sensus, intellectus, perceptio.</div><div class=\"def\">▼<b>～されたもの</b> percepta(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b> sentio, intellego, percipio.</div><div class=\"def\">⇒<a href=\"entry://感覚\">感覚</a>,<a href=\"entry://認識\">認識</a>,<a href=\"entry://理解\">理解</a>.</div>\r\n","<div class=\"hw jl\">知識</div><div class=\"def\">scientia, notitia, cognitio.</div><div class=\"def\">▼<b>～人</b> doctus [intellegens] homo, intellegentes(<i>pl</i>), sapientes(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://学識\">学識</a>,<a href=\"entry://認識\">認識</a>.</div>\r\n","<div class=\"hw jl\">短い</div><div class=\"def\">brevis.</div><div class=\"def\">▼<b>短く</b> breviter.</div><div class=\"def\">▼<b>短さ</b> brevitas.</div><div class=\"ex2\">短縮によってより短く, あるいは延長によってより長く<span class=\"ext\">aut contractione brevius aut productione longius.</span></div><div class=\"def\">⇒<a href=\"entry://長い\">長い</a>.</div>\r\n","<div class=\"hw jl\">短所</div><div class=\"def\">vitium.</div><div class=\"def\">⇒<a href=\"entry://欠点\">欠点</a>.</div>\r\n","<div class=\"hw jl\">短気</div><div class=\"def\">iracundia, animus irritabilis.</div><div class=\"def\">▼<b>～な</b> iracundus, irritabilis.</div>\r\n","<div class=\"hw jl\">短縮</div><div class=\"def\">contractio.</div><div class=\"def\">▼<b>～する</b> contraho, 〈alqd〉 breviorem facio.</div><div class=\"def\">⇒<a href=\"entry://省略\">省略</a>.</div>\r\n","<div class=\"hw jl\">石</div><div class=\"def\">lapis.</div><div class=\"def\">▼<b>小～</b> lapillus.</div><div class=\"def\">▼<b>なめらかな小～</b> calculus.</div><div class=\"def\">⇒<a href=\"entry://岩\">岩</a>.</div>\r\n","<div class=\"hw jl\">石油</div><div class=\"def\">petroleum, oleum terrigenum.</div><div class=\"def\">▼<b>～の</b> petrolearius.</div>\r\n","<div class=\"hw jl\">石炭</div><div class=\"def\">carbo fossilis.</div><div class=\"def\">⇒<a href=\"entry://木炭\">木炭</a>.</div>\r\n","<div class=\"hw jl\">石膏</div><div class=\"def\">gypsum.</div><div class=\"def\">▼<b>～でおおう</b> gypso.</div>\r\n","<div class=\"hw jl\">石鹸</div><div class=\"def\">sapo.</div>\r\n","<div class=\"hw jl\">砂</div><div class=\"def\">arena.</div>\r\n","<div class=\"hw jl\">砂利</div><div class=\"def\">glarea.</div><div class=\"def\">▼<b>～の多い</b> glareosus.</div>\r\n","<div class=\"hw jl\">砂漠</div><div class=\"def\">deserta(loca)(<i>pl</i>).</div><div class=\"ex2\">リビア～<span class=\"ext\">Libycae arenae(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">砂糖</div><div class=\"def\">saccharon.</div><div class=\"ex2\">～を入れる<span class=\"ext\">saccharo condio.</span></div>\r\n","<div class=\"hw jl\">研ぐ</div><div class=\"def\">exacuo, acuo.</div><div class=\"def\">⇒<a href=\"entry://磨く\">磨く</a>.</div>\r\n","<div class=\"hw jl\">研究</div><div class=\"def\">studium, investigatio.</div><div class=\"def\">▼<b>～者</b> investigator(<i>m</i>).</div><div class=\"def\">▼<b>～する</b> perspicio, contemplor(<i>dep</i>).</div><div class=\"ex2\">哲学の～をする<span class=\"ext\">studium philosophiae colo.</span></div><div class=\"def\">⇒<a href=\"entry://探求\">探求</a>.</div>\r\n","<div class=\"hw jl\">砕く</div><div class=\"def\">frango, confringo, molo, commolo.</div><div class=\"def\">⇒<a href=\"entry://粉々\">粉々</a>,<a href=\"entry://粉砕\">粉砕</a>.</div>\r\n","<div class=\"hw jl\">破る</div><div class=\"def\">(紙や布を)(=裂く)rumpo, lanio, lacero, scindo;(戦いで敵を)(=負かす)vinco, supero.</div><div class=\"ex2\">約束を～<span class=\"ext\">promissum fallo / fidem frango.</span></div><div class=\"ex2\">誓約を～<span class=\"ext\">jusjurandum violo / foedus frango.</span></div>\r\n","<div class=\"hw jl\">破壊</div><div class=\"def\">eversio, destructio, demolitio.</div><div class=\"def\">▼<b>～する</b> everto, destruo, demolior(<i>dep</i>), vasto, diruo, rumpo.</div><div class=\"def\">⇒<a href=\"entry://破滅\">破滅</a>.</div>\r\n","<div class=\"hw jl\">破滅</div><div class=\"def\">ruina, pernicies, interitus.</div><div class=\"def\">▼<b>～させる</b> perdo.</div><div class=\"def\">▼<b>～する</b>(=滅びる)ruo, se ipsum perdere(← perdo), in perniciem incurro, intereo.</div><div class=\"def\">▼<b>～した</b> ruinosus, perditus.</div><div class=\"def\">▼<b>～的な</b> perniciosus.</div><div class=\"def\">▼<b>～的に</b> perniciose.</div>\r\n","<div class=\"hw jl\">破片</div><div class=\"def\">fragmentum;(木や石の)assula, caementum.</div>\r\n","<div class=\"hw jl\">破産</div><div class=\"def\">decoctio, eversio [ruinae] rei familiaris, naufragium fortunarum.</div><div class=\"def\">▼<b>～する</b> decoquo, conturbo.</div><div class=\"def\">▼<b>～している</b> solvendo non sum.</div>\r\n","<div class=\"hw jl\">破門</div><div class=\"def\">excommunicatio, anathema.</div><div class=\"def\">▼<b>～する</b> excommunico, anathematizo.</div><div class=\"def\">⇒<a href=\"entry://排斥\">排斥</a>.</div>\r\n","<div class=\"hw jl\">硫黄</div><div class=\"def\">sulphur.</div><div class=\"def\">▼<b>～の</b> sulfureus.</div>\r\n","<div class=\"hw jl\">硬化</div><div class=\"def\">▼<b>～する</b> duresco, induresco.</div><div class=\"def\">⇒<a href=\"entry://固い\">固い</a>.</div>\r\n","<div class=\"hw jl\">硬直</div><div class=\"def\">rigor.</div><div class=\"def\">▼<b>～した</b> rigidus.</div><div class=\"def\">▼<b>～する</b> rigesco.</div><div class=\"def\">▼<b>～している</b> rigeo.</div>\r\n","<div class=\"hw jl\">硬貨</div><div class=\"def\">nomisma, nummus.</div><div class=\"def\">⇒<a href=\"entry://紙幣\">紙幣</a>,<a href=\"entry://貨幣\">貨幣</a>.</div>\r\n","<div class=\"hw jl\">確か</div><div class=\"def\">▼<b>～な</b> certus, exploratus.</div><div class=\"def\">▼<b>～に</b> certe, profecto, probe.</div><div class=\"def\">▼(...は)<b>～である</b> non [haud] dubium est quin 〈+<i>subj</i>〉, non ambigitur quin 〈+<i>subj</i>〉.</div><div class=\"ex2\">～なこととして言う<span class=\"ext\">pro certo dico.</span></div><div class=\"def\">⇒<a href=\"entry://確実\">確実</a>.</div>\r\n","<div class=\"hw jl\">確かめる</div><div class=\"def\">exploro.</div><div class=\"def\">⇒<a href=\"entry://点検\">点検</a>,<a href=\"entry://確認\">確認</a>,<a href=\"entry://試す\">試す</a>.</div>\r\n","<div class=\"hw jl\">確信</div><div class=\"def\">fides, fidentia.</div><div class=\"def\">▼<b>～している</b><span class=\"pos3\">[形]</span> fidens. <span class=\"pos3\">[動]</span> haud dubito quin 〈+<i>subj</i>〉, pro certo habeo.</div><div class=\"def\">▼<b>～する</b> confido 〈+<i>inf</i>〉.</div><div class=\"def\">▼<b>～して, ～をもって</b> fidenter.</div>\r\n","<div class=\"hw jl\">確固</div><div class=\"def\">(=不動, 堅固, 強固)firmitas.</div><div class=\"def\">▼<b>～たる</b> firmus.</div>\r\n","<div class=\"hw jl\">確定</div><div class=\"def\">▼<b>～する</b> finio, constituo, decerno.</div><div class=\"def\">⇒<a href=\"entry://決定\">決定</a>,<a href=\"entry://定める\">定める</a>,<a href=\"entry://決める\">決める</a>.</div>\r\n","<div class=\"hw jl\">確実</div><div class=\"def\">▼<b>～な</b>(=確かな)certus, exploratus.</div><div class=\"def\">▼<b>～に</b>(=確かに)certo, explorate.</div><div class=\"def\">▼<b>不～な</b> dubius, incertus.</div>\r\n","<div class=\"hw jl\">確認</div><div class=\"def\">confirmatio, affirmatio, approbatio.</div><div class=\"def\">▼<b>～する</b> confirmo, affirmo.</div>\r\n","<div class=\"hw jl\">磁器</div><div class=\"def\">porcellana, res ex argilla Sinensi.</div>\r\n","<div class=\"hw jl\">磁石</div><div class=\"def\">Magnes lapis.</div><div class=\"def\">▼<b>～の</b> magneticus.</div>\r\n","<div class=\"hw jl\">磨く</div><div class=\"def\">polio, expolio.</div><div class=\"def\">▼<b>磨いて仕上げること</b> expolitio.</div>\r\n","<div class=\"hw jl\">示す</div><div class=\"def\">indico, monstro, exhibeo, demonstro, praesto.</div><div class=\"def\">⇒<a href=\"entry://指示\">指示</a>.</div>\r\n","<div class=\"hw jl\">礼</div><div class=\"def\">▼(人に)<b> ～を言う</b>(=感謝する)〈alci〉 gratias ago.</div><div class=\"def\">⇒<a href=\"entry://礼儀\">礼儀</a>.</div>\r\n","<div class=\"hw jl\">礼儀</div><div class=\"def\">(=礼儀作法)humanitas, elegantia.</div><div class=\"def\">▼<b>～正しい</b> humanus, elegans.</div><div class=\"def\">▼<b>～正しく</b> urbane, eleganter.</div><div class=\"def\">⇒<a href=\"entry://洗練\">洗練</a>.</div>\r\n","<div class=\"hw jl\">礼拝</div><div class=\"def\">cultus, adoratio, officium.</div><div class=\"def\">▼<b>～堂</b> aedicula, sacrarium, sacellum.</div>\r\n","<div class=\"hw jl\">社会</div><div class=\"def\">humana societas [consortio], hominum communitas [consociatio], civilis [civium] societas, consociati homines(<i>pl</i>).</div><div class=\"def\">▼<b>～的な</b> socialis.</div><div class=\"def\">▼<b>～の, ～に関する</b> ad hominum societatem pertinens(<i>etc</i>).</div>\r\n","<div class=\"hw jl\">社会主義</div><div class=\"def\">socialismus, bonorum aequatio.</div><div class=\"def\">▼<b>～者</b> socialista, aequandorum bonorum fautor.</div><div class=\"def\">▼<b>～の</b> ad socialismum pertinens.</div>\r\n","<div class=\"hw jl\">社長</div><div class=\"def\">societatis summus moderator.</div>\r\n","<div class=\"hw jl\">祈る</div><div class=\"def\">(=祈願する)precor(<i>dep</i>).</div><div class=\"def\">▼<b>祈り</b>(=祈願)prex, precatio.</div>\r\n","<div class=\"hw jl\">祖国</div><div class=\"def\">patria.</div><div class=\"def\">▼<b>～の</b> patrius.</div>\r\n","<div class=\"hw jl\">祖母</div><div class=\"def\">avia.</div>\r\n","<div class=\"hw jl\">祖父</div><div class=\"def\">avus.</div><div class=\"def\">▼<b>～の</b> avitus.</div>\r\n","<div class=\"hw jl\">祝う</div><div class=\"def\">(祭りなどを)celebro, ago, agito;(=祝辞を述べる)gratulor(<i>dep</i>).</div><div class=\"def\">▼<b>～こと</b> celebratio.</div><div class=\"ex2\">誕生日を～<span class=\"ext\">diem natalem ago.</span></div><div class=\"def\">⇒<a href=\"entry://祝辞\">祝辞</a>.</div>\r\n","<div class=\"hw jl\">祝日</div><div class=\"def\">feriae(<i>pl</i>), dies populi [nationis].</div>\r\n","<div class=\"hw jl\">祝福</div><div class=\"def\">gratulatio, benedictio.</div><div class=\"def\">▼<b>～する</b> gratulor(<i>dep</i>), bene dico.</div>\r\n","<div class=\"hw jl\">祝辞</div><div class=\"def\">gratulatio.</div><div class=\"def\">▼<b>～を述べる人</b> gratulator.</div><div class=\"def\">▼<b>～を述べる</b> gratulor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">神</div><div class=\"def\">deus.</div><div class=\"def\">▼<b>～の(ごとき)</b> divus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">女神<span class=\"ext\">dea.</span></div>\r\n","<div class=\"hw jl\">神官</div><div class=\"def\">sacerdos.</div><div class=\"def\">⇒<a href=\"entry://祭司\">祭司</a>.</div>\r\n","<div class=\"hw jl\">神経</div><div class=\"def\">nervus.</div>\r\n","<div class=\"hw jl\">神聖</div><div class=\"def\">sanctitas.</div><div class=\"def\">▼<b>～な</b> sanctus, sacratus, sacer, religiosus.</div>\r\n","<div class=\"hw jl\">神託</div><div class=\"def\">oraculum.</div><div class=\"ex2\">～を求める<span class=\"ext\">oraculum peto [consulo].</span></div><div class=\"def\">⇒<a href=\"entry://予言\">予言</a>,<a href=\"entry://占い\">占い</a>.</div>\r\n","<div class=\"hw jl\">神話</div><div class=\"def\">fabula, mythos.</div>\r\n","<div class=\"hw jl\">票</div><div class=\"def\">⇒<a href=\"entry://投票\">投票</a>.</div>\r\n","<div class=\"hw jl\">祭り</div><div class=\"def\">(=祭典, 祭礼)solemne, solemnia(<i>pl</i>);(=祝祭日)dies festus [feriatus], feriae(<i>pl</i>).</div><div class=\"def\">▼<b>～を行なう</b> celebro.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">バッコスの祭<span class=\"ext\">Liberalia(<i>pl</i>).</span></div><div class=\"cf\">慰霊祭<span class=\"ext\">parentalia(<i>pl</i>).</span></div><div class=\"cf\">死者の慰霊祭を行なう<span class=\"ext\">mortuis parento.</span></div>\r\n","<div class=\"hw jl\">祭司</div><div class=\"def\">sacerdos, flamen.</div><div class=\"def\">▼<b>～職</b> sacerdotium.</div>\r\n","<div class=\"hw jl\">祭日</div><div class=\"def\">(=祝祭日)feriae(<i>pl</i>), dies festus [feriatus], festum.</div><div class=\"def\">▼<b>～の</b> festus, feriatus.</div><div class=\"def\">⇒<a href=\"entry://休日\">休日</a>,<a href=\"entry://祭り\">祭り</a>.</div>\r\n","<div class=\"hw jl\">禁欲</div><div class=\"def\">abstinentia.</div><div class=\"def\">▼<b>～的な</b> abstinens.</div>\r\n","<div class=\"hw jl\">禁止</div><div class=\"def\">(行為)prohibitio, interdictio;(=禁止令)interdictum.</div><div class=\"def\">▼<b>～する</b> prohibeo, interdico, veto.</div>\r\n","<div class=\"hw jl\">禁煙</div><div class=\"def\">▼<b>～する</b>(=喫煙の習慣をやめる)fumificationem depono.</div><div class=\"def\">⇒<a href=\"entry://喫煙\">喫煙</a>,<a href=\"entry://煙草\">煙草</a>.</div>\r\n","<div class=\"hw jl\">禅</div><div class=\"def\">doctrina zen.</div>\r\n","<div class=\"hw jl\">私</div><div class=\"def\">ego.</div><div class=\"def\">▼<b>～たち</b> nos.</div><div class=\"def\">▼<b>～の</b> meus.</div><div class=\"def\">▼<b>～たちの</b> noster.</div>\r\n","<div class=\"hw jl\">私有</div><div class=\"def\">▼<b>～の</b> privatus.</div>\r\n","<div class=\"hw jl\">私的</div><div class=\"def\">▼<b>～な</b> privatus.</div><div class=\"def\">▼<b>～に</b> privatim.</div>\r\n","<div class=\"hw jl\">秋</div><div class=\"def\">autumnus.</div><div class=\"def\">▼<b>～の</b> autumnus, autumnalis.</div><div class=\"def\">⇒<a href=\"entry://季節\">季節</a>.</div>\r\n","<div class=\"hw jl\">科学</div><div class=\"def\">(=自然科学)scientia naturalis;(=知識)scientia, doctrina.</div><div class=\"def\">▼<b>(自然)～者</b> doctus physicus.</div>\r\n","<div class=\"hw jl\">科白</div><div class=\"def\">(俳優の)(actoris)partes(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">秒</div><div class=\"def\">(temporis)punctum.</div><div class=\"ex2\">12時まであと何分ですか?―あと30～です<span class=\"ext\">quot minutis nunc abest horā duodecimā? ― triginta punctis.</span></div>\r\n","<div class=\"hw jl\">秘密</div><div class=\"def\">secretum, arcanum, occultum, occultatio.</div><div class=\"def\">▼<b>～の</b> secretus, arcanus, abditus, tectus, occultus.</div><div class=\"def\">▼<b>～にする</b> abdo, occulo, occulto.</div><div class=\"def\">▼<b>～に</b> secreto, occulte, arcano.</div><div class=\"def\">⇒<a href=\"entry://隠す\">隠す</a>.</div>\r\n","<div class=\"hw jl\">秘書</div><div class=\"def\">scriba, librarius, scriptor.</div>\r\n","<div class=\"hw jl\">秤</div><div class=\"def\">(=天秤)libra, trutina, statera.</div><div class=\"def\">▼<b>～にかける</b> examino.</div>\r\n","<div class=\"hw jl\">秩序</div><div class=\"def\">ordo.</div><div class=\"def\">⇒<a href=\"entry://治安\">治安</a>.</div>\r\n","<div class=\"hw jl\">称号</div><div class=\"def\">nomen, titulus, appellatio.</div>\r\n","<div class=\"hw jl\">移す</div><div class=\"def\">(=場所を移動させる)〈loco〉 moveo, 〈loco〉 commoveo, transfero, transmoveo, transmitto;(実行に)ad effectum adduco.</div><div class=\"def\">▼<b>～こと</b> motio.</div><div class=\"def\">⇒<a href=\"entry://移動\">移動</a>,<a href=\"entry://実行\">実行</a>.</div>\r\n","<div class=\"hw jl\">移り気</div><div class=\"def\">mentis inconstantia.</div><div class=\"def\">▼<b>～な</b> varius, mutabilis, ventosus.</div>\r\n","<div class=\"hw jl\">移る</div><div class=\"def\">(=場所を移動する)〈loco〉 se movere(← moveo), locum muto;(=病気などが感染する)(...から...へ)〈ab alqo ad alqm〉 mano, transilio.</div><div class=\"def\">⇒<a href=\"entry://感染\">感染</a>,<a href=\"entry://伝染\">伝染</a>.</div>\r\n","<div class=\"hw jl\">移住</div><div class=\"def\">migratio, demigratio.</div><div class=\"def\">▼<b>～する</b> migro, emigro, demigro, sedes muto.</div><div class=\"def\">▼<b>～者</b> migrans.</div><div class=\"def\">⇒<a href=\"entry://移民\">移民</a>.</div>\r\n","<div class=\"hw jl\">移動</div><div class=\"def\">(場所の)motio, motus, locorum mutatio, migratio.</div><div class=\"def\">▼<b>～する(ことができる)</b> mobilis.</div><div class=\"def\">▼(場所を)<b> ～させる</b> 〈loco〉 moveo.</div><div class=\"def\">▼(場所を)<b>～する</b> 〈loco〉 se movere(← moveo), migro.</div>\r\n","<div class=\"hw jl\">移植</div><div class=\"def\">translatio, propagatio.</div><div class=\"def\">▼(植物を)<b> ～する</b> transfero, propago.</div>\r\n","<div class=\"hw jl\">移民</div><div class=\"def\">(国内への)immigrans;(国外への)emigrans.</div><div class=\"def\">▼<b>～する</b>(国内へ)immigro;(国外へ)emigro, demigro.</div><div class=\"def\">▼<b>～すること</b> demigratio.</div>\r\n","<div class=\"hw jl\">移行</div><div class=\"def\">transgressio, transitus.</div><div class=\"def\">▼<b>～する</b> transgredior(<i>dep</i>), transeo.</div>\r\n","<div class=\"hw jl\">移転</div><div class=\"def\">(=住居を変えること)migratio, emigratio.</div><div class=\"def\">▼<b>～する</b> migro, emigro.</div>\r\n","<div class=\"hw jl\">程度</div><div class=\"def\">gradus.</div><div class=\"def\">▼<b>同～</b> aequalitas.</div><div class=\"def\">▼<b>同じ～に</b> aequabiliter.</div>\r\n","<div class=\"hw jl\">税</div><div class=\"def\">tributum, vectigal.</div><div class=\"def\">▼<b>直接～</b> tributum.</div><div class=\"def\">▼<b>間接～</b> vectigal.</div><div class=\"def\">▼<b>所得～</b> tributum ex reditibus.</div><div class=\"def\">▼<b>財産～</b> tributum ex censu.</div><div class=\"ex2\">～を納める<span class=\"ext\">tributum confero [persolvo], vectigalia pendo.</span></div><div class=\"ex2\">～を課す(=課税する)<span class=\"ext\">tributum [vectigal] impono.</span></div><div class=\"def\">⇒<a href=\"entry://関税\">関税</a>,<a href=\"entry://税務署\">税務署</a>,<a href=\"entry://免税\">免税</a>.</div>\r\n","<div class=\"hw jl\">税務署</div><div class=\"def\">sedes officii fiscalis.</div>\r\n","<div class=\"hw jl\">税金</div><div class=\"def\">⇒<a href=\"entry://税\">税</a>.</div>\r\n","<div class=\"hw jl\">税関</div><div class=\"def\">portitores(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://関税\">関税</a>.</div>\r\n","<div class=\"hw jl\">種</div><div class=\"def\">species.</div><div class=\"ex2\">類とは共通性によって互いに類似しながらも 「～」 によって互いに異なる部分を二つかそれ以上含んでいる<span class=\"ext\">genus autem id est, quod sui similes communione quadam, specie autem differentes, duas aut plures complectitur partes.</span></div><div class=\"def\">⇒<a href=\"entry://類\">類</a>.</div>\r\n","<div class=\"hw jl\">種</div><div class=\"def\">semen.</div><div class=\"def\">▼<b>～まき</b> satio.</div><div class=\"def\">▼<b>～をまく</b> sero.</div>\r\n","<div class=\"hw jl\">種子</div><div class=\"def\">semen.</div><div class=\"def\">⇒<a href=\"entry://種\">種<SUB>たね</SUB></a>.</div>\r\n","<div class=\"hw jl\">種類</div><div class=\"def\">species, genus.</div><div class=\"def\">⇒<a href=\"entry://種\">種<SUB>しゅ</SUB></a>,<a href=\"entry://類\">類</a>.</div>\r\n","<div class=\"hw jl\">稲</div><div class=\"def\">oryza.</div>\r\n","<div class=\"hw jl\">稲妻</div><div class=\"def\">(=雷の閃光)fulgur, fulgor, fulmen.</div><div class=\"ex2\">～が光る<span class=\"ext\">fulgrat, fulget(<i>impers</i>).</span></div>\r\n","<div class=\"hw jl\">稼ぐ</div><div class=\"def\">(=働いて金を得る)mereor(<i>dep</i>), demereo.</div>\r\n","<div class=\"hw jl\">穀物</div><div class=\"def\">frumentum.</div><div class=\"def\">▼<b>～に関する</b> frumentarius.</div>\r\n","<div class=\"hw jl\">積み重ねる</div><div class=\"def\">acervo, onero, aggero, agglomero.</div><div class=\"def\">▼<b>積み重なって</b> acervatim.</div><div class=\"def\">▼<b>積み重ね</b> acervus.</div><div class=\"def\">⇒<a href=\"entry://堆積\">堆積</a>.</div>\r\n","<div class=\"hw jl\">積む</div><div class=\"def\">(荷を)onero;(=積み上げる)congero, coacervo.</div><div class=\"def\">⇒<a href=\"entry://堆積\">堆積</a>,<a href=\"entry://積み重ねる\">積み重ねる</a>.</div>\r\n","<div class=\"hw jl\">積もる</div><div class=\"def\">accumulor(<i>pass</i>);(雪が)(nix)jacet(← jaceo).</div>\r\n","<div class=\"hw jl\">積荷</div><div class=\"def\">onus.</div><div class=\"def\">⇒<a href=\"entry://荷\">荷</a>,<a href=\"entry://重荷\">重荷</a>.</div>\r\n","<div class=\"hw jl\">穏やか</div><div class=\"def\">▼<b>～な</b> placidus, lenis, tranquillus, quietus, placatus.</div><div class=\"def\">▼<b>～に</b> tranquille.</div><div class=\"def\">▼<b>～さ</b> lenitas.</div><div class=\"def\">▼<b>～にする</b> lenio, placo.</div>\r\n","<div class=\"hw jl\">穴</div><div class=\"def\">cavus, cavum, foramen;(=ほら穴)caverna;(地面に掘った)scrobis.</div><div class=\"def\">▼<b>落とし～</b> fovea.</div><div class=\"def\">▼(...に)<b> ～をあける</b> cavo 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">空</div><div class=\"def\">(=空虚, 空の状態)vacuum, vacuitas.</div><div class=\"def\">▼<b>～の</b> vacuus, inanis.</div><div class=\"def\">▼<b>～にする</b> vacuefacio, evacuo, inanio.</div><div class=\"def\">▼<b>～である</b> vaco.</div>\r\n","<div class=\"hw jl\">空</div><div class=\"def\">caelum.</div><div class=\"def\">▼<b>～の</b> caelestis.</div><div class=\"def\">⇒<a href=\"entry://天\">天</a>.</div>\r\n","<div class=\"hw jl\">空いた</div><div class=\"def\">(=空いている, 空の)vacuus.</div>\r\n","<div class=\"hw jl\">空き地</div><div class=\"def\">area.</div>\r\n","<div class=\"hw jl\">空く</div><div class=\"def\">(容器や場所が)vacuefio.</div><div class=\"def\">▼<b>空いている</b> vaco.</div><div class=\"def\">⇒<a href=\"entry://空\">空<SUB>から</SUB></a>.</div>\r\n","<div class=\"hw jl\">空ける</div><div class=\"def\">(=容器や場所を空にする)vacuefacio.</div>\r\n","<div class=\"hw jl\">空しい</div><div class=\"def\">(=空<SUB>から</SUB>の)vacuus;(=内容のない, 無意味な)vanus;(=無益な, 無駄な)inanis, irritus, inutilis.</div><div class=\"def\">▼<b>空しく</b>(=無駄に, 無益に, 徒に)frustra, nequiquam, inaniter, inutiliter, incassum.</div>\r\n","<div class=\"hw jl\">空中</div><div class=\"def\">▼<b>～の</b> aerius.</div>\r\n","<div class=\"hw jl\">空想</div><div class=\"def\">somnium, phantasia, vana opinio, inanis cogitatio.</div><div class=\"def\">▼<b>～する</b> somnio.</div><div class=\"def\">▼<b>～的な</b> commenticius, inanis, vanus, phantasticus.</div><div class=\"def\">▼<b>～に満ちた</b> imaginosus.</div><div class=\"def\">⇒<a href=\"entry://夢想\">夢想</a>,<a href=\"entry://妄想\">妄想</a>,<a href=\"entry://幻想\">幻想</a>.</div>\r\n","<div class=\"hw jl\">空欄</div><div class=\"def\">vacans [vacuus] locus.</div>\r\n","<div class=\"hw jl\">空気</div><div class=\"def\">aer, spiritus.</div><div class=\"def\">▼<b>～の</b> aerius.</div>\r\n","<div class=\"hw jl\">空洞</div><div class=\"def\">cavum, lacuna.</div><div class=\"def\">▼<b>～の</b> cavus.</div><div class=\"def\">⇒<a href=\"entry://穴\">穴</a>,<a href=\"entry://洞窟\">洞窟</a>.</div>\r\n","<div class=\"hw jl\">空港</div><div class=\"def\">aeroportus, aeriportus, aeronavium portus, statio aeronautica, aerostatio.</div>\r\n","<div class=\"hw jl\">空白</div><div class=\"def\">(=何もないこと)vacuitas.</div><div class=\"def\">▼<b>～の</b>(=何もない)vacuus.</div><div class=\"def\">⇒<a href=\"entry://空\">空<SUB>から</SUB></a>.</div>\r\n","<div class=\"hw jl\">空間</div><div class=\"def\">spatium.</div><div class=\"def\">⇒<a href=\"entry://間\">間<SUB>あいだ</SUB></a>.</div>\r\n","<div class=\"hw jl\">突き通す</div><div class=\"def\">confodio, configo, transfodio, transfigo, trajicio, percutio.</div>\r\n","<div class=\"hw jl\">突然</div><div class=\"def\">▼<b>～の</b> subitus, repens, inopinatus.</div><div class=\"def\">▼<b>～のできごと</b> subitum.</div><div class=\"def\">▼<b>～(に)</b> repente, subito, (ex)inopinato, inopinate, inopinanter.</div>\r\n","<div class=\"hw jl\">突進</div><div class=\"def\">▼<b>～する</b> ruo, irruo, praecipito.</div>\r\n","<div class=\"hw jl\">窃盗</div><div class=\"def\">(行為)furtum;(人)fur.</div><div class=\"def\">▼<b>～の</b> furtivus.</div>\r\n","<div class=\"hw jl\">窓</div><div class=\"def\">fenestra, specularia(<i>pl</i>), lumen;(小さな)fenestella.</div><div class=\"ex2\">～を開ける<span class=\"ext\">fenestras aperio.</span></div>\r\n","<div class=\"hw jl\">窮地</div><div class=\"def\">artum.</div><div class=\"ex2\">～に追い込まれる<span class=\"ext\">in artum compellor(<i>pass</i>).</span></div>\r\n","<div class=\"hw jl\">窺う</div><div class=\"def\">observo, speculor(<i>dep</i>), exploro, aucupor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">立たせる</div><div class=\"def\">erigo.</div>\r\n","<div class=\"hw jl\">立ち上がる</div><div class=\"def\">surgo, assurgo, exsurgo.</div><div class=\"ex2\">一斉に～<span class=\"ext\">consurgo.</span></div>\r\n","<div class=\"hw jl\">立ち入る</div><div class=\"def\">⇒<a href=\"entry://入る\">入る</a>.</div>\r\n","<div class=\"hw jl\">立ち去る</div><div class=\"def\">abeo,exeo,excedo,discedo,proficiscor(<i>dep</i>), cedo.</div>\r\n","<div class=\"hw jl\">立ち寄る</div><div class=\"def\">⇒<a href=\"entry://寄り道\">寄り道</a>.</div>\r\n","<div class=\"hw jl\">立ち直る</div><div class=\"def\">resurgo.</div><div class=\"def\">⇒<a href=\"entry://回復\">回復</a>.</div>\r\n","<div class=\"hw jl\">立っている</div><div class=\"def\"><span class=\"pos3\">[動]</span> sto, insto.</div><div class=\"def\">━<span class=\"pos3\">[形]</span>(=立った, 直立の)rectus, erectus.</div>\r\n","<div class=\"hw jl\">立つ</div><div class=\"def\">sto;(=立ち上がる)surgo, assurgo, exsurgo.</div><div class=\"ex2\">髪の毛が～(=逆立つ)<span class=\"ext\">capilli horrent.</span></div><div class=\"def\">⇒<a href=\"entry://立っている\">立っている</a>.</div>\r\n","<div class=\"hw jl\">立候補</div><div class=\"def\">petitio.</div><div class=\"def\">▼<b>～者</b> candidatus, petitor, qui petunt(<i>pl</i>).</div><div class=\"def\">▼<b>～する</b> ostendere(← ostendo)se candidatum, profiteri(← profiteor)se petere.</div>\r\n","<div class=\"hw jl\">立場</div><div class=\"def\">locus.</div><div class=\"ex2\">なぜ私は自分の～を擁護することを恐れたりためらったりするのか<span class=\"ext\">cur timeam dubitemque locum defendere.</span></div>\r\n","<div class=\"hw jl\">立方体</div><div class=\"def\">cubus, quadrantal.</div><div class=\"def\">▼<b>～の</b> cubicus.</div>\r\n","<div class=\"hw jl\">立腹</div><div class=\"def\">ira, iracundia.</div><div class=\"def\">▼<b>～する</b> irascor(<i>dep</i>).</div><div class=\"def\">▼<b>～した</b> iratus.</div>\r\n","<div class=\"hw jl\">立身出世</div><div class=\"def\">▼<b>～の道</b> pronum ad honores iter.</div>\r\n","<div class=\"hw jl\">端</div><div class=\"def\">extrema pars, extremum, extremitas.</div><div class=\"def\">▼<b>～の</b> extremus, ultimus.</div>\r\n","<div class=\"hw jl\">競争</div><div class=\"def\">certamen, certatio, aemulatio, rivalitas.</div><div class=\"def\">▼<b>～相手</b> rivalis.</div><div class=\"def\">▼<b>～して</b> certatim.</div><div class=\"def\">▼<b>～する</b> certo, aemulor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://対抗\">対抗</a>.</div>\r\n","<div class=\"hw jl\">競売</div><div class=\"def\">auctio.</div><div class=\"def\">▼<b>～の</b> auctionarius.</div><div class=\"def\">▼<b>～にかける</b> auctionor(<i>dep</i>).</div><div class=\"def\">▼<b>～を催す</b> auctionem facio.</div>\r\n","<div class=\"hw jl\">競技</div><div class=\"def\">ludus, ludicrum.</div><div class=\"def\">▼<b>運動～</b> certamen athleticum.</div><div class=\"def\">▼<b>～者</b> athleta.</div><div class=\"def\">▼<b>～場</b> stadium.</div><div class=\"def\">▼<b>十種～</b> decathlum.</div><div class=\"def\">▼<b>近代五種～</b> pentathlum nostrae aetatis.</div><div class=\"def\">⇒<a href=\"entry://競争\">競争</a>,<a href=\"entry://競走\">競走</a>.</div>\r\n","<div class=\"hw jl\">競技会</div><div class=\"def\">ludi(<i>pl</i>).</div><div class=\"def\">▼<b>体育～</b> gymnicus agon.</div><div class=\"def\">▼<b>オリンピック～</b> Ludi Olympii(<i>pl</i>), Olympia(certamina)(<i>pl</i>).</div><div class=\"ex2\">～を開催する<span class=\"ext\">ludos celebro.</span></div>\r\n","<div class=\"hw jl\">競走</div><div class=\"def\">cursus.</div><div class=\"def\">▼<b>～者</b> cursor.</div><div class=\"ex2\">100メートル～<span class=\"ext\">cursus certamen centum metrorum.</span></div><div class=\"ex2\">(彼は)10000メートル～で世界新記録を達成した<span class=\"ext\">in cursu decem milium metrorum novum culmen mundanum consecutus est.</span></div>\r\n","<div class=\"hw jl\">競馬</div><div class=\"def\">equorum curriculum, cursus equester.</div><div class=\"def\">▼<b>～場</b> hippodromos.</div>\r\n","<div class=\"hw jl\">竹</div><div class=\"def\">arundo indica, arundo bambos.</div>\r\n","<div class=\"hw jl\">笑う</div><div class=\"def\">rideo.</div><div class=\"def\">▼<b>笑い</b> risus.</div><div class=\"ex2\">きみはなぜ～のか<span class=\"ext\">quid rides?</span></div><div class=\"def\">⇒<a href=\"entry://ほほえむ\">ほほえむ</a>.</div>\r\n","<div class=\"hw jl\">笑顔</div><div class=\"def\">subridens facies.</div><div class=\"def\">⇒<a href=\"entry://ほほえむ\">ほほえむ</a>.</div>\r\n","<div class=\"hw jl\">笛</div><div class=\"def\">tibia.</div><div class=\"def\">▼<b>～吹き</b>(人)tibicen(<i>m</i>), tibicina(<i>f</i>).</div><div class=\"def\">▼<b>～を吹く</b> tibiā cano, tibiam inflo.</div>\r\n","<div class=\"hw jl\">第一</div><div class=\"def\">▼<b>～の</b> primus.</div><div class=\"def\">▼<b>～に</b> primum, primo loco.</div>\r\n","<div class=\"hw jl\">等しい</div><div class=\"def\">aequus, aequalis, aequabilis, par.</div><div class=\"def\">▼<b>等しく</b> aeque, aequaliter, pariter.</div><div class=\"def\">▼<b>等しさ</b> aequitas, aequalitas.</div><div class=\"def\">▼<b>等しくする</b> aequo.</div>\r\n","<div class=\"hw jl\">筋肉</div><div class=\"def\">musculus.</div><div class=\"def\">▼<b>～の(多い)</b> musculosus.</div>\r\n","<div class=\"hw jl\">答え</div><div class=\"def\">responsum, responsio.</div><div class=\"def\">⇒<a href=\"entry://返事\">返事</a>.</div>\r\n","<div class=\"hw jl\">答える</div><div class=\"def\">respondeo, responso.</div>\r\n","<div class=\"hw jl\">策</div><div class=\"def\">dolus.</div><div class=\"def\">▼<b>～を弄する</b><span class=\"pos3\">[形]</span> dolosus.</div><div class=\"def\">⇒<a href=\"entry://策略\">策略</a>,<a href=\"entry://計画\">計画</a>.</div>\r\n","<div class=\"hw jl\">策略</div><div class=\"def\">astus, dolus, versutia.</div><div class=\"def\">▼<b>～にたけた</b> versutus, astutus.</div><div class=\"def\">⇒<a href=\"entry://詐欺\">詐欺</a>,<a href=\"entry://陰謀\">陰謀</a>.</div>\r\n","<div class=\"hw jl\">算数</div><div class=\"def\">(=算術)arithmetica, arithmetice.</div><div class=\"def\">▼<b>～の</b>(=算術の)arithmeticus.</div>\r\n","<div class=\"hw jl\">管</div><div class=\"def\">tubus, fistula, canalis.</div>\r\n","<div class=\"hw jl\">管理</div><div class=\"def\">cura, curatio, procuratio, gestio, administratio.</div><div class=\"def\">▼<b>～人, ～者</b> procurator, administrator.</div><div class=\"def\">▼<b>～する</b> procuro, administro, gero.</div>\r\n","<div class=\"hw jl\">箱</div><div class=\"def\">capsa, arca.</div><div class=\"def\">▼<b>小さな～</b> capsella, capsula, arcula.</div>\r\n","<div class=\"hw jl\">箸</div><div class=\"def\">bacilla [virgulae] edendi(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">節</div><div class=\"def\">(文章の)membrum.</div><div class=\"def\">⇒<a href=\"entry://句\">句</a>,<a href=\"entry://文\">文</a>.</div>\r\n","<div class=\"hw jl\">節</div><div class=\"def\">(植物の)nodus.</div>\r\n","<div class=\"hw jl\">節約</div><div class=\"def\">compendium, parsimonia.</div><div class=\"def\">▼<b>～する</b> parco, sumptus minuo [circumcido], impensas corripio.</div><div class=\"ex2\">時間を～する<span class=\"ext\">tempus parce dispenso.</span></div>\r\n","<div class=\"hw jl\">範囲</div><div class=\"def\">spatium.</div><div class=\"def\">▼<b>広～</b> laxitas.</div><div class=\"def\">▼<b>広～の</b> spatiosus.</div>\r\n","<div class=\"hw jl\">築く</div><div class=\"def\">exstruo, construo.</div><div class=\"def\">⇒<a href=\"entry://建築\">建築</a>.</div>\r\n","<div class=\"hw jl\">簡単</div><div class=\"def\">▼<b>～な</b> facilis.</div><div class=\"def\">▼<b>～に</b> facile.</div><div class=\"def\">▼<b>いとも～に</b> perfacile, sine ullo labore.</div><div class=\"def\">⇒<a href=\"entry://やさしい（易しい）\">易しい</a>.</div>\r\n","<div class=\"hw jl\">簡潔</div><div class=\"def\">brevitas.</div><div class=\"def\">▼<b>～な</b> brevis, concisus.</div>\r\n","<div class=\"hw jl\">米</div><div class=\"def\">oryza.</div>\r\n","<div class=\"hw jl\">粉</div><div class=\"def\">(=粉末)pulvis;(小麦の)farina.</div><div class=\"def\">⇒<a href=\"entry://ほこり\">ほこり</a>,<a href=\"entry://ちり\">ちり</a>,<a href=\"entry://花粉\">花粉</a>.</div>\r\n","<div class=\"hw jl\">粉々</div><div class=\"def\">▼<b>～にする</b> contundo.</div>\r\n","<div class=\"hw jl\">粉砕</div><div class=\"def\">▼<b>～する</b> elido.</div><div class=\"def\">⇒<a href=\"entry://砕く\">砕く</a>.</div>\r\n","<div class=\"hw jl\">粋な</div><div class=\"def\">(=趣味の良い)elegans.</div><div class=\"def\">⇒<a href=\"entry://おしゃれ\">おしゃれ</a>.</div>\r\n","<div class=\"hw jl\">粒</div><div class=\"def\">granum, manna.</div><div class=\"def\">▼<b>一～ずつ</b> granatim.</div><div class=\"ex2\">塩の～<span class=\"ext\">salis granum [ramentum].</span></div>\r\n","<div class=\"hw jl\">粗い</div><div class=\"def\">(布地の目などが)crassus, rarus;(=ざらざらした)asper, scaber.</div><div class=\"ex2\">目の～毛織物の手ぬぐい<span class=\"ext\">villis mantele solutis.</span></div>\r\n","<div class=\"hw jl\">粗野</div><div class=\"def\">rusticitas, incultus.</div><div class=\"def\">▼<b>～な</b> agrestis, rudis, rusticus, incultus.</div>\r\n","<div class=\"hw jl\">粘り</div><div class=\"def\">(=粘性)lentitia, lentor, lenta natura.</div><div class=\"def\">▼<b>粘る</b>(=粘着する, ねばねばする)<span class=\"pos3\">[形]</span> glutinosus, lentus, viscosus, tenax.</div>\r\n","<div class=\"hw jl\">粘り強い</div><div class=\"def\">perseverans.</div><div class=\"def\">▼<b>粘り強さ</b> perseverantia.</div><div class=\"def\">⇒<a href=\"entry://根気\">根気</a>,<a href=\"entry://我慢\">我慢</a>,<a href=\"entry://忍耐\">忍耐</a>.</div>\r\n","<div class=\"hw jl\">精</div><div class=\"def\">⇒<a href=\"entry://精力\">精力</a>.</div>\r\n","<div class=\"hw jl\">精力</div><div class=\"def\">vis, vigor.</div><div class=\"def\">▼<b>～的な</b> actuosus.</div>\r\n","<div class=\"hw jl\">精密</div><div class=\"def\">⇒<a href=\"entry://精巧\">精巧</a>.</div>\r\n","<div class=\"hw jl\">精巧</div><div class=\"def\">subtilitas.</div><div class=\"def\">▼<b>～な</b> subtilis.</div>\r\n","<div class=\"hw jl\">精神</div><div class=\"def\">spiritus, animus, mens.</div><div class=\"ex2\">人は～と肉体からなる<span class=\"ext\">homo constat ex animo et corpore.</span></div>\r\n","<div class=\"hw jl\">精算</div><div class=\"def\">▼(借金を)<b> ～する</b>(aes alienum)persolvo.</div>\r\n","<div class=\"hw jl\">糊</div><div class=\"def\">gluten, glutinum.</div><div class=\"def\">▼<b>～でくっつける</b> glutino.</div>\r\n","<div class=\"hw jl\">糖尿病</div><div class=\"def\">diabetes.</div>\r\n","<div class=\"hw jl\">糞</div><div class=\"def\">stercus, merda.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">排便する<span class=\"ext\">caco.</span></div><div class=\"def\">⇒<a href=\"entry://排泄物\">排泄物</a>.</div>\r\n","<div class=\"hw jl\">糸</div><div class=\"def\">filum, linum.</div>\r\n","<div class=\"hw jl\">系列</div><div class=\"def\">consecutio, series, ordo.</div><div class=\"def\">⇒<a href=\"entry://連鎖\">連鎖</a>,<a href=\"entry://連続\">連続</a>.</div>\r\n","<div class=\"hw jl\">紀元前</div><div class=\"ex2\">～480年に<span class=\"ext\">anno quadrigentesimo octogesimo ante Christum(natum).</span></div>\r\n","<div class=\"hw jl\">約...</div><div class=\"def\">circiter, prope, fere.</div><div class=\"def\">⇒<a href=\"entry://およそ\">およそ</a>.</div>\r\n","<div class=\"hw jl\">約束</div><div class=\"def\">(行為)promissio, pollicitatio;(内容, ことば)promissum, fides.</div><div class=\"def\">▼<b>～する</b> polliceor(<i>dep</i>), promitto, fidem do.</div><div class=\"ex2\">～を破る<span class=\"ext\">fidem fallo.</span></div><div class=\"ex2\">～を守る<span class=\"ext\">fidem praesto.</span></div>\r\n","<div class=\"hw jl\">紅茶</div><div class=\"def\">(=茶)theana potio.</div>\r\n","<div class=\"hw jl\">納得</div><div class=\"def\">▼<b>～させる</b> persuadeo.</div><div class=\"def\">▼(人が)<b>～する</b> 〈alci〉 persuadetur(<i>pass</i>;<i>impers</i>).</div><div class=\"def\">⇒<a href=\"entry://説得\">説得</a>.</div>\r\n","<div class=\"hw jl\">純粋</div><div class=\"def\">sinceritas, puritas.</div><div class=\"def\">▼<b>～な</b> purus, merus, sincerus.</div><div class=\"def\">▼<b>～に</b> pure.</div>\r\n","<div class=\"hw jl\">紙</div><div class=\"def\">charta.</div><div class=\"def\">▼<b>～の</b> chartaceus.</div>\r\n","<div class=\"hw jl\">紙幣</div><div class=\"def\">charta [chartula] nummaria.</div><div class=\"def\">⇒<a href=\"entry://硬貨\">硬貨</a>.</div>\r\n","<div class=\"hw jl\">紛争</div><div class=\"def\">conflictio, conflictus, controversia.</div><div class=\"def\">⇒<a href=\"entry://不和\">不和</a>.</div>\r\n","<div class=\"hw jl\">紛失</div><div class=\"def\">amissio.</div><div class=\"def\">⇒<a href=\"entry://なくす\">なくす</a>.</div>\r\n","<div class=\"hw jl\">紛糾</div><div class=\"def\">implicatio.</div><div class=\"def\">▼<b>～させる</b> implico.</div>\r\n","<div class=\"hw jl\">素人</div><div class=\"def\">idiota.</div><div class=\"def\">▼<b>～の</b> imperitus.</div><div class=\"def\">⇒<a href=\"entry://無知\">無知</a>.</div>\r\n","<div class=\"hw jl\">素朴</div><div class=\"def\">tenuitas.</div><div class=\"def\">▼<b>～な</b> tenuis, incomptus.</div><div class=\"def\">⇒<a href=\"entry://質素\">質素</a>.</div>\r\n","<div class=\"hw jl\">素材</div><div class=\"def\">⇒<a href=\"entry://材料\">材料</a>.</div>\r\n","<div class=\"hw jl\">素直</div><div class=\"def\">▼<b>～な</b>(=従順な)obsequens, oboediens, docilis, facilis.</div>\r\n","<div class=\"hw jl\">素質</div><div class=\"def\">ingenium, indoles.</div><div class=\"def\">▼<b>～がある</b> idoneus.</div><div class=\"def\">⇒<a href=\"entry://才能\">才能</a>.</div>\r\n","<div class=\"hw jl\">紫</div><div class=\"def\">(色)viola.</div><div class=\"def\">▼<b>～(色)の</b> violaceus, ianthinus.</div>\r\n","<div class=\"hw jl\">紫外線</div><div class=\"def\">▼<b>～の</b> perviolaceus.</div>\r\n","<div class=\"hw jl\">細い</div><div class=\"def\">tenuis, gracilis.</div><div class=\"def\">⇒<a href=\"entry://繊細\">繊細</a>,<a href=\"entry://細かい\">細かい</a>.</div>\r\n","<div class=\"hw jl\">細かい</div><div class=\"def\">minutus, pusillus, parvus;(神経が)subtilis.</div><div class=\"def\">⇒<a href=\"entry://繊細\">繊細</a>,<a href=\"entry://小さい\">小さい</a>,<a href=\"entry://細い\">細い</a>.</div>\r\n","<div class=\"hw jl\">細工</div><div class=\"def\">(=技巧)ars, artificium, manus.</div>\r\n","<div class=\"hw jl\">細胞</div><div class=\"def\">cellula.</div><div class=\"def\">▼<b>～からなる</b> cellulis constans, cellulosus, cellularis.</div>\r\n","<div class=\"hw jl\">細菌</div><div class=\"def\">bacterium, microbacterium.</div><div class=\"def\">▼<b>～学</b> bacteriologia, bacteriorum disciplina.</div><div class=\"def\">▼<b>～学者</b> bacteriorum disciplina imbutus, bacteriologus, de bacteriis peritus.</div>\r\n","<div class=\"hw jl\">細部</div><div class=\"def\">particula, singulae partes(<i>pl</i>), singula(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">紳士</div><div class=\"def\">humanissimus vir, integer [bonus, frugi, justus, probus, egregius] vir.</div>\r\n","<div class=\"hw jl\">紹介</div><div class=\"def\">▼<b>～する</b> introduco, deduco, perduco, commendo.</div>\r\n","<div class=\"hw jl\">終える</div><div class=\"def\">(...を)finio, conficio, 〈+<i>dat</i>〉 finem facio.</div><div class=\"ex2\">書くことを～<span class=\"ext\">finem facio scribendi.</span></div><div class=\"ex2\">病気で生涯を～<span class=\"ext\">morbo finior(<i>pass</i>).</span></div><div class=\"def\">⇒<a href=\"entry://終わる\">終わる</a>.</div>\r\n","<div class=\"hw jl\">終わり</div><div class=\"def\">(=終末)finis, exitus, exodium.</div>\r\n","<div class=\"hw jl\">終わる</div><div class=\"def\">finem habeo [capio], exitum habeo.</div><div class=\"def\">⇒<a href=\"entry://終える\">終える</a>.</div>\r\n","<div class=\"hw jl\">終末</div><div class=\"def\">terminus.</div>\r\n","<div class=\"hw jl\">終点</div><div class=\"def\">statio terminalis, exitus.</div><div class=\"ex2\">死は人間事象の～<span class=\"ext\">mors ultima linea rerum est.</span></div><div class=\"def\">⇒<a href=\"entry://終末\">終末</a>.</div>\r\n","<div class=\"hw jl\">組み合わせる</div><div class=\"def\">compono, conjungo.</div><div class=\"def\">▼<b>組合わせ</b> compositio.</div>\r\n","<div class=\"hw jl\">組む</div><div class=\"def\">plecto.</div><div class=\"ex2\">腕組みをして座っている<span class=\"ext\">compressis manibus sedeo.</span></div><div class=\"def\">⇒<a href=\"entry://組織\">組織</a>.</div>\r\n","<div class=\"hw jl\">組合</div><div class=\"def\">societas cooperativa, collegia(<i>pl</i>), coetus;(=労働組合)opificum collegium, consociatio operariorum [artificium].</div><div class=\"def\">▼<b>同業者～</b> societates ad professionem spectantes(<i>pl</i>).</div><div class=\"def\">▼<b>～員</b> consocius.</div>\r\n","<div class=\"hw jl\">組織</div><div class=\"def\">constitutio, institutio, institutum;(人体の)corporis temperatio;(国家の)rei publicae temperatio.</div><div class=\"def\">▼<b>階級～</b> hierarchia.</div><div class=\"def\">▼<b>～する</b> constituo.</div>\r\n","<div class=\"hw jl\">経つ</div><div class=\"def\">(時間が)(=経過する)praetereo, intercedo.</div>\r\n","<div class=\"hw jl\">経営</div><div class=\"def\">(会社の)(societatis)moderatio.</div><div class=\"def\">▼(会社の)<b>～者</b>(societatis)moderator.</div><div class=\"def\">⇒<a href=\"entry://管理\">管理</a>.</div>\r\n","<div class=\"hw jl\">経度</div><div class=\"def\">longitudo.</div><div class=\"def\">⇒<a href=\"entry://緯度\">緯度</a>.</div>\r\n","<div class=\"hw jl\">経歴</div><div class=\"def\">cursus(vitae).</div><div class=\"def\">⇒<a href=\"entry://履歴\">履歴</a>.</div>\r\n","<div class=\"hw jl\">経済</div><div class=\"def\">oeconomia, res oeconomica.</div><div class=\"def\">▼(ある地域や国の)<b> ～状況</b> status rei oeconomicae(alicujus regionis vel nationis).</div><div class=\"def\">▼<b>～大国</b> oeconomicus potentatus.</div><div class=\"def\">▼<b>～学</b> oeconomia, oeconomica disciplina, doctrina de regendis et interpretandis rebus oeconomicis.</div><div class=\"def\">▼<b>～学者</b> oeconomista, doctrinae oeconomicae peritus.</div><div class=\"def\">▼<b>～の</b> oeconomicus.</div>\r\n","<div class=\"hw jl\">経済的</div><div class=\"def\">▼<b>～な</b> minimi sumptus, minimae impensae.</div>\r\n","<div class=\"hw jl\">経理</div><div class=\"def\">⇒<a href=\"entry://会計\">会計</a>.</div>\r\n","<div class=\"hw jl\">経由</div><div class=\"def\">▼(...を)<b> ～して</b> per 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">経費</div><div class=\"def\">impendium, sumptus.</div><div class=\"def\">⇒<a href=\"entry://費用\">費用</a>.</div>\r\n","<div class=\"hw jl\">経験</div><div class=\"def\">usus, experientia, experimentum.</div><div class=\"def\">▼<b>～する</b> experior(<i>dep</i>).</div><div class=\"def\">▼<b>～を積んだ, ～豊かな</b> peritus.</div><div class=\"def\">⇒<a href=\"entry://体験\">体験</a>.</div>\r\n","<div class=\"hw jl\">結ぶ</div><div class=\"def\">ligo, necto;(=一緒にする)jungo, conjungo.</div><div class=\"def\">▼<b>結びつける</b> annecto.</div><div class=\"def\">⇒<a href=\"entry://縛る\">縛る</a>.</div>\r\n","<div class=\"hw jl\">結合</div><div class=\"def\">junctura, junctio, conjunctio, coagmentum, conjugium.</div><div class=\"def\">▼<b>～する</b> conjungo, coagmento.</div><div class=\"def\">⇒<a href=\"entry://結ぶ\">結ぶ</a>,<a href=\"entry://つなぐ\">つなぐ</a>.</div>\r\n","<div class=\"hw jl\">結婚</div><div class=\"def\">conjugium, conubium, matrimonium;(式)nuptiae(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b>(=夫婦の, 婚姻の)conjugalis, conjugialis, conubialis.</div><div class=\"def\">▼<b>～(式)の</b>(=婚礼の)nuptialis.</div><div class=\"def\">▼<b>～する</b>(=男が女を娶る)〈alqm〉 in matrimonium duco, uxorem duco;(=女が男に嫁ぐ)nubo.</div><div class=\"ex2\">ある人と娘を～させる<span class=\"ext\">do alicui filiam nuptam.</span></div><div class=\"ex2\">～式を祝う<span class=\"ext\">nuptias celebro.</span></div><div class=\"def\">⇒<a href=\"entry://嫁\">嫁</a>.</div>\r\n","<div class=\"hw jl\">結局</div><div class=\"def\">denique, tandem, extremo, extremum, postremo, postremum.</div>\r\n","<div class=\"hw jl\">結晶</div><div class=\"def\">crystallina forma, crystallum.</div><div class=\"def\">▼<b>～作用</b> in crystallinam formam mutatio.</div><div class=\"def\">▼<b>～の</b> crystallinus.</div><div class=\"def\">▼<b>～化する</b> in crystallinam formam [crystallum] verto [cogo, denso].</div>\r\n","<div class=\"hw jl\">結末</div><div class=\"def\">exitus.</div><div class=\"def\">⇒<a href=\"entry://結果\">結果</a>.</div>\r\n","<div class=\"hw jl\">結果</div><div class=\"def\">eventus, eventum, effectus.</div><div class=\"def\">▼<b>その～</b> ergo, igitur.</div><div class=\"ex2\">～として起こる<span class=\"ext\">sequitur.</span></div><div class=\"ex2\">その～...となる<span class=\"ext\">ex quo efficitur.</span></div><div class=\"ex2\">～が行為を正当化する<span class=\"ext\">exitus acta probat.</span></div><div class=\"def\">⇒<a href=\"entry://起こる\">起こる</a>,<a href=\"entry://結末\">結末</a>.</div>\r\n","<div class=\"hw jl\">結構</div><div class=\"def\">(=十分に, かなり)satis.</div><div class=\"def\">⇒<a href=\"entry://かなり\">かなり</a>.</div>\r\n","<div class=\"hw jl\">結論</div><div class=\"def\">conclusio.</div><div class=\"def\">▼<b>～する</b> concludo.</div>\r\n","<div class=\"hw jl\">給与</div><div class=\"def\">⇒<a href=\"entry://給料\">給料</a>.</div>\r\n","<div class=\"hw jl\">給料</div><div class=\"def\">(operae)merces, stipendium.</div><div class=\"def\">⇒<a href=\"entry://報酬\">報酬</a>.</div>\r\n","<div class=\"hw jl\">統一</div><div class=\"def\">unitas.</div><div class=\"def\">▼(...と...を)<b> ～する</b> 〈alqd et alqd〉 unum facio.</div><div class=\"def\">⇒<a href=\"entry://統合\">統合</a>,<a href=\"entry://首尾一貫\">首尾一貫</a>.</div>\r\n","<div class=\"hw jl\">統制</div><div class=\"def\">regimen.</div><div class=\"def\">▼<b>～する</b> rego.</div><div class=\"def\">▼<b>経済～</b> oeconomicum regimen.</div><div class=\"def\">⇒<a href=\"entry://統治\">統治</a>,<a href=\"entry://統御\">統御</a>.</div>\r\n","<div class=\"hw jl\">統合</div><div class=\"def\">unio.</div><div class=\"def\">▼<b>～する</b> unio.</div>\r\n","<div class=\"hw jl\">統御</div><div class=\"def\">gubernatio.</div><div class=\"def\">▼<b>～する</b> guberno.</div>\r\n","<div class=\"hw jl\">統治</div><div class=\"def\">dominatio, dominium, imperium, gubernatio.</div><div class=\"def\">▼<b>～する</b> dominor(<i>dep</i>), impero.</div>\r\n","<div class=\"hw jl\">統計</div><div class=\"def\">▼<b>～(学)</b> rationarium, rationalis doctrina.</div><div class=\"def\">▼<b>～(学)の</b> rationalis, ad rationarium pertinens.</div>\r\n","<div class=\"hw jl\">絵</div><div class=\"def\">tabula(picta), pictura.</div><div class=\"ex2\">戦争の～<span class=\"ext\">simulacra pugnarum picta.</span></div><div class=\"ex2\">～を描く<span class=\"ext\">tabulas pingo.</span></div><div class=\"ex2\">(人の)～を描く<span class=\"ext\">pingo 〈alqm;alcis speciem;alcis simulacrum〉.</span></div><div class=\"def\">⇒<a href=\"entry://画廊\">画廊</a>,<a href=\"entry://画家\">画家</a>.</div>\r\n","<div class=\"hw jl\">絵の具</div><div class=\"def\">pigmentum, color.</div>\r\n","<div class=\"hw jl\">絵本</div><div class=\"def\">liber imaginibus ornatus.</div>\r\n","<div class=\"hw jl\">絵画</div><div class=\"def\">⇒<a href=\"entry://絵\">絵</a>.</div>\r\n","<div class=\"hw jl\">絶対</div><div class=\"def\">▼<b>～の</b> absolutus.</div><div class=\"def\">▼<b>～に</b> absolute.</div><div class=\"ex2\">私は～にそれをやらなければならない<span class=\"ext\">mihi necesse est hoc facere.</span></div>\r\n","<div class=\"hw jl\">絶望</div><div class=\"def\">desperatio.</div><div class=\"def\">▼<b>～的な</b> depseratus.</div><div class=\"def\">▼<b>～する</b> despero, spem perdo.</div><div class=\"def\">▼<b>～した</b> spe dejectus.</div>\r\n","<div class=\"hw jl\">絶滅</div><div class=\"def\">exstinctio.</div><div class=\"def\">⇒<a href=\"entry://滅びる\">滅びる</a>,<a href=\"entry://全滅\">全滅</a>.</div>\r\n","<div class=\"hw jl\">絹</div><div class=\"def\">▼<b>～(で作られたもの)</b> sericum.</div><div class=\"def\">▼<b>～の</b> sericus.</div>\r\n","<div class=\"hw jl\">継ぐ</div><div class=\"def\">⇒<a href=\"entry://継承\">継承</a>,<a href=\"entry://後継\">後継</a>,<a href=\"entry://後継ぎ\">跡継ぎ</a>.</div>\r\n","<div class=\"hw jl\">継承</div><div class=\"def\">successio.</div><div class=\"def\">▼<b>～者</b> successor.</div><div class=\"def\">▼<b>～する</b> succedo.</div>\r\n","<div class=\"hw jl\">継母</div><div class=\"def\">noverca.</div><div class=\"def\">▼<b>～のような</b> novercalis.</div><div class=\"def\">▼<b>～のようにふるまう</b> novercor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">継続</div><div class=\"def\">successio.</div><div class=\"def\">▼(職務を)<b> ～する</b> continuo.</div><div class=\"def\">⇒<a href=\"entry://連続\">連続</a>,<a href=\"entry://継承\">継承</a>,<a href=\"entry://維持\">維持</a>.</div>\r\n","<div class=\"hw jl\">続き</div><div class=\"def\">sequentia(<i>pl</i>), id quod sequitur, ea quae sequuntur(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://連続\">連続</a>.</div>\r\n","<div class=\"hw jl\">続く</div><div class=\"def\">(後に)sequor(<i>dep</i>), consequor(<i>dep</i>), subsequor(<i>dep</i>);(時間的・空間的に)continuor(<i>pass</i>);(空間的に)protendor(<i>pass</i>);(時間的に)teneo, maneo.</div>\r\n","<div class=\"hw jl\">続ける</div><div class=\"def\">(...を)〈alqd〉 continuo;(=あくまでも...し続ける)〈+<i>inf</i>〉 pergo, persevero.</div>\r\n","<div class=\"hw jl\">維持</div><div class=\"def\">conservatio, tutela.</div><div class=\"def\">▼<b>～する</b> servo, conservo, teneo, retineo.</div>\r\n","<div class=\"hw jl\">綱</div><div class=\"def\">funis, restis;(細い)funiculus, resticula;(=引き綱)remulcum.</div>\r\n","<div class=\"hw jl\">網</div><div class=\"def\">rete.</div>\r\n","<div class=\"hw jl\">綿</div><div class=\"def\">(=綿布)xylinum.</div><div class=\"def\">⇒<a href=\"entry://綿\">綿<SUB>わた</SUB></a>.</div>\r\n","<div class=\"hw jl\">綿</div><div class=\"def\">(=綿毛)lanugo.</div><div class=\"def\">▼<b>～の木</b> gossypinus, gossypion, gossypinum.</div><div class=\"def\">⇒<a href=\"entry://綿\">綿<SUB>めん</SUB></a>.</div>\r\n","<div class=\"hw jl\">綿密</div><div class=\"def\">diligentia, scrupulositas, subtilitas.</div><div class=\"def\">▼<b>～な</b> diligens, scrupulosus, subtilis, accuratus.</div><div class=\"def\">⇒<a href=\"entry://正確\">正確</a>,<a href=\"entry://精巧\">精巧</a>.</div>\r\n","<div class=\"hw jl\">緊張</div><div class=\"def\">tensio, contentio, intentio.</div><div class=\"def\">▼<b>～させる</b>(=ぴんと張る)intendo, tendo, contendo.</div>\r\n","<div class=\"hw jl\">緊急</div><div class=\"def\">(状態)instantia.</div><div class=\"def\">▼<b>～事態</b> subitum.</div><div class=\"def\">▼<b>～の</b> subitus, instans, praesens.</div>\r\n","<div class=\"hw jl\">緑</div><div class=\"def\">viriditas, viride.</div><div class=\"def\">▼<b>～の</b> viridis, virens, viridans, prasinus;(=草色の)herbeus, herbaceus.</div><div class=\"def\">▼<b>～色をしている</b> vireo, viriditatem habeo.</div><div class=\"def\">▼<b>～色にする</b> virido.</div><div class=\"def\">▼<b>～になる</b> viridor(<i>pass</i>), viridesco.</div>\r\n","<div class=\"hw jl\">線</div><div class=\"def\">linea, lineamentum.</div><div class=\"def\">⇒<a href=\"entry://曲線\">曲線</a>,<a href=\"entry://直線\">直線</a>.</div>\r\n","<div class=\"hw jl\">編む</div><div class=\"def\">texo, necto.</div>\r\n","<div class=\"hw jl\">編物</div><div class=\"def\">textum, textus.</div>\r\n","<div class=\"hw jl\">編集</div><div class=\"def\">collectio.</div><div class=\"def\">▼<b>～者</b>(=編纂者)qui librum(ex alienis libris)componit;(=発行者)scriptis vulgandis praepositus, scriptis praelo edendis procurator.</div><div class=\"def\">▼<b>～する</b> colligo, congero.</div><div class=\"ex2\">本を(他の本から)～する<span class=\"ext\">librum(ex alienis libris)compono.</span></div><div class=\"def\">⇒<a href=\"entry://執筆\">執筆</a>.</div>\r\n","<div class=\"hw jl\">緩和</div><div class=\"def\">lenimen, placatio.</div><div class=\"def\">▼<b>～する</b> lenio, placo, mitigo, relaxo.</div><div class=\"def\">⇒<a href=\"entry://軽減\">軽減</a>.</div>\r\n","<div class=\"hw jl\">緯度</div><div class=\"def\">latitudo.</div><div class=\"def\">⇒<a href=\"entry://経度\">経度</a>.</div>\r\n","<div class=\"hw jl\">練習</div><div class=\"def\">exercitatio, exercitio, commentatio, meditatio.</div><div class=\"def\">▼<b>～する</b> se exercere(← exerceo), exercito, commentor(<i>dep</i>), meditor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://訓練\">訓練</a>,<a href=\"entry://鍛える\">鍛える</a>,<a href=\"entry://習慣\">習慣</a>.</div>\r\n","<div class=\"hw jl\">縁</div><div class=\"def\">cognatio, vinculum.</div><div class=\"ex2\">詩歌に～がない<span class=\"ext\">a poetice alienus.</span></div><div class=\"def\">⇒<a href=\"entry://無縁\">無縁</a>,<a href=\"entry://きずな\">きずな</a>,<a href=\"entry://関係\">関係</a>.</div>\r\n","<div class=\"hw jl\">縁</div><div class=\"def\">ora, margo.</div><div class=\"def\">▼<b>縁どる</b> circumcludo, margino.</div>\r\n","<div class=\"hw jl\">縁起</div><div class=\"def\">(=前兆)omen, augurium, auspicium.</div><div class=\"ex2\">～の良い<span class=\"ext\">auspicatus.</span></div><div class=\"ex2\">～の悪い(=凶兆の)<span class=\"ext\">ominosus.</span></div><div class=\"ex2\">～の悪いことば<span class=\"ext\">male ominata verba.</span></div>\r\n","<div class=\"hw jl\">縄</div><div class=\"def\">funis, restis;(細い)funiculus, resticula, taenia.</div><div class=\"def\">⇒<a href=\"entry://綱\">綱</a>.</div>\r\n","<div class=\"hw jl\">縛る</div><div class=\"def\">vincio, ligo, stringo, necto.</div><div class=\"def\">▼<b>固く～</b> deligo, constringo.</div><div class=\"def\">▼<b>縛りつける</b> alligo.</div>\r\n","<div class=\"hw jl\">縦</div><div class=\"def\">longitudo.</div><div class=\"def\">▼<b>～に</b> in longitudinem.</div><div class=\"def\">⇒<a href=\"entry://幅\">幅</a>,<a href=\"entry://横\">横</a>.</div>\r\n","<div class=\"hw jl\">縫う</div><div class=\"def\">suo.</div><div class=\"def\">▼<b>縫い合わせる</b> consuo.</div><div class=\"def\">▼<b>縫いもの</b> sutura.</div>\r\n","<div class=\"hw jl\">縮める</div><div class=\"def\">contraho, corripio.</div><div class=\"def\">⇒<a href=\"entry://短縮\">短縮</a>.</div>\r\n","<div class=\"hw jl\">繁栄</div><div class=\"def\">prosperitas, prospera fortuna.</div><div class=\"def\">▼<b>～する</b> prosperor(<i>dep</i>), floreo, fortunam florentem habeo.</div>\r\n","<div class=\"hw jl\">繁盛</div><div class=\"def\">prosperitas.</div><div class=\"def\">⇒<a href=\"entry://繁栄\">繁栄</a>.</div>\r\n","<div class=\"hw jl\">繊細</div><div class=\"def\">subtilitas.</div><div class=\"def\">▼<b>～な</b> subtilis.</div>\r\n","<div class=\"hw jl\">繊維</div><div class=\"def\">fibra.</div>\r\n","<div class=\"hw jl\">織る</div><div class=\"def\">texo.</div>\r\n","<div class=\"hw jl\">織物</div><div class=\"def\">textum, textile.</div>\r\n","<div class=\"hw jl\">繕う</div><div class=\"def\">sarcio.</div><div class=\"def\">⇒<a href=\"entry://修繕\">修繕</a>,<a href=\"entry://修理\">修理</a>.</div>\r\n","<div class=\"hw jl\">繭</div><div class=\"def\">tunica.</div>\r\n","<div class=\"hw jl\">繰り上げる</div><div class=\"def\">praefero.</div>\r\n","<div class=\"hw jl\">繰り広げる</div><div class=\"def\">⇒<a href=\"entry://展開\">展開</a>.</div>\r\n","<div class=\"hw jl\">繰り返す</div><div class=\"def\">itero, renovo.</div><div class=\"def\">▼<b>繰り返し(て)</b> identidem, iterum atque iterum, crebro, frequenter, saepenumero.</div><div class=\"def\">⇒<a href=\"entry://しばしば\">しばしば</a>,<a href=\"entry://たびたび\">たびたび</a>.</div>\r\n","<div class=\"hw jl\">罪</div><div class=\"def\">noxa, noxia, peccatum.</div><div class=\"def\">▼<b>～のある, ～を犯した</b> noxius, nocens, facinorosus.</div><div class=\"def\">⇒<a href=\"entry://過失\">過失</a>,<a href=\"entry://犯罪\">犯罪</a>,<a href=\"entry://過ち\">過ち</a>.</div>\r\n","<div class=\"hw jl\">罪滅ぼし</div><div class=\"def\">piamen, piamentum, piaculum.</div><div class=\"ex2\">～の儀式を行なう<span class=\"ext\">pio.</span></div>\r\n","<div class=\"hw jl\">置く</div><div class=\"def\">pono, colloco.</div><div class=\"ex2\">下へ(=地面に)～<span class=\"ext\">depono.</span></div><div class=\"ex2\">上に～<span class=\"ext\">superpono.</span></div><div class=\"ex2\">武器を～(=戦争をやめる)<span class=\"ext\">arma depono.</span></div><div class=\"ex2\">彼は手許に置いていた奴隷を送った<span class=\"ext\">servum misit quem secum habebat.</span></div>\r\n","<div class=\"hw jl\">罰</div><div class=\"def\">poena, supplicium, animadversio.</div><div class=\"def\">⇒<a href=\"entry://罰する\">罰する</a>.</div>\r\n","<div class=\"hw jl\">罰する</div><div class=\"def\">punio, punior(<i>dep</i>), mulco, castigo, animadverto.</div><div class=\"def\">⇒<a href=\"entry://罰\">罰</a>.</div>\r\n","<div class=\"hw jl\">署名</div><div class=\"def\">subscriptio, nomen subscriptum.</div><div class=\"def\">▼<b>～する</b> subscribo.</div>\r\n","<div class=\"hw jl\">罵倒</div><div class=\"def\">maledictum, convicium, verborum contumelia, probrum.</div><div class=\"def\">▼<b>～する</b> maledico.</div>\r\n","<div class=\"hw jl\">羊</div><div class=\"def\">(雌の)ovis;(雄の)aries;(虚勢した)vervex;(=小羊)agnus(<i>m</i>), agna(<i>f</i>).</div>\r\n","<div class=\"hw jl\">羊飼い</div><div class=\"def\">pastor, upilio, opilio.</div><div class=\"def\">▼<b>～の</b> pastoralis.</div>\r\n","<div class=\"hw jl\">美</div><div class=\"def\">pulchritudo, venustas;(=容姿の美しさ)forma, species.</div><div class=\"def\">⇒<a href=\"entry://美しい\">美しい</a>.</div>\r\n","<div class=\"hw jl\">美しい</div><div class=\"def\">pulcher, formosus, decorus, venustus.</div><div class=\"def\">▼<b>美しさ</b> pulchritudo, amoenitas, venustas.</div>\r\n","<div class=\"hw jl\">美人</div><div class=\"def\">(未婚の)virgo formosa;(既婚の)mulier pulchritudine eximia.</div><div class=\"ex2\">～コンテスト<span class=\"ext\">certamen pulchritudinis.</span></div>\r\n","<div class=\"hw jl\">美容</div><div class=\"def\">(=化粧)faciei medicamen, vultum fucandi ars.</div><div class=\"def\">▼<b>～の</b>(=化粧の)cosmeticus, ad artem vultus fucandi pertinens.</div><div class=\"def\">⇒<a href=\"entry://化粧\">化粧</a>.</div>\r\n","<div class=\"hw jl\">美容師</div><div class=\"def\">mundi muliebris perita(<i>f</i>), cosmetes.</div><div class=\"def\">⇒<a href=\"entry://美容\">美容</a>,<a href=\"entry://化粧\">化粧</a>.</div>\r\n","<div class=\"hw jl\">美徳</div><div class=\"def\">virtus.</div><div class=\"def\">⇒<a href=\"entry://悪徳\">悪徳</a>.</div>\r\n","<div class=\"hw jl\">美術</div><div class=\"def\">⇒<a href=\"entry://芸術\">芸術</a>.</div>\r\n","<div class=\"hw jl\">美食</div><div class=\"def\">gula.</div><div class=\"def\">▼<b>～家</b> homo palati peritissimus, subtilis gula, palatum doctum et eruditum.</div><div class=\"ex2\">私は～家だ<span class=\"ext\">ingenua est mihi gula.</span></div>\r\n","<div class=\"hw jl\">群れ</div><div class=\"def\">grex;(家畜の)pecuaria;(牛や馬などの)armentum, armentorum grex;(小さな家畜の)pecus, pecorum grex;(人の)(=群衆)turba.</div><div class=\"def\">⇒<a href=\"entry://群衆\">群衆</a>.</div>\r\n","<div class=\"hw jl\">群生本能</div><div class=\"def\">congregandi naturalis instinctus.</div><div class=\"def\">⇒<a href=\"entry://群衆\">群衆</a>,<a href=\"entry://群れ\">群れ</a>.</div>\r\n","<div class=\"hw jl\">群衆</div><div class=\"def\">turba, multitudo, frequentia.</div><div class=\"def\">⇒<a href=\"entry://群れ\">群れ</a>.</div>\r\n","<div class=\"hw jl\">義務</div><div class=\"def\">officium, munus.</div><div class=\"def\">▼<b>～を果たす</b> officio fungor(<i>dep</i>), officium facio [praesto], officio satisfacio.</div>\r\n","<div class=\"hw jl\">義理</div><div class=\"def\">(=恩義)officium, debitum;(=姻戚関係)affinitas.</div><div class=\"def\">▼<b>～の父</b>(=妻・夫の父)socer;(=継父)vitricus.</div><div class=\"def\">▼<b>～の母</b>(=姑, 妻・夫の母)socrus;(=継母)noverca.</div><div class=\"def\">▼<b>～の兄弟</b>(=夫の兄弟)levir;(=妻の兄弟)uxoris frater;(=姉妹の夫)sororis vir.</div><div class=\"def\">▼<b>～の姉妹</b>(=兄弟の妻, 夫の姉妹)glos.</div>\r\n","<div class=\"hw jl\">羽根</div><div class=\"def\">penna;(=羽毛)pluma.</div><div class=\"def\">▼<b>～でおおわれた</b> plumeus.</div><div class=\"def\">⇒<a href=\"entry://翼\">翼</a>.</div>\r\n","<div class=\"hw jl\">羽毛</div><div class=\"def\">pluma.</div><div class=\"def\">▼<b>～でおおわれた, ～のような</b> plumeus.</div>\r\n","<div class=\"hw jl\">翌日</div><div class=\"def\"><span class=\"pos3\">[名]</span> posterus dies.</div><div class=\"def\">━<span class=\"pos3\">[副]</span> postridie.</div><div class=\"def\">▼<b>～の朝に</b> postero die mane, mane postridie.</div><div class=\"ex2\">～に延期する<span class=\"ext\">in posterum(diem)differo.</span></div>\r\n","<div class=\"hw jl\">習う</div><div class=\"def\">disco.</div>\r\n","<div class=\"hw jl\">習得</div><div class=\"def\">▼<b>～する</b> disco.</div>\r\n","<div class=\"hw jl\">習慣</div><div class=\"def\">consuetudo, assuetudo, mos, victus.</div><div class=\"def\">▼(...する)<b> ～である</b> mos [moris] est 〈+<i>inf</i>〉.</div><div class=\"def\">▼(...を)<b>～としている</b> soleo 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw jl\">翻訳</div><div class=\"def\">(行為)versio, conversio, translatio;(本)liber translatus.</div><div class=\"def\">▼<b>～する</b> verto, converto, transfero, reddo.</div><div class=\"ex2\">ある言語から別の言語に～する<span class=\"ext\">ex alia lingua in aliam transfero.</span></div><div class=\"ex2\">ラテン語に～する<span class=\"ext\">in Latinum(con)verto / Latine reddo.</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">直訳<span class=\"ext\">translatio ad verbum expressa.</span></div><div class=\"cf\">直訳する<span class=\"ext\">verbum verbo reddo.</span></div><div class=\"cf\">ラテン語への逐語訳<span class=\"ext\">conversatio in Latinum ad verbum.</span></div><div class=\"def\">⇒<a href=\"entry://通訳\">通訳</a>.</div>\r\n","<div class=\"hw jl\">翼</div><div class=\"def\">ala.</div><div class=\"def\">⇒<a href=\"entry://羽根\">羽根</a>.</div>\r\n","<div class=\"hw jl\">老いる</div><div class=\"def\">senesco.</div><div class=\"def\">▼<b>老いた</b> senex.</div><div class=\"def\">▼<b>老い</b> senectus.</div><div class=\"def\">⇒<a href=\"entry://老年\">老年</a>.</div>\r\n","<div class=\"hw jl\">老ける</div><div class=\"def\">senesco, insenesco, senex fio.</div>\r\n","<div class=\"hw jl\">老人</div><div class=\"def\">senex.</div><div class=\"def\">▼<b>～の</b> senex, senilis.</div>\r\n","<div class=\"hw jl\">老化</div><div class=\"def\">senectus.</div><div class=\"def\">▼<b>～する</b> senesco, aetate procedo.</div>\r\n","<div class=\"hw jl\">老年</div><div class=\"def\">senectus.</div><div class=\"def\">▼<b>～の</b> senex, senilis.</div><div class=\"def\">⇒<a href=\"entry://老人\">老人</a>.</div>\r\n","<div class=\"hw jl\">考え</div><div class=\"def\">(=思考)cogitatio, ratio, mens, animus;(=意見)sententia, cogitatum.</div><div class=\"ex2\">私の～によると<span class=\"ext\">ad meam rationem.</span></div>\r\n","<div class=\"hw jl\">考える</div><div class=\"def\">cogito, sentio, censeo, puto, existimo, arbitror(<i>dep</i>), reor(<i>dep</i>), intellego.</div><div class=\"ex2\">何かをしたいと考えている<span class=\"ext\">habeo in animo facere aliquid.</span></div>\r\n","<div class=\"hw jl\">考古学</div><div class=\"def\">antiquitatis scientia, archeologia.</div><div class=\"def\">▼<b>～者</b> archeologiae studiosus [peritus].</div><div class=\"def\">▼<b>～の</b> ad antiquitatis doctrinam spectans, archeologicus.</div>\r\n","<div class=\"hw jl\">考察</div><div class=\"def\">consideratio, contemplatio.</div><div class=\"def\">▼<b>～する</b> considero, contemplor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://熟慮\">熟慮</a>.</div>\r\n","<div class=\"hw jl\">考慮</div><div class=\"def\">⇒<a href=\"entry://考え\">考え</a>,<a href=\"entry://考える\">考える</a>.</div>\r\n","<div class=\"hw jl\">考案</div><div class=\"def\">inventio.</div><div class=\"def\">▼<b>～者</b> inventor.</div><div class=\"def\">▼<b>～されたもの</b> inventum.</div><div class=\"def\">▼<b>～する</b> invenio.</div><div class=\"def\">⇒<a href=\"entry://発見\">発見</a>,<a href=\"entry://発明\">発明</a>.</div>\r\n","<div class=\"hw jl\">耐える</div><div class=\"def\">(...を)〈+<i>acc</i>〉 patior(<i>dep</i>), duro, fero, tolero, sustineo, perfero.</div><div class=\"def\">▼(精神的・身体的に)<b>耐えられない</b> intolerabilis;(精神的に)intolerandus.</div><div class=\"def\">▼<b>耐えられないほど</b> intoleranter.</div><div class=\"def\">⇒<a href=\"entry://忍耐\">忍耐</a>,<a href=\"entry://根気\">根気</a>,<a href=\"entry://我慢\">我慢</a>,<a href=\"entry://不寛容\">不寛容</a>.</div>\r\n","<div class=\"hw jl\">耕地</div><div class=\"def\">ager cultus.</div>\r\n","<div class=\"hw jl\">耳</div><div class=\"def\">auris.</div><div class=\"ex2\">～を貸す<span class=\"ext\">aures do.</span></div>\r\n","<div class=\"hw jl\">耽る</div><div class=\"def\">(=没頭する, 溺れる)(...に)〈in alqd〉 se mergere(← mergo).</div><div class=\"ex2\">快楽に～(=溺れる)<span class=\"ext\">se totum voluptatibus tradere(← trado)/ in voluptates procumbo.</span></div><div class=\"ex2\">学問に～(=没頭する)<span class=\"ext\">se studiis immergere(← immergo).</span></div>\r\n","<div class=\"hw jl\">聖典</div><div class=\"def\">sacrae litterae(<i>pl</i>), sacra scriptura.</div>\r\n","<div class=\"hw jl\">聖書</div><div class=\"def\">sacra scriptura.</div>\r\n","<div class=\"hw jl\">聖職者</div><div class=\"def\">clericus, clerici(<i>pl</i>);(集合的に)clerus.</div><div class=\"def\">▼<b>～の</b> clericus, clericalis.</div><div class=\"def\">⇒<a href=\"entry://祭司\">祭司</a>.</div>\r\n","<div class=\"hw jl\">聞く・聴く</div><div class=\"def\">audio;(注意して)ausculto.</div><div class=\"def\">▼<b>～こと</b> auditio, auditus.</div><div class=\"def\">▼<b>～人</b> auditor.</div>\r\n","<div class=\"hw jl\">聞こえる</div><div class=\"def\">(=聴覚に知覚される)auribus percipior(<i>pass</i>);(=音がする)sono.</div>\r\n","<div class=\"hw jl\">職人</div><div class=\"def\">opifex, faber.</div><div class=\"def\">▼<b>～の</b> faber.</div>\r\n","<div class=\"hw jl\">職務</div><div class=\"def\">munus.</div><div class=\"ex2\">～に従事している<span class=\"ext\">occupatus.</span></div><div class=\"ex2\">～に忠実な<span class=\"ext\">officiosus.</span></div><div class=\"ex2\">～から解放された<span class=\"ext\">immunis.</span></div><div class=\"def\">⇒<a href=\"entry://義務\">義務</a>,<a href=\"entry://仕事\">仕事</a>.</div>\r\n","<div class=\"hw jl\">職員</div><div class=\"def\">minister.</div>\r\n","<div class=\"hw jl\">職業</div><div class=\"def\">quaestus, professio.</div>\r\n","<div class=\"hw jl\">肉</div><div class=\"def\">caro.</div><div class=\"def\">▼<b>牛～</b>(caro)bubula.</div><div class=\"def\">▼<b>子牛～</b> vitulina.</div><div class=\"def\">▼<b>羊～</b> agnina.</div><div class=\"def\">▼<b>豚～</b> suilla.</div>\r\n","<div class=\"hw jl\">肉体</div><div class=\"def\">corpus.</div><div class=\"def\">▼<b>～の</b> corporeus.</div>\r\n","<div class=\"hw jl\">肉屋</div><div class=\"def\">(人)lanius;(店)laniena, carnaria taberna.</div>\r\n","<div class=\"hw jl\">肌</div><div class=\"def\">(=皮膚)cutis.</div>\r\n","<div class=\"hw jl\">肖像</div><div class=\"def\">imago, effigies.</div><div class=\"def\">▼<b>～画</b> imago picta.</div><div class=\"ex2\">哲学者の～<span class=\"ext\">philosophus pictus.</span></div>\r\n","<div class=\"hw jl\">肘</div><div class=\"def\">cubitum, cubitus.</div>\r\n","<div class=\"hw jl\">肝臓</div><div class=\"def\">jecur.</div>\r\n","<div class=\"hw jl\">肥料</div><div class=\"def\">laetamen.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">肥料によって肥やす<span class=\"ext\">laetifico.</span></div>\r\n","<div class=\"hw jl\">肥沃</div><div class=\"def\">(=豊饒)fertilitas, fecunditas, ubertas.</div><div class=\"def\">▼<b>～な</b> fertilis, fecundus, ferax, uber.</div>\r\n","<div class=\"hw jl\">肥満</div><div class=\"def\">▼<b>～した</b> pinguis.</div><div class=\"def\">⇒<a href=\"entry://太る\">太る</a>.</div>\r\n","<div class=\"hw jl\">肩</div><div class=\"def\">umerus;(両方の)umeri(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">肩書き</div><div class=\"def\">appellatio, titulus.</div><div class=\"def\">⇒<a href=\"entry://称号\">称号</a>.</div>\r\n","<div class=\"hw jl\">肯定</div><div class=\"def\">affirmatio.</div><div class=\"def\">▼<b>～する</b> affirmo, aio.</div><div class=\"def\">⇒<a href=\"entry://否定\">否定</a>.</div>\r\n","<div class=\"hw jl\">育つ</div><div class=\"def\">⇒<a href=\"entry://成長\">成長</a>.</div>\r\n","<div class=\"hw jl\">育てる</div><div class=\"def\">educo, nutrio, nutrico, nutricor(<i>dep</i>), alo.</div><div class=\"def\">⇒<a href=\"entry://養う\">養う</a>,<a href=\"entry://教育\">教育</a>.</div>\r\n","<div class=\"hw jl\">育児</div><div class=\"def\">(=養育, 保育)nutrimen, nutrimentum, educatio.</div>\r\n","<div class=\"hw jl\">肺</div><div class=\"def\">pulmo.</div><div class=\"def\">▼<b>～の</b> pulmoneus, pulmonalis.</div><div class=\"def\">▼<b>～炎</b> pulmonia.</div>\r\n","<div class=\"hw jl\">胃</div><div class=\"def\">stomachus.</div>\r\n","<div class=\"hw jl\">胆</div><div class=\"def\">⇒<a href=\"entry://肝臓\">肝臓</a>.</div>\r\n","<div class=\"hw jl\">胆汁</div><div class=\"def\">fel, bilis.</div><div class=\"def\">⇒<a href=\"entry://憂鬱\">憂鬱</a>.</div>\r\n","<div class=\"hw jl\">背</div><div class=\"def\">▼<b>～が高い</b> procerus, grandis.</div><div class=\"def\">▼<b>～の高い男</b> homo procerae staturae.</div><div class=\"def\">▼<b>～の低い男</b> homo corpore brevis.</div><div class=\"def\">⇒<a href=\"entry://背中\">背中</a>,<a href=\"entry://身長\">身長</a>.</div>\r\n","<div class=\"hw jl\">背く</div><div class=\"def\">deficio, non oboedio, non pareo.</div>\r\n","<div class=\"hw jl\">背中</div><div class=\"def\">dorsum, tergum.</div>\r\n","<div class=\"hw jl\">背後</div><div class=\"def\">tergum.</div><div class=\"def\">▼<b>～に</b> post tergum.</div><div class=\"def\">▼<b>～から</b> a tergo.</div>\r\n","<div class=\"hw jl\">背景</div><div class=\"def\">▼(絵画で)<b> 黒色の～</b> niger color substratus.</div><div class=\"def\">▼<b>舞台～</b>(=書割)scaenae tabula.</div>\r\n","<div class=\"hw jl\">背負う</div><div class=\"def\">(umeris)sustineo, succollo;(=荷を背負って運ぶ)bajulo.</div><div class=\"ex2\">(彼らは)エトナ火山より重い荷物を背負っていると言う<span class=\"ext\">onus se Aetna gravius dicunt sustinere.</span></div>\r\n","<div class=\"hw jl\">胡椒</div><div class=\"def\">piper.</div><div class=\"ex2\">～の粒<span class=\"ext\">granum piperis.</span></div>\r\n","<div class=\"hw jl\">胡麻</div><div class=\"def\">sesamum.</div><div class=\"def\">▼<b>～の</b> sesaminus.</div>\r\n","<div class=\"hw jl\">胴</div><div class=\"def\">truncus.</div>\r\n","<div class=\"hw jl\">胸</div><div class=\"def\">pectus;(=胸部)thorax.</div><div class=\"def\">⇒<a href=\"entry://乳房\">乳房</a>,<a href=\"entry://肺\">肺</a>.</div>\r\n","<div class=\"hw jl\">能力</div><div class=\"def\">facultas, potestas, ingenium.</div><div class=\"def\">▼<b>～がある</b> valeo.</div><div class=\"def\">⇒<a href=\"entry://才能\">才能</a>,<a href=\"entry://できる\">できる</a>,<a href=\"entry://有能\">有能</a>.</div>\r\n","<div class=\"hw jl\">脂肪</div><div class=\"def\">adeps, sebum, pingue.</div><div class=\"ex2\">豚の～<span class=\"ext\">adeps suilla.</span></div><div class=\"ex2\">牛の～<span class=\"ext\">sebum bubulinum.</span></div><div class=\"def\">⇒<a href=\"entry://油・脂\">油</a>.</div>\r\n","<div class=\"hw jl\">脅かす</div><div class=\"def\">terreo, terrifico.</div>\r\n","<div class=\"hw jl\">脅す</div><div class=\"def\">minor(<i>dep</i>), territo.</div><div class=\"def\">▼<b>～こと</b>(=脅し)minae(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://脅かす\">脅かす</a>.</div>\r\n","<div class=\"hw jl\">脅迫</div><div class=\"def\">minae(<i>pl</i>), minatio, comminatio.</div><div class=\"def\">▼<b>～的に</b> minaciter, minanter.</div><div class=\"def\">▼<b>～する</b> minor(<i>dep</i>), comminor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">脇</div><div class=\"def\">(=わきのした)axilla, ala;(=側面)latus.</div>\r\n","<div class=\"hw jl\">脈</div><div class=\"def\">(=血管)vena;(=脈拍)pulsus arteriarum [venarum].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">静脈<span class=\"ext\">vena.</span></div><div class=\"cf\">動脈<span class=\"ext\">arteria.</span></div>\r\n","<div class=\"hw jl\">脱ぐ</div><div class=\"def\">(服を)(vestem)pono;(帽子を)caput aperio.</div><div class=\"def\">▼(人の服を)<b>脱がす</b> 〈alqm veste〉 exuo, 〈alci vestimenta〉 extraho.</div><div class=\"def\">⇒<a href=\"entry://かぶる\">かぶる</a>,<a href=\"entry://着る\">着る</a>.</div>\r\n","<div class=\"hw jl\">脱線</div><div class=\"def\">(列車の)(hamaxostichi)exorbitatio.</div><div class=\"def\">▼<b>～する</b> exorbito, ex orbitis exeo.</div>\r\n","<div class=\"hw jl\">脱走</div><div class=\"def\">effugium, desertio, fuga.</div><div class=\"def\">▼<b>～者</b> transfuga, desertor.</div><div class=\"def\">▼<b>～兵</b> fugitivus.</div><div class=\"def\">▼<b>～する</b> fugio, effugio, transfugio, desero, in fugam sese dare(← do)[conjicere(← conjicio)], fugam facio.</div>\r\n","<div class=\"hw jl\">脳</div><div class=\"def\">cerebrum, cerebellum.</div>\r\n","<div class=\"hw jl\">腐る</div><div class=\"def\">putresco, puteo, putrefio.</div><div class=\"def\">▼<b>腐り始める</b> putesco.</div><div class=\"def\">▼<b>腐った</b> puter, putris, putridus, putidus.</div><div class=\"def\">⇒<a href=\"entry://腐敗\">腐敗</a>.</div>\r\n","<div class=\"hw jl\">腐敗</div><div class=\"def\">tabes, putor, corruptio, caries.</div><div class=\"def\">▼<b>～した</b> puter, putris, putridus, putidus, corruptus, cariosus.</div><div class=\"def\">▼<b>～する</b> putresco, putesco, corrumpor(<i>pass</i>).</div>\r\n","<div class=\"hw jl\">腕</div><div class=\"def\">brachium.</div><div class=\"def\">▼<b>～の</b> brachialis.</div>\r\n","<div class=\"hw jl\">腕時計</div><div class=\"def\">horologium brachiale.</div>\r\n","<div class=\"hw jl\">腕輪</div><div class=\"def\">(=ブレスレット)armilla.</div>\r\n","<div class=\"hw jl\">腰</div><div class=\"def\">lumbi(<i>pl</i>), renes(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">腰掛け</div><div class=\"def\">sedes, sella.</div><div class=\"def\">▼<b>長い～</b> subsellium.</div><div class=\"def\">▼<b>低い～</b> sedecula.</div><div class=\"def\">⇒<a href=\"entry://椅子\">椅子</a>,<a href=\"entry://座席\">座席</a>.</div>\r\n","<div class=\"hw jl\">腸</div><div class=\"def\">intestinum.</div><div class=\"def\">⇒<a href=\"entry://ソーセージ\">ソーセージ</a>.</div>\r\n","<div class=\"hw jl\">腹</div><div class=\"def\">venter.</div><div class=\"def\">▼<b>～を立てる</b> irascor(<i>dep</i>).</div><div class=\"def\">▼<b>～を立てた</b> iratus, iracundus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">下腹<span class=\"ext\">alvus, abdomen.</span></div>\r\n","<div class=\"hw jl\">腿</div><div class=\"def\">femur.</div>\r\n","<div class=\"hw jl\">膨らむ</div><div class=\"def\">tumesco, intumesco, turgesco.</div><div class=\"def\">▼<b>膨らんでいる</b> tumeo.</div><div class=\"def\">▼<b>膨らませる</b> tumefacio.</div><div class=\"def\">▼<b>膨らんだもの</b> tumor.</div><div class=\"def\">⇒<a href=\"entry://膨張\">膨張</a>.</div>\r\n","<div class=\"hw jl\">膨張</div><div class=\"def\">inflatio, expansio.</div><div class=\"def\">▼<b>～させる</b> inflo, expando.</div>\r\n","<div class=\"hw jl\">膿</div><div class=\"def\">pus.</div>\r\n","<div class=\"hw jl\">臆病</div><div class=\"def\">timiditas.</div><div class=\"def\">▼<b>～な</b> timidus, formidolosus.</div><div class=\"def\">▼<b>～にも</b> timide.</div>\r\n","<div class=\"hw jl\">臨時</div><div class=\"def\">▼<b>～の</b>(=一時的な)temporarius, temporalis.</div><div class=\"def\">▼<b>～に</b>(=一時的に)ad tempus, interim.</div>\r\n","<div class=\"hw jl\">自信</div><div class=\"def\">confidentia, fidentia, fiducia.</div><div class=\"def\">▼<b>～過剰</b> nimia fiducia.</div><div class=\"def\">▼<b>～のある, ～満々の</b> confidens, fidens.</div><div class=\"def\">▼<b>～をもって, ～満々で</b> confidenter, fidenter.</div>\r\n","<div class=\"hw jl\">自分</div><div class=\"def\">▼<b>～(自身)の</b>(三人称)suus.</div><div class=\"def\">▼<b>～(自身)を</b>(三人称)se.</div><div class=\"def\">▼<b>～(自身)に</b>(三人称)sibi.(一・二人称はそれぞれの人称代名詞を用いる).</div><div class=\"ex2\">真理は～で～を守る<span class=\"ext\">veritas se ipsa defendit.</span></div><div class=\"def\">⇒<a href=\"entry://自身\">自身</a>.</div>\r\n","<div class=\"hw jl\">自制</div><div class=\"def\">moderatio, modestia, continentia.</div><div class=\"def\">▼<b>～した</b> continens, sobrius.</div><div class=\"def\">▼<b>～して</b> continenter.</div><div class=\"def\">▼<b>～する</b>(=自分自身を制御する)se continere(← contineo).</div>\r\n","<div class=\"hw jl\">自動</div><div class=\"def\">▼<b>～の</b> automatus, automatarius.</div><div class=\"def\">▼<b>～機械</b> automatum, automatarium.</div>\r\n","<div class=\"hw jl\">自動車</div><div class=\"def\">autocinetum(vehiculum), vehiculum automatarium, automataria raeda, autoraeda, autovehiculum.</div><div class=\"def\">▼<b>～修理工場</b> officina vehiculis sarciendis.</div>\r\n","<div class=\"hw jl\">自尊心</div><div class=\"def\">superbia.</div><div class=\"def\">▼<b>～のある</b> superbus.</div><div class=\"def\">⇒<a href=\"entry://傲慢\">傲慢</a>,<a href=\"entry://虚栄\">虚栄</a>,<a href=\"entry://うぬぼれ\">うぬぼれ</a>.</div>\r\n","<div class=\"hw jl\">自己</div><div class=\"def\">⇒<a href=\"entry://自分\">自分</a>,<a href=\"entry://自身\">自身</a>.</div>\r\n","<div class=\"hw jl\">自慢</div><div class=\"def\">jactatio, jactantia, magniloquentia.</div><div class=\"def\">▼<b>～する</b> se jactare(← jacto), glorior(<i>dep</i>), tumeo.</div>\r\n","<div class=\"hw jl\">自殺</div><div class=\"def\">mors voluntaria [quaesita, arcessita], interitus voluntarius, nex voluntaria.</div><div class=\"def\">▼<b>～する</b> mortem [necem] sibi consciscere(← conscisco), se necare(← neco)[occidere(← occido)], se ipsum interficere(← interficio).</div>\r\n","<div class=\"hw jl\">自治</div><div class=\"def\">libertas.</div>\r\n","<div class=\"hw jl\">自然</div><div class=\"def\">natura.</div><div class=\"def\">▼<b>～な</b> naturalis.</div><div class=\"def\">▼<b>～の</b> nativus.</div><div class=\"def\">▼<b>～に</b> naturaliter.</div>\r\n","<div class=\"hw jl\">自由</div><div class=\"def\">libertas, licentia.</div><div class=\"def\">▼<b>～な</b> liber, licens.</div><div class=\"def\">▼<b>～に</b> libere, licenter.</div>\r\n","<div class=\"hw jl\">自発的</div><div class=\"def\">▼<b>～な</b> voluntarius.</div><div class=\"def\">▼<b>～に</b>(sua)voluntate, voluntarie, ultro.</div>\r\n","<div class=\"hw jl\">自覚</div><div class=\"def\">conscientia.</div><div class=\"def\">▼<b>～した</b> conscius.</div>\r\n","<div class=\"hw jl\">自身</div><div class=\"def\"><span class=\"pos3\">[代]</span> ipse. </div><div class=\"ex2\">カエサル～<span class=\"ext\">ipse Caesar.</span></div><div class=\"def\">⇒<a href=\"entry://自分\">自分</a>.</div>\r\n","<div class=\"hw jl\">自転車</div><div class=\"def\">birota.</div><div class=\"def\">▼<b>～に乗る人</b> birotarius.</div><div class=\"def\">▼<b>～競走</b> certamen birotulariorum.</div><div class=\"def\">▼<b>～に乗る</b> pedalia verso, pedalibus utor(<i>dep</i>), birotam pedibus propello.</div><div class=\"def\">▼<b>～の</b> birotalis.</div>\r\n","<div class=\"hw jl\">臭い</div><div class=\"def\"><span class=\"pos3\">[形]</span> putidus, putridus, foetidus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> male oleo, puteo, foeteo.</div><div class=\"def\">▼<b>臭くなる</b> putesco.</div><div class=\"def\">⇒<a href=\"entry://悪臭\">悪臭</a>.</div>\r\n","<div class=\"hw jl\">至る</div><div class=\"def\">(=届く, 達する)pertineo;(=到着する)pervenio, advenio.</div><div class=\"def\">▼(...に)<b>～まで</b> usque ad 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">至る所</div><div class=\"def\">▼<b>～に[で]</b> ubique, passim.</div><div class=\"def\">▼<b>～から</b>(=あらゆる方向から)undique, ex omnibus partibus.</div><div class=\"ex2\">世界の～に<span class=\"ext\">in diversis orbis terrarum partibus.</span></div>\r\n","<div class=\"hw jl\">至急</div><div class=\"def\">quam celerrime, summa celeritate.</div><div class=\"def\">⇒<a href=\"entry://緊急\">緊急</a>,<a href=\"entry://急いで\">急いで</a>,<a href=\"entry://すぐ\">すぐ</a>.</div>\r\n","<div class=\"hw jl\">致命的</div><div class=\"def\">▼<b>～な</b> mortifer, capitalis, letalis, letifer.</div>\r\n","<div class=\"hw jl\">臼</div><div class=\"def\">(=挽き臼)mola.</div>\r\n","<div class=\"hw jl\">興奮</div><div class=\"def\">concitatio, commotio.</div><div class=\"def\">▼<b>～させる</b> commoveo, excito, concito.</div><div class=\"def\">▼<b>～した</b> concitatus, commotus.</div>\r\n","<div class=\"hw jl\">舌</div><div class=\"def\">lingua.</div>\r\n","<div class=\"hw jl\">舞台</div><div class=\"def\">scaena, proscaenia(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> scaenicus.</div>\r\n","<div class=\"hw jl\">舞踊</div><div class=\"def\">saltatio, saltatus.</div><div class=\"def\">⇒<a href=\"entry://ダンス\">ダンス</a>.</div>\r\n","<div class=\"hw jl\">航海</div><div class=\"def\">(maris)navigatio, via maris.</div><div class=\"def\">▼<b>～する</b>(in mari)navigo.</div><div class=\"def\">⇒<a href=\"entry://航行\">航行</a>.</div>\r\n","<div class=\"hw jl\">航空</div><div class=\"def\">aeria navigatio.</div><div class=\"def\">▼<b>～機</b>(=飛行機)aeronavis, aerovehiculum, aeroplanum.</div><div class=\"def\">▼<b>～会社</b> societas aeronautica.</div><div class=\"def\">▼<b>～の</b> aeronauticus.</div>\r\n","<div class=\"hw jl\">航空便</div><div class=\"def\">▼<b>～で</b>(送る)aeriā viā(mitto).</div><div class=\"ex2\">～の手紙<span class=\"ext\">epistula aeriā viā missa.</span></div>\r\n","<div class=\"hw jl\">航行</div><div class=\"def\">navigatio.</div><div class=\"def\">▼<b>～する</b> navigo, in nave vehor(<i>pass</i>).</div><div class=\"def\">⇒<a href=\"entry://航海\">航海</a>.</div>\r\n","<div class=\"hw jl\">航路</div><div class=\"def\">cursus.</div><div class=\"def\">▼<b>海上～</b> cursus maritimus.</div>\r\n","<div class=\"hw jl\">舵</div><div class=\"def\">gubernaculum.</div><div class=\"def\">▼<b>～を取る</b> guberno.</div><div class=\"def\">▼<b>～を取る人</b> gubernator.</div><div class=\"def\">▼<b>～を取ること</b> gubernatio.</div>\r\n","<div class=\"hw jl\">船</div><div class=\"def\">navis;(小さな)navicula, linter, lembus, scapha.</div><div class=\"def\">⇒<a href=\"entry://軍艦\">軍艦</a>,<a href=\"entry://船長\">船長</a>,<a href=\"entry://いかだ\">いかだ</a>.</div>\r\n","<div class=\"hw jl\">船乗り</div><div class=\"def\">nauta.</div><div class=\"def\">▼<b>～の</b> nauticus.</div>\r\n","<div class=\"hw jl\">船長</div><div class=\"def\">navis magister;(軍艦の)navarchus;(商船の)navicularius.</div>\r\n","<div class=\"hw jl\">良心</div><div class=\"def\">(bona)conscientia.</div>\r\n","<div class=\"hw jl\">良識</div><div class=\"def\">prudentia, mens sana, animi sanitas, sapientia, ratio.</div><div class=\"def\">▼<b>～の欠如</b> insipientia.</div><div class=\"def\">▼<b>～ある</b> prudens, sapiens.</div><div class=\"def\">▼<b>～のない</b> insipiens, fatuus, stultus.</div><div class=\"def\">⇒<a href=\"entry://常識\">常識</a>.</div>\r\n","<div class=\"hw jl\">色</div><div class=\"def\">color.</div>\r\n","<div class=\"hw jl\">芝居</div><div class=\"def\">⇒<a href=\"entry://劇\">劇</a>.</div>\r\n","<div class=\"hw jl\">芝生</div><div class=\"def\">pratulum.</div>\r\n","<div class=\"hw jl\">花</div><div class=\"def\">flos.</div><div class=\"def\">▼<b>小さい～</b> flosculus.</div><div class=\"def\">▼<b>～の</b> floreus.</div><div class=\"def\">▼<b>～の咲いている, ～盛りの</b> florens, floridus.</div><div class=\"def\">▼<b>～が咲く, ～盛りである</b> floreo.</div>\r\n","<div class=\"hw jl\">花嫁</div><div class=\"def\">nova nupta.</div>\r\n","<div class=\"hw jl\">花火</div><div class=\"def\">spectaculum pyrotechnicum.</div>\r\n","<div class=\"hw jl\">花瓶</div><div class=\"def\">vas;(小さな)vasculum.</div>\r\n","<div class=\"hw jl\">花粉</div><div class=\"def\">fecundus pulvis.</div>\r\n","<div class=\"hw jl\">芸</div><div class=\"def\">(=技芸)ars.</div><div class=\"def\">⇒<a href=\"entry://芸術\">芸術</a>.</div>\r\n","<div class=\"hw jl\">芸人</div><div class=\"def\">artifex.</div>\r\n","<div class=\"hw jl\">芸術</div><div class=\"def\">ars.</div><div class=\"def\">▼<b>～作品</b> artificium.</div><div class=\"def\">▼<b>～家</b> artifex.</div><div class=\"def\">▼<b>～的な</b> artificiosus.</div>\r\n","<div class=\"hw jl\">芽</div><div class=\"def\">gemma, oculus.</div><div class=\"def\">▼(草木が)<b> ～を出す</b> gemmo, gemmasco, gemmas moveo.</div>\r\n","<div class=\"hw jl\">苔</div><div class=\"def\">muscus.</div>\r\n","<div class=\"hw jl\">若い</div><div class=\"def\">adulescens, juvenis.</div>\r\n","<div class=\"hw jl\">若者</div><div class=\"def\">juvenis, adulescens.</div><div class=\"def\">▼<b>～の</b> juvenis, juvenilis.</div>\r\n","<div class=\"hw jl\">若返る</div><div class=\"def\">reviresco.</div>\r\n","<div class=\"hw jl\">苦い</div><div class=\"def\">amarus, acer.</div><div class=\"def\">▼<b>少し～</b> subamarus.</div><div class=\"def\">▼<b>苦くなる</b> inamaresco.</div><div class=\"def\">▼<b>～味</b> amaror, amarities, amaritudo.</div>\r\n","<div class=\"hw jl\">苦しい</div><div class=\"def\">acerbus, gravis, aeger.</div><div class=\"def\">▼<b>苦しみ</b> dolor, cruciatus, acerbitas, aegritudo.</div>\r\n","<div class=\"hw jl\">苦しむ</div><div class=\"def\">laboro, doleo.</div><div class=\"ex2\">借金で～<span class=\"ext\">ex aere alieno laboro.</span></div>\r\n","<div class=\"hw jl\">苦しめる</div><div class=\"def\">crucio, excrucio, ango, torqueo.</div>\r\n","<div class=\"hw jl\">苦にする</div><div class=\"def\">(...を)〈alqd〉 sibi grave ducere(← duco).</div><div class=\"def\">▼<b>苦にしない</b> 〈alqd〉 sibi leve putare(← puto).</div><div class=\"ex2\">老年を～<span class=\"ext\">sibi senectutem gravem esse sentire(← sentio).</span></div>\r\n","<div class=\"hw jl\">苦労</div><div class=\"def\">labor.</div><div class=\"def\">▼<b>～を伴う[の多い]</b> laboriosus.</div><div class=\"def\">▼<b>～する</b> laboro.</div><div class=\"def\">▼<b>～して</b> laboriose.</div><div class=\"ex2\">～の種<span class=\"ext\">cura.</span></div><div class=\"def\">⇒<a href=\"entry://努力\">努力</a>.</div>\r\n","<div class=\"hw jl\">苦心</div><div class=\"def\">labor.</div><div class=\"def\">▼<b>～する</b> laboro.</div><div class=\"def\">▼<b>～して仕上げる</b> elaboro.</div><div class=\"def\">⇒<a href=\"entry://苦労\">苦労</a>,<a href=\"entry://努力\">努力</a>.</div>\r\n","<div class=\"hw jl\">苦情</div><div class=\"def\">(=不平, 抗議)querela, conquestio, questus, querimonia.</div><div class=\"def\">▼<b>～を述べる</b> conqueror(<i>dep</i>), queror(<i>dep</i>).</div><div class=\"def\">▼<b>～を訴える</b> accuso.</div>\r\n","<div class=\"hw jl\">苦手</div><div class=\"def\">▼(...が)<b> ～な</b> 〈in re〉 rudis, non peritus.</div><div class=\"def\">⇒<a href=\"entry://得意\">得意</a>.</div>\r\n","<div class=\"hw jl\">苦痛</div><div class=\"def\">dolor, malum, tormentum;(ひどい)cruciatus.</div>\r\n","<div class=\"hw jl\">英語</div><div class=\"def\">anglica(lingua).</div><div class=\"def\">▼<b>～の</b> anglicus.</div><div class=\"def\">▼<b>～で</b> anglice.</div>\r\n","<div class=\"hw jl\">英雄</div><div class=\"def\">heros(<i>m</i>), herois(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://偉人\">偉人</a>.</div>\r\n","<div class=\"hw jl\">茂み</div><div class=\"def\">dumetum, frutex, fruticetum.</div><div class=\"def\">▼<b>～でおおわれた</b> fruticosus.</div><div class=\"def\">⇒<a href=\"entry://やぶ\">やぶ</a>.</div>\r\n","<div class=\"hw jl\">茎</div><div class=\"def\">caulis, scapus, stipula, calamus.</div>\r\n","<div class=\"hw jl\">茶</div><div class=\"def\">(飲料)theana potio.</div>\r\n","<div class=\"hw jl\">草</div><div class=\"def\">herba, gramen.</div><div class=\"def\">▼<b>～でおおわれた</b> herbidus, herbosus.</div>\r\n","<div class=\"hw jl\">草原</div><div class=\"def\">pascuum, pratum.</div><div class=\"def\">▼<b>～の</b> pratensis.</div><div class=\"def\">⇒<a href=\"entry://牧草地\">牧草地</a>.</div>\r\n","<div class=\"hw jl\">草地</div><div class=\"def\">pratum.</div>\r\n","<div class=\"hw jl\">荒い</div><div class=\"def\">(性格や言動が)(=粗野な)ferus, asper, crassus.</div><div class=\"ex2\">金遣いが～人<span class=\"ext\">profligator.</span></div><div class=\"def\">⇒<a href=\"entry://きつい\">きつい</a>.</div>\r\n","<div class=\"hw jl\">荒らす</div><div class=\"def\">populo, populor(<i>dep</i>), depopulo, depopulor(<i>dep</i>), vasto, devasto, vexo, turbo, perturbo, spolio, lacero.</div>\r\n","<div class=\"hw jl\">荒れた</div><div class=\"def\">asper;(海・波・天候などが)turbulentus, procellosus, nimbosus.</div>\r\n","<div class=\"hw jl\">荒れる</div><div class=\"def\">(=荒廃する)vastesco.</div><div class=\"def\">⇒<a href=\"entry://荒らす\">荒らす</a>.</div>\r\n","<div class=\"hw jl\">荒野</div><div class=\"def\">desertum, vastitas, incultae regiones(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">荘重</div><div class=\"def\">⇒<a href=\"entry://壮大\">壮大</a>.</div>\r\n","<div class=\"hw jl\">荷</div><div class=\"def\">onus, sarcina.</div><div class=\"def\">▼<b>～を積んだ</b> onustus.</div>\r\n","<div class=\"hw jl\">荷物</div><div class=\"def\">sarcinae(<i>pl</i>), impedimenta(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">莫大</div><div class=\"def\">immensitas, immensum.</div><div class=\"def\">▼<b>～な</b> immensus.</div><div class=\"def\">⇒<a href=\"entry://無限\">無限</a>.</div>\r\n","<div class=\"hw jl\">菓子</div><div class=\"def\">placenta, crustum, tragemata(<i>pl</i>), cuppediae(<i>pl</i>);(お供えやお祝い用の)libum.</div><div class=\"def\">▼<b>～屋</b> pistor(<i>m</i>), pistrix(<i>f</i>), cuppedinarius.</div>\r\n","<div class=\"hw jl\">華やか</div><div class=\"def\">(=華美)magnificentia.</div><div class=\"def\">▼<b>～な</b> splendidus, magnificus.</div><div class=\"def\">▼<b>～に</b> splendide, magnifice.</div>\r\n","<div class=\"hw jl\">萎縮</div><div class=\"def\">▼<b>～する</b> tabesco, marcesco.</div>\r\n","<div class=\"hw jl\">落ちつき</div><div class=\"def\">tranquillitas.</div>\r\n","<div class=\"hw jl\">落ちつく</div><div class=\"def\">▼<b>落ちつかせる</b> sedo, tranquillo.</div><div class=\"def\">▼<b>落ちついた</b> sedatus, lenis, tranquillus.</div><div class=\"def\">▼<b>落ちついて</b> sedate, tranquille. </div><div class=\"ex2\">(心が)落ちついている<span class=\"ext\">tranquillo animo sum.</span></div><div class=\"def\">⇒<a href=\"entry://穏やか\">穏やか</a>.</div>\r\n","<div class=\"hw jl\">落ちる</div><div class=\"def\">cado, decido;(=すべり落ちる)labor(<i>dep</i>), delabor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://落選\">落選</a>.</div>\r\n","<div class=\"hw jl\">落ち度</div><div class=\"def\">⇒<a href=\"entry://過ち\">過ち</a>,<a href=\"entry://過失\">過失</a>,<a href=\"entry://失敗\">失敗</a>.</div>\r\n","<div class=\"hw jl\">落ち葉</div><div class=\"def\">folia decidua(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">落とす</div><div class=\"def\">demitto.</div>\r\n","<div class=\"hw jl\">落下</div><div class=\"def\">casus, lapsus.</div><div class=\"def\">▼<b>～する</b> cado, decido, labor(<i>dep</i>), delabor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">落書き</div><div class=\"def\">tabula inficetissime picta.</div><div class=\"def\">▼<b>～する</b> inficetissime pingo.</div>\r\n","<div class=\"hw jl\">落第</div><div class=\"def\">exitus contrarius, repulsa.</div>\r\n","<div class=\"hw jl\">落選</div><div class=\"def\">repulsa.</div>\r\n","<div class=\"hw jl\">葉</div><div class=\"def\">folium, frons.</div><div class=\"def\">▼<b>～の(茂った)</b> frondeus, frondosus.</div><div class=\"def\">▼<b>～をつけている</b><span class=\"pos3\">[動]</span> frondeo.</div><div class=\"def\">▼<b>～をつける</b> frondesco.</div>\r\n","<div class=\"hw jl\">葉書</div><div class=\"def\">▼<b>(郵便)～</b> chartula cursoria [cursualis].</div><div class=\"def\">▼<b>絵～</b> chartula variata.</div>\r\n","<div class=\"hw jl\">著しい</div><div class=\"def\">(=顕著な)insignis, conspicuus, egregius, eximius, praestans.</div>\r\n","<div class=\"hw jl\">著作権</div><div class=\"def\">jus proprietatis librariae.</div>\r\n","<div class=\"hw jl\">葦</div><div class=\"def\">calamus, harundo, canna.</div><div class=\"ex2\">羊飼いの～笛<span class=\"ext\">fistula.</span></div>\r\n","<div class=\"hw jl\">葬儀</div><div class=\"def\">⇒<a href=\"entry://葬式\">葬式</a>.</div>\r\n","<div class=\"hw jl\">葬式</div><div class=\"def\">funus, exsequiae(<i>pl</i>), funebria(<i>pl</i>), suprema(officia)(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> funebris, funebralis, exsequialis.</div><div class=\"def\">▼<b>～を行なう</b> funus [exsequias] celebro, funeri operam do, funus facio, exsequias duco.</div>\r\n","<div class=\"hw jl\">蒸し風呂</div><div class=\"def\">sudatorium.</div>\r\n","<div class=\"hw jl\">蒸す</div><div class=\"def\">(=蒸気で調理する)coquo(in [ex, cum])vapore aquae calidae.</div>\r\n","<div class=\"hw jl\">蒸気</div><div class=\"def\">vapor.</div><div class=\"def\">▼<b>～で満たす[おおう]</b> vaporo.</div>\r\n","<div class=\"hw jl\">蒸発</div><div class=\"def\">evaporatio, vaporatio.</div><div class=\"def\">▼<b>～する</b> evaporo.</div>\r\n","<div class=\"hw jl\">蓋</div><div class=\"def\">operculum, operimentum.</div>\r\n","<div class=\"hw jl\">薄い</div><div class=\"def\">tenuis, gracilis;(液体や色が)(=薄められた)dilutus.</div><div class=\"def\">⇒<a href=\"entry://厚い\">厚い</a>.</div>\r\n","<div class=\"hw jl\">薄める</div><div class=\"def\">(水で)diluo.</div>\r\n","<div class=\"hw jl\">薄暗い</div><div class=\"def\">pallidus.</div>\r\n","<div class=\"hw jl\">薪</div><div class=\"def\">(arida)ligna(<i>pl</i>).</div><div class=\"def\">▼<b>小さな～</b> cremia(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">薫製</div><div class=\"def\">▼<b>～にする</b> infumo, in fumo suspendo, fumo sicco.</div><div class=\"ex2\">～のハム<span class=\"ext\">fumosa perna.</span></div>\r\n","<div class=\"hw jl\">薬</div><div class=\"def\">(=医薬品, 薬剤)medicina, medicamentum, medicamen, remedium.</div><div class=\"def\">▼<b>～屋</b>(=薬を作り, 売る場所)pharmacopolum, pharmaceutica taberna, taberna medicamentaria;(=薬売り, 薬剤師)pharmacopola, medicamentarius(<i>m</i>).</div><div class=\"def\">▼<b>～になる</b>(=薬効のある)medicatus, medicabilis, medicinas continens.</div><div class=\"def\">⇒<a href=\"entry://飲む\">飲む</a>.</div>\r\n","<div class=\"hw jl\">薬品</div><div class=\"def\">medicamentum.</div><div class=\"def\">⇒<a href=\"entry://薬\">薬</a>.</div>\r\n","<div class=\"hw jl\">薬局</div><div class=\"def\">pharmacopolium, pharmaceutica taberna, taberna [officina] medicamentaria.</div><div class=\"def\">⇒<a href=\"entry://薬\">薬</a>.</div>\r\n","<div class=\"hw jl\">薬指</div><div class=\"def\">digitus medicus, digitus medicinalis, anularius digitus, digitus(qui est)minimo proximus.</div><div class=\"def\">⇒<a href=\"entry://指\">指</a>.</div>\r\n","<div class=\"hw jl\">虐待</div><div class=\"def\">vexatio, injuria.</div><div class=\"def\">▼<b>～する人</b> vexator.</div><div class=\"def\">▼<b>～する</b>(行為によって)male mulco;(ことばによって)maledictis vexo.</div>\r\n","<div class=\"hw jl\">虐殺</div><div class=\"def\">occisio, caedes, strages, internecio, trucidatio, jugulum.</div><div class=\"def\">▼<b>～する</b> trucido, jugulo.</div><div class=\"def\">⇒<a href=\"entry://殺す\">殺す</a>,<a href=\"entry://殺害\">殺害</a>.</div>\r\n","<div class=\"hw jl\">虚栄</div><div class=\"def\">vanitas, vanum.</div><div class=\"def\">▼<b>～心</b> gloria.</div><div class=\"def\">⇒<a href=\"entry://傲慢\">傲慢</a>,<a href=\"entry://うぬぼれ\">うぬぼれ</a>.</div>\r\n","<div class=\"hw jl\">虚構</div><div class=\"def\">fictum, commentum.</div><div class=\"def\">▼<b>～の</b> fictus, commenticius.</div>\r\n","<div class=\"hw jl\">虜</div><div class=\"def\">▼(比喩的に)<b> ～の</b> obnoxius, captivus.</div>\r\n","<div class=\"hw jl\">虫</div><div class=\"def\">bestiola, insectum.</div>\r\n","<div class=\"hw jl\">虹</div><div class=\"def\">arcus(caelestis).</div>\r\n","<div class=\"hw jl\">蚊</div><div class=\"def\">culex.</div>\r\n","<div class=\"hw jl\">蚕</div><div class=\"def\">bombyx.</div><div class=\"def\">▼<b>～の</b> bombycinus.</div>\r\n","<div class=\"hw jl\">蛇</div><div class=\"def\">serpens, anguis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">ボア<span class=\"ext\">boa.</span></div><div class=\"cf\">ニシキヘビ<span class=\"ext\">python.</span></div><div class=\"cf\">マムシ, 毒蛇<span class=\"ext\">vipera.</span></div>\r\n","<div class=\"hw jl\">蛇口</div><div class=\"def\">epitonion, epitonium.</div>\r\n","<div class=\"hw jl\">蛍光</div><div class=\"def\">▼<b>～(性)</b> fluorescentia.</div><div class=\"def\">▼<b>～を発する</b> fluorescens.</div>\r\n","<div class=\"hw jl\">蛙</div><div class=\"def\">rana.</div>\r\n","<div class=\"hw jl\">蛸</div><div class=\"def\">polypus.</div>\r\n","<div class=\"hw jl\">蜂</div><div class=\"def\">▼<b>蜜～</b> apis.</div><div class=\"def\">▼<b>雀～</b> vespa.</div>\r\n","<div class=\"hw jl\">蜂蜜</div><div class=\"def\">mel, mella.</div><div class=\"def\">▼<b>～色</b> melleus color.</div><div class=\"def\">▼<b>～の</b> melleus.</div><div class=\"def\">▼<b>～のように甘い</b> mellitus.</div>\r\n","<div class=\"hw jl\">蜘蛛</div><div class=\"def\">aranea.</div><div class=\"def\">▼<b>小さな～</b> araneola, araneolus.</div><div class=\"def\">▼<b>～の巣</b> araneae textura [tela].</div>\r\n","<div class=\"hw jl\">蜜</div><div class=\"def\">(=蜂蜜)mel.</div><div class=\"def\">▼<b>～酒</b> hydromellum.</div><div class=\"def\">▼<b>～の入った</b>(=甘い)mulsus, mulseus, mellitus.</div><div class=\"def\">⇒<a href=\"entry://蜂蜜\">蜂蜜</a>.</div>\r\n","<div class=\"hw jl\">蝋</div><div class=\"def\">cera.</div><div class=\"def\">▼<b>～の, ～でできた</b> cereus.</div><div class=\"def\">▼<b>～を塗られた</b> ceratus.</div><div class=\"def\">▼<b>～を塗る</b> cero.</div>\r\n","<div class=\"hw jl\">融合</div><div class=\"def\">confusio.</div><div class=\"def\">▼<b>～させる</b> confundo.</div>\r\n","<div class=\"hw jl\">融資</div><div class=\"def\">pecuniae suppeditatio [commodatio].</div><div class=\"def\">▼<b>～する</b> pecuniam suppedito [commodo].</div>\r\n","<div class=\"hw jl\">融通</div><div class=\"def\">(=心や行動の柔軟性)flexibilitas, facilitas.</div><div class=\"def\">▼<b>～が利く</b>(=柔軟な)flexibilis, mollis.</div><div class=\"def\">▼(金を)<b> ～する</b>(=貸す)(pecuniam)credo.</div><div class=\"def\">⇒<a href=\"entry://貸す\">貸す</a>.</div>\r\n","<div class=\"hw jl\">螺旋</div><div class=\"def\">helice, spira.</div><div class=\"def\">▼<b>～状の</b> helicae similis, ad helicam pertinens, in spirae modum convolutus.</div>\r\n","<div class=\"hw jl\">蟹</div><div class=\"def\">cancer.</div><div class=\"def\">▼<b>～座</b> cancer.</div>\r\n","<div class=\"hw jl\">蟻</div><div class=\"def\">formica.</div>\r\n","<div class=\"hw jl\">血</div><div class=\"def\">(=血液)sanguis;(殺傷において流される)cruor.</div><div class=\"def\">▼<b>～の</b> sanguineus.</div>\r\n","<div class=\"hw jl\">血圧</div><div class=\"def\">sanguinis pressus.</div><div class=\"def\">▼<b>高～</b> hypertensio.</div><div class=\"def\">▼<b>低～</b> hypotonia, sanguinis pressus exiguus.</div>\r\n","<div class=\"hw jl\">血液</div><div class=\"def\">sanguis.</div><div class=\"ex2\">～の循環<span class=\"ext\">sanguinis circulatio.</span></div>\r\n","<div class=\"hw jl\">血相</div><div class=\"def\">⇒<a href=\"entry://顔色\">顔色</a>.</div>\r\n","<div class=\"hw jl\">血管</div><div class=\"def\">vena.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">静脈<span class=\"ext\">vena.</span></div><div class=\"cf\">動脈<span class=\"ext\">arteria.</span></div>\r\n","<div class=\"hw jl\">血統</div><div class=\"def\">(=血筋)sanguis, genus, stirps.</div>\r\n","<div class=\"hw jl\">行き止まり</div><div class=\"def\">(=袋小路)fundula.</div><div class=\"ex2\">～だ<span class=\"ext\">iter exitum non habet.</span></div>\r\n","<div class=\"hw jl\">行き過ぎ</div><div class=\"def\">(=過度)immoderatio, immodestia, nimium, nimietas.</div><div class=\"def\">▼<b>行き過ぎた</b>(=過度の)nimius, immodicus, immodestus.</div>\r\n","<div class=\"hw jl\">行く</div><div class=\"def\">eo, vado, gradior(<i>dep</i>), incedo.</div><div class=\"def\">▼<b>急いで～</b>(=急行する)contendo, propero, advolo.</div>\r\n","<div class=\"hw jl\">行なう</div><div class=\"def\">ago, facio;(習慣的に, 繰り返し)factito.</div><div class=\"def\">▼<b>行なわれる</b> fio.</div><div class=\"ex2\">すべてを一度に～必要があった<span class=\"ext\">omnia uno tempore erant agenda.</span></div><div class=\"ex2\">その時, それはたやすく行なわれた<span class=\"ext\">quod tum facile fiebat.</span></div>\r\n","<div class=\"hw jl\">行事</div><div class=\"def\">sollemne.</div><div class=\"def\">⇒<a href=\"entry://儀式\">儀式</a>,<a href=\"entry://祭り\">祭り</a>.</div>\r\n","<div class=\"hw jl\">行列</div><div class=\"def\">pompa, incessus.</div>\r\n","<div class=\"hw jl\">行動</div><div class=\"def\">actio, actus.</div><div class=\"def\">⇒<a href=\"entry://行為\">行為</a>,<a href=\"entry://ふるまう\">ふるまう</a>.</div>\r\n","<div class=\"hw jl\">行政</div><div class=\"def\">reipublicae administratio [procuratio].</div>\r\n","<div class=\"hw jl\">行楽</div><div class=\"def\">excursio.</div><div class=\"def\">⇒<a href=\"entry://遠足\">遠足</a>,<a href=\"entry://遠出\">遠出</a>.</div>\r\n","<div class=\"hw jl\">行為</div><div class=\"def\">actus, actio;(成された)factum.</div><div class=\"def\">▼<b>～者</b> actor.</div><div class=\"ex2\">正しくなされた～<span class=\"ext\">recte facta.</span></div><div class=\"def\">⇒<a href=\"entry://行なう\">行なう</a>.</div>\r\n","<div class=\"hw jl\">行進</div><div class=\"def\">agmen.</div><div class=\"def\">⇒<a href=\"entry://前進\">前進</a>,<a href=\"entry://行列\">行列</a>.</div>\r\n","<div class=\"hw jl\">術語</div><div class=\"def\">propria verba 〈alcis rei〉.</div><div class=\"def\">▼<b>～的な</b> ad propria verba pertinens.</div>\r\n","<div class=\"hw jl\">街区</div><div class=\"def\">(regio の下位区分)vicus.</div>\r\n","<div class=\"hw jl\">街道</div><div class=\"def\">via.</div><div class=\"ex2\">アッピア～<span class=\"ext\">Via Appia.</span></div>\r\n","<div class=\"hw jl\">衛星</div><div class=\"def\">satelles.</div><div class=\"def\">▼<b>人工～</b> satelles artificiosus.</div>\r\n","<div class=\"hw jl\">衛生</div><div class=\"def\">(=健康の保全)curatio valetudinis.</div><div class=\"def\">▼<b>～学</b> valetudinis sustentandae scientia.</div>\r\n","<div class=\"hw jl\">衝撃</div><div class=\"def\">ictus.</div><div class=\"def\">⇒<a href=\"entry://衝突\">衝突</a>.</div>\r\n","<div class=\"hw jl\">衝突</div><div class=\"def\">collisus, conflictus, flictus.</div><div class=\"def\">▼<b>～する</b> offendo, offenso, confligo, concurro, collidor(<i>pass</i>).</div><div class=\"ex2\">物体の～<span class=\"ext\">duorum inter se corporum conflictio.</span></div><div class=\"ex2\">互いに～し合う<span class=\"ext\">inter se collidi(<i>pass</i>).</span></div>\r\n","<div class=\"hw jl\">衣服</div><div class=\"def\">⇒<a href=\"entry://服\">服</a>.</div>\r\n","<div class=\"hw jl\">衣装</div><div class=\"def\">vestitus, cultus, habitus, ornamenta(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">表</div><div class=\"def\">(=外)exterior pars;(=前面)frons.</div><div class=\"def\">▼<b>～で</b>(=外で)foris, sub divo.</div><div class=\"def\">▼<b>～に</b>(=外へ)foras, sub divum.</div><div class=\"def\">⇒<a href=\"entry://裏\">裏</a>.</div>\r\n","<div class=\"hw jl\">表</div><div class=\"def\">album, tabula, index.</div>\r\n","<div class=\"hw jl\">表わす</div><div class=\"def\">(=見せる, あらわにする)ostendo, exhibeo, monstro, aperio;(ことばや芸術によって)(=表現する)exprimo, declaro.</div>\r\n","<div class=\"hw jl\">表情</div><div class=\"def\">vultus, os, frons, vultūs [oris] species, vultūs habitus.</div>\r\n","<div class=\"hw jl\">表現</div><div class=\"def\">expressio, repraesentatio.</div><div class=\"def\">▼<b>～する</b> exprimo, repraesento.</div>\r\n","<div class=\"hw jl\">表面</div><div class=\"def\">superficies.</div>\r\n","<div class=\"hw jl\">衰える</div><div class=\"def\">deficio, languesco, relanguesco.</div><div class=\"def\">⇒<a href=\"entry://衰弱\">衰弱</a>.</div>\r\n","<div class=\"hw jl\">衰弱</div><div class=\"def\">debilitas, defectus, languor.</div><div class=\"def\">▼<b>～した</b> debilis, defectus, languidus.</div><div class=\"def\">▼<b>～する</b> deficio.</div><div class=\"def\">▼<b>～している</b> langueo.</div><div class=\"def\">⇒<a href=\"entry://衰える\">衰える</a>.</div>\r\n","<div class=\"hw jl\">袋</div><div class=\"def\">saccus.</div><div class=\"def\">▼<b>小さな～</b> sacculus.</div>\r\n","<div class=\"hw jl\">袖</div><div class=\"def\">(=長袖)manicae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">被告</div><div class=\"def\">(人)reus(<i>m</i>), rea(<i>f</i>).</div><div class=\"def\">⇒<a href=\"entry://告発\">告発</a>.</div>\r\n","<div class=\"hw jl\">裁く</div><div class=\"def\">judico.</div><div class=\"def\">⇒<a href=\"entry://判決\">判決</a>.</div>\r\n","<div class=\"hw jl\">裁判</div><div class=\"def\">judicium.</div><div class=\"def\">▼<b>～官</b> judex.</div><div class=\"def\">⇒<a href=\"entry://判決\">判決</a>,<a href=\"entry://法廷\">法廷</a>,<a href=\"entry://訴訟\">訴訟</a>,<a href=\"entry://告訴\">告訴</a>.</div>\r\n","<div class=\"hw jl\">裁縫</div><div class=\"def\">⇒<a href=\"entry://縫う\">縫う</a>.</div>\r\n","<div class=\"hw jl\">裂く</div><div class=\"def\">findo;(=切り裂く)rimor(<i>dep</i>).</div><div class=\"def\">▼<b>裂け目</b> fissum, fissura, rima.</div><div class=\"def\">▼<b>裂けた</b> rimosus.</div><div class=\"def\">⇒<a href=\"entry://割る\">割る</a>,<a href=\"entry://割れる\">割れる</a>,<a href=\"entry://引き裂く\">引き裂く</a>.</div>\r\n","<div class=\"hw jl\">装備</div><div class=\"def\">ornamentum, ornatus.</div><div class=\"def\">▼<b>～する</b> orno, comparo.</div>\r\n","<div class=\"hw jl\">装置</div><div class=\"def\">machinatio, machinamentum.</div>\r\n","<div class=\"hw jl\">装飾</div><div class=\"def\">ornamentus, decus.</div><div class=\"def\">⇒<a href=\"entry://飾る\">飾る</a>.</div>\r\n","<div class=\"hw jl\">裏</div><div class=\"def\">(=裏面, 裏側)aversa facies, aversum latus.</div><div class=\"def\">▼<b>紙の～</b> aversa charta, tergum.</div><div class=\"def\">▼<b>手の～</b> manus aversa.</div><div class=\"def\">⇒<a href=\"entry://表\">表</a>.</div>\r\n","<div class=\"hw jl\">裏切る</div><div class=\"def\">prodo, trado, vendo.</div><div class=\"def\">▼<b>裏切り</b> proditio.</div><div class=\"def\">▼<b>裏切り者</b> proditor(<i>m</i>), proditrix(<i>f</i>), traditor(<i>m</i>).</div>\r\n","<div class=\"hw jl\">裏返す</div><div class=\"def\">inverto.</div>\r\n","<div class=\"hw jl\">裕福</div><div class=\"def\">(=富裕)divitiae(<i>pl</i>), opulentia, fortunae(<i>pl</i>).</div><div class=\"def\">▼<b>～な</b>(=富裕な, 金持ちの)copiosus, locuples, fortunatus, dives, opulentus, opulens.</div>\r\n","<div class=\"hw jl\">補う</div><div class=\"def\">suppleo.</div><div class=\"def\">▼<b>～こと</b>(=補足, 補充)supplementum.</div>\r\n","<div class=\"hw jl\">補充</div><div class=\"def\">supplementum, suppletio.</div><div class=\"def\">▼<b>～の</b> suppletorius.</div><div class=\"def\">▼<b>～する</b> suppleo.</div>\r\n","<div class=\"hw jl\">補助</div><div class=\"def\">(=援助, 補助手段)auxilium, adjumentum, subsidium, praesidium.</div>\r\n","<div class=\"hw jl\">補強</div><div class=\"def\">firmamentum.</div><div class=\"def\">▼(壁を)<b> ～する</b>(parietis)soliditatem confirmo.</div><div class=\"def\">▼<b>～になる</b> firmamento esse(← sum).</div>\r\n","<div class=\"hw jl\">裸</div><div class=\"def\">▼<b>～の</b> nudus, nudatus, denudatus.</div><div class=\"def\">▼<b>～にする</b> nudo, denudo.</div><div class=\"def\">▼<b>～である</b> nullas vestes habeo.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">半裸の<span class=\"ext\">seminudus.</span></div>\r\n","<div class=\"hw jl\">裸足</div><div class=\"def\">▼<b>～で</b> nudis pedibus, nudo pede.</div>\r\n","<div class=\"hw jl\">製品</div><div class=\"def\">opus.</div><div class=\"def\">▼<b>手工業～</b> opus manu factum.</div>\r\n","<div class=\"hw jl\">製造</div><div class=\"def\">fabricatio.</div><div class=\"def\">▼<b>～する</b> facio, fabricor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://生産\">生産</a>.</div>\r\n","<div class=\"hw jl\">複写</div><div class=\"def\">(=写し)descriptio, exemplum.</div><div class=\"def\">▼<b>～する</b> describo, exscribo.</div>\r\n","<div class=\"hw jl\">複数</div><div class=\"def\">pluralis numerus, pluralitas, multitudo.</div><div class=\"def\">▼<b>～の</b> pluralis, multus.</div><div class=\"def\">⇒<a href=\"entry://単数\">単数</a>.</div>\r\n","<div class=\"hw jl\">複製</div><div class=\"def\">imago imitativa, imago imaginem imitans.</div><div class=\"def\">⇒<a href=\"entry://コピー\">コピー</a>,<a href=\"entry://複写\">複写</a>.</div>\r\n","<div class=\"hw jl\">複雑</div><div class=\"def\">▼<b>～な</b> multiplex.</div>\r\n","<div class=\"hw jl\">襟</div><div class=\"def\">colli tegmentum [tegmen].</div>\r\n","<div class=\"hw jl\">襲う</div><div class=\"def\">(=攻撃する, 襲いかかる)assulto, appeto, impeto, impugno, incesso, incido, ingruo, invado, oppugno, aggredior(<i>dep</i>), pertempto;(病気や害悪が)corripio.</div><div class=\"ex2\">私は痛風に襲われる<span class=\"ext\">pedum dolore corripior.</span></div><div class=\"def\">⇒<a href=\"entry://攻撃\">攻撃</a>.</div>\r\n","<div class=\"hw jl\">西</div><div class=\"def\">occidens.</div><div class=\"def\">▼<b>～の</b> occidentalis.</div><div class=\"def\">⇒<a href=\"entry://東\">東</a>.</div>\r\n","<div class=\"hw jl\">西洋</div><div class=\"def\">obeuntis solis partes(<i>pl</i>), occidens.</div><div class=\"def\">▼<b>～人</b> ad occasum habitantes(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> occidentalis.</div><div class=\"def\">▼<b>～的な</b> ad occidentis cultum humanum versus.</div><div class=\"def\">⇒<a href=\"entry://東洋\">東洋</a>.</div>\r\n","<div class=\"hw jl\">要するに</div><div class=\"def\">(=一言で言えば)uno verbo, ne multa(dicam);(=結局, 結論を言えば)ad summam, in summa, denique, postremo;(=もうこれ以上話さないために)ut plura non dicam, ut non dicam, ut nihil aliud dicam.</div>\r\n","<div class=\"hw jl\">要件</div><div class=\"def\">▼(...の)<b> あらゆる～を備えている</b> 〈alcis rei〉 onmnes numeros habeo.</div>\r\n","<div class=\"hw jl\">要塞</div><div class=\"def\">castrum.</div>\r\n","<div class=\"hw jl\">要求</div><div class=\"def\">(行為)expostulatio, postulatio;(物)postulatum, requisitum.</div><div class=\"def\">▼<b>～する</b> exigo, expostulo, posco, requiro, peto.</div><div class=\"def\">⇒<a href=\"entry://求める\">求める</a>,<a href=\"entry://請求\">請求</a>,<a href=\"entry://頼む\">頼む</a>.</div>\r\n","<div class=\"hw jl\">要点</div><div class=\"def\">caput, (res)summa, cardo, id quod caput est.</div><div class=\"def\">⇒<a href=\"entry://重要\">重要</a>,<a href=\"entry://主要\">主要</a>.</div>\r\n","<div class=\"hw jl\">要約</div><div class=\"def\">summarium, epitome, epitoma.</div><div class=\"def\">▼<b>～する</b> breviter complector(<i>dep</i>), breviter contraho.</div><div class=\"def\">⇒<a href=\"entry://要点\">要点</a>.</div>\r\n","<div class=\"hw jl\">要素</div><div class=\"def\">elementum.</div>\r\n","<div class=\"hw jl\">要請</div><div class=\"def\">(行為)postulatio, petitio;(物)postulatum.</div><div class=\"def\">▼<b>～する</b> postulo, peto.</div><div class=\"def\">⇒<a href=\"entry://要求\">要求</a>.</div>\r\n","<div class=\"hw jl\">見える</div><div class=\"def\"><span class=\"pos3\">[動]</span> videor(<i>pass</i>), conspicior(<i>pass</i>), appareo.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> aspectabilis.</div><div class=\"def\">⇒<a href=\"entry://明白\">明白</a>.</div>\r\n","<div class=\"hw jl\">見かけ</div><div class=\"def\">(=外見, 外観)species, facies, aspectus, frons.</div><div class=\"def\">▼<b>～は</b>(=外見上は)specie, in speciem, fronte.</div><div class=\"ex2\">～は自由だが本当は(...)<span class=\"ext\">liber specie sed re(...).</span></div>\r\n","<div class=\"hw jl\">見かける</div><div class=\"def\">video.</div>\r\n","<div class=\"hw jl\">見せしめ</div><div class=\"def\">documentum.</div>\r\n","<div class=\"hw jl\">見せる</div><div class=\"def\">(=示す, 提示する)〈alci alqd〉 ostendo, exhibeo, expono, ostento, monstro, indico, 〈alqd〉 in conspectum propono.</div>\r\n","<div class=\"hw jl\">見つける</div><div class=\"def\">invenio, reperio, nanciscor(<i>dep</i>), deprehendo, conspicio, conspicor(<i>dep</i>), provideo.</div><div class=\"def\">⇒<a href=\"entry://会う・遇う\">会う</a>.</div>\r\n","<div class=\"hw jl\">見つめる</div><div class=\"def\">▼<b>じっと～</b> tueor(<i>dep</i>), intueor(<i>dep</i>), obtueor(<i>dep</i>), inspicio.</div><div class=\"def\">▼<b>じっと～こと</b> obtutus.</div>\r\n","<div class=\"hw jl\">見る</div><div class=\"def\">video, specto, conspicio, aspicio, tueor(<i>dep</i>), intueor(<i>dep</i>), contueor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://見つける\">見つける</a>,<a href=\"entry://見分ける\">見分ける</a>,<a href=\"entry://観察\">観察</a>.</div>\r\n","<div class=\"hw jl\">見世物</div><div class=\"def\">spectaculum.</div><div class=\"def\">⇒<a href=\"entry://見物\">見物<SUB>けんぶつ</SUB></a>.</div>\r\n","<div class=\"hw jl\">見分ける</div><div class=\"def\">(=識別する, 違いが分かる)cerno, discerno, dignosco, internosco, dispicio.</div><div class=\"ex2\">真実と虚偽を～<span class=\"ext\">vera et falsa [vera a falsis] dijudico.</span></div><div class=\"def\">⇒<a href=\"entry://区別\">区別</a>.</div>\r\n","<div class=\"hw jl\">見切り</div><div class=\"def\">▼<b>～をつける</b>(=あきらめる, 放棄する)relinquo, depono, dimitto.</div>\r\n","<div class=\"hw jl\">見回す</div><div class=\"def\">circumspicio.</div>\r\n","<div class=\"hw jl\">見張る</div><div class=\"def\">custodio, speculor(<i>dep</i>).</div><div class=\"def\">▼<b>見張り</b> custodia, speculatio;(人)custos.</div><div class=\"def\">⇒<a href=\"entry://監視\">監視</a>.</div>\r\n","<div class=\"hw jl\">見抜く</div><div class=\"def\">perspicio, acutissime video, divino.</div>\r\n","<div class=\"hw jl\">見捨てる</div><div class=\"def\">desero, relinquo, destituo, derelinquo.</div><div class=\"def\">⇒<a href=\"entry://捨てる\">捨てる</a>.</div>\r\n","<div class=\"hw jl\">見損なう</div><div class=\"def\">(=見逃す)omitto.</div><div class=\"def\">⇒<a href=\"entry://見落とす\">見落とす</a>.</div>\r\n","<div class=\"hw jl\">見放す</div><div class=\"def\">⇒<a href=\"entry://見捨てる\">見捨てる</a>.</div>\r\n","<div class=\"hw jl\">見晴らし</div><div class=\"def\">▼<b>～の良い</b> late prospectans.</div><div class=\"def\">▼<b>見晴らす</b> possideo.</div><div class=\"ex2\">洋々たる海原, 長大な海岸線, この上なく美しい別荘地を見晴らす食堂<span class=\"ext\">cenatio quae latissimum mare longissimum litus villas amoenissimas possidet.</span></div><div class=\"def\">⇒<a href=\"entry://眺める\">眺める</a>.</div>\r\n","<div class=\"hw jl\">見本</div><div class=\"def\">exemplum.</div>\r\n","<div class=\"hw jl\">見物</div><div class=\"def\">spectatio.</div><div class=\"def\">▼<b>～人</b> spectator.</div><div class=\"def\">▼<b>～する</b> specto.</div><div class=\"def\">⇒<a href=\"entry://見世物\">見世物</a>.</div>\r\n","<div class=\"hw jl\">見直す</div><div class=\"def\">corrigo, emendo.</div><div class=\"def\">▼<b>見直し</b> correctio, emendatio.</div>\r\n","<div class=\"hw jl\">見舞う</div><div class=\"def\">(病人を)(ad aegros)viso.</div><div class=\"ex2\">災難に見舞われる<span class=\"ext\">cladem accipio.</span></div>\r\n","<div class=\"hw jl\">見落とす</div><div class=\"def\">praetermitto, praetereo, omitto.</div><div class=\"def\">▼<b>見落とし</b> praetermissio.</div><div class=\"def\">⇒<a href=\"entry://不注意\">不注意</a>,<a href=\"entry://無視\">無視</a>.</div>\r\n","<div class=\"hw jl\">見解</div><div class=\"def\">opinio, sententia.</div><div class=\"def\">⇒<a href=\"entry://意見\">意見</a>.</div>\r\n","<div class=\"hw jl\">見識</div><div class=\"def\">sapientia.</div><div class=\"def\">⇒<a href=\"entry://学識\">学識</a>,<a href=\"entry://知識\">知識</a>.</div>\r\n","<div class=\"hw jl\">見込み</div><div class=\"def\">exspectatio.</div><div class=\"def\">⇒<a href=\"entry://期待\">期待</a>.</div>\r\n","<div class=\"hw jl\">見送る</div><div class=\"def\">deduco.</div><div class=\"def\">▼<b>見送り</b> deductio.</div>\r\n","<div class=\"hw jl\">見逃す</div><div class=\"def\">omitto.</div><div class=\"def\">⇒<a href=\"entry://見落とす\">見落とす</a>.</div>\r\n","<div class=\"hw jl\">見通し</div><div class=\"def\">(=予知, 予見, 推測, 見込み, 期待)providentia, provisio, opinio, conjectura, exspectatio, spes.</div><div class=\"def\">▼<b>～を与える</b> prospicio.</div>\r\n","<div class=\"hw jl\">規則</div><div class=\"def\">regula;(=法規)lex.</div>\r\n","<div class=\"hw jl\">規定</div><div class=\"def\">definitio.</div><div class=\"def\">▼<b>～する</b> definio.</div><div class=\"def\">▼<b>～された</b> definitus.</div><div class=\"def\">⇒<a href=\"entry://規則\">規則</a>.</div>\r\n","<div class=\"hw jl\">規律</div><div class=\"def\">disciplina.</div>\r\n","<div class=\"hw jl\">規模</div><div class=\"def\">(=大きさ, 広さ)amplitudo, magnitudo.</div>\r\n","<div class=\"hw jl\">視力</div><div class=\"def\">visus, aspectus.</div>\r\n","<div class=\"hw jl\">視察</div><div class=\"def\">visitatio.</div><div class=\"def\">▼<b>～する</b> visito.</div>\r\n","<div class=\"hw jl\">視界</div><div class=\"def\">conspectus, aspectus.</div>\r\n","<div class=\"hw jl\">視線</div><div class=\"def\">oculus.</div><div class=\"def\">⇒<a href=\"entry://見つめる\">見つめる</a>.</div>\r\n","<div class=\"hw jl\">視聴者</div><div class=\"def\">(テレビの)exhibitionum televisificarum spectator.</div>\r\n","<div class=\"hw jl\">視野</div><div class=\"def\">prospectus.</div><div class=\"def\">⇒<a href=\"entry://視界\">視界</a>.</div>\r\n","<div class=\"hw jl\">覚えている</div><div class=\"def\">(=記憶している)<span class=\"pos3\">[動]</span> memini.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> memor.</div>\r\n","<div class=\"hw jl\">覚える</div><div class=\"def\">(=学んで知る)disco;(=記憶する)edisco.</div>\r\n","<div class=\"hw jl\">覚ます</div><div class=\"def\">▼<b>目を～</b> expergiscor(<i>pass</i>).</div><div class=\"def\">▼<b>目を覚まさせる</b> expergefacio, e somno excito.</div><div class=\"def\">▼<b>目を覚ました</b>(e somno)expergefactus.</div>\r\n","<div class=\"hw jl\">覚める</div><div class=\"def\">⇒<a href=\"entry://覚ます\">覚ます</a>.</div>\r\n","<div class=\"hw jl\">覚悟</div><div class=\"def\">▼<b>～した</b> paratus.</div><div class=\"ex2\">彼らはあらゆることに耐える～をして働いた<span class=\"ext\">omnia perpeti parati laborabant.</span></div>\r\n","<div class=\"hw jl\">覚書</div><div class=\"def\">libellus, comentarii(<i>pl</i>), memoria.</div>\r\n","<div class=\"hw jl\">親</div><div class=\"def\">(=父, 母)parens.</div><div class=\"def\">▼<b>～の</b> parentalis.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">両親<span class=\"ext\">parentes(<i>pl</i>).</span></div><div class=\"cf\">父親<span class=\"ext\">pater.</span></div><div class=\"cf\">母親<span class=\"ext\">mater.</span></div>\r\n","<div class=\"hw jl\">親しい</div><div class=\"def\">familiaris.</div><div class=\"def\">▼<b>親しく</b> familiariter. </div><div class=\"def\">▼<b>～こと</b> familiaritas.</div>\r\n","<div class=\"hw jl\">親切</div><div class=\"def\">benevolentia, beneficentia, beneficium, benignitas.</div><div class=\"def\">▼<b>～な</b> benignus, beneficus, comis.</div><div class=\"def\">▼(人に)<b> ～にする</b> 〈alci〉 bene facio.</div>\r\n","<div class=\"hw jl\">親密</div><div class=\"def\">familiaritas.</div><div class=\"def\">▼<b>～な</b> intimus, familiaris.</div><div class=\"ex2\">～な友人関係<span class=\"ext\">intima amicitia.</span></div>\r\n","<div class=\"hw jl\">親愛</div><div class=\"def\">▼<b>～の</b> carus.</div>\r\n","<div class=\"hw jl\">親戚</div><div class=\"def\">(父方の)agnatus.</div><div class=\"def\">▼<b>～(の)</b> propinquus, cognatus.</div>\r\n","<div class=\"hw jl\">親指</div><div class=\"def\">pollex.</div><div class=\"def\">⇒<a href=\"entry://指\">指</a>.</div>\r\n","<div class=\"hw jl\">親類</div><div class=\"def\">⇒<a href=\"entry://親戚\">親戚</a>.</div>\r\n","<div class=\"hw jl\">観光</div><div class=\"def\">res periegetica, periegesis.</div><div class=\"def\">▼<b>～客</b> periegetes, peregrinator voluptarius, peregrinus voluptarius.</div><div class=\"def\">⇒<a href=\"entry://旅行\">旅行</a>.</div>\r\n","<div class=\"hw jl\">観客</div><div class=\"def\">spectator(<i>m</i>), spectatrix(<i>f</i>);(集合的に)theatrum.</div><div class=\"def\">▼<b>～席</b> spectacula(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">観察</div><div class=\"def\">observatio, contemplatio, animadversio, spectatio.</div><div class=\"def\">▼<b>～者</b> spectator.</div><div class=\"def\">▼<b>～する</b> observo, contemplor(<i>dep</i>), animadverto, specto, tueor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">観念</div><div class=\"def\">species.</div><div class=\"def\">⇒<a href=\"entry://概念\">概念</a>.</div>\r\n","<div class=\"hw jl\">観測</div><div class=\"def\">observatio.</div><div class=\"def\">▼<b>～する</b> observo;(=観察し計測する)observo et dimetior.</div>\r\n","<div class=\"hw jl\">観点</div><div class=\"ex2\">物事をあらゆる～から考察する<span class=\"ext\">rem ex omni parte considero.</span></div><div class=\"def\">⇒<a href=\"entry://点\">点</a>.</div>\r\n","<div class=\"hw jl\">角</div><div class=\"def\">⇒<a href=\"entry://角度\">角度</a>.</div>\r\n","<div class=\"hw jl\">角</div><div class=\"def\">angulus.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">三つ角(=三叉路)<span class=\"ext\">trivium.</span></div><div class=\"cf\">四つ角<span class=\"ext\">compitum, quadrivium.</span></div>\r\n","<div class=\"hw jl\">角</div><div class=\"def\">cornu;(小さな)corniculum.</div>\r\n","<div class=\"hw jl\">角度</div><div class=\"def\">angulus.</div>\r\n","<div class=\"hw jl\">角,隅</div><div class=\"def\">angulus.</div>\r\n","<div class=\"hw jl\">解く</div><div class=\"def\">(問題を)solvo, expedio;(より, もつれを)explico.</div><div class=\"def\">⇒<a href=\"entry://ほどく\">ほどく</a>,<a href=\"entry://解放\">解放</a>.</div>\r\n","<div class=\"hw jl\">解体</div><div class=\"def\">dissolutio.</div><div class=\"def\">▼<b>～する</b> dissolvo, solvo.</div><div class=\"def\">⇒<a href=\"entry://解剖\">解剖</a>,<a href=\"entry://分解\">分解</a>.</div>\r\n","<div class=\"hw jl\">解剖</div><div class=\"def\">▼<b>～する</b> corpora mortuum incido.</div>\r\n","<div class=\"hw jl\">解放</div><div class=\"def\">liberatio, solutio.</div><div class=\"def\">▼<b>～者</b> liberator.</div><div class=\"def\">▼<b>～する</b> libero, solvo, (in libertatem)vindico.</div><div class=\"def\">⇒<a href=\"entry://自由\">自由</a>.</div>\r\n","<div class=\"hw jl\">解放運動</div><div class=\"def\">a potestate liberatio, ab auctoritate vindicatio.</div>\r\n","<div class=\"hw jl\">解散</div><div class=\"def\">▼<b>～する</b> dimitto.</div>\r\n","<div class=\"hw jl\">解毒剤</div><div class=\"def\">antidotum.</div>\r\n","<div class=\"hw jl\">解決</div><div class=\"def\">explicatio, expeditio, solutio.</div><div class=\"def\">▼<b>～する</b> explico, expedio, dissolvo, decerno, solvo.</div>\r\n","<div class=\"hw jl\">解消</div><div class=\"def\">▼<b>～する</b> solvo, dissolvo.</div>\r\n","<div class=\"hw jl\">解答</div><div class=\"def\">responsum.</div><div class=\"def\">⇒<a href=\"entry://解決\">解決</a>.</div>\r\n","<div class=\"hw jl\">解説</div><div class=\"def\">interpretatio.</div><div class=\"def\">▼<b>～する</b> interpretor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://注釈\">注釈</a>.</div>\r\n","<div class=\"hw jl\">解釈</div><div class=\"def\">interpretatio, explanatio.</div><div class=\"def\">▼<b>～者</b> interpres.</div><div class=\"def\">▼<b>～する</b> interpretor(<i>dep</i>), explano.</div><div class=\"def\">⇒<a href=\"entry://説明\">説明</a>.</div>\r\n","<div class=\"hw jl\">解除</div><div class=\"def\">absolutio.</div><div class=\"def\">▼<b>～する</b> solvo.</div><div class=\"ex2\">町の包囲が～されて<span class=\"ext\">soluta urbis obsidione.</span></div>\r\n","<div class=\"hw jl\">解雇</div><div class=\"def\">(=免職, 解職)dimissio.</div><div class=\"def\">▼<b>～する</b> mitto, dimitto.</div><div class=\"def\">⇒<a href=\"entry://退職\">退職</a>.</div>\r\n","<div class=\"hw jl\">触る</div><div class=\"def\">tango, attingo.</div><div class=\"def\">⇒<a href=\"entry://触れる\">触れる</a>.</div>\r\n","<div class=\"hw jl\">触れる</div><div class=\"def\">tango, attingo, contingo, attrecto, tracto, palpo, palpor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://なでる\">なでる</a>.</div>\r\n","<div class=\"hw jl\">言いつける</div><div class=\"def\">(=命じる)impero, mando, praecipio;(=告げ口する, 密告する)defero.</div><div class=\"def\">⇒<a href=\"entry://密告\">密告</a>.</div>\r\n","<div class=\"hw jl\">言いのがれ</div><div class=\"def\">(=口実, 言い抜け)tergiversatio, latebra, deverticulum, perfugium, excusatio.</div><div class=\"def\">▼<b>言いのがれる</b> tergiversor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://口実\">口実</a>,<a href=\"entry://言い訳\">言い訳</a>.</div>\r\n","<div class=\"hw jl\">言い換える</div><div class=\"def\">paraphrasi verto.</div><div class=\"def\">▼<b>言い換え</b> paraphrasis.</div><div class=\"ex2\">～ならば<span class=\"ext\">hoc est.</span></div>\r\n","<div class=\"hw jl\">言い聞かせる</div><div class=\"def\">⇒<a href=\"entry://命令\">命令</a>,<a href=\"entry://言いつける\">言いつける</a>,<a href=\"entry://説得\">説得</a>,<a href=\"entry://忠告\">忠告</a>.</div>\r\n","<div class=\"hw jl\">言い訳</div><div class=\"def\">excusatio, apologia.</div><div class=\"ex2\">～を探す<span class=\"ext\">excusationem quaero.</span></div><div class=\"ex2\">～を認める<span class=\"ext\">excusationem accipio.</span></div><div class=\"def\">⇒<a href=\"entry://弁解\">弁解</a>,<a href=\"entry://弁明\">弁明</a>,<a href=\"entry://口実\">口実</a>.</div>\r\n","<div class=\"hw jl\">言い返す</div><div class=\"def\">(=返答する)respondeo;(=反論する)retorqueo.</div>\r\n","<div class=\"hw jl\">言う</div><div class=\"def\">dico, aio, inquam.</div><div class=\"def\">▼(...と)<b>言われている</b>(=伝えられている)fertur 〈+<i>inf</i>〉, traditur 〈+<i>inf</i>〉, traditum est 〈+<i>inf</i>〉.</div><div class=\"ex2\">ホメロスは盲目だったと言われている<span class=\"ext\">Homerus dicitur caecus fuisse.</span></div><div class=\"ex2\">A という(名前の)<span class=\"ext\">qui A vocatur / nomine A / cui nomen A.</span></div>\r\n","<div class=\"hw jl\">言わば</div><div class=\"def\">ut ita dicam, ut sic dixerim.</div>\r\n","<div class=\"hw jl\">言及</div><div class=\"def\">mentio, commemoratio.</div><div class=\"def\">▼(...について)<b> ～する</b> 〈de+<i>abl</i>〉 commemoro, 〈+<i>gen</i>〉 mentionem facio.</div>\r\n","<div class=\"hw jl\">言明</div><div class=\"def\">oratio.</div><div class=\"def\">⇒<a href=\"entry://明言\">明言</a>,<a href=\"entry://断言\">断言</a>.</div>\r\n","<div class=\"hw jl\">言語</div><div class=\"def\">(個別の)lingua, sermo;(=人間の話すことば)oratio.</div>\r\n","<div class=\"hw jl\">言語学</div><div class=\"def\">glottologica disciplina, sermonis normae rationisque scientia.</div><div class=\"def\">▼<b>～者</b> glottologus, linguarum studiosus, vir linguis doctus, glottologiae cultor, multarum linguarum peritus.</div><div class=\"def\">▼<b>～の</b> glottologicus.</div><div class=\"def\">⇒<a href=\"entry://語学\">語学</a>,<a href=\"entry://文献学\">文献学</a>.</div>\r\n","<div class=\"hw jl\">言論</div><div class=\"def\">oratio.</div><div class=\"ex2\">～の自由<span class=\"ext\">libera lingua / libertas loquendi.</span></div>\r\n","<div class=\"hw jl\">訂正</div><div class=\"def\">correctio, emendatio.</div><div class=\"def\">▼<b>～する</b> corrigo, emendo, sano.</div>\r\n","<div class=\"hw jl\">計</div><div class=\"def\">(=合計)summa.</div><div class=\"def\">⇒<a href=\"entry://計算\">計算</a>,<a href=\"entry://合計\">合計</a>.</div>\r\n","<div class=\"hw jl\">計る</div><div class=\"def\">metior(<i>dep</i>), dimetior(<i>dep</i>), libro.</div>\r\n","<div class=\"hw jl\">計画</div><div class=\"def\">consilium, propositum, institutum.</div><div class=\"def\">▼<b>～する</b> consilium capio [ineo], propono.</div><div class=\"ex2\">戦争を～する<span class=\"ext\">de bello consilia ineo.</span></div><div class=\"def\">⇒<a href=\"entry://考え\">考え</a>,<a href=\"entry://意図\">意図</a>.</div>\r\n","<div class=\"hw jl\">計略</div><div class=\"def\">⇒<a href=\"entry://策略\">策略</a>.</div>\r\n","<div class=\"hw jl\">計算</div><div class=\"def\">ratio, dinumeratio, computatio, ratiocinium, calculatio, supputatio.</div><div class=\"def\">▼<b>～する</b> numero, computo, dinumero, reputo, calculo, supputo, rationem ineo [habeo].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">足し算<span class=\"ext\">consummatio.</span></div><div class=\"cf\">掛け算<span class=\"ext\">multiplicatio.</span></div><div class=\"cf\">引き算<span class=\"ext\">deductio.</span></div><div class=\"cf\">割り算<span class=\"ext\">divisio.</span></div><div class=\"cf\">指で数える<span class=\"ext\">digitis computo.</span></div><div class=\"cf\">星の数を数える<span class=\"ext\">stellas dinumero.</span></div><div class=\"def\">⇒<a href=\"entry://算数\">算数</a>.</div>\r\n","<div class=\"hw jl\">計算機</div><div class=\"def\">(=電卓)machinula calculatoria.</div><div class=\"def\">▼<b>電子～</b> instrumentum computatorium.</div><div class=\"def\">▼<b>～センター</b> sedes mechanicographica.</div><div class=\"def\">⇒<a href=\"entry://コンピュータ\">コンピュータ</a>.</div>\r\n","<div class=\"hw jl\">計量</div><div class=\"def\">mensura.</div><div class=\"def\">▼<b>～する</b> metior(<i>dep</i>), demetior(<i>dep</i>);(重さを)penso, appendo.</div>\r\n","<div class=\"hw jl\">討つ</div><div class=\"def\">(=敵を攻撃する)impugno.</div><div class=\"ex2\">(...のために)仇を～<span class=\"ext\">ulciscor 〈+<i>acc</i>〉.</span></div>\r\n","<div class=\"hw jl\">討論</div><div class=\"def\">disceptatio, disputatio, sermo, dialogus.</div><div class=\"def\">▼<b>～する</b> discepto, disputo.</div><div class=\"def\">⇒<a href=\"entry://論争\">論争</a>.</div>\r\n","<div class=\"hw jl\">討議</div><div class=\"def\">disceptatio, disputatio, deliberatio.</div><div class=\"def\">▼<b>～する</b> agito, ago, consilior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://討論\">討論</a>,<a href=\"entry://審議\">審議</a>,<a href=\"entry://協議\">協議</a>.</div>\r\n","<div class=\"hw jl\">訓練</div><div class=\"def\">exercitium, exercitatio.</div><div class=\"def\">▼<b>～する</b> exerceo, exercito.</div><div class=\"def\">⇒<a href=\"entry://練習\">練習</a>.</div>\r\n","<div class=\"hw jl\">記号</div><div class=\"def\">signum.</div>\r\n","<div class=\"hw jl\">記念</div><div class=\"def\">▼<b>～(碑)</b> memoria.</div><div class=\"def\">▼<b>～物</b> monumentum.</div><div class=\"def\">▼<b>～日</b> anniversarius dies.</div>\r\n","<div class=\"hw jl\">記憶</div><div class=\"def\">memoria.</div><div class=\"def\">▼<b>～術</b> ars memoriae.</div><div class=\"def\">▼<b>～する</b> memoriae commendo, memoriae mando, memoriā teneo.</div><div class=\"def\">▼<b>～している</b><span class=\"pos3\">[動]</span> memini. <span class=\"pos3\">[形]</span> memor.</div><div class=\"ex2\">～に値する<span class=\"ext\">memorabilis.</span></div><div class=\"ex2\">～をたよりに<span class=\"ext\">memoriter.</span></div><div class=\"def\">⇒<a href=\"entry://暗記\">暗記</a>.</div>\r\n","<div class=\"hw jl\">記者</div><div class=\"def\">▼<b>(新聞)～</b>(actorum)diurnorum confector(<i>m</i>).</div><div class=\"def\">⇒<a href=\"entry://新聞\">新聞</a>.</div>\r\n","<div class=\"hw jl\">記録</div><div class=\"def\">perscriptio;(文書)commentarius, monumentum, tabula, litterae(<i>pl</i>).</div><div class=\"def\">▼<b>世界新～</b> novum culmen mundanum.</div><div class=\"def\">▼(...を)<b> ～する</b> 〈+<i>acc</i>〉 perscribo, in commentarium refero, litteris mando, memoriae prodo.</div>\r\n","<div class=\"hw jl\">訪ねる</div><div class=\"def\">⇒<a href=\"entry://訪問\">訪問</a>.</div>\r\n","<div class=\"hw jl\">訪れる</div><div class=\"def\">(=訪問する)viso, visito, adeo.</div>\r\n","<div class=\"hw jl\">訪問</div><div class=\"def\">salutatio, adventus.</div><div class=\"def\">▼<b>～客</b> salutator(<i>m</i>), hospes(<i>m</i>), hospita(<i>f</i>).</div><div class=\"def\">▼<b>～する</b>(=訪れる)saluto, inviso, viso, obeo, convenio, adeo.</div>\r\n","<div class=\"hw jl\">設備</div><div class=\"def\">instrumentum.</div><div class=\"def\">⇒<a href=\"entry://装備\">装備</a>.</div>\r\n","<div class=\"hw jl\">許す・赦す</div><div class=\"def\">(罪や過失を)(=容赦する)ignosco, veniam do;(=許可する, 放置する, 承認する)permitto, patior(<i>dep</i>), sino, concedo.</div><div class=\"def\">▼<b>許されている</b> licet(<i>impers</i>).</div><div class=\"ex2\">あなたにこんなに長い手紙を書くことを許して下さい<span class=\"ext\">velim mihi ignoscas quod ad te scribo tam multa.</span></div>\r\n","<div class=\"hw jl\">許可</div><div class=\"def\">permissio, licentia.</div><div class=\"def\">▼<b>～する</b> permitto, patior(<i>dep</i>), sino, licentiam do.</div><div class=\"def\">▼(...に)(...が)<b>～されている</b>(=許されている)licet 〈alci〉 〈+<i>inf</i>〉.</div><div class=\"ex2\">それは私に～されなかった(=認めてもらえなかった)<span class=\"ext\">id mihi non est concessum.</span></div><div class=\"def\">⇒<a href=\"entry://許す・赦す\">許す</a>.</div>\r\n","<div class=\"hw jl\">訳</div><div class=\"def\">(=翻訳)translatio, conversio.</div><div class=\"def\">⇒<a href=\"entry://翻訳\">翻訳</a>.</div>\r\n","<div class=\"hw jl\">訴え</div><div class=\"def\">(=苦情, 不平)querela.</div><div class=\"def\">▼<b>訴える</b>(=苦情を言う)queror(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://告訴\">告訴</a>,<a href=\"entry://苦情\">苦情</a>,<a href=\"entry://不平\">不平</a>.</div>\r\n","<div class=\"hw jl\">訴訟</div><div class=\"def\">lis, causa, actio, actus, judicium.</div><div class=\"def\">▼<b>～当事者</b> litigator.</div><div class=\"def\">▼<b>～好きな</b> litigiosus.</div><div class=\"def\">▼<b>～を起こす</b> litigo, causam ago.</div>\r\n","<div class=\"hw jl\">診察</div><div class=\"def\">corporis inspectio [observatio, cognitio], inspectio clinica.</div>\r\n","<div class=\"hw jl\">診断</div><div class=\"def\">morborum cognitio.</div>\r\n","<div class=\"hw jl\">証人</div><div class=\"def\">testis.</div>\r\n","<div class=\"hw jl\">証券</div><div class=\"def\">perscriptiones(<i>pl</i>), mandata nummaria, chartae nummariae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">証拠</div><div class=\"def\">argumentum, testimonium.</div>\r\n","<div class=\"hw jl\">証明</div><div class=\"def\">demonstratio, probatio, ostentus.</div><div class=\"def\">▼<b>～する</b> demonstro, probo.</div>\r\n","<div class=\"hw jl\">証言</div><div class=\"def\">testimonium, testificatio, testatio.</div><div class=\"def\">▼<b>～する</b> testificor(<i>dep</i>), testimonium do.</div>\r\n","<div class=\"hw jl\">詐欺</div><div class=\"def\">fraus, dolus(malus), fallacia, praestigiae(<i>pl</i>), circumscriptio.</div><div class=\"def\">▼<b>～師</b> praestigiator, circumscriptor.</div><div class=\"def\">▼<b>～によって</b> dolose.</div><div class=\"def\">⇒<a href=\"entry://欺く\">欺く</a>,<a href=\"entry://だます\">だます</a>.</div>\r\n","<div class=\"hw jl\">評価</div><div class=\"def\">aestimatio, taxatio, taxa.</div><div class=\"def\">▼<b>～の</b> taxatorius.</div><div class=\"def\">▼<b>～する人</b> taxator.</div><div class=\"def\">▼<b>～する</b> aestimo, taxo, metior(<i>dep</i>);(高く)diligo.</div>\r\n","<div class=\"hw jl\">評判</div><div class=\"def\">fama, rumor.</div>\r\n","<div class=\"hw jl\">試す</div><div class=\"def\">experior(<i>dep</i>), periclitor(<i>dep</i>), tempto, probo, exploro.</div><div class=\"def\">⇒<a href=\"entry://試み\">試み</a>.</div>\r\n","<div class=\"hw jl\">試み</div><div class=\"def\">experientia, temptatio, temptamen, temptamentum.</div>\r\n","<div class=\"hw jl\">試みる</div><div class=\"def\">tempto.</div>\r\n","<div class=\"hw jl\">試合</div><div class=\"def\">ludus, certamen, lusorium [athleticum] certamen.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">決勝戦<span class=\"ext\">ludus finalis.</span></div><div class=\"cf\">準決勝戦<span class=\"ext\">certamina semifinalia(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">試験</div><div class=\"def\">periculum, temptamentum, experientia;(=学力試験)cognitio, probatio.</div><div class=\"def\">▼<b>～する</b> experior(<i>dep</i>), tempto.</div><div class=\"ex2\">(人の)知識を～する<span class=\"ext\">alcis scientiam tempto.</span></div><div class=\"ex2\">(人の)読み書きの知識を～する<span class=\"ext\">〈alcis〉 periculum in litteris facio.</span></div><div class=\"def\">⇒<a href=\"entry://試み\">試み</a>,<a href=\"entry://試す\">試す</a>.</div>\r\n","<div class=\"hw jl\">詩</div><div class=\"def\">(=詩歌)poema, carmen.</div><div class=\"def\">▼<b>～学</b> poetica.</div><div class=\"def\">▼<b>～作, 作～法</b> poesis.</div><div class=\"def\">▼<b>～の</b> poeticus.</div><div class=\"def\">⇒<a href=\"entry://詩人\">詩人</a>,<a href=\"entry://叙事詩\">叙事詩</a>,<a href=\"entry://抒情詩\">抒情詩</a>,<a href=\"entry://劇\">劇</a>.</div>\r\n","<div class=\"hw jl\">詩人</div><div class=\"def\">poeta.</div><div class=\"def\">▼<b>～の</b> poeticus.</div><div class=\"def\">⇒<a href=\"entry://詩\">詩</a>.</div>\r\n","<div class=\"hw jl\">詭弁</div><div class=\"def\">captio, cavillatio, calumnia, sophisma.</div><div class=\"def\">▼<b>～家</b> cavillator.</div><div class=\"def\">▼<b>～を弄する</b><span class=\"pos3\">[形]</span> captiosus. <span class=\"pos3\">[動]</span> cavillor(<i>dep</i>), calumnior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">詮索</div><div class=\"def\">▼<b>～する</b> scrutor(<i>dep</i>).</div><div class=\"def\">▼<b>～する人</b> scrutator(<i>m</i>), scrutatrix(<i>f</i>).</div>\r\n","<div class=\"hw jl\">詰まった</div><div class=\"def\">(いっぱいに, ぎっしり)refertus, plenus, cumulatus, frequens.</div>\r\n","<div class=\"hw jl\">詰める</div><div class=\"def\">(いっぱいに)farcio;(=切り詰める)abrumpo.</div><div class=\"def\">⇒<a href=\"entry://ふさぐ\">ふさぐ</a>.</div>\r\n","<div class=\"hw jl\">詰め込む</div><div class=\"def\">farcio.</div>\r\n","<div class=\"hw jl\">話</div><div class=\"def\">sermo, fabula.</div><div class=\"def\">⇒<a href=\"entry://会話\">会話</a>,<a href=\"entry://話す\">話す</a>,<a href=\"entry://物語\">物語</a>.</div>\r\n","<div class=\"hw jl\">話しかける</div><div class=\"def\">appello, alloquor(<i>dep</i>), affor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">話し合う</div><div class=\"def\">(=会話する, 論議する)colloquor(<i>dep</i>).</div><div class=\"def\">▼<b>話し合い</b>(=会話)colloquium, collocutio, sermo.</div><div class=\"def\">⇒<a href=\"entry://会話\">会話</a>,<a href=\"entry://議論\">議論</a>.</div>\r\n","<div class=\"hw jl\">話す</div><div class=\"def\">loquor(<i>dep</i>), narro.</div><div class=\"def\">▼<b>～こと</b> narratio.</div><div class=\"ex2\">ラテン語を～<span class=\"ext\">Latine loquor.</span></div>\r\n","<div class=\"hw jl\">話題</div><div class=\"def\">(=主題, 題材)materies, materia, res, argumentum, propositum.</div><div class=\"def\">▼<b>～が</b>(...に)<b>及ぶ</b> incidit sermo 〈de+<i>abl</i>〉.</div><div class=\"def\">⇒<a href=\"entry://主題\">主題</a>.</div>\r\n","<div class=\"hw jl\">該当</div><div class=\"def\">▼(...に)<b> ～する</b>(=当てはまる)〈ad+<i>acc</i>〉 attineo, pertineo.</div>\r\n","<div class=\"hw jl\">誇り</div><div class=\"def\">(=自尊心)superbia;(=名誉)honor.</div><div class=\"def\">▼<b>誇る</b> superbio.</div><div class=\"def\">⇒<a href=\"entry://傲慢\">傲慢</a>,<a href=\"entry://自慢\">自慢</a>,<a href=\"entry://名誉\">名誉</a>.</div>\r\n","<div class=\"hw jl\">誇大</div><div class=\"def\">▼<b>～な</b> veritatem superans, vero major.</div><div class=\"def\">▼<b>～妄想</b> megalomania.</div><div class=\"def\">⇒<a href=\"entry://誇張\">誇張</a>.</div>\r\n","<div class=\"hw jl\">誇張</div><div class=\"def\">superlatio, verborum immoderatio.</div><div class=\"def\">▼<b>～された</b> superlativus.</div><div class=\"def\">▼<b>～して</b> superlatius, inflatius.</div><div class=\"def\">▼<b>～する</b> augeo, in majus vero fero, inflatius commemoro.</div><div class=\"def\">⇒<a href=\"entry://誇大\">誇大</a>.</div>\r\n","<div class=\"hw jl\">誇示</div><div class=\"def\">ostentatio, ostentus.</div><div class=\"def\">▼<b>～する</b> ostento.</div><div class=\"def\">▼<b>～する人</b> ostentator.</div>\r\n","<div class=\"hw jl\">認める</div><div class=\"def\">(=承認・容認・認知する)agnosco, probo, concedo, fateor(<i>dep</i>), conspicor(<i>dep</i>);(=気づく)conspicio, video, percipio, animadverto.</div><div class=\"def\">▼<b>認めない</b>(=否認する)improbo, abdico.</div><div class=\"def\">⇒<a href=\"entry://気づく\">気づく</a>.</div>\r\n","<div class=\"hw jl\">認可</div><div class=\"def\">permissio, permissus.</div><div class=\"def\">▼<b>～する</b> permitto, concedo.</div>\r\n","<div class=\"hw jl\">認識</div><div class=\"def\">cognitio, notio, perspicientia, perceptio;(正しい)sapientia.</div><div class=\"def\">▼<b>～する</b> cognosco, nosco, perspicio.</div><div class=\"def\">⇒<a href=\"entry://知識\">知識</a>,<a href=\"entry://意識\">意識</a>,<a href=\"entry://知覚\">知覚</a>,<a href=\"entry://感覚\">感覚</a>.</div>\r\n","<div class=\"hw jl\">誓い</div><div class=\"def\">jus jurandum, sacramentum, juratio, adjuratio, juramentum.</div>\r\n","<div class=\"hw jl\">誓う</div><div class=\"def\">juro, adjuro.</div>\r\n","<div class=\"hw jl\">誕生</div><div class=\"def\">natus, ortus.</div><div class=\"def\">▼<b>～日</b> natalis(dies).</div><div class=\"def\">▼<b>～する</b> nascor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://生まれる\">生まれる</a>.</div>\r\n","<div class=\"hw jl\">誘う</div><div class=\"def\">invito, persuadeo.</div><div class=\"def\">⇒<a href=\"entry://誘惑\">誘惑</a>.</div>\r\n","<div class=\"hw jl\">誘導</div><div class=\"def\">▼<b>～する</b> moderor(<i>dep</i>), dirigo, rego, duco.</div>\r\n","<div class=\"hw jl\">誘惑</div><div class=\"def\">tentatio, tentamen, corruptela, sollicitatio, illecebra.</div><div class=\"def\">▼<b>～する</b> tempto, corrumpo, sollicito, illicio, illecebro.</div>\r\n","<div class=\"hw jl\">誘拐</div><div class=\"def\">plagium, raptio, raptus.</div><div class=\"def\">▼<b>～者</b>(=人さらい)plagiarius(<i>m</i>), plagiaria(<i>f</i>).</div><div class=\"def\">▼<b>～する</b> rapio, subripio.</div><div class=\"def\">⇒<a href=\"entry://略奪\">略奪</a>.</div>\r\n","<div class=\"hw jl\">語</div><div class=\"def\">verbum.</div><div class=\"def\">⇒<a href=\"entry://言語\">言語</a>,<a href=\"entry://品詞\">品詞</a>.</div>\r\n","<div class=\"hw jl\">語る</div><div class=\"def\">narro, memoro.</div><div class=\"def\">▼<b>語り</b>(=物語)narratio.</div><div class=\"def\">▼<b>語り手</b> narrator.</div>\r\n","<div class=\"hw jl\">語学</div><div class=\"def\">(=文学・言語・文法の研究)grammatica.</div><div class=\"def\">⇒<a href=\"entry://言語学\">言語学</a>,<a href=\"entry://文献学\">文献学</a>.</div>\r\n","<div class=\"hw jl\">語彙</div><div class=\"def\">verba linguae propria, verborum copia.</div>\r\n","<div class=\"hw jl\">語源</div><div class=\"def\">verbi origo [originatio].</div><div class=\"def\">▼<b>～学</b> etymologia, etymologice, verborum originis disciplina.</div><div class=\"def\">▼<b>～学者</b> etymologus.</div><div class=\"def\">▼<b>～(学)の</b> etymologicus.</div>\r\n","<div class=\"hw jl\">誠実</div><div class=\"def\">probitas, sinceritas, fidelitas, (bona)fides, veritas, diligentia.</div><div class=\"def\">▼<b>～な</b> probus, sincerus, fidus, fidelis, verus.</div><div class=\"def\">▼<b>～に</b> sincere, fide, fideliter, (ex)bona fide.</div><div class=\"def\">⇒<a href=\"entry://不誠実\">不誠実</a>.</div>\r\n","<div class=\"hw jl\">誠意</div><div class=\"def\">fides.</div><div class=\"def\">⇒<a href=\"entry://誠実\">誠実</a>.</div>\r\n","<div class=\"hw jl\">誤って</div><div class=\"def\">falso, perperam.</div><div class=\"ex2\">私は～ 「...」 と書きました<span class=\"ext\">perperam “ ... \" scripsi.</span></div>\r\n","<div class=\"hw jl\">誤る</div><div class=\"def\">erro, pecco.</div><div class=\"def\">⇒<a href=\"entry://間違える\">間違える</a>.</div>\r\n","<div class=\"hw jl\">誤植</div><div class=\"def\">typographicum mendum.</div>\r\n","<div class=\"hw jl\">誤算</div><div class=\"def\">error.</div>\r\n","<div class=\"hw jl\">誤解</div><div class=\"def\">error.</div><div class=\"def\">▼<b>～する</b> perperam [male, haud recte] intellego.</div><div class=\"def\">⇒<a href=\"entry://間違い\">間違い</a>.</div>\r\n","<div class=\"hw jl\">説き明かす</div><div class=\"def\">explico.</div><div class=\"ex2\">カトー自身のことばが老年についての私の考えをすべて説き明かしてくれるでしょう<span class=\"ext\">ipsius Catonis sermo explicabit nostram omnem de senectute sententiam.</span></div>\r\n","<div class=\"hw jl\">説く</div><div class=\"def\">doceo.</div><div class=\"def\">⇒<a href=\"entry://説明\">説明</a>.</div>\r\n","<div class=\"hw jl\">説得</div><div class=\"def\">persuasio.</div><div class=\"def\">▼(人を)<b> ～する</b> 〈alci〉 persuadeo [fidem facio], 〈alqm〉 ad suam sententiam perducere(← perduco).</div><div class=\"def\">▼<b>～的な</b> ad probandum firmus.</div><div class=\"def\">▼<b>～的に</b> ad persuadendum accommodate [apte].</div><div class=\"def\">▼<b>～力のない</b> ad probandum infirmus, parum potens.</div>\r\n","<div class=\"hw jl\">説教</div><div class=\"def\">sermo.</div>\r\n","<div class=\"hw jl\">説明</div><div class=\"def\">explicatio, explanatio, interpretatio.</div><div class=\"def\">▼<b>～する</b> explico, explano, interpretor(<i>dep</i>), doceo.</div>\r\n","<div class=\"hw jl\">読む</div><div class=\"def\">lego;(声に出して)(=朗読する)recito.</div><div class=\"def\">⇒<a href=\"entry://読書\">読書</a>.</div>\r\n","<div class=\"hw jl\">読書</div><div class=\"def\">lectio.</div>\r\n","<div class=\"hw jl\">読者</div><div class=\"def\">lector, legens, ei qui legunt(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">誰</div><div class=\"def\">▼<b>～(が)</b> quis, quisnam;(二人のうち)uter.</div><div class=\"def\">▼<b>～か(が)</b> aliquis.</div><div class=\"def\">▼<b>～かある(知らない)人</b> nescio quis.</div><div class=\"def\">▼<b>～も...ない</b> nemo, non ullus, nullus, non quisquam, non aliquis.</div><div class=\"def\">▼(われわれ二人のうち)<b>～も</b> neuter nostrum.</div><div class=\"def\">▼<b>～でも</b> quilibet unus(<i>m</i>), quivis unus(<i>m</i>).</div><div class=\"def\">▼(関係代名詞)(...する人は)<b>～でも</b> quisquis.</div><div class=\"ex2\">死ぬまで～も幸福ではない<span class=\"ext\">nemo ante mortem beatus.</span></div><div class=\"ex2\">彼は～も愛さず～からも愛されないだろう<span class=\"ext\">neque amet quemquam nec ametur ullo.</span></div>\r\n","<div class=\"hw jl\">誹謗</div><div class=\"def\">convicium.</div><div class=\"def\">▼<b>～者</b> conviciator.</div><div class=\"def\">▼<b>～する</b> convicior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://ののしる\">ののしる</a>,<a href=\"entry://ざん訴\">ざん訴</a>.</div>\r\n","<div class=\"hw jl\">調べる</div><div class=\"def\">probo, perspicio, exigo, cognosco.</div><div class=\"def\">⇒<a href=\"entry://吟味\">吟味</a>,<a href=\"entry://探求\">探求</a>,<a href=\"entry://審査\">審査</a>,<a href=\"entry://調査\">調査</a>.</div>\r\n","<div class=\"hw jl\">調停</div><div class=\"def\">intercessio, reconciliatio.</div><div class=\"def\">▼<b>～者</b> conciliator, reconciliator, intercessor.</div><div class=\"def\">▼<b>～する</b> intercedo.</div><div class=\"def\">⇒<a href=\"entry://仲裁\">仲裁</a>,<a href=\"entry://和解\">和解</a>.</div>\r\n","<div class=\"hw jl\">調味料</div><div class=\"def\">condimentum.</div>\r\n","<div class=\"hw jl\">調和</div><div class=\"def\">concentus, harmonia, concordia.</div><div class=\"def\">▼<b>～する</b> concino, concordo.</div><div class=\"def\">▼<b>～した</b> concors.</div><div class=\"def\">▼<b>～して</b> concorditer.</div><div class=\"def\">⇒<a href=\"entry://協調\">協調</a>.</div>\r\n","<div class=\"hw jl\">調子</div><div class=\"ex2\">～はいかがですか<span class=\"ext\">quid agis?</span></div><div class=\"ex2\">～は良いですか<span class=\"ext\">valesne?</span></div>\r\n","<div class=\"hw jl\">調査</div><div class=\"def\">inquisitio, requisitio, examinatio.</div><div class=\"def\">▼<b>～する</b> inquiro, examino.</div><div class=\"def\">▼<b>～する人</b> examinator.</div><div class=\"def\">⇒<a href=\"entry://探求\">探求</a>,<a href=\"entry://人口調査\">人口調査</a>,<a href=\"entry://調べる\">調べる</a>.</div>\r\n","<div class=\"hw jl\">調達</div><div class=\"def\">comparatio.</div><div class=\"def\">▼<b>～する</b> comparo, paro.</div>\r\n","<div class=\"hw jl\">請求</div><div class=\"def\">postulatio, petitio.</div><div class=\"def\">▼<b>～する</b> postulo, posco, imputo, peto.</div><div class=\"def\">▼<b>～者</b> petitor.</div>\r\n","<div class=\"hw jl\">請願</div><div class=\"def\">postulatio, postulatum, petitio.</div><div class=\"def\">▼<b>～書</b> libellus.</div>\r\n","<div class=\"hw jl\">論じる</div><div class=\"def\">(...について)〈de re〉 dissero, disputo.</div>\r\n","<div class=\"hw jl\">論争</div><div class=\"def\">disputatio, concertatio, contentio, lis, dialogus.</div><div class=\"def\">▼<b>～する</b> disputo, concerto, contendo.</div><div class=\"def\">⇒<a href=\"entry://口論\">口論</a>,<a href=\"entry://討論\">討論</a>,<a href=\"entry://議論\">議論</a>.</div>\r\n","<div class=\"hw jl\">論文</div><div class=\"def\">dissertatio, commentatio, disputatio.</div>\r\n","<div class=\"hw jl\">論理</div><div class=\"def\">▼<b>～学</b> logica(<i>pl</i>), logica(<i>f</i><i>sg</i>), logice, rationalis philosophiae pars.</div><div class=\"def\">▼<b>～的な</b> logicus.</div>\r\n","<div class=\"hw jl\">論証</div><div class=\"def\">argumentum, argumentatio.</div><div class=\"def\">▼<b>～する</b> argumentor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">論説</div><div class=\"def\">(新聞の)prima diarii commentatio.</div>\r\n","<div class=\"hw jl\">諸島</div><div class=\"ex2\">キュクラデス～<span class=\"ext\">Cyclades insulae(<i>pl</i>).</span></div>\r\n","<div class=\"hw jl\">諺</div><div class=\"def\">proverbium.</div>\r\n","<div class=\"hw jl\">謎</div><div class=\"def\">aenigma, griphus.</div>\r\n","<div class=\"hw jl\">謙虚</div><div class=\"def\">modestia, verecundia, pudor.</div><div class=\"def\">▼<b>～な</b> modestus, verecundus.</div><div class=\"def\">▼<b>～に</b> verecunde.</div><div class=\"def\">⇒<a href=\"entry://遠慮\">遠慮</a>,<a href=\"entry://控えめ\">控えめ</a>,<a href=\"entry://恥\">恥</a>.</div>\r\n","<div class=\"hw jl\">謙遜</div><div class=\"def\">verecundia, modestia.</div><div class=\"def\">▼<b>～した</b> verecundus, modestus.</div><div class=\"def\">⇒<a href=\"entry://謙虚\">謙虚</a>.</div>\r\n","<div class=\"hw jl\">講和</div><div class=\"def\">pacificatio.</div><div class=\"def\">▼<b>～条約</b> pax, pacis foedus.</div><div class=\"def\">⇒<a href=\"entry://平和\">平和</a>.</div>\r\n","<div class=\"hw jl\">講堂</div><div class=\"def\">auditorium.</div><div class=\"def\">⇒<a href=\"entry://講義\">講義</a>.</div>\r\n","<div class=\"hw jl\">講師</div><div class=\"def\">(大学などの)docendi facultate praeditus, licentiatus.</div><div class=\"def\">▼<b>～職</b> docendi munus, magisterium, magistri officium.</div><div class=\"def\">⇒<a href=\"entry://教師\">教師</a>.</div>\r\n","<div class=\"hw jl\">講演</div><div class=\"def\">acroasis, dictio.</div><div class=\"def\">⇒<a href=\"entry://演説\">演説</a>,<a href=\"entry://弁論\">弁論</a>.</div>\r\n","<div class=\"hw jl\">講義</div><div class=\"def\">auditio, schola.</div><div class=\"def\">▼<b>～室</b> auditorium, schola.</div><div class=\"def\">⇒<a href=\"entry://講演\">講演</a>,<a href=\"entry://授業\">授業</a>.</div>\r\n","<div class=\"hw jl\">講習</div><div class=\"def\">⇒<a href=\"entry://授業\">授業</a>.</div>\r\n","<div class=\"hw jl\">講読</div><div class=\"def\">lectio.</div>\r\n","<div class=\"hw jl\">謝る</div><div class=\"def\">(=謝罪する)(...に)veniam peto 〈ab+<i>abl</i>〉.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">許して下さい<span class=\"ext\">ignosce, da veniam, obsecro ut mihi ignoscas.</span></div><div class=\"def\">⇒<a href=\"entry://謝罪\">謝罪</a>.</div>\r\n","<div class=\"hw jl\">謝礼</div><div class=\"def\">honorarium.</div><div class=\"def\">⇒<a href=\"entry://報酬\">報酬</a>.</div>\r\n","<div class=\"hw jl\">謝罪</div><div class=\"def\">satisfactio.</div><div class=\"def\">▼(人に)<b> ～する</b> 〈alci〉 satisfacio, 〈ab alqo〉 veniam peto.</div><div class=\"def\">▼(人の)<b>～を受け入れる</b> 〈alcis〉 satisfactionem accipio, 〈alci〉 veniam do.</div><div class=\"def\">⇒<a href=\"entry://許す・赦す\">許す</a>.</div>\r\n","<div class=\"hw jl\">警備</div><div class=\"def\">custodia, vigilia.</div><div class=\"def\">▼<b>～員</b> custos, vigil.</div><div class=\"def\">⇒<a href=\"entry://護衛\">護衛</a>.</div>\r\n","<div class=\"hw jl\">警句</div><div class=\"def\">sententia;(短い)sententiola.</div><div class=\"def\">▼<b>～の, ～的な</b> sententiosus.</div>\r\n","<div class=\"hw jl\">警告</div><div class=\"def\">monitum(<i>pl</i>), monitio, admonitio, documentum.</div><div class=\"def\">▼<b>～する</b> moneo, admoneo;(前もって)praemoneo.</div>\r\n","<div class=\"hw jl\">警報</div><div class=\"def\">ad arma conclamatio, publica admonitio, publicus monitus.</div>\r\n","<div class=\"hw jl\">警官</div><div class=\"def\">urbis [civilis disciplinae, publicus] custos(<i>m</i>), minister publicus(<i>m</i>), biocolyta.</div><div class=\"def\">⇒<a href=\"entry://警察\">警察</a>.</div>\r\n","<div class=\"hw jl\">警察</div><div class=\"def\">custodes publici(<i>pl</i>), urbis securitatis [quietis] cura, securitatis urbanae cura, publicae securitatis ministri(<i>pl</i>), corpus biocolyticum, custodia, tutela.</div><div class=\"def\">▼<b>～官</b> minister publicus.</div><div class=\"def\">▼<b>～署</b> sedes biocolytica, publicae securitatis sedes.</div><div class=\"def\">▼<b>～の</b> ad disciplinam pertinens, biocolyticus.</div>\r\n","<div class=\"hw jl\">警戒</div><div class=\"def\">vigilantia, vigilia, custodia, cautio.</div><div class=\"def\">▼<b>～する</b> caveo, vigilo, custodio.</div><div class=\"def\">⇒<a href=\"entry://注意\">注意</a>,<a href=\"entry://用心\">用心</a>.</div>\r\n","<div class=\"hw jl\">議会</div><div class=\"def\">comitia.</div><div class=\"def\">⇒<a href=\"entry://会\">会</a>,<a href=\"entry://集会\">集会</a>,<a href=\"entry://会議\">会議</a>.</div>\r\n","<div class=\"hw jl\">議員</div><div class=\"def\">popularis legatus, orator popularis.</div><div class=\"def\">▼<b>下院～</b>(=代議士)delegatus parlamentarius.</div><div class=\"def\">▼<b>上院～</b>(=元老院議員)senator.</div><div class=\"def\">⇒<a href=\"entry://議会\">議会</a>.</div>\r\n","<div class=\"hw jl\">議論</div><div class=\"def\">disputatio, disceptatio, dissertatio.</div><div class=\"def\">▼<b>～する</b> discepto, disputo, dissero, disserto.</div><div class=\"def\">⇒<a href=\"entry://討議\">討議</a>,<a href=\"entry://討論\">討論</a>,<a href=\"entry://論争\">論争</a>,<a href=\"entry://会議\">会議</a>.</div>\r\n","<div class=\"hw jl\">議長</div><div class=\"def\">praeses, is qui praesidet.</div>\r\n","<div class=\"hw jl\">議題</div><div class=\"def\">argumentum(in conventu tractandum).</div>\r\n","<div class=\"hw jl\">譲る</div><div class=\"def\">cedo, concedo, defero.</div><div class=\"def\">⇒<a href=\"entry://与える\">与える</a>.</div>\r\n","<div class=\"hw jl\">譲歩</div><div class=\"def\">concessio, concessus.</div><div class=\"def\">▼<b>～する</b> cedo, concedo.</div><div class=\"ex2\">武器はトガ(市民権)に～すべきだ<span class=\"ext\">cedant arma togae.</span></div>\r\n","<div class=\"hw jl\">護衛</div><div class=\"def\">custodia, praesidium, satellites(<i>pl</i>), corporis custodes(<i>pl</i>).</div><div class=\"def\">▼<b>～者</b> custos, praesidium, stipator.</div><div class=\"def\">▼<b>～する</b>(=警護する)comitor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">護送</div><div class=\"def\">(=付き添って護り送ること)comitatus.</div><div class=\"def\">▼<b>～する</b> comitor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://付き添う\">付き添う</a>,<a href=\"entry://護衛\">護衛</a>,<a href=\"entry://運ぶ\">運ぶ</a>.</div>\r\n","<div class=\"hw jl\">谷</div><div class=\"def\">vallis;(=狭い谷, 峡谷)convallis.</div>\r\n","<div class=\"hw jl\">豆</div><div class=\"def\">faba.</div><div class=\"def\">▼<b>小さな～</b> fabella.</div><div class=\"def\">▼<b>～の</b> fabaceus, fabalis.</div>\r\n","<div class=\"hw jl\">豊かな</div><div class=\"def\">(=裕福な, 金持ちの)locuples, dives, opulentus, opulens, fortunatus, abundans, copiosus, pecuniosus;(実りの)(=豊饒な)fertilis, uber, fecundus.</div><div class=\"def\">⇒<a href=\"entry://富ます\">富ます</a>.</div>\r\n","<div class=\"hw jl\">豊富</div><div class=\"def\">copia, abundantia, plenitas, plenitudo, largitas.</div><div class=\"def\">▼<b>～な</b> copiosus, abundans, plenus, largus.</div><div class=\"def\">▼<b>～に</b> copiose, abunde, plene, large, largiter.</div>\r\n","<div class=\"hw jl\">豚</div><div class=\"def\">sus, porcus.</div><div class=\"def\">▼<b>雌～</b> porca.</div><div class=\"def\">▼<b>子～</b> porculus, porcellus.</div><div class=\"def\">▼<b>～の</b> suillus.</div><div class=\"def\">▼<b>～肉</b> suilla, laridum.</div>\r\n","<div class=\"hw jl\">象</div><div class=\"def\">elephans, elephas, elephantus.</div>\r\n","<div class=\"hw jl\">象徴</div><div class=\"def\">signum.</div><div class=\"def\">▼<b>～主義</b> symbolismus.</div><div class=\"def\">▼<b>～する</b> allegorice exprimo.</div>\r\n","<div class=\"hw jl\">象牙</div><div class=\"def\">ebur.</div><div class=\"def\">▼<b>～(製)の</b> eburneus.</div>\r\n","<div class=\"hw jl\">豪勢</div><div class=\"def\">▼<b>～な</b> sumptuosus, magnificus.</div>\r\n","<div class=\"hw jl\">豪華</div><div class=\"def\">▼<b>～な</b> sumptuosus, luxuriosus, magnificus, splendidus.</div><div class=\"def\">⇒<a href=\"entry://ぜいたく\">ぜいたく</a>.</div>\r\n","<div class=\"hw jl\">貝</div><div class=\"def\">conchylium, concha.</div>\r\n","<div class=\"hw jl\">負う</div><div class=\"def\">(親切や借金を)debeo;(責任を)ad se ipsum recipere(← recipio).</div>\r\n","<div class=\"hw jl\">負ける</div><div class=\"def\">(=負かされる)vincor(<i>pass</i>);(=値引きする)pretia submitto.</div><div class=\"def\">⇒<a href=\"entry://勝つ\">勝つ</a>.</div>\r\n","<div class=\"hw jl\">負債</div><div class=\"def\">(=借金, 債務)creditum, aes alienum, debita pecunia, debitum.</div><div class=\"def\">▼(...に)<b>～がある</b> 〈alci〉 pecuniam debeo.</div>\r\n","<div class=\"hw jl\">負傷</div><div class=\"def\">vulnus.</div><div class=\"def\">▼<b>～する</b> se vulnerare(← vulnero), vulneror(<i>pass</i>), saucior(<i>pass</i>).</div><div class=\"def\">▼<b>～させる</b> vulnero.</div><div class=\"def\">▼<b>～させること</b> vulneratio.</div><div class=\"def\">▼<b>～した</b> vulneratus, saucius.</div>\r\n","<div class=\"hw jl\">負担</div><div class=\"def\">onus.</div><div class=\"def\">▼<b>～の重い, ～になる</b> onerosus.</div><div class=\"def\">▼<b>～を負わせる</b> onero.</div>\r\n","<div class=\"hw jl\">財布</div><div class=\"def\">crumina, crumena, saccus, sacculus, marsuppium.</div>\r\n","<div class=\"hw jl\">財政</div><div class=\"def\">res nummaria publica.</div><div class=\"def\">▼<b>～学</b> nummariae rei disciplina.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">財務(大蔵)大臣<span class=\"ext\">administer rei nummariae publicae praepositus</span></div>\r\n","<div class=\"hw jl\">財源</div><div class=\"def\">facultas.</div>\r\n","<div class=\"hw jl\">財産</div><div class=\"def\">fortunae(<i>pl</i>), bona(<i>pl</i>), res.</div>\r\n","<div class=\"hw jl\">貢献</div><div class=\"def\">adjumentum.</div><div class=\"ex2\">私たちは同胞諸君に多大な～をした<span class=\"ext\">magnum attulimus adjumentum hominibus nostris.</span></div><div class=\"def\">⇒<a href=\"entry://寄与\">寄与</a>,<a href=\"entry://役立つ\">役立つ</a>.</div>\r\n","<div class=\"hw jl\">貧しい</div><div class=\"def\"><span class=\"pos3\">[形]</span>(=貧乏な, 乏しい)pauper, pauperculus, egens, inops, exilis;(非常に)perpauper.</div><div class=\"def\">━<span class=\"pos3\">[動]</span>(=足りない, 事欠く)egeo.</div><div class=\"def\">⇒<a href=\"entry://金持ち\">金持ち</a>,<a href=\"entry://乞食\">乞食</a>.</div>\r\n","<div class=\"hw jl\">貧乏</div><div class=\"def\">▼<b>～な</b> pauper.</div><div class=\"def\">⇒<a href=\"entry://貧しい\">貧しい</a>.</div>\r\n","<div class=\"hw jl\">貧困</div><div class=\"def\">paupertas, pauperies.</div><div class=\"def\">▼<b>～な</b>(=貧しい)pauper.</div>\r\n","<div class=\"hw jl\">貧弱</div><div class=\"def\">tenuitas, exiguitas, paupertas, infirmitas.</div><div class=\"def\">▼<b>～な</b> tenuis, exiguus, pauper, infirmus.</div><div class=\"def\">▼<b>～に</b> exigue.</div>\r\n","<div class=\"hw jl\">貧血</div><div class=\"def\">anhaemia, sanguinis debilitas [defectio, infirmitas].</div><div class=\"def\">▼<b>～の</b> anhaemiā [sanguinis debilitate] laborans, sanguine debilis.</div>\r\n","<div class=\"hw jl\">貨幣</div><div class=\"def\">nummus, nomisma, argentum, aes.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">金貨<span class=\"ext\">aurum, aureus(nummus).</span></div><div class=\"cf\">銀貨<span class=\"ext\">argentum(signatum).</span></div><div class=\"cf\">銅貨<span class=\"ext\">aes(signatum), aereus(nummus).</span></div><div class=\"cf\">紙幣(=銀行券)<span class=\"ext\">charta nummaria, argentarii [nummularii] scidula, nummus chartaceus, pecunia chartacea, scidula nummaria.</span></div>\r\n","<div class=\"hw jl\">販売</div><div class=\"def\">venditum, venditio.</div><div class=\"def\">▼<b>～する</b> vendo, vendito.</div><div class=\"def\">▼<b>～者</b> venditor.</div>\r\n","<div class=\"hw jl\">貪欲</div><div class=\"def\">▼<b>～な</b> avidus, avarus.</div><div class=\"ex2\">権力に～な<span class=\"ext\">avidus potentiae.</span></div><div class=\"ex2\">～な者は常に困窮する<span class=\"ext\">semper avarus eget.</span></div>\r\n","<div class=\"hw jl\">貫く</div><div class=\"def\">pertundo.</div>\r\n","<div class=\"hw jl\">貫録</div><div class=\"def\">dignitas, majestas.</div><div class=\"def\">⇒<a href=\"entry://威厳\">威厳</a>.</div>\r\n","<div class=\"hw jl\">責める</div><div class=\"def\">(=非難する)accuso, reprehendo, culpo, obicio, objecto, exprobro, vitupero.</div><div class=\"def\">⇒<a href=\"entry://非難\">非難</a>.</div>\r\n","<div class=\"hw jl\">責任</div><div class=\"def\">▼(...の)<b>～を負う</b> 〈alqd〉 praesto.</div><div class=\"ex2\">私たちは過失のほかいかなる～も負うべきではない<span class=\"ext\">nihil nobis praestandum est praeter culpam.</span></div>\r\n","<div class=\"hw jl\">貯める</div><div class=\"def\">⇒<a href=\"entry://取っておく\">取っておく</a>,<a href=\"entry://貯金\">貯金</a>.</div>\r\n","<div class=\"hw jl\">貯水池</div><div class=\"def\">aquae receptaculum.</div>\r\n","<div class=\"hw jl\">貯蔵</div><div class=\"def\">▼<b>～する</b> condo.</div><div class=\"def\">▼<b>～庫</b> horreum, receptaculum.</div><div class=\"def\">⇒<a href=\"entry://保存\">保存</a>,<a href=\"entry://保つ\">保つ</a>.</div>\r\n","<div class=\"hw jl\">貯金</div><div class=\"def\">nummi repositi(<i>pl</i>).</div><div class=\"def\">▼<b>～箱</b> theca nummaria.</div><div class=\"def\">⇒<a href=\"entry://預金\">預金</a>,<a href=\"entry://銀行\">銀行</a>.</div>\r\n","<div class=\"hw jl\">貴族</div><div class=\"def\">optimates(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">貴重</div><div class=\"def\">▼<b>～な</b> carus, pretiosus.</div>\r\n","<div class=\"hw jl\">買い物</div><div class=\"def\">emptio.</div><div class=\"ex2\">よい～をする(=安く買う)<span class=\"ext\">emo bene.</span></div><div class=\"ex2\">悪い～をする(=高く買う)<span class=\"ext\">emo male.</span></div><div class=\"ex2\">～に行く<span class=\"ext\">eo ad emendum.</span></div><div class=\"def\">⇒<a href=\"entry://買う\">買う</a>.</div>\r\n","<div class=\"hw jl\">買う</div><div class=\"def\">emo, mercor(<i>dep</i>).</div><div class=\"def\">▼<b>買い集める</b> coemo.</div><div class=\"def\">▼<b>買い戻す</b> redimo.</div>\r\n","<div class=\"hw jl\">買収</div><div class=\"def\">(=購入)emptio, comparatio;(=賄賂で人の心を買うこと)corruptio.</div><div class=\"def\">▼<b>～する</b>(=購入する)mercor(<i>dep</i>), emo, comparo;(賄賂で)(pretio)corrumpo, pecuniā tempto.</div><div class=\"def\">▼<b>～された</b> corruptus.</div><div class=\"def\">▼<b>～者</b> corruptor.</div>\r\n","<div class=\"hw jl\">貸す</div><div class=\"def\">(物を)commodo;(金を)pecuniam credo;(利子を取って金を)faenero, faeneror(<i>dep</i>), pecuniam faenori do.</div><div class=\"ex2\">14000セステルティウスを～<span class=\"ext\">sestertia quattuordecim mutua do.</span></div><div class=\"ex2\">手を～<span class=\"ext\">manum commodo, manum affero.</span></div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">貸手(=債権者)<span class=\"ext\">creditor.</span></div>\r\n","<div class=\"hw jl\">費用</div><div class=\"def\">impensa, sumptus, impendium, dispendium.</div><div class=\"def\">▼<b>～のかかる</b> sumptuosus, impendiosus.</div><div class=\"def\">⇒<a href=\"entry://高価\">高価</a>.</div>\r\n","<div class=\"hw jl\">貼る</div><div class=\"def\">glutino.</div><div class=\"def\">▼<b>貼り付ける</b> agglutino.</div><div class=\"def\">▼<b>貼り合わせる</b> conglutino.</div>\r\n","<div class=\"hw jl\">貿易</div><div class=\"def\">(=交易, 商業)permutatio, negotiatio, commercium, mercatura;(=国際取引)gentium inter se commercium, commercium internationale.</div><div class=\"def\">▼<b>自由～</b> librum permutatio [commercium], mercatura vectigalibus immunis.</div>\r\n","<div class=\"hw jl\">賃金</div><div class=\"def\">⇒<a href=\"entry://給料\">給料</a>.</div>\r\n","<div class=\"hw jl\">賄賂</div><div class=\"def\">pretium.</div><div class=\"ex2\">(人を)～で買収する<span class=\"ext\">〈alqm〉 pretio corrumpo.</span></div>\r\n","<div class=\"hw jl\">資力</div><div class=\"def\">pecunia, opes(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">資料</div><div class=\"def\">materia, materies.</div>\r\n","<div class=\"hw jl\">資本</div><div class=\"def\">▼<b>～金</b> pecunia, fundus pecuniarius.</div><div class=\"def\">▼<b>～主義</b> capitalismus.</div>\r\n","<div class=\"hw jl\">資格</div><div class=\"def\">▼<b>～のある</b> idoneus.</div>\r\n","<div class=\"hw jl\">資源</div><div class=\"def\">facultates(<i>pl</i>), opes(<i>pl</i>), copiae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">資産</div><div class=\"def\">⇒<a href=\"entry://財産\">財産</a>.</div>\r\n","<div class=\"hw jl\">資金</div><div class=\"def\">⇒<a href=\"entry://金\">金<SUB>かね</SUB></a>,<a href=\"entry://資力\">資力</a>,<a href=\"entry://財源\">財源</a>.</div>\r\n","<div class=\"hw jl\">賛嘆</div><div class=\"def\">admiratio.</div>\r\n","<div class=\"hw jl\">賛成</div><div class=\"def\">assensio, assensus, assentatio.</div><div class=\"def\">▼<b>～する</b> assentior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://同意\">同意</a>,<a href=\"entry://認める\">認める</a>,<a href=\"entry://承認\">承認</a>.</div>\r\n","<div class=\"hw jl\">賛辞</div><div class=\"def\">laudatio.</div><div class=\"def\">⇒<a href=\"entry://賞賛\">賞賛</a>.</div>\r\n","<div class=\"hw jl\">賞</div><div class=\"def\">praemium.</div><div class=\"ex2\">ノーベル～<span class=\"ext\">praemia Nobeliana(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://受賞\">受賞</a>.</div>\r\n","<div class=\"hw jl\">賞賛</div><div class=\"def\">laus, laudatio, honor.</div><div class=\"def\">▼<b>～されるべき, ～に値する</b> laudabilis, laudatus.</div><div class=\"def\">▼<b>～する</b> laudo.</div><div class=\"def\">▼<b>～者</b> laudator.</div><div class=\"def\">⇒<a href=\"entry://ほめる\">ほめる</a>.</div>\r\n","<div class=\"hw jl\">賠償</div><div class=\"def\">(=償い)restitutio, compensatio, pensatio.</div><div class=\"def\">▼(損害を)<b> ～する</b> compenso, penso, (damnum)dissolvo [resarcio], (jacturam)restituo.</div>\r\n","<div class=\"hw jl\">賢い</div><div class=\"def\"><span class=\"pos3\">[形]</span> sapiens.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> sapio.</div><div class=\"def\">▼<b>賢さ</b> sapientia.</div><div class=\"def\">▼<b>賢く</b> sapienter.</div>\r\n","<div class=\"hw jl\">賢明</div><div class=\"def\">sapientia.</div><div class=\"def\">▼<b>～な</b> sapiens.</div><div class=\"def\">▼<b>～に</b> sapienter.</div><div class=\"def\">⇒<a href=\"entry://賢い\">賢い</a>.</div>\r\n","<div class=\"hw jl\">質</div><div class=\"def\">(量に対して)qualitas.</div>\r\n","<div class=\"hw jl\">質問</div><div class=\"def\">interrogatio, percontatio, rogatio.</div><div class=\"def\">▼<b>～する</b> interrogo, percontor(<i>dep</i>), rogo.</div><div class=\"def\">⇒<a href=\"entry://尋ねる\">尋ねる</a>.</div>\r\n","<div class=\"hw jl\">質素</div><div class=\"def\">▼<b>～な</b> modicus, simplex, parcus, siccus.</div><div class=\"def\">▼<b>～に</b> simpliciter.</div><div class=\"def\">⇒<a href=\"entry://素朴\">素朴</a>,<a href=\"entry://控えめ\">控えめ</a>.</div>\r\n","<div class=\"hw jl\">質量</div><div class=\"def\">massa.</div><div class=\"def\">⇒<a href=\"entry://物体\">物体</a>.</div>\r\n","<div class=\"hw jl\">賭け</div><div class=\"def\">▼<b>～をする</b> sponsionem facio, pignore contendo, pignore certo;(人と)pignus pono 〈cum alqo〉.</div><div class=\"def\">▼<b>～金</b> pignus.</div>\r\n","<div class=\"hw jl\">賭ける</div><div class=\"def\">⇒<a href=\"entry://賭け\">賭け</a>.</div>\r\n","<div class=\"hw jl\">購入</div><div class=\"def\">emptio.</div><div class=\"def\">▼<b>～する</b> mercor(<i>dep</i>), emo, emptionem facio.</div><div class=\"def\">⇒<a href=\"entry://買う\">買う</a>.</div>\r\n","<div class=\"hw jl\">購買</div><div class=\"def\">⇒<a href=\"entry://購入\">購入</a>.</div>\r\n","<div class=\"hw jl\">贈る</div><div class=\"def\">dono.</div><div class=\"ex2\">(...を人に)贈物として～(=与える)<span class=\"ext\">dono do 〈alqd alci〉.</span></div>\r\n","<div class=\"hw jl\">贈物</div><div class=\"def\">donum, munus.</div><div class=\"ex2\">新年の～<span class=\"ext\">strena.</span></div><div class=\"ex2\">～をする<span class=\"ext\">dono, 〈+<i>dat</i>〉 donum do [affero], 〈+<i>acc</i>〉 munere dono.</span></div>\r\n","<div class=\"hw jl\">赤</div><div class=\"def\">▼<b>～い</b> ruber, rubens.</div><div class=\"def\">▼<b>～色</b> rubor.</div><div class=\"def\">▼<b>～い色をしている</b> rubeo.</div><div class=\"def\">▼<b>～くなる</b> rubesco.</div>\r\n","<div class=\"hw jl\">赤ん坊</div><div class=\"def\">(=乳児)lactens, lactens puer.</div><div class=\"def\">⇒<a href=\"entry://幼児\">幼児</a>,<a href=\"entry://子供\">子供</a>.</div>\r\n","<div class=\"hw jl\">赤字</div><div class=\"def\">lacuna </div><div class=\"def\">▼<b>～である</b>(=支出が収入を超過する)sumptus fructum superat.</div><div class=\"def\">⇒<a href=\"entry://損失\">損失</a>.</div>\r\n","<div class=\"hw jl\">赤道</div><div class=\"def\">aequinoctialis [meridianus] circulus, aequator.</div><div class=\"def\">▼<b>～の</b> aequinoctialis, ad circulum aequinoctialem pertinens.</div>\r\n","<div class=\"hw jl\">赤面</div><div class=\"def\">rubor.</div><div class=\"def\">▼<b>～する</b> erubesco, rubesco, rubeo.</div><div class=\"def\">⇒<a href=\"entry://恥ずかしがり\">恥ずかしがり</a>.</div>\r\n","<div class=\"hw jl\">走る</div><div class=\"def\">curro.</div><div class=\"def\">▼<b>～人</b> cursor.</div><div class=\"def\">▼<b>～こと</b> cursus.</div><div class=\"def\">▼<b>あちこち走り回る</b> cursito, curso.</div><div class=\"def\">▼<b>走って</b> cursim.</div>\r\n","<div class=\"hw jl\">起きている</div><div class=\"def\">(=目覚めている)<span class=\"pos3\">[形]</span> experrectus.</div><div class=\"def\">━<span class=\"pos3\">[動]</span> vigilo.</div><div class=\"def\">⇒<a href=\"entry://起きる\">起きる</a>,<a href=\"entry://目覚める\">目覚める</a>.</div>\r\n","<div class=\"hw jl\">起きる</div><div class=\"def\">(=立ち上がる)surgo, orior(<i>dep</i>);(=発生する)orior(<i>dep</i>), accido, advenio, evenio, fio;(結果として)consequor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://目覚める\">目覚める</a>.</div>\r\n","<div class=\"hw jl\">起こす</div><div class=\"def\">(=眠りから覚ます)expergefacio, (e somno)excito [suscito];(=立たす)erigo, suscito.</div>\r\n","<div class=\"hw jl\">起こる</div><div class=\"def\">(=生じる)accido, incido;〈quod;ut;+<i>inf</i>〉 accidit, evenit, contingit(<i>impers</i>).</div><div class=\"ex2\">(驚くべき偶然で)(...が)起こった<span class=\"ext\">(magno casu)〈ut〉 accidit.</span></div><div class=\"ex2\">(誠に都合よく)(...が)起こった<span class=\"ext\">(per commode)〈quod〉 accidit.</span></div>\r\n","<div class=\"hw jl\">起源</div><div class=\"def\">origo, principium, primordium.</div><div class=\"ex2\">鳥の～は恐竜である<span class=\"ext\">aves ex dinosauris originem habent / aves ex dinosauris ortae sunt.</span></div><div class=\"def\">⇒<a href=\"entry://根源\">根源</a>.</div>\r\n","<div class=\"hw jl\">起草</div><div class=\"def\">confectio.</div><div class=\"def\">▼<b>～する</b> scribo.</div>\r\n","<div class=\"hw jl\">超過</div><div class=\"def\">id quod excedit.</div><div class=\"def\">▼<b>～する</b> excedo.</div><div class=\"def\">⇒<a href=\"entry://過剰\">過剰</a>.</div>\r\n","<div class=\"hw jl\">越える・超える</div><div class=\"def\">transilio, transcendo, transeo, transgredior(<i>dep</i>), supero, praetereo.</div><div class=\"ex2\">度を超えて<span class=\"ext\">supra modum.</span></div><div class=\"ex2\">ライン川を越えて<span class=\"ext\">trans Rhenum.</span></div><div class=\"ex2\">城壁を越えて<span class=\"ext\">super murum.</span></div>\r\n","<div class=\"hw jl\">越す・超す</div><div class=\"ex2\">度を～<span class=\"ext\">modum excedo.</span></div><div class=\"def\">⇒<a href=\"entry://越える・超える\">越える</a>,<a href=\"entry://過度\">過度</a>.</div>\r\n","<div class=\"hw jl\">趣味</div><div class=\"def\">praeoptata subsiciva occupatio, oblectatio, studium, voluptas.</div><div class=\"def\">⇒<a href=\"entry://気晴らし\">気晴らし</a>,<a href=\"entry://娯楽\">娯楽</a>,<a href=\"entry://嗜好\">嗜好</a>,<a href=\"entry://審美眼\">審美眼</a>.</div>\r\n","<div class=\"hw jl\">足</div><div class=\"def\">pes;(ひざから下の)crus.</div><div class=\"ex2\">～の裏<span class=\"ext\">planta.</span></div><div class=\"ex2\">～の指<span class=\"ext\">digiti pedis(<i>pl</i>).</span></div><div class=\"def\">⇒<a href=\"entry://すね\">すね</a>,<a href=\"entry://かかと\">かかと</a>,<a href=\"entry://ふくらはぎ\">ふくらはぎ</a>,<a href=\"entry://ひざ\">ひざ</a>,<a href=\"entry://腿\">腿</a>.</div>\r\n","<div class=\"hw jl\">足し算</div><div class=\"def\">⇒<a href=\"entry://計算\">計算</a>,<a href=\"entry://合計\">合計</a>.</div>\r\n","<div class=\"hw jl\">足す</div><div class=\"def\">(=加える, 付け加える)adjungo, addo, adicio.</div>\r\n","<div class=\"hw jl\">足もと</div><div class=\"def\">▼<b>～に</b>(人の)(alcis)ad pedes;(=目の前に)ante pedes.</div>\r\n","<div class=\"hw jl\">足りる</div><div class=\"def\">sufficio, suppeto, suppedito.</div><div class=\"def\">▼(...が)<b> 足りない</b> desum, deficio, 〈alcis rei〉 est inopia, non sufficio, non suppedito.</div><div class=\"def\">⇒<a href=\"entry://十分\">十分</a>,<a href=\"entry://不足\">不足</a>.</div>\r\n","<div class=\"hw jl\">足跡</div><div class=\"def\">vestigium.</div>\r\n","<div class=\"hw jl\">跡</div><div class=\"def\">(=痕跡, 足跡)vestigium;(=傷跡)cicatrix.</div><div class=\"def\">▼<b>～をつける</b> vestigo.</div>\r\n","<div class=\"hw jl\">跳ぶ</div><div class=\"def\">salio.</div><div class=\"def\">▼<b>跳びはねること</b> saltus.</div>\r\n","<div class=\"hw jl\">跳躍</div><div class=\"def\">saltus.</div><div class=\"def\">▼<b>～する</b> salio.</div>\r\n","<div class=\"hw jl\">踊る</div><div class=\"def\">salto, salio.</div><div class=\"ex2\">踊りを～<span class=\"ext\">saltationem salto.</span></div><div class=\"def\">▼<b>踊り</b> saltatio.</div>\r\n","<div class=\"hw jl\">踏む</div><div class=\"def\">calco.</div>\r\n","<div class=\"hw jl\">蹴る</div><div class=\"def\">calce ferio [caedo, peto, contundo], calcitro.</div><div class=\"def\">▼<b>蹴り</b> calcitratus, calcis [pedis] ictus.</div>\r\n","<div class=\"hw jl\">身</div><div class=\"def\">(=肉)caro;(=身体)corpus.</div>\r\n","<div class=\"hw jl\">身なり</div><div class=\"def\">vestitus, ornatus, cultus.</div>\r\n","<div class=\"hw jl\">身体</div><div class=\"def\">corpus.</div><div class=\"def\">▼<b>～の</b> corporeus.</div>\r\n","<div class=\"hw jl\">身分</div><div class=\"def\">(=階級, 地位)ordo, locus, genus, condicio.</div>\r\n","<div class=\"hw jl\">身投げ</div><div class=\"def\">▼<b>～する</b>(=投身自殺する)se praecipitare(← praecipito)〈ex re;in alqd〉.</div>\r\n","<div class=\"hw jl\">身振り</div><div class=\"def\">gestus, gesticulatio, motus, corporis jactatio.</div>\r\n","<div class=\"hw jl\">身軽</div><div class=\"def\">▼<b>～な</b> expeditus, levis.</div><div class=\"def\">▼<b>～に</b> expedite.</div><div class=\"def\">⇒<a href=\"entry://すばやい\">すばやい</a>,<a href=\"entry://軽快\">軽快</a>.</div>\r\n","<div class=\"hw jl\">身長</div><div class=\"def\">statura, proceritas, spatium a vestigio ad verticem.</div>\r\n","<div class=\"hw jl\">車庫</div><div class=\"def\">autocinetorum receptaculum, tabernaculum automatariis vehiculis [raedis] asservandis.</div><div class=\"def\">⇒<a href=\"entry://駐車\">駐車</a>.</div>\r\n","<div class=\"hw jl\">車輪</div><div class=\"def\">rota.</div>\r\n","<div class=\"hw jl\">車道</div><div class=\"def\">via vehicularis.</div><div class=\"def\">⇒<a href=\"entry://歩道\">歩道</a>.</div>\r\n","<div class=\"hw jl\">軌道</div><div class=\"def\">circulus;(天体の)orbita.</div>\r\n","<div class=\"hw jl\">軍</div><div class=\"def\">⇒<a href=\"entry://軍隊\">軍隊</a>.</div>\r\n","<div class=\"hw jl\">軍事</div><div class=\"def\">res militaris.</div><div class=\"def\">▼<b>～(上)の, ～的な</b> militaris.</div>\r\n","<div class=\"hw jl\">軍人</div><div class=\"def\">(=兵士)miles, homo [vir] militaris.</div>\r\n","<div class=\"hw jl\">軍備</div><div class=\"def\">belli instrumentum [apparatus], apparatus militaris, armamenta(<i>pl</i>), arma(<i>pl</i>).</div><div class=\"def\">▼<b>～拡張競争</b> rei militaris augendae contentio, apparatūs militaris studium.</div><div class=\"def\">⇒<a href=\"entry://軍縮\">軍縮</a>.</div>\r\n","<div class=\"hw jl\">軍勢</div><div class=\"def\">copiae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">軍旗</div><div class=\"def\">signum, aquila, vexillum.</div>\r\n","<div class=\"hw jl\">軍服</div><div class=\"def\">vestimenta militaria(<i>pl</i>), ornatus [vestitus, habitus] militaris.</div>\r\n","<div class=\"hw jl\">軍縮</div><div class=\"def\">ab armis discessio [discessus], apparatus militaris [armorum] diminutio, armamentorum ademptio.</div>\r\n","<div class=\"hw jl\">軍艦</div><div class=\"def\">navis longa [bellica].</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">三段櫂船<span class=\"ext\">triremis(navis), trieris(navis).</span></div><div class=\"cf\">輸送艦<span class=\"ext\">navis oneraria.</span></div><div class=\"cf\">哨戒艇<span class=\"ext\">speculatoria navigia.</span></div><div class=\"cf\">航空母艦<span class=\"ext\">navis aeroplanorum vectrix.</span></div>\r\n","<div class=\"hw jl\">軍隊</div><div class=\"def\">exercitus, milites(<i>pl</i>), militia.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">軍団<span class=\"ext\">legio.</span></div><div class=\"cf\">大隊<span class=\"ext\">cohors.</span></div><div class=\"cf\">中隊<span class=\"ext\">manipulus.</span></div><div class=\"cf\">百人隊<span class=\"ext\">centuria.</span></div><div class=\"cf\">兵士<span class=\"ext\">miles.</span></div><div class=\"def\">⇒<a href=\"entry://軍勢\">軍勢</a>.</div>\r\n","<div class=\"hw jl\">転がす</div><div class=\"def\">volvo, voluto.</div>\r\n","<div class=\"hw jl\">転がる</div><div class=\"def\">volvor(<i>pass</i>), volutor(<i>pass</i>), se volutare(← voluto).</div><div class=\"def\">▼<b>転げ回ること</b> volutatio.</div>\r\n","<div class=\"hw jl\">転ぶ</div><div class=\"def\">⇒<a href=\"entry://倒れる\">倒れる</a>.</div>\r\n","<div class=\"hw jl\">軸</div><div class=\"def\">axis.</div>\r\n","<div class=\"hw jl\">軽い</div><div class=\"def\">levis.</div><div class=\"def\">▼<b>軽く</b> leviter.</div><div class=\"def\">▼<b>軽くする</b> levo.</div><div class=\"def\">▼<b>軽さ</b> levitas.</div>\r\n","<div class=\"hw jl\">軽快</div><div class=\"def\">pernicitas.</div><div class=\"def\">▼<b>～な</b> pernix, expeditus.</div><div class=\"def\">▼<b>～に</b> perniciter, expedite.</div><div class=\"def\">⇒<a href=\"entry://身軽\">身軽</a>,<a href=\"entry://すばやい\">すばやい</a>.</div>\r\n","<div class=\"hw jl\">軽減</div><div class=\"def\">levamen, levamentum, levatio.</div><div class=\"def\">▼<b>～する</b> levo, exonero.</div><div class=\"def\">⇒<a href=\"entry://緩和\">緩和</a>,<a href=\"entry://和らげる\">和らげる</a>.</div>\r\n","<div class=\"hw jl\">軽率</div><div class=\"def\">temeritas, inconsiderantia, imprudentia.</div><div class=\"def\">▼<b>～な</b> temerarius, inconsultus, inconsideratus, imprudens.</div><div class=\"def\">▼<b>～に</b> temere, inconsulte, incaute, inconsiderate, imprudenter.</div><div class=\"def\">⇒<a href=\"entry://浅はか\">浅はか</a>.</div>\r\n","<div class=\"hw jl\">軽蔑</div><div class=\"def\">despicientia, despectio, despicatus, contemptio, contemptus.</div><div class=\"def\">▼<b>～する</b> despicio, despicor(<i>dep</i>), contemno;(人を)habeo 〈alqm〉 despicatui.</div><div class=\"def\">▼<b>～して</b> contemptim.</div>\r\n","<div class=\"hw jl\">軽薄</div><div class=\"def\">levitas.</div><div class=\"def\">▼<b>～な</b> frivolus, levis, nugatorius.</div>\r\n","<div class=\"hw jl\">軽視</div><div class=\"def\">▼<b>～する</b> postfero.</div>\r\n","<div class=\"hw jl\">載せる</div><div class=\"def\">(=上に置く)impono.</div>\r\n","<div class=\"hw jl\">輝き</div><div class=\"def\">splendor, nitor, fulgor.</div><div class=\"def\">⇒<a href=\"entry://光\">光</a>.</div>\r\n","<div class=\"hw jl\">輝く</div><div class=\"def\">(明るく)<span class=\"pos3\">[動]</span> fulgeo, luceo, splendeo, niteo, candeo.</div><div class=\"def\">━<span class=\"pos3\">[形]</span> fulgens, splendidus, clarus, candidus, nitidus.</div><div class=\"def\">▼<b>輝き出す, 輝き始める</b> lucesco, splendesco, nitesco.</div>\r\n","<div class=\"hw jl\">輩出</div><div class=\"ex2\">今年は多くの詩人が～した<span class=\"ext\">magnum proventum poetarum annus hic attulit.</span></div>\r\n","<div class=\"hw jl\">輪</div><div class=\"def\">circulus, orbis, gyrus.</div>\r\n","<div class=\"hw jl\">輪郭</div><div class=\"def\">circumscriptio, lineamenta(<i>pl</i>), lineae extremae(<i>pl</i>).</div>\r\n","<div class=\"hw jl\">輸入</div><div class=\"def\">invectio, importatio.</div><div class=\"def\">▼<b>～品</b> merx importaticia.</div><div class=\"def\">▼<b>～者</b> importator(<i>m</i>).</div><div class=\"def\">▼<b>～する</b> importo, inveho, arcesso.</div>\r\n","<div class=\"hw jl\">輸出</div><div class=\"def\">exportatio.</div><div class=\"def\">▼<b>～者</b> exportator.</div><div class=\"def\">▼<b>～する</b> exporto.</div>\r\n","<div class=\"hw jl\">輸血</div><div class=\"def\">transfusio sanguinis.</div>\r\n","<div class=\"hw jl\">輸送</div><div class=\"def\">portatio, vectio, vectura, subvectio, convectio.</div><div class=\"def\">▼<b>～する</b> fero, transporto, transfero, veho, vecto, supporto.</div><div class=\"def\">⇒<a href=\"entry://運ぶ\">運ぶ</a>.</div>\r\n","<div class=\"hw jl\">辛い</div><div class=\"def\">(=味が刺激的な)(sapore)acutus, mordax;(=塩辛い)salsus.</div><div class=\"def\">▼<b>～味</b> sapor acutus.</div><div class=\"def\">⇒<a href=\"entry://酸っぱい\">酸っぱい</a>,<a href=\"entry://苦い\">苦い</a>.</div>\r\n","<div class=\"hw jl\">辛辣</div><div class=\"def\">acerbitas, mordacitas, acumen.</div><div class=\"def\">▼<b>～な</b> acerbus, mordax, acutus.</div><div class=\"ex2\">彼は～家だった<span class=\"ext\">acerbae linguae fuit.</span></div>\r\n","<div class=\"hw jl\">辞める</div><div class=\"def\">(...を)〈+<i>abl</i>〉 abeo, se abdicare(← abdico), 〈+<i>acc</i>〉 depono, abdico.</div><div class=\"ex2\">官職を辞める<span class=\"ext\">magistratu abeo.</span></div>\r\n","<div class=\"hw jl\">辞任</div><div class=\"def\">ejuratio.</div><div class=\"def\">▼<b>～する</b> abdico, depono, ejuro.</div>\r\n","<div class=\"hw jl\">辞書</div><div class=\"def\">lexicon, glossarium.</div>\r\n","<div class=\"hw jl\">辞職</div><div class=\"def\">abdicatio, ejuratio.</div><div class=\"def\">▼<b>～する</b> se abdicare(← abdico), abdico.</div><div class=\"def\">⇒<a href=\"entry://辞める\">辞める</a>,<a href=\"entry://辞任\">辞任</a>,<a href=\"entry://退職\">退職</a>.</div>\r\n","<div class=\"hw jl\">農夫</div><div class=\"def\">agricola, agricultor, agrestis.</div>\r\n","<div class=\"hw jl\">農業</div><div class=\"def\">(=耕作, 農耕)agricultura, cultura(agri), agrorum cultus.</div>\r\n","<div class=\"hw jl\">辺り</div><div class=\"def\">⇒<a href=\"entry://近く\">近く</a>.</div>\r\n","<div class=\"hw jl\">込み入った</div><div class=\"def\">⇒<a href=\"entry://錯綜\">錯綜</a>.</div>\r\n","<div class=\"hw jl\">込む</div><div class=\"def\">⇒<a href=\"entry://混雑\">混雑</a>.</div>\r\n","<div class=\"hw jl\">迂回</div><div class=\"def\">▼<b>～(路)</b> deverticulum.</div><div class=\"def\">▼<b>～させる</b> deverto.</div>\r\n","<div class=\"hw jl\">迎える</div><div class=\"def\">(=受け入れる, 招待する)excipio, accipio;(人を家に)(alqm tecto;alqm domum)recipio.</div>\r\n","<div class=\"hw jl\">迎合</div><div class=\"def\">adulatio.</div><div class=\"def\">▼<b>～する</b> adulor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://お追従\">お追従</a>.</div>\r\n","<div class=\"hw jl\">近い</div><div class=\"def\">propinquus, vicinus, prope 〈+<i>acc</i>〉 situs.</div>\r\n","<div class=\"hw jl\">近く</div><div class=\"def\">vicinitas, propinquitas, proximitas.</div><div class=\"def\">▼<b>～に[で]</b> in propinquo, (in)propinquis locis, in proximo, in vicino, circum haec loca, propter, propre.</div><div class=\"def\">▼<b>～から</b> ex propinquo.</div><div class=\"def\">▼(...の)<b>～に[で]</b> prope 〈+<i>acc</i>〉, propter 〈+<i>acc</i>〉, juxta 〈+<i>acc</i>〉, ad 〈+<i>acc</i>〉.</div><div class=\"ex2\">町のすぐ～で<span class=\"ext\">prope oppidum.</span></div><div class=\"def\">⇒<a href=\"entry://近い\">近い</a>,<a href=\"entry://側\">側<SUB>そば</SUB></a>.</div>\r\n","<div class=\"hw jl\">近づく</div><div class=\"def\">appropinquo, propinquo, accedo, advento, adeo.</div><div class=\"def\">▼<b>～こと</b> appropinquatio.</div><div class=\"def\">▼<b>～機会[手段]</b> aditus.</div><div class=\"def\">⇒<a href=\"entry://接近\">接近</a>.</div>\r\n","<div class=\"hw jl\">近代</div><div class=\"def\">(=近現代, 現代)novitas, haec tempora(<i>pl</i>), haec aetas.</div><div class=\"def\">▼<b>～の</b>(=現代の)hujus aetatis, hodiernus, recens, nostri temporis, praesentis aetatis, modernus.</div>\r\n","<div class=\"hw jl\">近代化</div><div class=\"def\">(=現代風にすること)accommodatio ad praesentia.</div><div class=\"def\">▼<b>～する</b> ad praesentia accommodo, ad nostrae aetatis rationem redigo, ad nova exempla compono [reconcinno].</div>\r\n","<div class=\"hw jl\">近寄る</div><div class=\"def\">⇒<a href=\"entry://近づく\">近づく</a>.</div>\r\n","<div class=\"hw jl\">近所</div><div class=\"def\">vicinitas, vicinum, propinquitas, vicini(<i>pl</i>).</div><div class=\"def\">▼<b>～の</b> vicinus, propinquus.</div><div class=\"def\">▼(...の)<b> ～に</b>(=近くに)juxta 〈+<i>acc</i>〉, circum 〈+<i>acc</i>〉, prope 〈+<i>acc</i>〉.</div><div class=\"def\">⇒<a href=\"entry://近い\">近い</a>,<a href=\"entry://近く\">近く</a>.</div>\r\n","<div class=\"hw jl\">近東</div><div class=\"def\">(=中近東)Oriens Proximus.</div>\r\n","<div class=\"hw jl\">近視</div><div class=\"def\">myopia.</div><div class=\"def\">▼<b>～の</b> myops.</div>\r\n","<div class=\"hw jl\">返す</div><div class=\"def\">reddo, restituo;(人に金を)(alci)pecuniam remunero.</div>\r\n","<div class=\"hw jl\">返事</div><div class=\"def\">(手紙による)responsum.</div><div class=\"def\">▼(人に)<b> ～を書く</b> 〈ad alqm;alci〉 rescribo;(手紙に対して)〈litteris;ad litteras〉 rescribo, respondeo.</div><div class=\"def\">⇒<a href=\"entry://返答\">返答</a>.</div>\r\n","<div class=\"hw jl\">返済</div><div class=\"def\">solutio, pensio.</div><div class=\"def\">▼<b>～する</b> solvo, pendo.</div><div class=\"def\">⇒<a href=\"entry://支払い\">支払い</a>.</div>\r\n","<div class=\"hw jl\">返答</div><div class=\"def\">(質問に対する)responsio, responsum.</div><div class=\"def\">▼<b>～する</b> respondeo.</div><div class=\"def\">⇒<a href=\"entry://返事\">返事</a>.</div>\r\n","<div class=\"hw jl\">返送</div><div class=\"def\">remissio.</div><div class=\"def\">▼<b>～する</b> remitto.</div>\r\n","<div class=\"hw jl\">迫る</div><div class=\"def\">(=強いて求める)compello;(=近くまで押しよせる, 切迫する)immineo, impendeo, urgeo, propinquo, insto.</div>\r\n","<div class=\"hw jl\">迫害</div><div class=\"def\">vexatio, insectatio, persecutio.</div><div class=\"def\">▼<b>～する</b> vexo, insector(<i>dep</i>), persequor(<i>dep</i>).</div><div class=\"ex2\">キリスト教徒に対する～<span class=\"ext\">populi Christiani [Chiristianorum] vexatio.</span></div><div class=\"ex2\">キリスト教徒を～する<span class=\"ext\">in Christianos saevio, Christianos persequor.</span></div>\r\n","<div class=\"hw jl\">述べる</div><div class=\"def\">dico, enuntio, exprimo, promo, expromo, commemoro, expono.</div>\r\n","<div class=\"hw jl\">迷う</div><div class=\"def\">(判断に)(=躊躇する)dubito, haesito;(道に)aberro, erro, deerro.</div>\r\n","<div class=\"hw jl\">迷信</div><div class=\"def\">superstitio.</div><div class=\"def\">▼<b>～的な</b> superstitiosus.</div>\r\n","<div class=\"hw jl\">迷子</div><div class=\"ex2\">人込みの中で～になった子供<span class=\"ext\">puer inter homines a patre deerrans [aberrans].</span></div><div class=\"def\">⇒<a href=\"entry://迷う\">迷う</a>.</div>\r\n","<div class=\"hw jl\">迷惑</div><div class=\"def\">(=厄介)molestia.</div><div class=\"def\">▼<b>～な</b> molestus.</div><div class=\"def\">▼<b>～でなければ</b> nisi molestum est, si tibi grave non est.</div><div class=\"def\">▼(...に)<b>～をかける</b> 〈alci〉 molestiam affero, 〈alqm〉 molestiā afficio.</div>\r\n","<div class=\"hw jl\">追いこす</div><div class=\"def\">praetereo, praecurro, insequor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">追いつく</div><div class=\"def\">assequor(<i>dep</i>), consequor(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">追いつめる</div><div class=\"def\">urgeo, premo.</div>\r\n","<div class=\"hw jl\">追い出す</div><div class=\"def\">expello, exigo.</div><div class=\"def\">⇒<a href=\"entry://追い払う\">追い払う</a>,<a href=\"entry://追放\">追放</a>.</div>\r\n","<div class=\"hw jl\">追い払う</div><div class=\"def\">expello, discutio, dispello, pello, depello, exigo, dimoveo, ago.</div><div class=\"def\">⇒<a href=\"entry://追い出す\">追い出す</a>.</div>\r\n","<div class=\"hw jl\">追い込む</div><div class=\"def\">(...に)compello 〈ad+<i>acc</i>〉.</div><div class=\"ex2\">彼らは町の中に追い込まれる<span class=\"ext\">intra oppida compelluntur.</span></div>\r\n","<div class=\"hw jl\">追う</div><div class=\"def\">(後を)sequor(<i>dep</i>), persequor(<i>dep</i>), subsequor(<i>dep</i>);(=追いたてる)ago.</div><div class=\"def\">⇒<a href=\"entry://追い払う\">追い払う</a>.</div>\r\n","<div class=\"hw jl\">追加</div><div class=\"def\">(=追加部分)additamentum, supplementum.</div><div class=\"def\">▼<b>～する</b> addo, suppleo.</div>\r\n","<div class=\"hw jl\">追放</div><div class=\"def\">exactio, ejectio, expulsio, exsulatio.</div><div class=\"def\">▼<b>～する</b> exigo, eicio, expello, pello, depello, exsulo.</div><div class=\"def\">▼<b>～された人</b> exsul.</div><div class=\"def\">⇒<a href=\"entry://亡命\">亡命</a>.</div>\r\n","<div class=\"hw jl\">追求</div><div class=\"def\">insectatio, persecutio, prosecutio.</div><div class=\"def\">▼<b>～する</b> consector(<i>dep</i>), sequor(<i>dep</i>), sector(<i>dep</i>), affecto, insto.</div>\r\n","<div class=\"hw jl\">追跡</div><div class=\"def\">insectatio, prosecutio.</div><div class=\"def\">▼<b>～する</b> persequor(<i>dep</i>), insequor(<i>dep</i>), sequor(<i>dep</i>), prosequor(<i>dep</i>), consector(<i>dep</i>), consequor(<i>dep</i>), exagito, insto.</div>\r\n","<div class=\"hw jl\">退ける</div><div class=\"def\">repello.</div><div class=\"def\">⇒<a href=\"entry://拒絶\">拒絶</a>.</div>\r\n","<div class=\"hw jl\">退却</div><div class=\"def\">regressus, recessus, receptus.</div><div class=\"def\">▼<b>～する</b> recedo, se recipere(← recipio), regredior(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://後退\">後退</a>.</div>\r\n","<div class=\"hw jl\">退去</div><div class=\"def\">discessus.</div>\r\n","<div class=\"hw jl\">退屈</div><div class=\"def\">taedium.</div><div class=\"def\">▼<b>～する</b> pertaedet(<i>impers</i>), taedet(<i>impers</i>).</div><div class=\"def\">▼<b>～な</b> odiosus.</div><div class=\"def\">⇒<a href=\"entry://疲れる\">疲れる</a>.</div>\r\n","<div class=\"hw jl\">退職</div><div class=\"def\">missio.</div><div class=\"def\">▼<b>～させる</b> missionem do.</div><div class=\"def\">▼<b>～する</b> missionem accipio.</div><div class=\"def\">▼<b>～した</b> missicius.</div><div class=\"ex2\">～の願いを出す<span class=\"ext\">missionem postulo.</span></div>\r\n","<div class=\"hw jl\">送る</div><div class=\"def\">(=送り出す)mitto.</div><div class=\"def\">▼<b>～こと</b>(=発送, 派遣)missio.</div><div class=\"def\">⇒<a href=\"entry://過ごす\">過ごす</a>.</div>\r\n","<div class=\"hw jl\">送料</div><div class=\"def\">⇒<a href=\"entry://運賃\">運賃</a>.</div>\r\n","<div class=\"hw jl\">逃げる</div><div class=\"def\">fugio, effugio, dilabor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://逃亡\">逃亡</a>.</div>\r\n","<div class=\"hw jl\">逃亡</div><div class=\"def\">fuga, effugium, transfugium.</div><div class=\"def\">▼<b>～する</b> fugio, effugio, profugio.</div><div class=\"def\">▼<b>～している</b> profugus.</div><div class=\"def\">▼<b>～した</b> fugitivus.</div><div class=\"def\">▼<b>～奴隷</b> fugitivus(servus).</div><div class=\"def\">⇒<a href=\"entry://脱走\">脱走</a>.</div>\r\n","<div class=\"hw jl\">逆</div><div class=\"def\">(=反対)contrarium.</div><div class=\"def\">▼<b>～の</b>(=逆さまの)inversus, perversus;(裏表・上下が)conversus;(前後が)praeposterus;(=反対の)contrarius.</div><div class=\"def\">▼<b>～に</b>(=反対に)perverse, contrarie, ex contrario;(前後が)praepostere.</div><div class=\"def\">▼<b>～にする</b> perverto, inverto, converto.</div><div class=\"def\">⇒<a href=\"entry://反対\">反対</a>.</div>\r\n","<div class=\"hw jl\">逆さ</div><div class=\"def\">▼<b>～に</b> perverse.</div><div class=\"def\">▼<b>～の</b> perversus.</div><div class=\"def\">⇒<a href=\"entry://反対\">反対</a>,<a href=\"entry://逆\">逆</a>.</div>\r\n","<div class=\"hw jl\">逆さま</div><div class=\"def\">▼<b>～の</b> praeposterus.</div><div class=\"def\">⇒<a href=\"entry://逆\">逆</a>.</div>\r\n","<div class=\"hw jl\">逆らう</div><div class=\"def\">adversor(<i>dep</i>), se opponere(← oppono), resisto, renitor(<i>dep</i>).</div><div class=\"def\">⇒<a href=\"entry://反抗\">反抗</a>.</div>\r\n","<div class=\"hw jl\">逆説</div><div class=\"def\">paradoxa(<i>pl</i>), quod contra opinionem omnium est.</div>\r\n","<div class=\"hw jl\">逆転</div><div class=\"def\">conversio.</div><div class=\"def\">⇒<a href=\"entry://ひっくり返す\">ひっくり返す</a>.</div>\r\n","<div class=\"hw jl\">透きとおる</div><div class=\"def\"><span class=\"pos3\">[形]</span> perlucidus, translucidus.</div><div class=\"def\">▼<b>透きとおって輝く</b><span class=\"pos3\">[動]</span> transluceo.</div>\r\n","<div class=\"hw jl\">透明</div><div class=\"def\">perluciditas, perspicuitas.</div><div class=\"def\">▼<b>～な</b> perspicuus, perlucidus, perlucidulus, translucidus.</div><div class=\"def\">▼<b>～である</b> perluceo, transluceo.</div>\r\n","<div class=\"hw jl\">途中</div><div class=\"def\">▼<b>～で</b> in via, in itinere, inter viam [vias].</div>\r\n","<div class=\"hw jl\">這う</div><div class=\"def\">repo, serpo.</div>\r\n","<div class=\"hw jl\">通う</div><div class=\"def\">frequento.</div>\r\n","<div class=\"hw jl\">通じて</div><div class=\"def\">(...を)per 〈+<i>acc</i>〉.</div><div class=\"ex2\">2日間を～<span class=\"ext\">per biduum.</span></div><div class=\"ex2\">困難を～天(栄光)へ<span class=\"ext\">per aspera ad astra.</span></div>\r\n","<div class=\"hw jl\">通じている</div><div class=\"def\"><span class=\"pos3\">[形]</span> peritus.</div>\r\n","<div class=\"hw jl\">通じる</div><div class=\"def\">⇒<a href=\"entry://理解\">理解</a>,<a href=\"entry://分かる\">分かる</a>.</div>\r\n","<div class=\"hw jl\">通す</div><div class=\"def\">(=通過させる)transmitto, traduco.</div><div class=\"ex2\">ざっと目を～<span class=\"ext\">percurro.</span></div>\r\n","<div class=\"hw jl\">通って</div><div class=\"def\">(...を)per 〈+<i>acc</i>〉.</div><div class=\"ex2\">属州を～<span class=\"ext\">per provinciam.</span></div>\r\n","<div class=\"hw jl\">通り</div><div class=\"def\">via, vicus;(=大通り)platea;(=裏通り)angiportum.</div>\r\n","<div class=\"hw jl\">通り過ぎる</div><div class=\"def\">praetereo, transgredior(<i>dep</i>), praetergredior(<i>dep</i>), praetervehor(<i>dep</i>).</div><div class=\"def\">▼(...を)<b> 通り過ぎて</b> praeter 〈+<i>acc</i>〉.</div><div class=\"ex2\">陣営のそばを通り過ぎて<span class=\"ext\">praeter castra.</span></div>\r\n","<div class=\"hw jl\">通る</div><div class=\"def\">(...を)eo 〈+<i>abl</i>〉, incedo 〈per+<i>acc</i>〉, transeo 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw jl\">通俗</div><div class=\"def\">▼<b>～の</b> vulgaris, vulgatus.</div>\r\n","<div class=\"hw jl\">通信</div><div class=\"def\">(手紙による)epistulae(<i>pl</i>).</div><div class=\"def\">▼<b>～員</b> epistularius socius.</div><div class=\"def\">⇒<a href=\"entry://知らせる\">知らせる</a>.</div>\r\n","<div class=\"hw jl\">通常</div><div class=\"def\">▼<b>～(は)</b> fere, plerumque.</div><div class=\"def\">▼<b>～の</b> ordinarius.</div><div class=\"def\">⇒<a href=\"entry://普通\">普通</a>,<a href=\"entry://一般\">一般</a>,<a href=\"entry://たいてい\">たいてい</a>.</div>\r\n","<div class=\"hw jl\">通知</div><div class=\"def\">denuntiatio, renuntiatio.</div><div class=\"def\">▼<b>～する</b> denuntio, renuntio.</div>\r\n","<div class=\"hw jl\">通行止め</div><div class=\"ex2\">道路が～になっている<span class=\"ext\">via est praeclusa.</span></div>\r\n","<div class=\"hw jl\">通訳</div><div class=\"def\">interpretatio.</div><div class=\"def\">▼<b>～する</b> interpretor(<i>dep</i>).</div><div class=\"def\">▼<b>～者</b> interpres.</div>\r\n","<div class=\"hw jl\">通貨</div><div class=\"def\">nummus, pecunia.</div><div class=\"def\">▼<b>共通～</b> chartae nummariae monetaeque communes.</div><div class=\"def\">▼<b>～切上げ</b> revaloratio.</div><div class=\"def\">▼<b>国際～基金</b>(IMF)Fundus Monetarius Internationalis.</div><div class=\"def\">⇒<a href=\"entry://金\">金<SUB>かね</SUB></a>,<a href=\"entry://コイン\">コイン</a>,<a href=\"entry://貨幣\">貨幣</a>,<a href=\"entry://紙幣\">紙幣</a>.</div>\r\n","<div class=\"hw jl\">通過</div><div class=\"def\">transitus.</div><div class=\"def\">▼<b>～する</b> transvado, transeo, pervado, praetereo, perago.</div><div class=\"def\">▼<b>～させる</b> transmitto, transveho;(法案を)(rogationem)perfero.</div><div class=\"ex2\">法案が～する<span class=\"ext\">lex perfertur.</span></div>\r\n","<div class=\"hw jl\">速い</div><div class=\"def\">(速度が)(=急速な, 急いでいる)celer, rapidus, citatus, velox, concitatus.</div><div class=\"def\">▼<b>速さ, ～こと</b> celeritas, rapiditas, velocitas, pernicitas.</div><div class=\"def\">▼<b>速く</b>(=急いで)rapide, velociter, celeriter, raptim, cito, concitate.</div>\r\n","<div class=\"hw jl\">速度</div><div class=\"def\">celeritas, velocitas.</div><div class=\"cf0\"><i>cf</i>.</div><div class=\"cf\">時速20キロを超える<span class=\"ext\">velocitatem viginti chiliometrorum horalium excedo.</span></div>\r\n","<div class=\"hw jl\">速達</div><div class=\"def\">▼<b>～(の手紙)</b> litterae celeriores(<i>pl</i>), epistula celerrime ferenda, citissimus nuntius.</div>\r\n","<div class=\"hw jl\">連れ</div><div class=\"def\">comes;(旅の)convector.</div><div class=\"def\">⇒<a href=\"entry://相手\">相手</a>.</div>\r\n","<div class=\"hw jl\">連れる</div><div class=\"def\">▼<b>連れて行く</b> duco, adduco.</div><div class=\"def\">▼<b>連れ出す</b> educo, deduco.</div><div class=\"def\">▼<b>連れ去る</b> abduco.</div><div class=\"def\">⇒<a href=\"entry://付き添う\">付き添う</a>.</div>\r\n","<div class=\"hw jl\">連合</div><div class=\"def\">conjunctio, societas, consociatio, unio.</div>\r\n","<div class=\"hw jl\">連帯</div><div class=\"def\">societas.</div><div class=\"def\">▼<b>～の</b> socius.</div>\r\n","<div class=\"hw jl\">連盟</div><div class=\"def\">societas.</div><div class=\"def\">⇒<a href=\"entry://同盟\">同盟</a>.</div>\r\n","<div class=\"hw jl\">連絡</div><div class=\"def\">(=知らせ)nuntii(<i>pl</i>);(手紙による)litterae(<i>pl</i>).</div><div class=\"ex2\">私たちに～して下さい<span class=\"ext\">fac nos certiores quid agas.</span></div><div class=\"ex2\">あなたからの～を待っています<span class=\"ext\">exspecto tuas litteras.</span></div>\r\n","<div class=\"hw jl\">連続</div><div class=\"def\">continuatio, successio, series, tenor.</div><div class=\"def\">▼<b>～的な</b> continuus, continens, perpetuus.</div>\r\n","<div class=\"hw jl\">連邦</div><div class=\"def\">foederatae civitates.</div>\r\n","<div class=\"hw jl\">連鎖</div><div class=\"def\">continuatio, catena.</div><div class=\"def\">⇒<a href=\"entry://連続\">連続</a>.</div>\r\n","<div class=\"hw jl\">逮捕</div><div class=\"def\">comprehensio.</div><div class=\"def\">▼<b>～する</b> comprehendo, prehendo.</div>\r\n","<div class=\"hw jl\">週</div><div class=\"def\">hebdomas, hebdomada, septem dies(<i>pl</i>), septem dierum spatium, septimana.</div><div class=\"def\">▼<b>毎～の</b> hebdomadalis.</div><div class=\"def\">▼<b>今～</b><span class=\"pos3\">[副]</span> hac septimana.</div><div class=\"def\">▼<b>先～</b><span class=\"pos3\">[副]</span> septimanā proximā [(proxime)praeteritā].</div><div class=\"def\">⇒<a href=\"entry://曜日\">曜日</a>,<a href=\"entry://週末\">週末</a>.</div>\r\n","<div class=\"hw jl\">週末</div><div class=\"def\">exiens hebdomada, hebdomadae exitus [finis], ultimi septimanae dies(<i>pl</i>), dies hebdomadae finientis(<i>pl</i>).</div><div class=\"def\">⇒<a href=\"entry://週\">週</a>.</div>\r\n","<div class=\"hw jl\">進む</div><div class=\"def\">progredior(<i>dep</i>), prodeo.</div><div class=\"def\">▼(時計が)<b>進んでいる</b>(horologium)currit ocius.</div><div class=\"ex2\">決勝(戦)に～<span class=\"ext\">in certamen finale prodeo.</span></div><div class=\"def\">⇒<a href=\"entry://遅れる\">遅れる</a>.</div>\r\n","<div class=\"hw jl\">進める</div><div class=\"def\">(=前進させる)promoveo, proveho, profero, produco.</div><div class=\"def\">⇒<a href=\"entry://前進\">前進</a>.</div>\r\n","<div class=\"hw jl\">進化</div><div class=\"def\">evolutio(phylogenetica), progressio.</div><div class=\"def\">▼<b>～論</b> ratio evolutionis;(=ダーウィニズム)Darvinismus, Darviniana doctrina.</div>\r\n","<div class=\"hw jl\">進歩</div><div class=\"def\">progressus, progressio, profectus, processus.</div><div class=\"def\">▼<b>～する</b> procedo, progredior(<i>dep</i>), proficio.</div><div class=\"ex2\">科学の～<span class=\"ext\">disciplinarum profectus.</span></div>\r\n","<div class=\"hw jl\">進行</div><div class=\"def\">progressus, progressio.</div><div class=\"def\">▼<b>～する</b> progredior(<i>dep</i>).</div>\r\n","<div class=\"hw jl\">逸脱</div><div class=\"def\">digressio, declinatio.</div><div class=\"def\">▼(正しい道から)<b> ～する</b>(de recta regione)digredior(<i>dep</i>), declino.</div><div class=\"def\">⇒<a href=\"entry://それる\">それる</a>.</div>\r\n"]);
